}

final class SubtitleStylePresetStore: @unchecked Sendable {
    static let shared = SubtitleStylePresetStore()

    static let presetsChangedNotification = Notification.Name("SubtitleStylePresetStore.presetsChangedNotification")
    private static let defaultsSeededKey = "nuvio.subtitle_presets.defaults_seeded.v1"

    func savedPresetID(defaults: UserDefaults = ProfileSettings.current) -> String? {
        defaults.string(forKey: SubtitleStyleKey.selectedPresetID)
    }

    func savePresets(_ presets: [SubtitleStylePreset], defaults: UserDefaults = ProfileSettings.current) {
        if let encoded = try? JSONEncoder().encode(presets) {
            defaults.set(encoded, forKey: SubtitleStyleKey.customPresets)
        }
        NotificationCenter.default.post(name: Self.presetsChangedNotification, object: nil)
    }

    func allPresets(defaults: UserDefaults = ProfileSettings.current) -> [SubtitleStylePreset] {
        if !defaults.bool(forKey: Self.defaultsSeededKey) {
            var seeded = SubtitleStylePreset.appleTVPresets
            if let data = defaults.data(forKey: SubtitleStyleKey.customPresets),
               let existing = try? JSONDecoder().decode([SubtitleStylePreset].self, from: data) {
                for item in existing where !seeded.contains(where: { $0.id == item.id }) {
                    seeded.append(item)
                }
            }
            savePresets(seeded, defaults: defaults)
            defaults.set(true, forKey: Self.defaultsSeededKey)
            return seeded
        }

        guard let data = defaults.data(forKey: SubtitleStyleKey.customPresets),
              let presets = try? JSONDecoder().decode([SubtitleStylePreset].self, from: data) else {
            return SubtitleStylePreset.appleTVPresets
        }
        return presets
    }

    func customPresets(defaults: UserDefaults = ProfileSettings.current) -> [SubtitleStylePreset] {
        allPresets(defaults: defaults)
    }

    func activePreset(for style: SubtitleStyle, defaults: UserDefaults = ProfileSettings.current) -> SubtitleStylePreset? {
        let presets = allPresets(defaults: defaults)
        if let exact = presets.first(where: { $0.style.matches(style) }) {
            return exact
        }
        if let savedID = savedPresetID(defaults: defaults),
           let saved = presets.first(where: { $0.id == savedID }) {
            return saved
        }
        return nil
    }

    func activePresetTitle(for style: SubtitleStyle, defaults: UserDefaults = ProfileSettings.current) -> String {
        let presets = allPresets(defaults: defaults)
        if let exact = presets.first(where: { $0.style.matches(style) }) {
            return exact.name
        }
        if let savedID = savedPresetID(defaults: defaults),
           let saved = presets.first(where: { $0.id == savedID }) {
            return saved.name
        }
        return L10n.string("subtitle_style_custom", fallback: "Custom")
    }

    func applyPreset(_ preset: SubtitleStylePreset, defaults: UserDefaults = ProfileSettings.current) {
        defaults.set(preset.id, forKey: SubtitleStyleKey.selectedPresetID)
        preset.style.applyToDefaults(defaults)
    }

    func suggestedCustomPresetName(defaults: UserDefaults = ProfileSettings.current) -> String {
        let existing = allPresets(defaults: defaults)
        let nextIndex = existing.count + 1
        return "\(L10n.string("subtitle_style_custom", fallback: "Custom Style")) \(nextIndex)"
    }

    @discardableResult
    func saveCurrentAsPreset(name: String? = nil, defaults: UserDefaults = ProfileSettings.current) -> SubtitleStylePreset {
        var existing = allPresets(defaults: defaults)
        let resolvedName: String
        if let name = name?.trimmingCharacters(in: .whitespacesAndNewlines), !name.isEmpty {
            resolvedName = name
        } else {
            resolvedName = suggestedCustomPresetName(defaults: defaults)
        }
        let newPreset = SubtitleStylePreset(
            id: "custom-\(UUID().uuidString)",
            name: resolvedName,
            isBuiltIn: false,
            style: SubtitleStyle.current
        )
        existing.append(newPreset)
        savePresets(existing, defaults: defaults)
        defaults.set(newPreset.id, forKey: SubtitleStyleKey.selectedPresetID)
        return newPreset
    }

    func updateCustomPresetStyle(
        id: String,
        style: SubtitleStyle,
        newName: String? = nil,
        defaults: UserDefaults = ProfileSettings.current
    ) {
        var existing = allPresets(defaults: defaults)
        guard let index = existing.firstIndex(where: { $0.id == id }) else { return }
        existing[index].style = style
        if let newName = newName?.trimmingCharacters(in: .whitespacesAndNewlines), !newName.isEmpty {
            existing[index].name = newName
        }
        savePresets(existing, defaults: defaults)
        defaults.set(id, forKey: SubtitleStyleKey.selectedPresetID)
        style.applyToDefaults(defaults)
    }

    func renameCustomPreset(id: String, newName: String, defaults: UserDefaults = ProfileSettings.current) {
        var existing = allPresets(defaults: defaults)
        guard let index = existing.firstIndex(where: { $0.id == id }) else { return }
        let trimmed = newName.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        existing[index].name = trimmed
        savePresets(existing, defaults: defaults)
    }

    func deleteCustomPreset(id: String, defaults: UserDefaults = ProfileSettings.current) {
        var existing = allPresets(defaults: defaults)
        existing.removeAll { $0.id == id }
        savePresets(existing, defaults: defaults)
        if savedPresetID(defaults: defaults) == id {
            if let first = existing.first {
                applyPreset(first, defaults: defaults)
            } else {
                defaults.removeObject(forKey: SubtitleStyleKey.selectedPresetID)
            }
        }
    }

    func movePreset(at index: Int, up: Bool, defaults: UserDefaults = ProfileSettings.current) {
        var existing = allPresets(defaults: defaults)
        let targetIndex = up ? index - 1 : index + 1
        guard existing.indices.contains(index), existing.indices.contains(targetIndex) else { return }
        existing.swapAt(index, targetIndex)
        savePresets(existing, defaults: defaults)
    }

    func resetToDefaults(defaults: UserDefaults = ProfileSettings.current) {
        defaults.removeObject(forKey: Self.defaultsSeededKey)
        defaults.removeObject(forKey: SubtitleStyleKey.customPresets)
        let seeded = allPresets(defaults: defaults)
        if let first = seeded.first {
            applyPreset(first, defaults: defaults)
        }
    }
}

enum SubtitleLanguagePreferences {
    static let disabledValues = ["System", "None"]
    static let supportedLanguages = [
        "English", "Arabic", "Bulgarian", "Chinese", "Croatian", "Czech",
        "Danish", "Dutch", "Finnish", "French", "German", "Greek", "Hebrew",
        "Hindi", "Hungarian", "Indonesian", "Italian", "Japanese", "Korean",
        "Norwegian", "Polish", "Portuguese", "Romanian", "Russian", "Spanish",
        "Swedish", "Thai", "Turkish", "Ukrainian", "Vietnamese"
    ]
    static let settingsOptions = ["System"] + supportedLanguages
    static let audioSettingsOptions = ["System", "Original"] + supportedLanguages

    private static let languageCodes: [String: [String]] = [
        "Arabic": ["ara", "ar"],
        "Bulgarian": ["bul", "bg"],
        "Chinese": ["chi", "zho", "zh", "cn"],
        "Croatian": ["hrv", "hr"],
        "Czech": ["cze", "ces", "cs"],
        "Danish": ["dan", "da"],
        "Dutch": ["dut", "nld", "nl"],
        "English": ["eng", "en"],
        "Finnish": ["fin", "fi"],
        "French": ["fre", "fra", "fr"],
        "German": ["ger", "deu", "de"],
        "Greek": ["gre", "ell", "el"],
        "Hebrew": ["heb", "he"],
        "Hindi": ["hin", "hi"],
        "Hungarian": ["hun", "hu"],
        "Indonesian": ["ind", "id"],
        "Italian": ["ita", "it"],
        "Japanese": ["jpn", "ja"],
        "Korean": ["kor", "ko"],
        "Norwegian": ["nor", "nb", "no"],
        "Polish": ["pol", "pl"],
        "Portuguese": ["por", "pt", "pob", "pb"],
        "Romanian": ["rum", "ron", "ro"],
        "Russian": ["rus", "ru"],
        "Spanish": ["spa", "es"],
        "Swedish": ["swe", "sv"],
        "Thai": ["tha", "th"],
        "Turkish": ["tur", "tr"],
        "Ukrainian": ["ukr", "uk"],
        "Vietnamese": ["vie", "vi"]
    ]

    private static let languageAliases: [String: [String]] = [
        "Chinese": ["chinese", "mandarin", "cantonese"],
        "Dutch": ["dutch", "nederlands"],
        "Greek": ["greek", "ellinika"],
        "Norwegian": ["norwegian", "norsk", "bokmal", "bokmaal"],
        "Portuguese": ["portuguese", "portugues", "português", "brazilian", "brasil"],
        "Russian": ["russian", "russkiy", "русский"],
        "Spanish": ["spanish", "espanol", "español", "castellano"],
        "Turkish": ["turkish", "turkce", "türkçe"]
    ]

    static func ordered(_ languages: [String]) -> [String] {
        var seen: Set<String> = []
        return languages
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { language in
                !language.isEmpty &&
                !isDisabled(language) &&
                seen.insert(normalized(language)).inserted
            }
    }

    static func ordered(primary: String, secondary: String, tertiary: String) -> [String] {
        // System is an explicit no-filter mode. It must override stale legacy
        // secondary/tertiary slots so every language remains visible.
        guard primary.trimmingCharacters(in: .whitespacesAndNewlines)
            .caseInsensitiveCompare("System") != .orderedSame else {
            return []
        }
        return ordered([primary, secondary, tertiary])
    }

    /// Reads the unlimited ordered selection. A present JSON `[]` is an
    /// intentional System choice; an absent/invalid value falls back to the
    /// legacy three slots so existing profiles migrate without losing choices.
    static func ordered(
        encoded: String,
        primary: String,
        secondary: String,
        tertiary: String
    ) -> [String] {
        if let decoded = decodedLanguages(encoded) {
            return decoded
        }
        return ordered(primary: primary, secondary: secondary, tertiary: tertiary)
    }

    static func orderedFromDefaults(defaults: UserDefaults = ProfileSettings.current) -> [String] {
        let encoded = defaults.string(forKey: SettingsKey.subtitleLanguages) ?? ""
        if let decoded = decodedLanguages(encoded) {
            return decoded
        }
        return ordered(
            primary: defaults.string(forKey: SettingsKey.subtitleLanguage) ?? "System",
            secondary: defaults.string(forKey: SettingsKey.subtitleLanguageSecondary) ?? "None",
            tertiary: defaults.string(forKey: SettingsKey.subtitleLanguageTertiary) ?? "None"
        )
    }

    static func encode(_ languages: [String]) -> String {
        let normalizedLanguages = ordered(languages)
        guard let data = try? JSONEncoder().encode(normalizedLanguages),
              let value = String(data: data, encoding: .utf8) else {
            return "[]"
        }
        return value
    }

    private static func decodedLanguages(_ encoded: String) -> [String]? {
        guard !encoded.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
              let data = encoded.data(using: .utf8),
              let languages = try? JSONDecoder().decode([String].self, from: data) else {
            return nil
        }
        return ordered(languages)
    }

    static func smartMatchingEnabled(defaults: UserDefaults = ProfileSettings.current) -> Bool {
        (defaults.object(forKey: SettingsKey.smartSubtitleMatching) as? Bool) ?? true
    }

    static func matches(_ languageText: String?, target: String) -> Bool {
        guard let languageText else { return false }
        let text = normalized(languageText)
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        let tokens = Set(trimmed.components(separatedBy: CharacterSet.alphanumerics.inverted).filter { !$0.isEmpty })
        let codes = exactCodes(for: target)
        if codes.contains(trimmed) { return true }
        if let primaryCode = trimmed.components(separatedBy: CharacterSet(charactersIn: "-_")).first,
           codes.contains(primaryCode) { return true }
        if !tokens.isDisjoint(with: codes) { return true }
        return aliases(for: target).contains { alias in
            text.contains(normalized(alias))
        }
    }

    static func exactCodes(for language: String) -> [String] {
        languageCodes[language] ?? [normalized(language)]
    }

    static func aliases(for language: String) -> [String] {
        [normalized(language)] + (languageAliases[language] ?? [])
    }

    static func humanLanguageName(from codeOrName: String) -> String {
        let trimmed = codeOrName.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return "" }

        if let match = supportedLanguages.first(where: { matches(trimmed, target: $0) }) {
            return match
        }

        let lower = trimmed.lowercased()
        if let locName = Locale.current.localizedString(forLanguageCode: lower) ??
                         Locale.current.localizedString(forIdentifier: lower) {
            return locName.prefix(1).uppercased() + locName.dropFirst()
        }

        if let enName = Locale(identifier: "en").localizedString(forLanguageCode: lower) ??
                        Locale(identifier: "en").localizedString(forIdentifier: lower) {
            return enName.prefix(1).uppercased() + enName.dropFirst()
        }

        return trimmed.prefix(1).uppercased() + trimmed.dropFirst()
    }

    static func mpvLanguageList(for languages: [String]) -> String? {
        var seen: Set<String> = []
        let codes = languages.flatMap { exactCodes(for: $0) }
            .filter { seen.insert($0).inserted }
        return codes.isEmpty ? nil : codes.joined(separator: ",")
    }

    static func preferredAudioLanguage(
        meta: NuvioMeta? = nil,
        defaults: UserDefaults = ProfileSettings.current
    ) -> String? {
        let preferred: String
        if let showId = meta.flatMap({ ShowAudioLanguageStore.canonicalKey(meta: $0) }),
           let showOverride = ShowAudioLanguageStore.getLanguage(for: showId, defaults: defaults) {
            preferred = showOverride
        } else {
            preferred = defaults.string(forKey: SettingsKey.audioLanguage) ?? "System"
        }
        if preferred.caseInsensitiveCompare("Original") == .orderedSame {
            if let metaLanguage = meta?.language?.trimmingCharacters(in: .whitespacesAndNewlines), !metaLanguage.isEmpty {
                return supportedLanguages.first { matches(metaLanguage, target: $0) } ?? metaLanguage
            }
            if meta?.isAnime == true {
                return "Japanese"
            }
            return nil
        }
        if !disabledValues.contains(preferred) { return preferred }

        // App language is stored as a BCP-47 tag (or empty / "System" for device).
        let appLanguage = AppLanguage.fromStored(defaults.string(forKey: SettingsKey.language))
        if let name = appLanguage.audioLanguageName, supportedLanguages.contains(name) {
            return name
        }

        return Locale.preferredLanguages.lazy.compactMap { identifier in
            let normalizedIdentifier = normalized(identifier)
            let pieces = normalizedIdentifier.components(separatedBy: CharacterSet(charactersIn: "-_"))
            let code = pieces.first ?? normalizedIdentifier
            return supportedLanguages.first { exactCodes(for: $0).contains(code) }
        }.first
    }

    private static func isDisabled(_ value: String) -> Bool {
        disabledValues.contains { $0.caseInsensitiveCompare(value) == .orderedSame }
    }

    private static func normalized(_ value: String) -> String {
        value
            .folding(options: [.caseInsensitive, .diacriticInsensitive], locale: .current)
            .lowercased()
    }
}

enum AISubtitleProvider: String, CaseIterable, Identifiable {
    case gemini = "Gemini"
    case openRouter = "OpenRouter"

    var id: String { rawValue }

    var setupSubtitle: String {
        switch self {
        case .gemini:
            return L10n.string(
                "settings_ai_subtitles_gemini_setup_subtitle",
                fallback: "Create a free key in Google AI Studio; it stays on this Apple TV"
            )
        case .openRouter:
            return L10n.string(
                "settings_ai_subtitles_openrouter_setup_subtitle",
                fallback: "Use an OpenRouter API key; it stays on this Apple TV"
            )
        }
    }

    var apiKeyTitle: String {
        L10n.format("settings_ai_subtitles_provider_api_key_title", fallback: "%@ API Key", rawValue)
    }

    var apiKeySubtitle: String {
        switch self {
        case .gemini:
            return L10n.string(
                "settings_ai_subtitles_gemini_api_key_subtitle",
                fallback: "Paste a Google AI Studio API key"
            )
        case .openRouter:
            return L10n.string(
                "settings_ai_subtitles_openrouter_api_key_subtitle",
                fallback: "Paste an OpenRouter API key"
            )
        }
    }

    var privacyDescription: String {
        switch self {
        case .gemini:
            return L10n.string(
                "settings_ai_subtitles_gemini_privacy_description",
                fallback: "Gemini translates subtitle cues as they appear. Your key and subtitle text are sent directly to Google only while this feature is on."
            )
        case .openRouter:
            return L10n.string(
                "settings_ai_subtitles_openrouter_privacy_description",
                fallback: "OpenRouter translates subtitle cues as they appear. Your key and subtitle text are sent to OpenRouter and its selected model provider only while this feature is on."
            )
        }
    }
}

/// Device-local AI subtitle credentials. The non-secret enable/model
/// preferences remain per-profile in UserDefaults, while keys stay in Keychain.
enum AISubtitleKeyStore {
    private static let service = "com.nuvio.tv.ai-subtitles"

    static func apiKey(
        for provider: AISubtitleProvider,
        defaults: UserDefaults = ProfileSettings.current
    ) -> String {
        let scope = ProfileSettings.activeProfileScope
        if provider == .gemini {
            return migrateLegacyKey(from: defaults, profileScope: scope)
        }
        return read(for: provider, profileScope: scope) ?? ""
    }

    /// Moves a legacy UserDefaults key into the named Keychain namespace. This
    /// is internal so profile activation can migrate the pre-profile store
    /// before its value is intentionally excluded from settings copies.
    @discardableResult
    static func migrateLegacyKey(from defaults: UserDefaults, profileScope: String) -> String {
        if let secureKey = read(for: .gemini, profileScope: profileScope) {
            defaults.removeObject(forKey: SettingsKey.aiSubtitlesGeminiAPIKey)
            return secureKey
        }
        let legacyKey = (defaults.string(forKey: SettingsKey.aiSubtitlesGeminiAPIKey) ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !legacyKey.isEmpty else { return "" }
        guard save(legacyKey, for: .gemini, profileScope: profileScope) else { return "" }
        defaults.removeObject(forKey: SettingsKey.aiSubtitlesGeminiAPIKey)
        return legacyKey
    }

    @discardableResult
    static func save(
        _ key: String,
        for provider: AISubtitleProvider,
        profileScope: String = ProfileSettings.activeProfileScope
    ) -> Bool {
        let trimmed = key.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            return remove(for: provider, profileScope: profileScope)
        }

        let data = Data(trimmed.utf8)
        var addQuery = keychainQuery(for: provider, profileScope: profileScope)
        addQuery[kSecAttrAccessible as String] = kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly
        addQuery[kSecValueData as String] = data
        let status = SecItemAdd(addQuery as CFDictionary, nil)
        if status == errSecDuplicateItem {
            return SecItemUpdate(
                keychainQuery(for: provider, profileScope: profileScope) as CFDictionary,
                [kSecValueData as String: data] as CFDictionary
            ) == errSecSuccess
        }
        return status == errSecSuccess
    }

    @discardableResult
    static func remove(
        for provider: AISubtitleProvider,
        profileScope: String = ProfileSettings.activeProfileScope
    ) -> Bool {
        let status = SecItemDelete(keychainQuery(for: provider, profileScope: profileScope) as CFDictionary)
        return status == errSecSuccess || status == errSecItemNotFound
    }

    @discardableResult
    static func remove(profileScope: String = ProfileSettings.activeProfileScope) -> Bool {
        AISubtitleProvider.allCases.reduce(true) { result, provider in
            remove(for: provider, profileScope: profileScope) && result
        }
    }

    private static func read(for provider: AISubtitleProvider, profileScope: String) -> String? {
        var query = keychainQuery(for: provider, profileScope: profileScope)
        query[kSecReturnData as String] = kCFBooleanTrue
        query[kSecMatchLimit as String] = kSecMatchLimitOne
        var item: CFTypeRef?
        guard SecItemCopyMatching(query as CFDictionary, &item) == errSecSuccess,
              let data = item as? Data else { return nil }
        return String(data: data, encoding: .utf8)?
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private static func keychainQuery(
        for provider: AISubtitleProvider,
        profileScope: String
    ) -> [String: Any] {
        [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: "\(provider.rawValue.lowercased()).\(profileScope)"
        ]
    }
}

/// Runtime configuration shared by the settings screen and the player cue
/// translator. The key remains device-local; it is never included in profile
/// sync payloads.
struct AISubtitleTranslationSettings: Equatable {
    static let defaultModel = "gemini-3.6-flash"
    /// Gemini and Gemma models that support the Gemini API's
    /// `generateContent` endpoint used for subtitle translation.
    static let availableModels = [
        "gemini-3.6-flash",
        "gemini-3.5-flash-lite",
        "gemini-3.1-flash-lite",
        "gemma-4-26b-a4b-it",
        "gemma-4-31b-it"
    ]
    static let defaultOpenRouterModel = "google/gemini-2.5-flash"

    let isEnabled: Bool
    let provider: AISubtitleProvider
    let apiKey: String
    let model: String
    let targetLanguage: String
    let autoSelect: Bool
    let stripHearingImpaired: Bool

    static func current(defaults: UserDefaults = ProfileSettings.current) -> Self {
        let preferredLanguage = SubtitleLanguagePreferences.orderedFromDefaults(defaults: defaults).first
            ?? SubtitleLanguagePreferences.preferredAudioLanguage(defaults: defaults)
            ?? "English"
        let configuredTarget = defaults.string(forKey: SettingsKey.aiSubtitlesTargetLanguage) ?? "Preferred Subtitle"
        let provider = AISubtitleProvider(
            rawValue: defaults.string(forKey: SettingsKey.aiSubtitlesProvider) ?? ""
        ) ?? .gemini
        let model: String
        switch provider {
        case .gemini:
            model = normalizedModel(defaults.string(forKey: SettingsKey.aiSubtitlesGeminiModel))
        case .openRouter:
            model = normalizedOpenRouterModel(defaults.string(forKey: SettingsKey.aiSubtitlesOpenRouterModel))
        }
        return Self(
            isEnabled: defaults.bool(forKey: SettingsKey.aiSubtitlesEnabled),
            provider: provider,
            apiKey: AISubtitleKeyStore.apiKey(for: provider, defaults: defaults),
            model: model,
            targetLanguage: configuredTarget == "Preferred Subtitle" ? preferredLanguage : configuredTarget,
            autoSelect: defaults.object(forKey: SettingsKey.aiSubtitlesAutoSelect) as? Bool ?? true,
            stripHearingImpaired: defaults.object(forKey: SettingsKey.aiSubtitlesStripHearingImpaired) as? Bool ?? true
        )
    }

    static func normalizedModel(_ storedModel: String?) -> String {
        let model = (storedModel ?? defaultModel).trimmingCharacters(in: .whitespacesAndNewlines)
        return availableModels.contains(model) ? model : defaultModel
    }

    static func normalizedOpenRouterModel(_ storedModel: String?) -> String {
        let model = (storedModel ?? defaultOpenRouterModel).trimmingCharacters(in: .whitespacesAndNewlines)
        return model.isEmpty ? defaultOpenRouterModel : model
    }

    var cacheModelIdentifier: String { "\(provider.rawValue):\(model)" }
}

enum SettingsAccent: String, CaseIterable, Identifiable {
    case white = "White"
    case sky = "Sky"
    case emerald = "Emerald"
    case rose = "Rose"
    case amber = "Amber"
    case violet = "Violet"

    var id: String { rawValue }

    var color: Color {
        switch self {
        case .white: return .white
        case .sky: return Color(red: 0.25, green: 0.62, blue: 0.96)
        case .emerald: return Color(red: 0.19, green: 0.78, blue: 0.48)
        case .rose: return Color(red: 0.95, green: 0.31, blue: 0.48)
        case .amber: return Color(red: 0.97, green: 0.72, blue: 0.26)
        case .violet: return Color(red: 0.60, green: 0.45, blue: 0.95)
        }
    }

    static func color(for rawValue: String) -> Color {
        SettingsAccent(rawValue: rawValue)?.color ?? SettingsAccent.white.color
    }
}

/// Dark background tints for the app body. Distinct from `SettingsAccent`
/// (which are bright focus/accent colors unsuitable as a full-screen fill).
enum SettingsBackground: String, CaseIterable, Identifiable {
    case charcoal = "Charcoal"
    case black = "Black"
    case midnight = "Midnight"
    case forest = "Forest"
    case plum = "Plum"
    case slate = "Slate"
    case wine = "Wine"
    case ocean = "Ocean"
    case indigo = "Indigo"
    case crimson = "Crimson"
    case rust = "Rust"
    case teal = "Teal"

    var id: String { rawValue }

    var color: Color {
        switch self {
        case .charcoal: return Color(red: 13.0 / 255.0, green: 13.0 / 255.0, blue: 13.0 / 255.0)
        case .black: return .black
        case .midnight: return Color(red: 0.020, green: 0.030, blue: 0.065)
        case .forest: return Color(red: 0.018, green: 0.048, blue: 0.036)
        case .plum: return Color(red: 0.045, green: 0.020, blue: 0.060)
        case .slate: return Color(red: 0.040, green: 0.046, blue: 0.056)
        case .wine: return Color(red: 0.110, green: 0.015, blue: 0.040)
        case .ocean: return Color(red: 0.012, green: 0.055, blue: 0.085)
        case .indigo: return Color(red: 0.035, green: 0.028, blue: 0.100)
        case .crimson: return Color(red: 0.130, green: 0.012, blue: 0.025)
        case .rust: return Color(red: 0.100, green: 0.040, blue: 0.012)
        case .teal: return Color(red: 0.012, green: 0.070, blue: 0.065)
        }
    }

    /// A slightly brighter swatch fill so dark tints stay visible in the picker.
    var swatchColor: Color {
        switch self {
        case .charcoal: return Color(red: 0.16, green: 0.16, blue: 0.18)
        case .black: return Color(red: 0.07, green: 0.07, blue: 0.07)
        case .midnight: return Color(red: 0.12, green: 0.18, blue: 0.34)
        case .forest: return Color(red: 0.10, green: 0.28, blue: 0.20)
        case .plum: return Color(red: 0.26, green: 0.12, blue: 0.34)
        case .slate: return Color(red: 0.24, green: 0.27, blue: 0.32)
        case .wine: return Color(red: 0.52, green: 0.09, blue: 0.20)
        case .ocean: return Color(red: 0.09, green: 0.36, blue: 0.50)
        case .indigo: return Color(red: 0.24, green: 0.19, blue: 0.56)
        case .crimson: return Color(red: 0.64, green: 0.11, blue: 0.14)
        case .rust: return Color(red: 0.56, green: 0.27, blue: 0.09)
        case .teal: return Color(red: 0.07, green: 0.42, blue: 0.39)
        }
    }

    static func color(for rawValue: String) -> Color {
        SettingsBackground(rawValue: rawValue)?.color ?? SettingsBackground.charcoal.color
    }
}

/// True while focus is still in the sidebar and hasn't entered the detail pane.
/// Every focusable detail row reads this and disables itself when set, so the
/// only focusable target on a right-press is the pane's first row (which opts out
/// via `.settingsEntryAnchor()`). That makes "right" always land on the first row
/// instead of whichever row happens to line up with the sidebar pill's height.
private struct SettingsEntryLockedKey: EnvironmentKey {
    static let defaultValue = false
}

extension EnvironmentValues {
    var settingsEntryLocked: Bool {
        get { self[SettingsEntryLockedKey.self] }
        set { self[SettingsEntryLockedKey.self] = newValue }
    }
}

extension View {
    /// Marks the detail pane's first row so it stays focusable while the rest of
    /// the pane is entry-locked — i.e. the row a right-press should land on.
    func settingsEntryAnchor() -> some View {
        environment(\.settingsEntryLocked, false)
    }

    /// Conditional variant: anchors only when `isActive`, otherwise leaves the
    /// inherited lock untouched. For panes whose first focusable row changes
    /// (e.g. Account & Profiles swaps its first row for a non-focusable info
    /// row when signed out).
    func settingsEntryAnchor(_ isActive: Bool) -> some View {
        modifier(ConditionalSettingsEntryAnchor(isActive: isActive))
    }

    /// Disables this focusable row whenever the pane is entry-locked (focus still
    /// in the sidebar), reading the flag from the environment so call sites don't
    /// have to thread it. Composes with any other `.disabled(...)` on the row.
    func entryLockable() -> some View {
        modifier(EntryLockable())
    }
}

private struct EntryLockable: ViewModifier {
    @Environment(\.settingsEntryLocked) private var locked
    func body(content: Content) -> some View {
        content.disabled(locked)
    }
}

private struct ConditionalSettingsEntryAnchor: ViewModifier {
    let isActive: Bool
    @Environment(\.settingsEntryLocked) private var locked
    func body(content: Content) -> some View {
        content.environment(\.settingsEntryLocked, isActive ? false : locked)
    }
}

private enum LanguagePickerKind: Hashable {
    case appLanguage
    case audio
    case subtitles
}

struct SettingsView: View {
    @Binding var selectedCategory: SettingsCategory
    let activeProfile: Profile?
    let accountEmail: String?
    let isAuthenticated: Bool
    let sessionNeedsReauthentication: Bool
    let onChangeProfileName: ((String, String) -> Void)?
    let onChangeProfileAvatar: ((String, String) -> Void)?
    let onChangeProfileBackground: ((String, String?, String?) -> Void)?
    let onChangeProfilePin: ((String, String?, String?) async -> Bool)?
    let onVerifyProfilePin: ((String, String) async -> Bool)?
    let onSignIn: (() -> Void)?
    let onSignOut: (() -> Void)?

    init(
        selectedCategory: Binding<SettingsCategory>,
        activeProfile: Profile? = nil,
        accountEmail: String? = nil,
        isAuthenticated: Bool = false,
        sessionNeedsReauthentication: Bool = false,
        onChangeProfileName: ((String, String) -> Void)? = nil,
        onChangeProfileAvatar: ((String, String) -> Void)? = nil,
        onChangeProfileBackground: ((String, String?, String?) -> Void)? = nil,
        onChangeProfilePin: ((String, String?, String?) async -> Bool)? = nil,
        onVerifyProfilePin: ((String, String) async -> Bool)? = nil,
        onSignIn: (() -> Void)? = nil,
        onSignOut: (() -> Void)? = nil
    ) {
        self._selectedCategory = selectedCategory
        self.activeProfile = activeProfile
        self.accountEmail = accountEmail
        self.isAuthenticated = isAuthenticated
        self.sessionNeedsReauthentication = sessionNeedsReauthentication
        self.onChangeProfileName = onChangeProfileName
        self.onChangeProfileAvatar = onChangeProfileAvatar
        self.onChangeProfileBackground = onChangeProfileBackground
        self.onChangeProfilePin = onChangeProfilePin
        self.onVerifyProfilePin = onVerifyProfilePin
        self.onSignIn = onSignIn
        self.onSignOut = onSignOut
    }

    @State private var presentedLanguagePicker: LanguagePickerKind?
    @State private var presentedProfilePinMode: ProfilePinSheetMode?
    @FocusState private var focusedCategory: SettingsCategory?
    @FocusState private var focusedLanguagePreference: LanguagePickerKind?
    /// Whether focus has entered the current category's detail pane at least once.
    /// The entry lock (land on the first row) only fires on the first entry; after
    /// that, re-entry stays unlocked so the detail's own focus restoration can
    /// return to the last row instead of being blocked by the lock.
    @State private var detailVisited = false
    @AppStorage(SettingsKey.theme) private var theme = SettingsAccent.white.rawValue
    @AppStorage(SettingsKey.amoled) private var amoled = false
    @AppStorage(SettingsKey.bodyColor) private var bodyColor = SettingsBackground.charcoal.rawValue
    @AppStorage(SettingsKey.font) private var appFont = "Inter"
    /// BCP-47 app UI language tag; empty string means System default.
    @AppStorage(SettingsKey.language) private var appLanguageTag = ""
    @AppStorage(SettingsKey.audioLanguage) private var audioLanguage = "System"
    @AppStorage(SettingsKey.subtitleLanguages) private var subtitleLanguages = ""
    @AppStorage(SettingsKey.subtitleLanguage) private var subtitleLanguage = "System"
    @AppStorage(SettingsKey.subtitleLanguageSecondary) private var subtitleLanguageSecondary = "None"
    @AppStorage(SettingsKey.subtitleLanguageTertiary) private var subtitleLanguageTertiary = "None"

    private let pickerLanguages = SubtitleLanguagePreferences.settingsOptions
    /// Display labels for the app-language panel (System first, then native endonyms).
    private var appLanguagePickerOptions: [String] {
        AppLanguage.pickerLanguages.map { language in
            language == .system ? "System" : language.nativeDisplayName
        }
    }

    private var accentColor: Color {
        SettingsAccent.color(for: theme)
    }

    var body: some View {
        ZStack {
            HStack(spacing: 0) {
                categoryGrid
                    .focusSection()
                    .defaultFocusIfAvailable($focusedCategory, selectedCategory)
                    .onChange(of: focusedCategory) { _, newValue in
                        // focusedCategory goes nil exactly when focus leaves the
                        // sidebar for the detail pane — record that so re-entry is
                        // no longer locked to the first row.
                        if newValue == nil { detailVisited = true }
                    }
                    .onChange(of: selectedCategory) { oldCat, newCat in
                        TVHomeDebugTrace.log("settings.selectedCategory changed from \(oldCat.rawValue) to \(newCat.rawValue)")
                        // A newly opened category should lock to its first row again.
                        detailVisited = false
                    }

                Group {
                    if selectedCategory == .subtitles {
                        VStack(alignment: .leading, spacing: 28) {
                            selectedCategoryHeader
                            SubtitleStyleSettingsView(accentColor: accentColor)
                        }
                        .padding(.leading, 44)
                        .padding(.trailing, 72)
                        // No bottom padding: the scrolling controls run all the way
                        // to the screen edge (the preview above stays pinned), so the
                        // list isn't cut short with dead space below it.
                        .padding(.top, 56)
                    } else {
                        ScrollView {
                            VStack(alignment: .leading, spacing: 28) {
                                selectedCategoryHeader
                                selectedCategoryContent
                            }
                            .padding(.leading, 44)
                            .padding(.trailing, 72)
                            .padding(.vertical, 56)
                        }
                        // Every category shares this one ScrollView, so without a
                        // per-category identity SwiftUI reuses it and carries the
                        // previous category's scroll offset into the next one.
                        // (Subtitles looked right only because it lives in the
                        // other branch, which is rebuilt on the way in.)
                        .id(selectedCategory)
                    }
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .focusSection()
                // Lock every detail row except the first while focus is still in
                // the sidebar and this category hasn't been entered yet, so the
                // first right-press lands on the first row regardless of which pill
                // it came from. Cleared once focus enters so re-entry isn't blocked.
                .environment(\.settingsEntryLocked, focusedCategory != nil && !detailVisited)
                // Back from a setting returns focus to its selected category;
                // Back from the category list remains handled by the TabView.
                .onExitCommand { focusedCategory = selectedCategory }
            }
            .disabled(presentedLanguagePicker != nil || presentedProfilePinMode != nil)
            .allowsHitTesting(presentedLanguagePicker == nil && presentedProfilePinMode == nil)

            if let picker = presentedLanguagePicker {
                LanguagePickerWindow(
                    title: languagePickerTitle(picker),
                    subtitle: languagePickerSubtitle(picker),
                    systemImage: languagePickerSystemImage(picker),
                    selection: languagePickerSelection(picker),
                    languages: picker == .appLanguage ? appLanguagePickerOptions : (picker == .audio ? SubtitleLanguagePreferences.audioSettingsOptions : pickerLanguages),
                    allowsMultiple: picker == .subtitles,
                    accentColor: accentColor
                ) {
                    dismissLanguagePicker(picker)
                }
                .id(picker)
                .transition(.opacity.combined(with: .scale(scale: 0.96)))
                .zIndex(1)
            }

            if let mode = presentedProfilePinMode, let profile = activeProfile {
                ProfilePinManagementView(
                    mode: mode,
                    profileName: ProfileDisplayName.resolve(
                        profile: profile,
                        settingsName: profile.name
                    ),
                    onVerify: { pin in
                        await onVerifyProfilePin?(profile.id, pin) == true
                    },
                    onSave: { pin, currentPin in
                        await onChangeProfilePin?(profile.id, pin, currentPin) == true
                    },
                    onDismiss: {
                        presentedProfilePinMode = nil
                    }
                )
                .transition(.opacity)
                .zIndex(2)
                .onExitCommand {
                    presentedProfilePinMode = nil
                }
            }
        }
        .background(Color.nuvioBackground(amoled: amoled, body: bodyColor).ignoresSafeArea())
        .animation(.easeOut(duration: 0.16), value: presentedLanguagePicker != nil)
        .animation(.easeInOut(duration: 0.18), value: presentedProfilePinMode != nil)
        .onAppear {
            TVHomeDebugTrace.log("settings.appear category=\(selectedCategory.rawValue)")
        }
        .onDisappear {
            TVHomeDebugTrace.log("settings.disappear")
            NuvioSyncManager.current?.flushPendingPushes()
        }
    }

    private var audioLanguageSelection: Binding<[String]> {
        Binding(
            get: {
                (SubtitleLanguagePreferences.supportedLanguages.contains(audioLanguage) || audioLanguage.caseInsensitiveCompare("Original") == .orderedSame)
                    ? [audioLanguage]
                    : []
            },
            set: { selection in
                audioLanguage = selection.first ?? "System"
            }
        )
    }

    private var subtitleLanguageSelection: Binding<[String]> {
        Binding(
            get: {
                SubtitleLanguagePreferences.ordered(
                    encoded: subtitleLanguages,
                    primary: subtitleLanguage,
                    secondary: subtitleLanguageSecondary,
                    tertiary: subtitleLanguageTertiary
                )
            },
            set: { selection in
                let ordered = SubtitleLanguagePreferences.ordered(selection)
                subtitleLanguages = SubtitleLanguagePreferences.encode(ordered)

                // Mirror the first three choices for older synced app builds.
                subtitleLanguage = ordered.indices.contains(0) ? ordered[0] : "System"
                subtitleLanguageSecondary = ordered.indices.contains(1) ? ordered[1] : "None"
                subtitleLanguageTertiary = ordered.indices.contains(2) ? ordered[2] : "None"
            }
        )
    }

    /// Single-select binding for app UI language. Empty selection = System (same
    /// contract LanguagePickerWindow uses for Preferred Audio).
    private var appLanguageSelection: Binding<[String]> {
        Binding(
            get: {
                let language = AppLanguage.fromStored(appLanguageTag)
                return language == .system ? [] : [language.nativeDisplayName]
            },
            set: { selection in
                let choice = selection.first
                let language: AppLanguage
                if choice == nil || choice == "System" {
                    language = .system
                } else if let match = AppLanguage.pickerLanguages.first(where: {
                    $0 != .system && $0.nativeDisplayName == choice
                }) {
                    language = match
                } else {
                    language = .system
                }
                appLanguageTag = language.tag
                AppLocaleManager.shared.setLanguage(language, persist: true)
            }
        )
    }

    private func languagePickerTitle(_ picker: LanguagePickerKind) -> String {
        switch picker {
        case .appLanguage:
            return L10n.string("appearance_language", fallback: "App Language")
        case .audio:
            return L10n.string("tvos_playback_preferred_audio", fallback: "Preferred Audio")
        case .subtitles:
            return L10n.string("tvos_playback_preferred_subtitle", fallback: "Preferred Subtitle")
        }
    }

    private func languagePickerSubtitle(_ picker: LanguagePickerKind) -> String {
        switch picker {
        case .appLanguage:
            return L10n.string(
                "appearance_language_subtitle",
                fallback: "Override system language"
            )
        case .audio:
            return L10n.string(
                "tvos_playback_choose_audio",
                fallback: "Choose the default audio language."
            )
        case .subtitles:
            return L10n.string(
                "tvos_playback_choose_subtitle",
                fallback: "Choose any languages in priority order. System shows every language in the player."
            )
        }
    }

    private func languagePickerSystemImage(_ picker: LanguagePickerKind) -> String {
        switch picker {
        case .appLanguage: return "globe"
        case .audio: return "speaker.wave.2.fill"
        case .subtitles: return "captions.bubble.fill"
        }
    }

    private func languagePickerSelection(_ picker: LanguagePickerKind) -> Binding<[String]> {
        switch picker {
        case .appLanguage: return appLanguageSelection
        case .audio: return audioLanguageSelection
        case .subtitles: return subtitleLanguageSelection
        }
    }

    private func dismissLanguagePicker(_ picker: LanguagePickerKind) {
        presentedLanguagePicker = nil
        DispatchQueue.main.async {
            focusedLanguagePreference = picker
        }
    }

    private var categoryGrid: some View {
        VStack(alignment: .leading, spacing: 24) {
            Text(L10n.string("nav_settings", fallback: "Settings"))
                .font(.system(size: 42, weight: .bold))
                .foregroundColor(.white)
                .padding(.leading, 10)

            VStack(alignment: .leading, spacing: 14) {
                ForEach(SettingsCategory.allCases) { category in
                    let isSelectedCategory = selectedCategory == category
                    let isFocusedCategory = focusedCategory == category
                    // Fixes "left out of the detail pane flashes the wrong pill":
                    // while focus is in the detail pane (focusedCategory == nil), only
                    // the open category stays focusable. A left-press is directional
                    // and tvOS lands on the geometric nearest *focusable* pill, so
                    // with a single candidate it goes straight to the open one — no
                    // wrong pill ever receives focus, so none can flash. All pills
                    // become focusable again the moment focus is back in the sidebar,
                    // so up/down still moves between every category. Disabling is safe
                    // visually here: PosterCardButtonStyle ignores isEnabled, so a
                    // non-focusable pill looks identical to a focusable one.
                    let isFocusable = isSelectedCategory || focusedCategory != nil

                    SettingsCategoryPill(
                        category: category,
                        isSelected: isSelectedCategory,
                        isFocused: isFocusedCategory,
                        accentColor: accentColor
                    ) {
                        selectedCategory = category
                    }
                    .focused($focusedCategory, equals: category)
                    .disabled(!isFocusable)
                }
            }
        }
        .padding(.leading, 58)
        .padding(.trailing, 22)
        .padding(.top, 58)
        .frame(width: 510)
        .frame(maxHeight: .infinity, alignment: .topLeading)
    }

    private var selectedCategoryHeader: some View {
        SettingsDetailHeader(
            title: selectedCategory.title,
            subtitle: selectedCategory.subtitle,
            iconName: selectedCategory.iconName,
            accentColor: accentColor
        )
    }

    @ViewBuilder
    private var selectedCategoryContent: some View {
        switch selectedCategory {
        case .account:
            AccountSettingsView(
                accentColor: accentColor,
                activeProfile: activeProfile,
                accountEmail: accountEmail,
                isAuthenticated: isAuthenticated,
                sessionNeedsReauthentication: sessionNeedsReauthentication,
                onChangeProfileName: onChangeProfileName,
                onChangeProfileAvatar: onChangeProfileAvatar,
                onChangeProfileBackground: onChangeProfileBackground,
                onChangeProfilePin: onChangeProfilePin,
                onVerifyProfilePin: onVerifyProfilePin,
                onSignIn: onSignIn,
                onSignOut: onSignOut,
                onPresentPin: { mode in
                    presentedProfilePinMode = mode
                }
            )
        case .appearance:
            AppearanceSettingsView(
                accentColor: accentColor,
                languageFocus: $focusedLanguagePreference,
                onAppLanguage: {
                    focusedLanguagePreference = .appLanguage
                    presentedLanguagePicker = .appLanguage
                }
            )
        case .layout:
            LayoutDiscoverySettingsView(accentColor: accentColor)
        case .integrations:
            IntegrationSettingsView(
                accentColor: accentColor,
                profileID: activeProfile?.id
            )
                .id(activeProfile?.id ?? "none")
        case .playback:
            PlaybackSettingsView(
                accentColor: accentColor,
                languageFocus: $focusedLanguagePreference,
                onAudioLanguage: {
                    focusedLanguagePreference = .audio
                    presentedLanguagePicker = .audio
                },
                onSubtitleLanguages: {
                    focusedLanguagePreference = .subtitles
                    presentedLanguagePicker = .subtitles
                }
            )
        case .subtitles:
            SubtitleStyleSettingsView(accentColor: accentColor)
        case .advanced:
            AdvancedSettingsView(accentColor: accentColor)
        case .about:
            AboutSettingsView(accentColor: accentColor)
        }
    }
}

private struct SettingsCategoryPill: View {
    let category: SettingsCategory
    let isSelected: Bool
    let isFocused: Bool
    let accentColor: Color
    let action: () -> Void

    var body: some View {
        Button(action: action) {
            HStack(spacing: 22) {
                Image(systemName: category.iconName)
                    .font(.system(size: 36, weight: .semibold))
                    .foregroundColor(iconColor)
                    .frame(width: 48, height: 48)

                Text(category.title)
                    .font(.system(size: 30, weight: .bold))
                    .foregroundColor(textColor)
                    .lineLimit(1)
                    .minimumScaleFactor(0.68)
                    .frame(maxWidth: .infinity, alignment: .leading)
            }
            .padding(.horizontal, 26)
            .frame(width: 430, height: 92, alignment: .leading)
            .modifier(SettingsCategoryPillBackground(isSelected: isSelected, isFocused: isFocused))
            .overlay(
                Capsule()
                    .strokeBorder(borderColor, lineWidth: isFocused ? AppFocusOutline.width : 1)
            )
            .animation(.easeOut(duration: 0.14), value: isSelected)
        }
        .buttonStyle(PosterCardButtonStyle())
        .focusEffectDisabledIfAvailable()
        .scaleEffect(isFocused ? 1.06 : 1.0)
        .zIndex(isFocused ? 1 : 0)
        .animation(.easeOut(duration: 0.14), value: isFocused)
    }

    private var iconColor: Color {
        if isFocused { return .black }
        return isSelected ? .white.opacity(0.90) : .white.opacity(0.78)
    }

    private var textColor: Color {
        if isFocused { return .black }
        return isSelected ? .white.opacity(0.96) : .white.opacity(0.82)
    }

    private var borderColor: Color {
        if isFocused {
            return .clear
        }
        return Color.white.opacity(isSelected ? 0.14 : 0.07)
    }
}

private struct SettingsCategoryPillBackground: ViewModifier {
    let isSelected: Bool
    let isFocused: Bool

    @ViewBuilder
    func body(content: Content) -> some View {
        if isFocused {
            content.background(Color.white, in: Capsule())
        } else if isSelected {
            content.background(Color.white.opacity(0.14), in: Capsule())
        } else {
            content.background(Color.white.opacity(0.06), in: Capsule())
        }
    }
}

private struct AccountSettingsView: View {
    let accentColor: Color
    let activeProfile: Profile?
    let accountEmail: String?
    let isAuthenticated: Bool
    let sessionNeedsReauthentication: Bool
    let onChangeProfileName: ((String, String) -> Void)?
    let onChangeProfileAvatar: ((String, String) -> Void)?
    let onChangeProfileBackground: ((String, String?, String?) -> Void)?
    let onChangeProfilePin: ((String, String?, String?) async -> Bool)?
    let onVerifyProfilePin: ((String, String) async -> Bool)?
    let onSignIn: (() -> Void)?
    let onSignOut: (() -> Void)?
    let onPresentPin: (ProfilePinSheetMode) -> Void

    @AppStorage(SettingsKey.profileName) private var profileName = "Nuvio User"
    @AppStorage(SettingsKey.profileAutoSelectLast, store: .standard) private var autoSelectLastProfile = true
    @AppStorage(SettingsKey.profileRequireSelectionAfterBackground, store: .standard)
    private var requireProfileSelectionAfterBackground = false
    @AppStorage(SettingsKey.accountSyncWatchState) private var syncWatchState = true
    @AppStorage(SettingsKey.iCloudSyncEnabled, store: .standard) private var iCloudSyncEnabled = false
    @ObservedObject private var iCloudSyncManager = ICloudSettingsSyncManager.shared
    @State private var editableProfileName = ""
    @State private var showingAvatarPicker = false
    @State private var showingBackgroundPicker = false

    private var accountStatusText: String {
        guard isAuthenticated else {
            return L10n.string("tvos_account_not_signed_in", fallback: "Not Signed In")
        }
        if sessionNeedsReauthentication {
            return L10n.string(
                "tvos_account_session_expired",
                fallback: "Signed In — session expired, sign in again to resume syncing"
            )
        }
        return L10n.string("tvos_account_signed_in", fallback: "Signed In")
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 22) {
            SettingsGroup(
                title: L10n.string("settings_profiles", fallback: "Profiles"),
                subtitle: L10n.string(
                    "profile_subtitle",
                    fallback: "Manage user profiles for this account"
                )
            ) {
                HStack(spacing: 22) {
                    ProfileAvatarView(
                        avatarId: activeProfile?.avatarId ?? ProfileAvatarCatalog.defaultId,
                        size: 84
                    )

                    VStack(alignment: .leading, spacing: 8) {
                        Text(displayProfileName)
                            .font(.system(size: 28, weight: .bold))
                            .foregroundColor(.white)
                            .lineLimit(1)

                        Text(
                            isPinProtected
                                ? L10n.string(
                                    "profile_pin_enabled_subtitle",
                                    fallback: "This profile requires a 4-digit PIN before switching."
                                )
                                : L10n.string(
                                    "profile_pin_disabled_subtitle",
                                    fallback: "Set a 4-digit PIN to lock this profile."
                                )
                        )
                            .font(.system(size: 19, weight: .medium))
                            .foregroundColor(.white.opacity(0.58))
                    }

                    Spacer()
                }
                .padding(.bottom, 6)

                // First focusable row in the pane carries the entry anchor —
                // without one the entry lock leaves the pane unenterable.
                SettingsTextFieldRow(
                    title: L10n.string("profile_name_placeholder", fallback: "Profile name"),
                    subtitle: L10n.string(
                        "tvos_profile_name_subtitle",
                        fallback: "Change the name shown for this profile"
                    ),
                    placeholder: L10n.string("profile_name_placeholder", fallback: "Profile name"),
                    text: $editableProfileName,
                    fieldWidth: 340,
                    centerDisplayText: true,
                    onCommit: saveProfileName
                )
                .settingsEntryAnchor(activeProfile != nil && onChangeProfileName != nil)
                .disabled(activeProfile == nil || onChangeProfileName == nil)

                SettingsActionRow(
                    title: L10n.string("profile_choose_avatar", fallback: "Choose Avatar"),
                    subtitle: L10n.string(
                        "tvos_profile_avatar_subtitle",
                        fallback: "Choose the avatar shown across Nuvio"
                    ),
                    value: L10n.string("profile_edit_label", fallback: "Edit"),
                    accentColor: accentColor
                ) {
                    showingAvatarPicker = true
                }
                .opacity(activeProfile != nil && onChangeProfileAvatar != nil ? 1 : 0.46)
                .disabled(activeProfile == nil || onChangeProfileAvatar == nil)

                SettingsActionRow(
                    title: L10n.string("profile_background_title", fallback: "Profile Background"),
                    subtitle: L10n.string(
                        "profile_background_subtitle",
                        fallback: "Personalize profile selection with supporter animated backgrounds or custom URLs"
                    ),
                    value: currentBackgroundLabel,
                    accentColor: accentColor
                ) {
                    showingBackgroundPicker = true
                }
                .opacity(activeProfile != nil && onChangeProfileBackground != nil ? 1 : 0.46)
                .disabled(activeProfile == nil || onChangeProfileBackground == nil)

                SettingsToggleRow(
                    title: L10n.string("profile_pin_title", fallback: "Profile PIN lock"),
                    subtitle: L10n.string(
                        "profile_pin_enabled_subtitle",
                        fallback: "This profile requires a 4-digit PIN before switching."
                    ),
                    isOn: pinProtectionBinding,
                    accentColor: accentColor
                )
                .settingsEntryAnchor(activeProfile == nil || onChangeProfileName == nil)
                .opacity(canManagePin ? 1 : 0.46)
                .disabled(!canManagePin)

                SettingsToggleRow(
                    title: L10n.string(
                        "advanced_remember_last_profile",
                        fallback: "Remember Last Profile"
                    ),
                    subtitle: L10n.string(
                        "advanced_remember_last_profile_subtitle",
                        fallback: "Remember last selected profile at startup"
                    ),
                    isOn: $autoSelectLastProfile,
                    accentColor: accentColor
                )

                SettingsToggleRow(
                    title: L10n.string(
                        "profile_select_on_return",
                        fallback: "Choose Profile on Return"
                    ),
                    subtitle: L10n.string(
                        "profile_select_on_return_subtitle",
                        fallback: "Ask who's watching whenever Nuvio returns from the background"
                    ),
                    isOn: $requireProfileSelectionAfterBackground,
                    accentColor: accentColor
                )
            }

            SettingsGroup(
                title: L10n.string("settings_account", fallback: "Account"),
                subtitle: L10n.string(
                    "settings_account_section_subtitle",
                    fallback: "Account and sync status"
                )
            ) {
                // A session the server will no longer renew still reads as
                // authenticated locally, so "Signed In" would be the one thing
                // on screen contradicting an account that syncs nothing.
                SettingsInfoRow(
                    title: L10n.string("tvos_account_status", fallback: "Status"),
                    value: accountStatusText
                )

                if let accountEmail, !accountEmail.isEmpty {
                    SettingsInfoRow(
                        title: L10n.string("tvos_account_email", fallback: "Email"),
                        value: accountEmail
                    )
                }

                SettingsToggleRow(
                    title: L10n.string(
                        "tvos_account_sync_watched",
                        fallback: "Sync Watched State"
                    ),
                    subtitle: L10n.string(
                        "tvos_account_sync_watched_subtitle",
                        fallback: "Keep watched history, resume points, and library state eligible for sync"
                    ),
                    isOn: $syncWatchState,
                    accentColor: accentColor
                )

                SettingsToggleRow(
                    title: L10n.string(
                        "tvos_account_icloud_sync",
                        fallback: "iCloud Settings Sync"
                    ),
                    subtitle: L10n.string(
                        "tvos_account_icloud_sync_subtitle",
                        fallback: "Sync themes, layout, player preferences, and integration keys across Apple TVs on this iCloud account"
                    ),
                    isOn: $iCloudSyncEnabled,
                    accentColor: accentColor
                )

                if iCloudSyncEnabled {
                    SettingsActionRow(
                        title: L10n.string("tvos_settings_icloud_sync_now", fallback: "Sync Now"),
                        subtitle: L10n.string(
                            "tvos_settings_icloud_sync_now_subtitle",
                            fallback: "Push and pull the latest settings to and from iCloud"
                        ),
                        value: L10n.string("action_sync", fallback: "Sync"),
                        accentColor: accentColor,
                        action: {
                            ICloudSettingsSyncManager.shared.syncNow()
                        }
                    )

                    if let lastSync = iCloudSyncManager.lastSyncDate {
                        SettingsInfoRow(
                            title: L10n.string("tvos_settings_icloud_last_sync", fallback: "Last iCloud Sync"),
                            value: DateFormatter.localizedString(from: lastSync, dateStyle: .short, timeStyle: .medium)
                        )
                    }
                }

                if isAuthenticated {
                    if sessionNeedsReauthentication {
                        SettingsActionRow(
                            title: L10n.string("reauth_action_title", fallback: "Reconnect Account"),
                            subtitle: L10n.string(
                                "reauth_action_subtitle",
                                fallback: "Your session expired. Scan QR or sign in to resume sync"
                            ),
                            value: L10n.string("tvos_account_sign_in", fallback: "Sign In"),
                            accentColor: Color(red: 1.0, green: 0.72, blue: 0.2)
                        ) {
                            onSignIn?()
                        }
                        .opacity(onSignIn != nil ? 1 : 0.46)
                        .disabled(onSignIn == nil)
                    }

                    SettingsActionRow(
                        title: L10n.string("tvos_account_sign_out", fallback: "Sign Out"),
                        subtitle: L10n.string(
                            "tvos_account_sign_out_subtitle",
                            fallback: "Remove this Nuvio account from this Apple TV"
                        ),
                        value: L10n.string("action_disconnect", fallback: "Disconnect"),
                        accentColor: Color(red: 1.0, green: 0.43, blue: 0.43)
                    ) {
                        onSignOut?()
                    }
                    .opacity(onSignOut != nil ? 1 : 0.46)
                    .disabled(onSignOut == nil)
                } else {
                    SettingsActionRow(
                        title: L10n.string("tvos_account_sign_in", fallback: "Sign In"),
                        subtitle: L10n.string(
                            "tvos_account_sign_in_subtitle",
                            fallback: "Connect a Nuvio account to sync profiles, add-ons, and progress"
                        ),
                        value: L10n.string("action_connect", fallback: "Connect"),
                        accentColor: accentColor
                    ) {
                        onSignIn?()
                    }
                    .opacity(onSignIn != nil ? 1 : 0.46)
                    .disabled(onSignIn == nil)
                }
            }
        }
        .onAppear { refreshEditableName() }
        .onChange(of: activeProfile) { _, _ in refreshEditableName() }
        .sheet(isPresented: $showingAvatarPicker) {
            if let profile = activeProfile {
                ProfileAvatarPickerSheet(
                    isPresented: $showingAvatarPicker,
                    title: displayProfileName,
                    selectedAvatarId: profile.avatarId.isEmpty
                        ? ProfileAvatarCatalog.defaultId
                        : profile.avatarId
                ) { avatarId in
                    onChangeProfileAvatar?(profile.id, avatarId)
                }
            }
        }
        .sheet(isPresented: $showingBackgroundPicker) {
            if let profile = activeProfile {
                ProfileBackgroundPickerSheet(
                    isPresented: $showingBackgroundPicker,
                    title: displayProfileName,
                    standardColor: profileColor(for: profile),
                    initialBackgroundId: profile.profileBackgroundId,
                    initialBackgroundUrl: profile.profileBackgroundUrl
                ) { backgroundId, backgroundUrl in
                    onChangeProfileBackground?(profile.id, backgroundId, backgroundUrl)
                }
            }
        }
        .onChange(of: iCloudSyncEnabled) { _, newValue in
            ICloudSettingsSyncManager.shared.isEnabled = newValue
        }
    }

    private var currentBackgroundLabel: String {
        guard let profile = activeProfile else {
            return L10n.string("profile_background_normal", fallback: "Standard")
        }
        let custom = profile.profileBackgroundUrl?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if !custom.isEmpty {
            return L10n.string("profile_background_custom", fallback: "Custom")
        }
        if let bgId = profile.profileBackgroundId?.trimmingCharacters(in: .whitespacesAndNewlines), !bgId.isEmpty {
            return ProfileBackgroundCatalogStore.shared.item(for: bgId)?.displayName ?? bgId
        }
        return L10n.string("profile_background_normal", fallback: "Standard")
    }

    private func profileColor(for profile: Profile) -> Color {
        if let item = AvatarCatalogStore.shared.item(for: profile.avatarId),
           let bgHex = item.bgColor, !bgHex.isEmpty {
            return Color(hex: bgHex)
        }
        return Color(hex: "#1E88E5")
    }

    private var displayProfileName: String {
        if !isAuthenticated, activeProfile == nil { return L10n.string("tvos_settings_nuvio_guest", fallback: "Nuvio Guest") }
        return ProfileDisplayName.resolve(profile: activeProfile, settingsName: profileName)
    }

    private var isPinProtected: Bool {
        activeProfile?.isPinProtected == true
    }

    private var canManagePin: Bool {
        activeProfile != nil && onChangeProfilePin != nil && onVerifyProfilePin != nil
    }

    private var pinProtectionBinding: Binding<Bool> {
        Binding(
            get: { isPinProtected },
            set: { requestedValue in
                guard requestedValue != isPinProtected else { return }
                onPresentPin(requestedValue ? .enable : .disable)
            }
        )
    }

    private func refreshEditableName() {
        editableProfileName = displayProfileName
    }

    private func saveProfileName() {
        let name = editableProfileName.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let profileId = activeProfile?.id, !name.isEmpty else {
            refreshEditableName()
            return
        }
        editableProfileName = name
        profileName = name
        onChangeProfileName?(profileId, name)
    }
}

enum ProfilePinSheetMode: String, Identifiable {
    case enable
    case disable

    var id: String { rawValue }
}

struct ProfilePinManagementView: View {
    let mode: ProfilePinSheetMode
    let profileName: String
    let onVerify: (String) async -> Bool
    let onSave: (String?, String?) async -> Bool
    let onDismiss: () -> Void

    @State private var enteredPin = ""
    @State private var pendingPin: String?
    @State private var errorMessage: String?
    @State private var isWorking = false
    @FocusState private var focusedPinKey: String?

    var body: some View {
        ZStack {
            Color.black.opacity(0.52).ignoresSafeArea()

            VStack(spacing: 24) {
                Text(title)
                    .font(.system(size: 34, weight: .bold))
                    .foregroundColor(.white)

                Text(instructions)
                    .font(.system(size: 20, weight: .medium))
                    .foregroundColor(.white.opacity(0.64))
                    .multilineTextAlignment(.center)

                HStack(spacing: 18) {
                    ForEach(0..<4, id: \.self) { index in
                        Circle()
                            .fill(index < enteredPin.count ? Color.white : Color.white.opacity(0.24))
                            .frame(width: 18, height: 18)
                    }
                }
                .padding(.vertical, 4)

                Text(isWorking ? L10n.string("tvos_settings_saving_pin", fallback: "Saving PIN…") : (errorMessage ?? " "))
                    .font(.system(size: 18, weight: .semibold))
                    .foregroundColor(isWorking ? .white.opacity(0.72) : .red)
                    .frame(height: 24)

                LazyVGrid(
                    columns: Array(repeating: GridItem(.fixed(80)), count: 3),
                    spacing: 18
                ) {
                    ForEach(1...9, id: \.self) { number in
                        PinButton(
                            number: "\(number)",
                            focus: $focusedPinKey,
                            focusKey: "pin-\(number)"
                        ) {
                            addDigit("\(number)")
                        }
                    }

                    PinButton(number: "", isDisabled: true, focus: $focusedPinKey, focusKey: "pin-empty") {}
                    PinButton(number: "0", focus: $focusedPinKey, focusKey: "pin-0") { addDigit("0") }

                    PinDeleteButton(action: deleteDigit)
                }
                .focusSection()
                .defaultFocusIfAvailable($focusedPinKey, "pin-1")

                PinSheetActionButton(title: L10n.string("action_cancel", fallback: "Cancel"), action: onDismiss)
                    .padding(.top, 4)
            }
            .frame(width: 520)
            .padding(48)
            .loginGlassPanel()
            .overlay {
                RoundedRectangle(cornerRadius: 22, style: .continuous)
                    .stroke(Color.white.opacity(0.12), lineWidth: 1)
            }
            .shadow(color: .black.opacity(0.38), radius: 32, y: 18)
        }
        .onAppear {
            DispatchQueue.main.async { focusedPinKey = "pin-1" }
        }
        .onExitCommand {
            guard !isWorking else { return }
            onDismiss()
        }
    }

    private var title: String {
        switch mode {
        case .enable:
            return pendingPin == nil ? "Create PIN" : "Confirm PIN"
        case .disable:
            return L10n.string("tvos_settings_turn_off_pin_protection", fallback: "Turn Off PIN Protection")
        }
    }

    private var instructions: String {
        switch mode {
        case .enable:
            return pendingPin == nil
                ? "Enter a 4-digit PIN for \(profileName)."
                : "Enter the same PIN again."
        case .disable:
            return L10n.format(
                "tvos_settings_enter_pin_for_profile",
                fallback: "Enter the current PIN for %@.",
                profileName
            )
        }
    }

    private func addDigit(_ digit: String) {
        guard !isWorking, enteredPin.count < 4 else { return }
        let completedPin = enteredPin + digit
        enteredPin = completedPin
        errorMessage = nil
        guard completedPin.count == 4 else { return }

        switch mode {
        case .enable:
            if pendingPin == nil {
                pendingPin = completedPin
                enteredPin = ""
            } else if pendingPin != completedPin {
                enteredPin = ""
                errorMessage = "PINs did not match. Try again."
            } else {
                savePin(completedPin, currentPin: nil)
            }

        case .disable:
            disablePin(currentPin: completedPin)
        }
    }

    private func savePin(_ pin: String, currentPin: String?) {
        isWorking = true
        Task { @MainActor in
            let saved = await onSave(pin, currentPin)
            isWorking = false
            if saved {
                onDismiss()
            } else {
                enteredPin = ""
                errorMessage = "The PIN could not be saved. Check your connection and try again."
            }
        }
    }

    private func disablePin(currentPin: String) {
        isWorking = true
        Task { @MainActor in
            guard await onVerify(currentPin) else {
                isWorking = false
                enteredPin = ""
                errorMessage = "Incorrect PIN"
                return
            }

            let cleared = await onSave(nil, currentPin)
            isWorking = false
            if cleared {
                onDismiss()
            } else {
                enteredPin = ""
                errorMessage = "PIN protection could not be turned off. Check your connection and try again."
            }
        }
    }

    private func deleteDigit() {
        guard !isWorking, !enteredPin.isEmpty else { return }
        enteredPin.removeLast()
        errorMessage = nil
    }
}

struct PinDeleteButton: View {
    let action: () -> Void
    @FocusState private var isFocused: Bool

    var body: some View {
        Button(action: action) {
            Image(systemName: "delete.left")
                .font(.system(size: 30, weight: .semibold))
                .foregroundColor(isFocused ? .black : .white)
                .frame(width: 80, height: 80)
                .loginGlassCapsule(highlighted: isFocused)
        }
        .buttonStyle(PosterCardButtonStyle())
        .focused($isFocused)
        .focusEffectDisabledIfAvailable()
        .scaleEffect(isFocused ? 1.06 : 1)
        .animation(.easeOut(duration: 0.12), value: isFocused)
    }
}

struct PinSheetActionButton: View {
    let title: String
    let action: () -> Void
    @FocusState private var isFocused: Bool

    var body: some View {
        Button(action: action) {
            Text(title)
                .font(.system(size: 20, weight: .semibold))
                .foregroundColor(isFocused ? .black : .white)
                .padding(.horizontal, 30)
                .frame(height: 56)
                .loginGlassCapsule(highlighted: isFocused)
        }
        .buttonStyle(PosterCardButtonStyle())
        .focused($isFocused)
        .focusEffectDisabledIfAvailable()
        .scaleEffect(isFocused ? 1.04 : 1)
        .animation(.easeOut(duration: 0.12), value: isFocused)
    }
}

private struct AppearanceSettingsView: View {
    let accentColor: Color
    let languageFocus: FocusState<LanguagePickerKind?>.Binding
    let onAppLanguage: () -> Void

    @AppStorage(SettingsKey.theme) private var theme = SettingsAccent.white.rawValue
    @AppStorage(SettingsKey.bodyColor) private var bodyColor = SettingsBackground.charcoal.rawValue
    @AppStorage(SettingsKey.font) private var appFont = "Inter"
    /// BCP-47 language tag; empty string means System default (matches Android TV).
    @AppStorage(SettingsKey.language) private var languageTag = ""
    @AppStorage(SettingsKey.amoled) private var amoled = false
    @AppStorage(SettingsKey.amoledSurfaces) private var amoledSurfaces = false
    @AppStorage(SettingsKey.cardCornerRadius) private var cardCornerRadius = AppCardStyle.defaultCornerRadiusRaw
    @AppStorage(SettingsKey.liquidGlassCards) private var liquidGlassCards = true
    @AppStorage(SettingsKey.showCalendarTab) private var showCalendarTab = true
    @AppStorage(SettingsKey.useTopNavigation) private var useTopNavigation = false
    @AppStorage(SettingsKey.showWatchPartyTab) private var showWatchPartyTab = true
    @AppStorage(SettingsKey.customPosterURLPattern) private var customPosterURLPattern = ""
    @AppStorage(SettingsKey.customPosterEnabledScreens) private var customPosterEnabledScreens = "all"
    @State private var customPosterURLDraft = ""
    @ObservedObject private var localeManager = AppLocaleManager.shared

    private let cardRadiusOptions = CardCornerRadiusOption.allCases.map(\.rawValue)

    private var accentSwatches: [SettingsSwatch] {
        SettingsAccent.allCases.map { SettingsSwatch(id: $0.rawValue, label: $0.rawValue, color: $0.color) }
    }

    private var backgroundSwatches: [SettingsSwatch] {
        SettingsBackground.allCases.map { SettingsSwatch(id: $0.rawValue, label: $0.rawValue, color: $0.swatchColor) }
    }

    private var appLanguageSummary: String {
        AppLanguage.fromStored(languageTag).nativeDisplayName
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 22) {
            SettingsGroup(
                title: L10n.string("settings_poster_card_style", fallback: "Card & Poster Style"),
                subtitle: L10n.string(
                    "settings_poster_description",
                    fallback: "Customize card corner radius and Apple TV liquid glass appearance"
                )
            ) {
                CardStyleLivePreview(
                    customPosterURLPattern: customPosterURLPattern,
                    cornerRadiusOption: CardCornerRadiusOption.from(rawValue: cardCornerRadius),
                    isLiquidGlass: liquidGlassCards
                )
                .id(customPosterURLPattern)

                SettingsOptionRow(
                    title: L10n.string("settings_poster_card_radius", fallback: "Corner Radius"),
                    subtitle: L10n.string(
                        "tvos_card_radius_subtitle",
                        fallback: "Choose sharp, subtle, classic, rounded, or pill card corners"
                    ),
                    selection: $cardCornerRadius,
                    options: cardRadiusOptions,
                    accentColor: accentColor
                )
                .settingsEntryAnchor()
                .onAppear {
                    if CardCornerRadiusOption(rawValue: cardCornerRadius) == nil {
                        cardCornerRadius = CardCornerRadiusOption.from(rawValue: cardCornerRadius).rawValue
                    }
                }

                SettingsToggleRow(
                    title: L10n.string("tvos_liquid_glass_cards", fallback: "Liquid Glass Cards"),
                    subtitle: L10n.string(
                        "tvos_liquid_glass_cards_subtitle",
                        fallback: "Apply Apple TV frosted liquid glass effect, specular reflections, and translucent materials to portrait, landscape, and episode cards"
                    ),
                    isOn: $liquidGlassCards,
                    accentColor: accentColor
                )

                SettingsTextFieldRow(
                    title: "Custom Poster URL",
                    subtitle: "Leave blank to use provider artwork. Supports {id}, {id_type}, {typed_id}, {type}, {shape}, and ID types ({imdb_id}, {tmdb_id}, {tvdb_id}, etc.).",
                    placeholder: "https://example.com/poster?id={id}&id_type={id_type}&type={type}",
                    text: $customPosterURLDraft,
                    fieldWidth: 650,
                    onCommit: {
                        let committedPattern = CustomPosterURLResolver.sanitizePattern(customPosterURLDraft)
                        customPosterURLDraft = committedPattern
                        customPosterURLPattern = committedPattern
                    }
                )
                .onAppear {
                    customPosterURLDraft = customPosterURLPattern
                }
                .onChange(of: customPosterURLPattern) { _, newPattern in
                    customPosterURLDraft = newPattern
                }

                if !customPosterURLPattern.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    customPosterScreens
                }
            }

            SettingsGroup(
                title: L10n.string("settings_sidebar_tabs", fallback: "Sidebar"),
                subtitle: L10n.string("settings_sidebar_tabs_subtitle", fallback: "Choose which sections appear in the sidebar")
            ) {
                SettingsToggleRow(
                    title: L10n.string("settings_top_navigation", fallback: "Top Navigation Bar"),
                    subtitle: L10n.string("settings_top_navigation_subtitle", fallback: "Use the Apple TV top tab bar instead of the sidebar"),
                    isOn: $useTopNavigation,
                    accentColor: accentColor
                )
                SettingsToggleRow(
                    title: L10n.string("nav_calendar", fallback: "Calendar"),
                    subtitle: L10n.string(
                        "settings_show_calendar_tab_subtitle",
                        fallback: "Upcoming episodes and releases from your library"
                    ),
                    isOn: $showCalendarTab,
                    accentColor: accentColor
                )
                SettingsToggleRow(
                    title: L10n.string("nav_watch_party", fallback: "Watch Party"),
                    subtitle: L10n.string(
                        "settings_show_watch_party_tab_subtitle",
                        fallback: "Show Watch Party in the sidebar"
                    ),
                    isOn: $showWatchPartyTab,
                    accentColor: accentColor
                )
            }

            SettingsGroup(
                title: L10n.string("tvos_appearance_focus_outline", fallback: "Focus Outline"),
                subtitle: L10n.string(
                    "tvos_appearance_focus_outline_subtitle",
                    fallback: "Accent color used for focused cards and controls"
                )
            ) {
                SettingsSwatchRow(swatches: accentSwatches, selection: $theme, accentColor: accentColor)
            }

            SettingsGroup(
                title: L10n.string("tvos_appearance_app_background", fallback: "App Background"),
                subtitle: L10n.string(
                    "tvos_appearance_app_background_subtitle",
                    fallback: "Body background color behind every screen"
                )
            ) {
                SettingsSwatchRow(swatches: backgroundSwatches, selection: $bodyColor, accentColor: accentColor)

                SettingsToggleRow(
                    title: L10n.string("appearance_amoled_mode", fallback: "AMOLED Mode"),
                    subtitle: L10n.string(
                        "appearance_amoled_mode_subtitle",
                        fallback: "Force a pure black background, overriding the choice above"
                    ),
                    isOn: $amoled,
                    accentColor: accentColor
                )

                SettingsToggleRow(
                    title: L10n.string("appearance_amoled_surfaces_mode", fallback: "AMOLED Surfaces"),
                    subtitle: L10n.string(
                        "appearance_amoled_surfaces_mode_subtitle",
                        fallback: "Flatten card and row surfaces when AMOLED mode is enabled"
                    ),
                    isOn: $amoledSurfaces,
                    accentColor: accentColor
                )
                .opacity(amoled ? 1 : 0.46)
                .disabled(!amoled)
            }

            SettingsGroup(
                title: L10n.string("appearance_font_and_language", fallback: "Font and Language"),
                subtitle: L10n.string(
                    "appearance_font_and_language_subtitle",
                    fallback: "Choose the typeface and locale used throughout the app"
                )
            ) {
                SettingsChoiceRow(
                    title: L10n.string("appearance_font", fallback: "App Font"),
                    subtitle: L10n.string(
                        "appearance_font_subtitle",
                        fallback: "Choose your preferred font"
                    ),
                    selection: $appFont,
                    options: AppFont.allCases.map(\.rawValue),
                    optionLabels: Dictionary(uniqueKeysWithValues: AppFont.allCases.map { ($0.rawValue, $0.displayName) }),
                    accentColor: accentColor
                )
                .onChange(of: appFont) { _, newValue in
                    AppFontManager.shared.setFont(AppFont.fromStored(newValue), persist: true)
                }

                // Same SettingsActionRow + LanguagePickerWindow pattern as Preferred Audio.
                SettingsActionRow(
                    title: L10n.string("appearance_language", fallback: "App Language"),
                    subtitle: L10n.string(
                        "appearance_language_subtitle",
                        fallback: "Override system language for the entire app"
                    ),
                    value: appLanguageSummary,
                    accentColor: accentColor
                ) {
                    onAppLanguage()
                }
                .focused(languageFocus, equals: .appLanguage)
            }
        }
        .onAppear {
            let resolvedFont = AppFont.fromStored(appFont)
            if appFont != resolvedFont.rawValue {
                appFont = resolvedFont.rawValue
            }
            // Migrate legacy English display names (e.g. "English") to BCP-47 tags.
            let resolved = AppLanguage.fromStored(languageTag)
            if languageTag != resolved.tag {
                languageTag = resolved.tag
            }
            if languageTag != localeManager.language.tag {
                localeManager.applyStoredTag(languageTag)
            }
        }
        .onChange(of: languageTag) { _, newValue in
            localeManager.applyStoredTag(newValue)
        }
        .onChange(of: localeManager.revision) { _, _ in
            // Keep summary in sync when the picker writes via AppLocaleManager.
            let resolved = AppLocaleManager.shared.language
            if languageTag != resolved.tag {
                languageTag = resolved.tag
            }
        }
        .onChange(of: cardCornerRadius) { _, _ in
            ProfileSettings.notifySettingsChanged()
        }
        .onChange(of: theme) { _, _ in
            ProfileSettings.notifySettingsChanged()
        }
        .onChange(of: bodyColor) { _, _ in
            ProfileSettings.notifySettingsChanged()
        }
        .onChange(of: amoled) { _, _ in
            ProfileSettings.notifySettingsChanged()
        }
        .onChange(of: liquidGlassCards) { _, _ in
            ProfileSettings.notifySettingsChanged()
        }
        .onChange(of: customPosterURLPattern) { oldPattern, newPattern in
            if oldPattern != newPattern {
                Task {
                    await PosterArtworkCache.clearAllArtwork()
                }
            }
            ProfileSettings.notifySettingsChanged()
        }
        .onChange(of: customPosterEnabledScreens) { oldScreens, newScreens in
            if oldScreens != newScreens {
                Task {
                    await PosterArtworkCache.clearAllArtwork()
                }
            }
            ProfileSettings.notifySettingsChanged()
        }
    }

    private func customPosterScreenBinding(for screen: CustomPosterScreen) -> Binding<Bool> {
        Binding(
            get: {
                CustomPosterScreen.fromStorageValue(customPosterEnabledScreens).contains(screen)
            },
            set: { isEnabled in
                var screens = CustomPosterScreen.fromStorageValue(customPosterEnabledScreens)
                if isEnabled {
                    screens.insert(screen)
                } else {
                    screens.remove(screen)
                }
                customPosterEnabledScreens = CustomPosterScreen.storageValue(for: screens)
            }
        )
    }

    @ViewBuilder
    private var customPosterScreens: some View {
        let screens = CustomPosterScreen.allCases.filter { $0 != .tvRecommendations }
        ForEach(screens) { screen in
            SettingsToggleRow(
                title: "Apply to \(screen.title)",
                subtitle: "Use custom poster artwork on \(screen.title.lowercased()) cards.",
                isOn: customPosterScreenBinding(for: screen),
                accentColor: accentColor
            )
        }
    }
}

// MARK: - Card Style Live Preview

private struct CardStyleLivePreview: View {
    let customPosterURLPattern: String
    let cornerRadiusOption: CardCornerRadiusOption
    let isLiquidGlass: Bool

    @State private var selectedTitle = PreviewTitle.random()
    @State private var loadedMetadata: NuvioMeta?
    @State private var hasAppeared = false

    private struct PreviewTitle: Identifiable {
        let id: String
        let name: String
        let tmdbId: Int

        static let samples = [
            PreviewTitle(id: "tt1375666", name: "Inception", tmdbId: 27_205),
            PreviewTitle(id: "tt0816692", name: "Interstellar", tmdbId: 157_336),
            PreviewTitle(id: "tt15239678", name: "Dune: Part Two", tmdbId: 693_134)
        ]

        static func random() -> PreviewTitle {
            samples.randomElement() ?? samples[0]
        }

        var fallbackMetadata: NuvioMeta {
            NuvioMeta(
                id: id,
                name: name,
                posterUrl: "https://images.metahub.space/poster/small/\(id)/img",
                imdbId: id,
                tmdbId: tmdbId,
                type: "movie"
            )
        }
    }

    private var portraitRadius: CGFloat { cornerRadiusOption.radius }

    private var previewMetadata: NuvioMeta {
        loadedMetadata ?? selectedTitle.fallbackMetadata
    }

    private var customPortraitArtworkURL: String? {
        CustomPosterURLResolver.resolve(
            pattern: customPosterURLPattern,
            meta: previewMetadata,
            shape: "poster"
        )
    }

    private var originalLandscapeArtworkURL: String? {
        previewMetadata.backgroundUrl ?? previewMetadata.landscapePosterUrl ?? previewMetadata.posterUrl
    }

    private var customLandscapeArtworkURL: String? {
        CustomPosterURLResolver.resolve(
            pattern: customPosterURLPattern,
            meta: previewMetadata,
            shape: "landscape"
        )
    }

    private var previewTitle: String {
        loadedMetadata?.name ?? selectedTitle.name
    }

    var body: some View {
        VStack(spacing: 16) {
            HStack(spacing: 28) {
                VStack(alignment: .leading, spacing: 8) {
                    Text("PORTRAIT")
                        .font(.system(size: 13, weight: .bold))
                        .foregroundColor(.white.opacity(0.55))
                        .tracking(1.2)

                    CachedPosterArtwork(
                        urlString: customPortraitArtworkURL ?? previewMetadata.posterUrl,
                        fallbackURLString: customPortraitArtworkURL == nil ? nil : previewMetadata.posterUrl,
                        width: 140,
                        height: 210,
                        maximumWidth: 140
                    ) {
                        Rectangle().fill(Color.white.opacity(0.07))
                    }
                    .frame(width: 140, height: 210)
                    .clipShape(RoundedRectangle(cornerRadius: portraitRadius, style: .continuous))
                    .overlay(
                        RoundedRectangle(cornerRadius: portraitRadius, style: .continuous)
                            .strokeBorder(
                                isLiquidGlass
                                    ? LinearGradient(
                                        colors: [Color.white.opacity(0.55), Color.white.opacity(0.20), Color.white.opacity(0.35)],
                                        startPoint: .topLeading,
                                        endPoint: .bottomTrailing
                                    )
                                    : LinearGradient(colors: [Color.clear], startPoint: .top, endPoint: .bottom),
                                lineWidth: 1.5
                            )
                    )
                    .overlay(
                        RoundedRectangle(cornerRadius: portraitRadius, style: .continuous)
                            .stroke(AppFocusOutline.color, lineWidth: AppFocusOutline.width)
                    )

                    Text(previewTitle)
                        .font(.system(size: 14, weight: .semibold))
                        .foregroundColor(.white.opacity(0.78))
                        .lineLimit(1)
                        .frame(width: 140, alignment: .leading)
                }

                VStack(alignment: .leading, spacing: 8) {
                    Text("LANDSCAPE")
                        .font(.system(size: 13, weight: .bold))
                        .foregroundColor(.white.opacity(0.55))
                        .tracking(1.2)

                    CachedPosterArtwork(
                        urlString: customLandscapeArtworkURL ?? originalLandscapeArtworkURL,
                        fallbackURLString: customLandscapeArtworkURL == nil ? nil : originalLandscapeArtworkURL,
                        width: 373,
                        height: 210,
                        maximumWidth: 373
                    ) {
                        Rectangle().fill(Color.white.opacity(0.07))
                    }
                    .frame(width: 373, height: 210)
                    .clipShape(RoundedRectangle(cornerRadius: portraitRadius, style: .continuous))
                    .overlay(
                        RoundedRectangle(cornerRadius: portraitRadius, style: .continuous)
                            .strokeBorder(
                                isLiquidGlass
                                    ? LinearGradient(
                                        colors: [Color.white.opacity(0.55), Color.white.opacity(0.20), Color.white.opacity(0.35)],
                                        startPoint: .topLeading,
                                        endPoint: .bottomTrailing
                                    )
                                    : LinearGradient(colors: [Color.clear], startPoint: .top, endPoint: .bottom),
                                lineWidth: 1.5
                            )
                    )

                    Text(previewTitle)
                        .font(.system(size: 14, weight: .semibold))
                        .foregroundColor(.white.opacity(0.78))
                        .lineLimit(1)
                        .frame(width: 373, alignment: .leading)
                }
            }
            .padding(.vertical, 16)
            .padding(.horizontal, 24)
            .frame(maxWidth: .infinity)
            .background(
                RoundedRectangle(cornerRadius: 18, style: .continuous)
                    .fill(Color.white.opacity(0.04))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 18, style: .continuous)
                    .stroke(Color.white.opacity(0.08), lineWidth: 1)
            )
        }
        .animation(.spring(response: 0.32, dampingFraction: 0.78), value: cornerRadiusOption)
        .animation(.spring(response: 0.32, dampingFraction: 0.78), value: isLiquidGlass)
        .task(id: selectedTitle.id) {
            loadedMetadata = nil
            do {
                let metadata = try await CinemetaCatalogRepository().getMetadata(id: selectedTitle.id, type: "movie")
                guard !Task.isCancelled else { return }
                loadedMetadata = metadata
            } catch {
                // Keep the seeded title, IDs, and portrait fallback when Cinemeta is unavailable.
            }
        }
        .onAppear {
            if hasAppeared {
                selectedTitle = PreviewTitle.random()
                loadedMetadata = nil
            }
            hasAppeared = true
        }
    }
}

// MARK: - Home Layout Live Preview

private struct HomeLayoutLivePreview: View {
    let layout: String
    let heroEnabled: Bool
    var fullscreenHeroBackdrop: Bool = true
    var heroRatingsEnabled = true
    let posterLabels: Bool
    let catalogAddonNames: Bool
    var landscapePosters: Bool = false
    var gridRows: Int = TVHomeGridLayout.defaultRows
    let accentColor: Color

    @AppStorage(SettingsKey.cardCornerRadius) private var cardCornerRadius = AppCardStyle.defaultCornerRadiusRaw
    @AppStorage(SettingsKey.liquidGlassCards) private var liquidGlassCards = true

    private func cardCornerRadius(forWidth width: CGFloat, isLandscape: Bool = false) -> CGFloat {
        let opt = CardCornerRadiusOption.from(rawValue: cardCornerRadius)
        if opt == .sharp { return 0 }
        if isLandscape {
            let fullRadius = AppCardStyle.episodeCornerRadius(for: cardCornerRadius)
            return max(1, fullRadius * (width / 340.0))
        } else {
            let fullRadius = opt.radius
            return max(1, fullRadius * (width / 210.0))
        }
    }

    private var miniCornerRadius: CGFloat {
        cardCornerRadius(forWidth: 66, isLandscape: false)
    }

    private var miniShape: RoundedRectangle {
        RoundedRectangle(cornerRadius: miniCornerRadius, style: .continuous)
    }

    private var miniLandscapeCornerRadius: CGFloat {
        cardCornerRadius(forWidth: 172, isLandscape: true)
    }

    private var miniLandscapeShape: RoundedRectangle {
        RoundedRectangle(cornerRadius: miniLandscapeCornerRadius, style: .continuous)
    }

    private struct MovieItem {
        let title: String
        let colors: [Color]
        let hasWatchedBadge: Bool
    }

    private let movies: [MovieItem] = [
        MovieItem(title: "The Invite", colors: [Color(red: 0.76, green: 0.65, blue: 0.48), Color(red: 0.18, green: 0.12, blue: 0.08)], hasWatchedBadge: false),
        MovieItem(title: "Don't Say Good Luck", colors: [Color(red: 0.28, green: 0.48, blue: 0.36), Color(red: 0.08, green: 0.16, blue: 0.10)], hasWatchedBadge: false),
        MovieItem(title: "Project Hail Mary", colors: [Color(red: 0.20, green: 0.45, blue: 0.72), Color(red: 0.05, green: 0.12, blue: 0.25)], hasWatchedBadge: true),
        MovieItem(title: "Masters of Universe", colors: [Color(red: 0.78, green: 0.35, blue: 0.18), Color(red: 0.22, green: 0.08, blue: 0.06)], hasWatchedBadge: false),
        MovieItem(title: "Disclosure Day", colors: [Color(red: 0.45, green: 0.60, blue: 0.68), Color(red: 0.12, green: 0.16, blue: 0.20)], hasWatchedBadge: false),
        MovieItem(title: "Severance", colors: [Color(red: 0.15, green: 0.45, blue: 0.55), Color(red: 0.04, green: 0.10, blue: 0.15)], hasWatchedBadge: false),
        MovieItem(title: "Fallout", colors: [Color(red: 0.75, green: 0.55, blue: 0.15), Color(red: 0.18, green: 0.12, blue: 0.04)], hasWatchedBadge: true)
    ]

    var body: some View {
        VStack(spacing: 0) {
            // Centered 16:9 Widescreen TV Mockup
            ZStack(alignment: .topLeading) {
                // Cinematic Full-Bleed Ambient Backdrop
                let previewBg = Color(red: 0.04, green: 0.05, blue: 0.08)
                ZStack(alignment: .topTrailing) {
                    previewBg

                    if fullscreenHeroBackdrop {
                        LinearGradient(
                            colors: [
                                Color(red: 0.14, green: 0.18, blue: 0.24),
                                Color(red: 0.08, green: 0.10, blue: 0.14),
                                previewBg
                            ],
                            startPoint: .topTrailing,
                            endPoint: .bottomLeading
                        )

                        // Left & Bottom gradient shadow
                        LinearGradient(
                            stops: [
                                .init(color: previewBg.opacity(0.95), location: 0.0),
                                .init(color: previewBg.opacity(0.70), location: 0.45),
                                .init(color: .clear, location: 0.85)
                            ],
                            startPoint: .leading,
                            endPoint: .trailing
                        )

                        LinearGradient(
                            stops: [
                                .init(color: .clear, location: 0.2),
                                .init(color: previewBg.opacity(0.85), location: 0.7),
                                .init(color: previewBg, location: 1.0)
                            ],
                            startPoint: .top,
                            endPoint: .bottom
                        )
                    } else {
                        LinearGradient(
                            colors: [
                                Color(red: 0.16, green: 0.22, blue: 0.30),
                                Color(red: 0.10, green: 0.13, blue: 0.18),
                                previewBg
                            ],
                            startPoint: .topTrailing,
                            endPoint: .bottomLeading
                        )
                        .frame(width: 380, height: 165)
                        .mask(
                            LinearGradient(
                                stops: [
                                    .init(color: .clear, location: 0),
                                    .init(color: .black.opacity(0.30), location: 0.28),
                                    .init(color: .black, location: 0.65)
                                ],
                                startPoint: .leading,
                                endPoint: .trailing
                            )
                        )
                        .mask(
                            LinearGradient(
                                stops: [
                                    .init(color: .black, location: 0),
                                    .init(color: .black, location: 0.48),
                                    .init(color: .black.opacity(0.40), location: 0.78),
                                    .init(color: .clear, location: 1.0)
                                ],
                                startPoint: .top,
                                endPoint: .bottom
                            )
                        )
                    }
                }

                // Screen Layout Contents
                VStack(alignment: .leading, spacing: 6) {
                    Spacer(minLength: 0)

                    if heroEnabled {
                        heroDetailsSection
                            .transition(.opacity.combined(with: .scale(scale: 0.98, anchor: .top)))
                    }

                    if layout == "Grid View" {
                        gridViewSection
                            .transition(.opacity)
                    } else if layout == "Compact" {
                        compactRowsSection
                            .transition(.opacity)
                    } else {
                        modernRowsSection
                            .transition(.opacity)
                    }
                }
                .padding(.horizontal, 20)
                .padding(.top, 12)
                .padding(.bottom, 8)
            }
            .frame(width: 640, height: 330)
            .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
            .overlay(
                RoundedRectangle(cornerRadius: 16, style: .continuous)
                    .stroke(Color.white.opacity(0.12), lineWidth: 1)
            )
            .shadow(color: .black.opacity(0.50), radius: 20, y: 8)
        }
        .padding(.vertical, 16)
        .padding(.horizontal, 24)
        .frame(maxWidth: .infinity)
        .background(
            RoundedRectangle(cornerRadius: 18, style: .continuous)
                .fill(Color.white.opacity(0.04))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 18, style: .continuous)
                .stroke(Color.white.opacity(0.08), lineWidth: 1)
        )
        .animation(.spring(response: 0.32, dampingFraction: 0.80), value: layout)
        .animation(.spring(response: 0.32, dampingFraction: 0.80), value: heroEnabled)
        .animation(.spring(response: 0.32, dampingFraction: 0.80), value: fullscreenHeroBackdrop)
        .animation(.spring(response: 0.32, dampingFraction: 0.80), value: heroRatingsEnabled)
        .animation(.spring(response: 0.32, dampingFraction: 0.80), value: posterLabels)
        .animation(.spring(response: 0.32, dampingFraction: 0.80), value: catalogAddonNames)
        .animation(.spring(response: 0.32, dampingFraction: 0.80), value: cardCornerRadius)
        .animation(.spring(response: 0.32, dampingFraction: 0.80), value: liquidGlassCards)
    }

    // MARK: - Hero Details Section (Matches Modern Home reference)

    private var heroDetailsSection: some View {
        return VStack(alignment: .leading, spacing: 4) {
            // Glowing stylized title logo
            Text("DUNE: PART TWO")
                .font(.system(size: 24, weight: .black, design: .rounded))
                .foregroundStyle(
                    LinearGradient(
                        colors: [.white, Color(red: 0.85, green: 0.92, blue: 1.0)],
                        startPoint: .top,
                        endPoint: .bottom
                    )
                )

            // Metadata line
            HStack(spacing: 5) {
                Text("Movie · Sci-Fi · 2h 46m · Mar 1, 2024\(heroRatingsEnabled ? " · IMDb 8.6 · TMDB 81 · RT 96%" : "")")
                    .font(.system(size: 9, weight: .medium))
                    .foregroundColor(.white.opacity(0.70))
            }

            // Multi-line synopsis
            Text("Paul Atreides unites with Chani and the Fremen while seeking revenge against the conspirators who destroyed his family.")
                .font(.system(size: 7.8, weight: .regular))
                .foregroundColor(.white.opacity(0.68))
                .lineLimit(2)
                .frame(maxWidth: 420, alignment: .leading)
                .lineSpacing(1.5)
        }
        .padding(.bottom, 4)
    }

    // MARK: - Row Header

    @ViewBuilder
    private func rowHeader(title: String, addon: String) -> some View {
        HStack(spacing: 6) {
            Text(title)
                .font(.system(size: 11.5, weight: .bold))
                .foregroundColor(.white.opacity(0.92))

            if catalogAddonNames {
                Text(addon)
                    .font(.system(size: 8, weight: .semibold))
                    .foregroundColor(accentColor)
                    .padding(.horizontal, 5)
                    .padding(.vertical, 1)
                    .background(accentColor.opacity(0.18), in: Capsule())
            }
        }
    }

    // MARK: - Modern Rows Layout (Expanded 16:9 Focused Card + Portrait Row)

    private var modernRowsSection: some View {
        VStack(alignment: .leading, spacing: 6) {
            // First Row
            VStack(alignment: .leading, spacing: 4) {
                rowHeader(title: "Popular - Movies", addon: "Cinemeta")

                HStack(spacing: 10) {
                    // 1. FOCUSED CARD (Expands to 16:9 Landscape Card)
                    VStack(alignment: .leading, spacing: 2) {
                        ZStack {
                            LinearGradient(
                                colors: [
                                    Color(red: 0.12, green: 0.18, blue: 0.28),
                                    Color(red: 0.05, green: 0.07, blue: 0.12)
                                ],
                                startPoint: .topLeading,
                                endPoint: .bottomTrailing
                            )

                            VStack(spacing: 2) {
                                Text("FOCUS")
                                    .font(.system(size: 13, weight: .heavy, design: .monospaced))
                                    .tracking(3)
                                    .foregroundStyle(
                                        LinearGradient(
                                            colors: [.cyan, .white, .orange],
                                            startPoint: .leading,
                                            endPoint: .trailing
                                        )
                                    )
                                Text("F E A T U R E S")
                                    .font(.system(size: 6, weight: .bold))
                                    .tracking(2)
                                    .foregroundColor(.white.opacity(0.70))
                            }
                        }
                        .frame(width: 172, height: 98)
                        .clipShape(miniLandscapeShape)
                        .modifier(
                            LiquidGlassCardModifier(
                                cornerRadius: miniLandscapeCornerRadius,
                                isFocused: true,
                                isEnabled: liquidGlassCards
                            )
                        )
                        .overlay(
                            miniLandscapeShape
                                .stroke(AppFocusOutline.color, lineWidth: 2)
                        )

                        if posterLabels {
                            Text("Dune: Part Two")
                                .font(.system(size: 7.5, weight: .bold))
                                .foregroundColor(.white)
                                .lineLimit(1)
                                .frame(width: 172, alignment: .leading)
                        }
                    }

                    // 2. PORTRAIT / LANDSCAPE POSTER CARDS
                    if landscapePosters {
                        ForEach(0..<2, id: \.self) { idx in
                            let item = movies[idx % movies.count]
                            miniLandscapeCard(width: 172, height: 98, item: item)
                        }
                    } else {
                        ForEach(0..<5, id: \.self) { idx in
                            let item = movies[idx % movies.count]
                            miniPortraitCard(width: 66, height: 98, item: item)
                        }
                    }
                }
            }

            // Second Row Peeking (Popular - Series)
            VStack(alignment: .leading, spacing: 4) {
                rowHeader(title: "Popular - Series", addon: "TMDB")

                HStack(spacing: 10) {
                    if landscapePosters {
                        ForEach(2..<5, id: \.self) { idx in
                            let item = movies[idx % movies.count]
                            miniLandscapeCard(width: 172, height: 40, item: item, isPeeking: true)
                        }
                    } else {
                        ForEach(2..<8, id: \.self) { idx in
                            let item = movies[idx % movies.count]
                            miniPortraitCard(width: 66, height: 40, item: item, isPeeking: true)
                        }
                    }
                }
            }
        }
    }

    // MARK: - Compact Rows Layout

    private var compactRowsSection: some View {
        VStack(alignment: .leading, spacing: 6) {
            VStack(alignment: .leading, spacing: 4) {
                rowHeader(title: "Popular - Movies", addon: "Cinemeta")

                HStack(spacing: 8) {
                    ForEach(0..<8, id: \.self) { idx in
                        let item = movies[idx % movies.count]
                        miniPortraitCard(width: 62, height: 86, item: item, isFocused: idx == 0)
                    }
                }
            }

            VStack(alignment: .leading, spacing: 4) {
                rowHeader(title: "Popular - Series", addon: "TMDB")

                HStack(spacing: 8) {
                    ForEach(1..<9, id: \.self) { idx in
                        let item = movies[idx % movies.count]
                        miniPortraitCard(width: 62, height: 86, item: item)
                    }
                }
            }
        }
    }

    // MARK: - Grid View Layout

    private var gridViewSection: some View {
        VStack(alignment: .leading, spacing: 4) {
            rowHeader(title: "All Catalogs Grid", addon: "7 × \(gridRows) Grid")

            LazyVGrid(
                columns: Array(repeating: GridItem(.fixed(75), spacing: 10), count: 7),
                spacing: 6
            ) {
                let previewCount = heroEnabled ? min(7, gridRows * 7) : min(14, gridRows * 7)
                ForEach(0..<previewCount, id: \.self) { idx in
                    let item = movies[idx % movies.count]
                    miniPortraitCard(width: 75, height: heroEnabled ? 80 : 92, item: item, isFocused: idx == 0)
                }
            }
        }
    }

    // MARK: - Mini Portrait Card

    private func miniPortraitCard(
        width: CGFloat,
        height: CGFloat,
        item: MovieItem,
        isFocused: Bool = false,
        isPeeking: Bool = false
    ) -> some View {
        let radius = cardCornerRadius(forWidth: width, isLandscape: false)
        let shape = RoundedRectangle(cornerRadius: radius, style: .continuous)

        return VStack(alignment: .leading, spacing: 2) {
            ZStack(alignment: .topTrailing) {
                LinearGradient(
                    colors: item.colors,
                    startPoint: .topLeading,
                    endPoint: .bottomTrailing
                )

                // Watched checkmark badge (like Project Hail Mary in screenshot)
                if item.hasWatchedBadge && !isPeeking {
                    Circle()
                        .fill(Color(red: 0.10, green: 0.75, blue: 0.40))
                        .frame(width: 12, height: 12)
                        .overlay(
                            Image(systemName: "checkmark")
                                .font(.system(size: 7, weight: .heavy))
                                .foregroundColor(.white)
                        )
                        .padding(4)
                }
            }
            .frame(width: width, height: height)
            .clipShape(shape)
            .modifier(
                LiquidGlassCardModifier(
                    cornerRadius: radius,
                    isFocused: isFocused,
                    isEnabled: liquidGlassCards
                )
            )
            .overlay(
                shape
                    .stroke(
                        isFocused ? AppFocusOutline.color : Color.clear,
                        lineWidth: isFocused ? 2 : 0
                    )
            )

            if posterLabels && !isPeeking {
                Text(item.title)
                    .font(.system(size: 7, weight: isFocused ? .bold : .medium))
                    .foregroundColor(isFocused ? .white : .white.opacity(0.65))
                    .lineLimit(1)
                    .frame(width: width, alignment: .leading)
            }
        }
    }

    private func miniLandscapeCard(
        width: CGFloat,
        height: CGFloat,
        item: MovieItem,
        isFocused: Bool = false,
        isPeeking: Bool = false
    ) -> some View {
        let radius = cardCornerRadius(forWidth: width, isLandscape: true)
        let shape = RoundedRectangle(cornerRadius: radius, style: .continuous)

        return VStack(alignment: .leading, spacing: 2) {
            ZStack(alignment: .topTrailing) {
                LinearGradient(
                    colors: item.colors,
                    startPoint: .topLeading,
                    endPoint: .bottomTrailing
                )

                if item.hasWatchedBadge && !isPeeking {
                    Circle()
                        .fill(Color(red: 0.10, green: 0.75, blue: 0.40))
                        .frame(width: 12, height: 12)
                        .overlay(
                            Image(systemName: "checkmark")
                                .font(.system(size: 7, weight: .heavy))
                                .foregroundColor(.white)
                        )
                        .padding(4)
                }
            }
            .frame(width: width, height: height)
            .clipShape(shape)
            .modifier(
                LiquidGlassCardModifier(
                    cornerRadius: radius,
                    isFocused: isFocused,
                    isEnabled: liquidGlassCards
                )
            )
            .overlay(
                shape
                    .stroke(
                        isFocused ? AppFocusOutline.color : Color.clear,
                        lineWidth: isFocused ? 2 : 0
                    )
            )

            if posterLabels && !isPeeking {
                Text(item.title)
                    .font(.system(size: 7, weight: isFocused ? .bold : .medium))
                    .foregroundColor(isFocused ? .white : .white.opacity(0.65))
                    .lineLimit(1)
                    .frame(width: width, alignment: .leading)
            }
        }
    }
}

private struct SettingsFeatureSummaryCard: View {
    let featureName: String
    let status: String
    let actionSubtitle: String
    let accentColor: Color
    var isEntryAnchor = false
    let action: () -> Void

    var body: some View {
        VStack(alignment: .leading, spacing: 16) {
            VStack(alignment: .leading, spacing: 5) {
                Text(featureName)
                    .font(.system(size: 28, weight: .bold))
                    .foregroundColor(.white)

                Text(status)
                    .font(.system(size: 18, weight: .medium))
                    .foregroundColor(.white.opacity(0.56))
            }

            SettingsActionRow(
                title: L10n.format("tvos_settings_manage_feature", fallback: "Manage %@", featureName),
                subtitle: actionSubtitle,
                value: L10n.string("tvos_settings_open", fallback: "Open"),
                accentColor: accentColor,
                action: action
            )
            .settingsEntryAnchor(isEntryAnchor)
        }
        .padding(20)
        .frame(maxWidth: .infinity, alignment: .leading)
        .settingsGlass(shape: RoundedRectangle(cornerRadius: 30, style: .continuous), isProminent: false)
        .overlay(
            RoundedRectangle(cornerRadius: 30, style: .continuous)
                .strokeBorder(Color.white.opacity(0.12), lineWidth: 1)
        )
    }
}

/// Settings → Playback → Stream List: every size of the stream list on the left, and on the
/// right the list itself with sample streams, as it will look.
private struct StreamListStyleEditor: View {
    let accentColor: Color

    @Environment(\.dismiss) private var dismiss
    @AppStorage(SettingsKey.amoled) private var amoled = false
    @AppStorage(SettingsKey.bodyColor) private var bodyColor = SettingsBackground.charcoal.rawValue

    @AppStorage(SettingsKey.streamListTextScale) private var textScale = 100
    @AppStorage(SettingsKey.streamListDetailSize) private var detailSize = StreamListStyle.Step.standard.rawValue
    @AppStorage(SettingsKey.streamListBadgeSize) private var badgeSize = StreamListStyle.Step.standard.rawValue
    @AppStorage(SettingsKey.streamListLogoSize) private var logoSize = StreamListStyle.Step.standard.rawValue
    @AppStorage(SettingsKey.showAddonLogo) private var showAddonLogo = false
    @AppStorage(SettingsKey.streamListCardSize) private var cardSize = StreamListStyle.CardSize.standard.rawValue
    @AppStorage(SettingsKey.streamListSpacing) private var spacing = StreamListStyle.Spacing.standard.rawValue
    @AppStorage(SettingsKey.streamListWidth) private var width = StreamListStyle.Width.standard.rawValue
    @AppStorage(SettingsKey.streamListHeight) private var height = StreamListStyle.Height.standard.rawValue
    @AppStorage(SettingsKey.streamListEpisodeHeader) private var episodeHeader = true
    @AppStorage(SettingsKey.streamListNameLines) private var nameLines = 2
    @AppStorage(SettingsKey.streamListDescriptionLines) private var descriptionLines = 6
    @AppStorage(SettingsKey.streamListExpandFocused) private var expandFocused = false

    private var style: StreamListStyle {
        StreamListStyle(
            textScale: textScale, cardSize: cardSize, width: width,
            nameLines: nameLines, descriptionLines: descriptionLines,
            episodeHeader: episodeHeader, expandFocused: expandFocused,
            detailSize: detailSize, badgeSize: badgeSize, logoSize: logoSize,
            spacing: spacing, height: height)
    }

    var body: some View {
        GeometryReader { proxy in
            let previewWidth = max(proxy.size.width - 64 - 640 - 48 - 64, 400)
            ZStack(alignment: .topLeading) {
                Color.nuvioBackground(amoled: amoled, body: bodyColor)
                    .ignoresSafeArea()

                HStack(alignment: .top, spacing: 48) {
                    ScrollView(showsIndicators: false) {
                        VStack(alignment: .leading, spacing: 14) {
                            VStack(alignment: .leading, spacing: 7) {
                                Text(L10n.string("tvos_settings_stream_list", fallback: "Stream List"))
                                    .font(.system(size: 36, weight: .bold))
                                    .foregroundColor(.white)
                                Text(L10n.string("tvos_settings_stream_list_editor_subtitle", fallback: "Every change shows in the preview at once"))
                                    .font(.system(size: 20, weight: .medium))
                                    .foregroundColor(.white.opacity(0.62))
                            }
                            .padding(.bottom, 10)

                            rows
                        }
                        .padding(.vertical, 38)
                    }
                    .frame(width: 640)
                    .focusSection()

                    VStack(alignment: .leading, spacing: 14) {
                        Text(L10n.string("tvos_settings_stream_list_preview", fallback: "Live preview · sample streams"))
                            .font(.system(size: 20, weight: .semibold))
                            .foregroundColor(.white.opacity(0.55))
                        StreamListPreview(style: style, showAddonLogo: showAddonLogo, width: previewWidth)
                    }
                    .padding(.top, 110)
                }
                .padding(.horizontal, 64)
            }
        }
        .onExitCommand { dismiss() }
    }

    @ViewBuilder
    private var rows: some View {
        SettingsOptionRow(
            title: L10n.string("tvos_settings_stream_list_text_size", fallback: "Text Size"),
            subtitle: L10n.string("tvos_settings_stream_list_text_size_subtitle", fallback: "Everything in the list, 50 % to 150 %"),
            selection: Binding(
                get: { StreamListStyle.textScaleLabel(textScale) },
                set: { textScale = StreamListStyle.textScale(fromLabel: $0) }),
            options: StreamListStyle.textScales.map(StreamListStyle.textScaleLabel),
            accentColor: accentColor,
            optionLabel: { $0 }
        )

        stepRow(
            title: L10n.string("tvos_settings_stream_list_detail_size", fallback: "Details Size"),
            subtitle: L10n.string("tvos_settings_stream_list_detail_size_subtitle", fallback: "The file name and details against the name"),
            value: $detailSize)

        stepRow(
            title: L10n.string("tvos_settings_stream_list_badge_size", fallback: "Badge Size"),
            subtitle: L10n.string("tvos_settings_stream_list_badge_size_subtitle", fallback: "Imported badges and the file size"),
            value: $badgeSize)

        SettingsOptionRow(
            title: L10n.string("tvos_settings_addon_logo", fallback: "Add-on Logo"),
            subtitle: L10n.string("tvos_settings_stream_list_logo_subtitle", fallback: "The source add-on's logo beside each stream, and its size"),
            selection: Binding(
                get: { showAddonLogo ? (StreamListStyle.Step(rawValue: logoSize) ?? .standard).label : "Off" },
                set: { label in
                    if let step = StreamListStyle.Step.allCases.first(where: { $0.label == label }) {
                        showAddonLogo = true
                        logoSize = step.rawValue
                    } else {
                        showAddonLogo = false
                    }
                }),
            options: ["Off"] + StreamListStyle.Step.allCases.map(\.label),
            accentColor: accentColor
        )

        SettingsOptionRow(
            title: L10n.string("tvos_settings_stream_list_card_size", fallback: "Card Size"),
            subtitle: L10n.string("tvos_settings_stream_list_card_size_subtitle", fallback: "Compact fits more streams on screen"),
            selection: labelBinding($cardSize, StreamListStyle.CardSize.allCases, \.label),
            options: StreamListStyle.CardSize.allCases.map(\.label),
            accentColor: accentColor
        )

        SettingsOptionRow(
            title: L10n.string("tvos_settings_stream_list_spacing", fallback: "Spacing"),
            subtitle: L10n.string("tvos_settings_stream_list_spacing_subtitle", fallback: "Space between the lines of a card"),
            selection: labelBinding($spacing, StreamListStyle.Spacing.allCases, \.label),
            options: StreamListStyle.Spacing.allCases.map(\.label),
            accentColor: accentColor
        )

        SettingsOptionRow(
            title: L10n.string("tvos_settings_stream_list_width", fallback: "List Width"),
            subtitle: L10n.string("tvos_settings_stream_list_width_subtitle", fallback: "Wide narrows the summary, Full leaves it out"),
            selection: labelBinding($width, StreamListStyle.Width.allCases, \.label),
            options: StreamListStyle.Width.allCases.map(\.label),
            accentColor: accentColor
        )

        SettingsOptionRow(
            title: L10n.string("tvos_settings_stream_list_height", fallback: "List Height"),
            subtitle: L10n.string("tvos_settings_stream_list_height_subtitle", fallback: "Tall and Full use more of the screen"),
            selection: labelBinding($height, StreamListStyle.Height.allCases, \.label),
            options: StreamListStyle.Height.allCases.map(\.label),
            accentColor: accentColor
        )

        SettingsToggleRow(
            title: L10n.string("tvos_settings_stream_list_episode_header", fallback: "Episode Info Above the List"),
            subtitle: L10n.string("tvos_settings_stream_list_episode_header_subtitle", fallback: "With Full width: the logo and the episode between the add-ons and the first stream"),
            isOn: $episodeHeader,
            accentColor: accentColor,
            enabled: width == StreamListStyle.Width.full.rawValue
        )

        SettingsOptionRow(
            title: L10n.string("tvos_settings_stream_list_name_lines", fallback: "Name Lines"),
            subtitle: L10n.string("tvos_settings_stream_list_name_lines_subtitle", fallback: "Lines of the stream name before it is cut"),
            selection: Binding(
                get: { StreamListStyle.linesLabel(nameLines) },
                set: { nameLines = StreamListStyle.lines(fromLabel: $0) }),
            options: StreamListStyle.nameLineChoices.map(StreamListStyle.linesLabel),
            accentColor: accentColor
        )

        SettingsOptionRow(
            title: L10n.string("tvos_settings_stream_list_description_lines", fallback: "Description Lines"),
            subtitle: L10n.string("tvos_settings_stream_list_description_lines_subtitle", fallback: "The file name and details under it"),
            selection: Binding(
                get: { StreamListStyle.linesLabel(descriptionLines) },
                set: { descriptionLines = StreamListStyle.lines(fromLabel: $0) }),
            options: StreamListStyle.descriptionLineChoices.map(StreamListStyle.linesLabel),
            accentColor: accentColor
        )

        SettingsToggleRow(
            title: L10n.string("tvos_settings_stream_list_expand_focused", fallback: "Expand Focused Card (Experimental)"),
            subtitle: L10n.string("tvos_settings_stream_list_expand_focused_subtitle", fallback: "The selected stream shows its whole name and description"),
            isOn: $expandFocused,
            accentColor: accentColor
        )

        SettingsActionRow(
            title: L10n.string("tvos_settings_stream_list_reset", fallback: "Reset to Defaults"),
            subtitle: L10n.string("tvos_settings_stream_list_reset_subtitle", fallback: "The list as it was, add-on logo off"),
            value: L10n.string("tvos_settings_reset", fallback: "Reset"),
            accentColor: accentColor,
            action: reset
        )
    }

    private func stepRow(title: String, subtitle: String, value: Binding<String>) -> some View {
        SettingsOptionRow(
            title: title,
            subtitle: subtitle,
            selection: labelBinding(value, StreamListStyle.Step.allCases, \.label),
            options: StreamListStyle.Step.allCases.map(\.label),
            accentColor: accentColor
        )
    }

    /// The stored raw value shown as its label.
    private func labelBinding<Option: RawRepresentable>(
        _ stored: Binding<String>,
        _ options: [Option],
        _ label: KeyPath<Option, String>
    ) -> Binding<String> where Option.RawValue == String {
        Binding(
            get: { (options.first { $0.rawValue == stored.wrappedValue } ?? options.first { $0.rawValue == "default" } ?? options[0])[keyPath: label] },
            set: { newLabel in
                if let option = options.first(where: { $0[keyPath: label] == newLabel }) {
                    stored.wrappedValue = option.rawValue
                }
            })
    }

    private func reset() {
        textScale = 100
        detailSize = StreamListStyle.Step.standard.rawValue
        badgeSize = StreamListStyle.Step.standard.rawValue
        logoSize = StreamListStyle.Step.standard.rawValue
        showAddonLogo = false
        cardSize = StreamListStyle.CardSize.standard.rawValue
        spacing = StreamListStyle.Spacing.standard.rawValue
        width = StreamListStyle.Width.standard.rawValue
        height = StreamListStyle.Height.standard.rawValue
        episodeHeader = true
        nameLines = 2
        descriptionLines = 6
        expandFocused = false
    }
}

private struct SettingsFeatureSettingsSheet<Content: View>: View {
    let title: String
    let subtitle: String
    @ViewBuilder let content: Content

    @Environment(\.dismiss) private var dismiss
    @AppStorage(SettingsKey.amoled) private var amoled = false
    @AppStorage(SettingsKey.bodyColor) private var bodyColor = SettingsBackground.charcoal.rawValue

    var body: some View {
        ZStack {
            Color.nuvioBackground(amoled: amoled, body: bodyColor)
                .ignoresSafeArea()

            ScrollView {
                VStack(alignment: .leading, spacing: 24) {
                    VStack(alignment: .leading, spacing: 7) {
                        Text(title)
                            .font(.system(size: 36, weight: .bold))
                            .foregroundColor(.white)

                        Text(subtitle)
                            .font(.system(size: 20, weight: .medium))
                            .foregroundColor(.white.opacity(0.62))
                    }

                    content
                }
                .frame(width: 1_000, alignment: .leading)
                .padding(.horizontal, 52)
                .padding(.vertical, 38)
            }
            .focusSection()
        }
        .onExitCommand { dismiss() }
    }
}

private func settingsCountSummary(_ count: Int, singular: String, plural: String) -> String {
    "\(count) \(count == 1 ? singular : plural)"
}

private struct LayoutDiscoverySettingsView: View {
    let accentColor: Color

    @AppStorage(SettingsKey.homeLayout) private var homeLayout = "Modern"
    @AppStorage(SettingsKey.gridRows) private var gridRows = TVHomeGridLayout.defaultRows
    @AppStorage(SettingsKey.heroEnabled) private var heroEnabled = true
    @AppStorage(SettingsKey.heroCatalogs) private var heroCatalogsData = Data()
    @AppStorage(SettingsKey.fullscreenHeroBackdrop) private var fullscreenHeroBackdrop = true
    @AppStorage(SettingsKey.homeHeroRatingsEnabled) private var homeHeroRatingsEnabled = true
    @AppStorage(SettingsKey.posterLabels) private var posterLabels = false
    @AppStorage(SettingsKey.continueWatchingLabels) private var continueWatchingLabels = CardLabelVisibility.always.rawValue
    @AppStorage(SettingsKey.catalogAddonNames) private var catalogAddonNames = true
    @AppStorage(SettingsKey.landscapePosters) private var landscapePosters = false
    @AppStorage(SettingsKey.discoverLocation) private var discoverLocation = "Search"
    @AppStorage(SettingsKey.searchStyle) private var searchStyle = "Netflix"
    @AppStorage(SettingsKey.preferAddonArtworkInSearch) private var preferAddonArtworkInSearch = true
    @AppStorage(SettingsKey.continueWatchingVisible) private var continueWatchingVisible = true
    @AppStorage(SettingsKey.continueWatchingLandscape) private var continueWatchingLandscape = false
    @AppStorage(SettingsKey.continueWatchingSort) private var continueWatchingSort = "Default"
    @AppStorage(SettingsKey.upNextFromFurthestEpisode) private var upNextFromFurthestEpisode = true
    @AppStorage(SettingsKey.showUnairedNextUp) private var showUnairedNextUp = true
    @AppStorage(SettingsKey.continueWatchingEpisodeRatings) private var continueWatchingEpisodeRatings = AddonRatingsService.defaultEpisodeRatingsOption
    @AppStorage(SettingsKey.continueWatchingBlurNextUp) private var continueWatchingBlurNextUp = false
    @AppStorage(SettingsKey.blurUnwatchedEpisodes) private var blurUnwatchedEpisodes = false
    @AppStorage(SettingsKey.hideUnwatchedEpisodeDescriptions) private var hideUnwatchedEpisodeDescriptions = false
    @AppStorage(SettingsKey.hideUnwatchedEpisodeTitles) private var hideUnwatchedEpisodeTitles = false
    @AppStorage(SettingsKey.homeCalendarToday) private var homeCalendarToday = true
    @AppStorage(SettingsKey.hideUnreleased) private var hideUnreleased = false
    @AppStorage(SettingsKey.showFullDates) private var showFullDates = true
    @AppStorage(SettingsKey.focusedPosterBackdropEnabled) private var focusedPosterBackdropEnabled = true
    @AppStorage(SettingsKey.focusedPosterBackdropDelay) private var focusedPosterBackdropDelay = 3
    @AppStorage(SettingsKey.detailsActionsBelowInfo) private var detailsActionsBelowInfo = false
    @State private var showingHomeCatalogOrderSettings = false
    @State private var showingCollectionsSettings = false
    @State private var showingDetailsSectionsSettings = false
    @State private var homeCatalogSummaryCount = 0
    @State private var collectionsSummaryCount = 0
    @State private var detailsSectionsActiveCount = TVDetailsSectionOrder.activeSectionCount()

    /// Classic was never a distinct layout (behaved like Modern).
    private let layouts = ["Modern", "Grid View", "Compact"]
    // Search is the only screen that currently hosts the full Discover surface.
    // Do not offer Home/Library as dead selections that merely hide Discover.
    private let discoverLocations = ["Search", "Off"]
    private let searchStyles = ["Netflix", "Classic", "Native", "Grid"]
    private let continueWatchingSorts = ["Default", "Streaming Style", "Separate Upcoming Row"]

    var body: some View {
        VStack(alignment: .leading, spacing: 22) {
            SettingsGroup(
                title: L10n.string("tvos_layout_home", fallback: "Home Layout"),
                subtitle: L10n.string(
                    "tvos_layout_home_subtitle",
                    fallback: "How the home screen presents rows and artwork"
                )
            ) {
                HomeLayoutLivePreview(
                    layout: homeLayout,
                    heroEnabled: heroEnabled,
                    fullscreenHeroBackdrop: fullscreenHeroBackdrop,
                    heroRatingsEnabled: homeHeroRatingsEnabled,
                    posterLabels: posterLabels,
                    catalogAddonNames: catalogAddonNames,
                    landscapePosters: landscapePosters,
                    gridRows: gridRows,
                    accentColor: accentColor
                )

                SettingsOptionRow(
                    title: L10n.string("tvos_layout_layout", fallback: "Layout"),
                    subtitle: L10n.string(
                        "tvos_layout_layout_subtitle",
                        fallback: "Modern and Compact use rows; Grid View shows each catalog in a poster grid"
                    ),
                    selection: $homeLayout,
                    options: layouts,
                    accentColor: accentColor
                )
                .settingsEntryAnchor()
                .onAppear {
                    if homeLayout == "Classic" { homeLayout = "Modern" }
                }

                SettingsToggleRow(
                    title: L10n.string("tvos_layout_hero", fallback: "Hero Section"),
                    subtitle: L10n.string(
                        "tvos_layout_hero_subtitle",
                        fallback: "Show featured artwork above catalog rows"
                    ),
                    isOn: $heroEnabled,
                    accentColor: accentColor
                )

                if homeLayout == "Grid View" {
                    HeroCatalogSelectionRow(
                        selectionData: $heroCatalogsData,
                        accentColor: accentColor
                    )
                    .transition(.opacity.combined(with: .move(edge: .top)))

                    SettingsStepperRow(
                        title: L10n.string(
                            "tvos_layout_grid_rows",
                            fallback: "Grid Rows"
                        ),
                        subtitle: L10n.string(
                            "tvos_layout_grid_rows_subtitle",
                            fallback: "Number of movie and TV show rows displayed per catalog (1–10)"
                        ),
                        value: $gridRows,
                        range: TVHomeGridLayout.minRows...TVHomeGridLayout.maxRows,
                        step: 1,
                        suffix: gridRows == 1 ? " row" : " rows",
                        accentColor: accentColor
                    )
                    .transition(.opacity.combined(with: .move(edge: .top)))
                }

                SettingsToggleRow(
                    title: L10n.string(
                        "layout_fullscreen_hero_backdrop",
                        fallback: "Fullscreen Hero Backdrop"
                    ),
                    subtitle: L10n.string(
