                    isOn: $fullscreenHeroBackdrop,
                    accentColor: accentColor
                )
                .opacity(heroEnabled ? 1 : 0.46)
                .disabled(!heroEnabled)

                SettingsToggleRow(
                    title: L10n.string("tvos_layout_hero_ratings", fallback: "Hero Ratings"),
                    subtitle: L10n.string(
                        "tvos_layout_hero_ratings_subtitle",
                        fallback: "Show enabled rating providers in the order set in Rating Providers & Order"
                    ),
                    isOn: $homeHeroRatingsEnabled,
                    accentColor: accentColor
                )
                .opacity(heroEnabled ? 1 : 0.46)
                .disabled(!heroEnabled)

                SettingsOptionRow(
                    title: L10n.string("tvos_layout_continue_labels", fallback: "Continue Watching Labels"),
                    subtitle: L10n.string("tvos_layout_continue_labels_subtitle",
                                          fallback: "When episode, time-left, and next-up labels appear on cards"),
                    selection: $continueWatchingLabels,
                    options: CardLabelVisibility.allCases.map(\.rawValue),
                    accentColor: accentColor,
                    optionLabel: { L10n.optionLabel(CardLabelVisibility(rawValue: $0)?.label ?? $0) }
                )

                SettingsToggleRow(
                    title: L10n.string("tvos_layout_poster_labels", fallback: "Poster Labels"),
                    subtitle: L10n.string(
                        "tvos_layout_poster_labels_subtitle",
                        fallback: "Show titles below poster cards"
                    ),
                    isOn: $posterLabels,
                    accentColor: accentColor
                )

                SettingsToggleRow(
                    title: L10n.string(
                        "tvos_layout_catalog_addon_names",
                        fallback: "Catalog Add-on Names"
                    ),
                    subtitle: L10n.string(
                        "tvos_layout_catalog_addon_names_subtitle",
                        fallback: "Show source add-on names beside catalog titles"
                    ),
                    isOn: $catalogAddonNames,
                    accentColor: accentColor
                )

                SettingsToggleRow(
                    title: L10n.string("layout_landscape_posters", fallback: "Landscape Posters"),
                    subtitle: L10n.string(
                        "layout_landscape_posters_sub",
                        fallback: "Switch between portrait and landscape cards for Modern view."
                    ),
                    isOn: $landscapePosters,
                    accentColor: accentColor
                )

            }

            SettingsGroup(
                title: L10n.string("tvos_settings_focused_poster", fallback: "Focused Poster"),
                subtitle: L10n.string(
                    "tvos_settings_focused_poster_description",
                    fallback: "Expand focused posters into backdrop cards"
                )
            ) {
                SettingsToggleRow(
                    title: L10n.string(
                        "tvos_settings_expand_focused_poster_to_backdrop",
                        fallback: "Expand Focused Poster to Backdrop"
                    ),
                    subtitle: L10n.string(
                        "tvos_settings_expand_focused_poster_after_idle_delay",
                        fallback: "Expand focused poster after idle delay"
                    ),
                    isOn: $focusedPosterBackdropEnabled,
                    accentColor: accentColor
                )

                SettingsStepperRow(
                    title: L10n.string(
                        "tvos_settings_backdrop_expand_delay",
                        fallback: "Backdrop Expand Delay"
                    ),
                    subtitle: L10n.string(
                        "tvos_settings_how_long_before_expanding_focused_cards",
                        fallback: "How long to wait before expanding focused cards"
                    ),
                    value: $focusedPosterBackdropDelay,
                    range: 0...10,
                    step: 1,
                    suffix: "s",
                    accentColor: accentColor
                )
                .opacity(focusedPosterBackdropEnabled ? 1 : 0.46)
                .disabled(!focusedPosterBackdropEnabled)
            }

            SettingsFeatureSummaryCard(
                featureName: L10n.string("tvos_settings_home_catalogs", fallback: "Home Catalogs"),
                status: settingsCountSummary(homeCatalogSummaryCount, singular: "catalog row", plural: "catalog rows"),
                actionSubtitle: L10n.string("tvos_settings_home_catalogs_open_subtitle", fallback: "Reorder, refresh, and manage Home catalog rows"),
