        )
        _traktClientSecret = AppStorage(
            wrappedValue: storedTraktClientSecret,
            SettingsKey.traktClientSecret,
            store: profileStore
        )
        _traktRedirectURI = AppStorage(
            wrappedValue: storedTraktRedirectURI,
