/// Full-screen-style device login: large QR + activation code + auto-poll.
private struct TraktDeviceLoginSheet: View {
    @ObservedObject var viewModel: TraktSettingsViewModel
    let accentColor: Color
    @Environment(\.dismiss) private var dismiss

    private var activationURL: String {
        if let code = viewModel.deviceUserCode, !code.isEmpty {
            return "https://trakt.tv/activate/\(code)"
        }
        return viewModel.verificationURL ?? "https://trakt.tv/activate"
    }

    var body: some View {
        VStack(spacing: 28) {
            Text(viewModel.mode == .connected ? L10n.string("tvos_settings_trakt_connected", fallback: "Trakt Connected") : L10n.string("tvos_settings_connect_trakt", fallback: "Connect Trakt"))
                .font(.system(size: 42, weight: .regular))
                .foregroundColor(.white)

            if viewModel.mode == .connected {
                if let displayName = viewModel.resolvedDisplayName {
                    Text(L10n.format("tvos_settings_signed_in_as", fallback: "Signed in as %@", displayName))
                        .font(.system(size: 23, weight: .medium))
                        .foregroundColor(.white.opacity(0.66))
                        .multilineTextAlignment(.center)
                } else {
                    Text(L10n.string(
                        "tvos_settings_this_apple_tv_is_linked_to_trakt",
                        fallback: "This Apple TV is linked to Trakt."
                    ))
                    .font(.system(size: 23, weight: .medium))
                    .foregroundColor(.white.opacity(0.66))
                    .multilineTextAlignment(.center)
                }
                dialogButton(title: L10n.string("tvos_settings_done", fallback: "Done"), isPrimary: true) { dismiss() }
            } else if viewModel.deviceUserCode == nil && viewModel.errorMessage == nil {
                ProgressView()
                    .controlSize(.large)
                    .tint(.white)
                    .frame(height: 320)
                Text(viewModel.statusMessage ?? L10n.string("tvos_settings_starting_trakt_login", fallback: "Starting Trakt login…"))
                    .font(.system(size: 20, weight: .medium))
                    .foregroundColor(.white.opacity(0.64))
                dialogButton(title: L10n.string("action_cancel", fallback: "Cancel"), isPrimary: false) {
                    viewModel.cancelDeviceFlow()
                    dismiss()
                }
            } else if let code = viewModel.deviceUserCode, !code.isEmpty {
                Text(L10n.string("tvos_settings_trakt_qr_scan_hint", fallback: "Scan the QR on your phone, or open trakt.tv/activate and enter the code."))
                    .font(.system(size: 23, weight: .medium))
                    .foregroundColor(.white.opacity(0.68))
                    .multilineTextAlignment(.center)
                    .fixedSize(horizontal: false, vertical: true)

                if let image = QRCode.image(from: activationURL, scale: 10) {
                    Image(uiImage: image)
                        .interpolation(.none)
                        .resizable()
                        .frame(width: 300, height: 300)
                        .padding(16)
                        .background(Color.white, in: RoundedRectangle(cornerRadius: 24, style: .continuous))
                }

                VStack(spacing: 12) {
                    Text(code)
                        .font(.system(size: 54, weight: .bold, design: .rounded))
                        .tracking(4)
                        .foregroundColor(.white)
                        .accessibilityLabel(
                            L10n.format(
                                "tvos_settings_trakt_activation_code",
                                fallback: "Trakt activation code %@",
                                code
                            )
                        )
                    Text(activationURL)
                        .font(.system(size: 20, weight: .medium))
                        .foregroundColor(.white.opacity(0.54))
                        .lineLimit(1)
                }

                HStack(spacing: 10) {
                    if viewModel.isPolling { ProgressView().tint(.white) }
                    Text(viewModel.statusMessage ?? L10n.string("trakt_waiting_approval", fallback: "Waiting for approval…"))
                        .font(.system(size: 20, weight: .medium))
                        .foregroundColor(.white.opacity(0.64))
                }

                if let error = viewModel.errorMessage, !error.isEmpty {
                    Text(error)
                        .font(.system(size: 20, weight: .semibold))
                        .foregroundColor(Color(red: 1.0, green: 0.43, blue: 0.43))
                        .multilineTextAlignment(.center)
                }

                HStack(spacing: 18) {
                    dialogButton(title: L10n.string("action_cancel", fallback: "Cancel"), isPrimary: false) {
                        viewModel.cancelDeviceFlow()
                        dismiss()
                    }
                    dialogButton(title: L10n.string("action_retry", fallback: "Retry"), isPrimary: true) {
                        viewModel.cancelDeviceFlow()
                        viewModel.connect()
                    }
                }
            } else {
                Text(viewModel.errorMessage ?? L10n.string("tvos_settings_unable_to_start_trakt_login", fallback: "Unable to start Trakt login."))
                    .font(.system(size: 22, weight: .medium))
                    .foregroundColor(Color(red: 1.0, green: 0.43, blue: 0.43))
                    .multilineTextAlignment(.center)
                HStack(spacing: 18) {
                    dialogButton(title: L10n.string("action_close", fallback: "Close"), isPrimary: false) { dismiss() }
                    dialogButton(title: L10n.string("action_retry", fallback: "Retry"), isPrimary: true) { viewModel.connect() }
                }
            }
        }
        .frame(width: 960)
        .padding(.horizontal, 88)
        .padding(.vertical, 64)
        .onAppear {
            if viewModel.mode != .connected && viewModel.deviceUserCode == nil {
                viewModel.connect()
            } else if viewModel.mode == .awaitingApproval {
                viewModel.retryPolling()
            }
        }
        .onChange(of: viewModel.mode) { _, mode in
            if mode == .connected {
                // Brief success state then close.
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                    dismiss()
                }
            }
        }
    }

    @ViewBuilder
    private func dialogButton(title: String, isPrimary: Bool, action: @escaping () -> Void) -> some View {
        ProviderLoginGlassButton(title: title, isPrimary: isPrimary, action: action)
    }
}

private struct SimklConnectionSettingsCard: View {
    @ObservedObject var viewModel: SimklSettingsViewModel
    let accentColor: Color
    let credentialsReady: Bool
    let onStartLogin: () -> Void
    let onOpenSettings: () -> Void

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack(alignment: .top, spacing: 18) {
                ZStack {
                    RoundedRectangle(cornerRadius: 18, style: .continuous)
                        .fill(Color(red: 0.08, green: 0.55, blue: 0.82))
                    Text("SIMKL")
                        .font(.system(size: 21, weight: .black))
                        .foregroundColor(.white)
                }
                .frame(width: 92, height: 62)

                VStack(alignment: .leading, spacing: 8) {
                    Text(statusTitle)
                        .font(.system(size: 24, weight: .bold))
                        .foregroundColor(.white)

                    Text(statusSubtitle)
                        .font(.system(size: 18, weight: .medium))
                        .foregroundColor(.white.opacity(0.62))
                        .fixedSize(horizontal: false, vertical: true)
                }

                Spacer(minLength: 16)
            }

            switch viewModel.mode {
            case .disconnected, .awaitingApproval:
                SettingsActionRow(
                    title: viewModel.mode == .awaitingApproval
                        ? L10n.string("tvos_settings_continue_simkl_login", fallback: "Continue Simkl Login")
                        : L10n.string("tvos_settings_connect_with_simkl", fallback: "Connect with Simkl"),
                    subtitle: credentialsReady
                        ? L10n.string("tvos_settings_simkl_scan_qr_hint", fallback: "Scan the QR or enter the PIN at simkl.com/pin")
                        : L10n.string("tvos_settings_simkl_enter_credentials_first", fallback: "Enter your Simkl Client ID first"),
                    value: viewModel.mode == .awaitingApproval
                        ? L10n.string("tvos_settings_resume", fallback: "Resume")
                        : L10n.string("tvos_settings_connect", fallback: "Connect"),
                    accentColor: accentColor
                ) {
                    onStartLogin()
                }
                .opacity(credentialsReady ? 1 : 0.5)
                .disabled(!credentialsReady)
            case .connected:
                SettingsActionRow(
                    title: L10n.string("tvos_settings_simkl_account_title", fallback: "Simkl Account"),
                    subtitle: L10n.string("tvos_settings_simkl_account_subtitle", fallback: "View the connected account or disconnect this profile"),
                    value: L10n.string("tvos_settings_open", fallback: "Open"),
                    accentColor: accentColor,
                    action: onOpenSettings
                )
            }

            if viewModel.mode == .connected && viewModel.isLegacyV1 {
                Text("Using legacy V1 Client ID. Register a V2 app at simkl.com/settings/developer and enter its Client ID above to enable OAuth 2.0.")
                    .font(.system(size: 16, weight: .medium))
                    .foregroundColor(Color(red: 1.0, green: 0.75, blue: 0.2))
            }

            if let message = viewModel.statusMessage,
               !message.isEmpty,
               viewModel.mode == .connected {
                Text(message)
                    .font(.system(size: 17, weight: .medium))
                    .foregroundColor(.white.opacity(0.62))
            }

            if let error = viewModel.errorMessage,
               !error.isEmpty,
               viewModel.mode != .awaitingApproval {
                Text(error)
                    .font(.system(size: 17, weight: .semibold))
                    .foregroundColor(Color(red: 1.0, green: 0.43, blue: 0.43))
            }
        }
    }

    private var statusTitle: String {
        switch viewModel.mode {
        case .disconnected:
            return L10n.string("tvos_settings_not_connected", fallback: "Not connected")
        case .awaitingApproval:
            return L10n.string("tvos_settings_waiting_for_approval", fallback: "Waiting for approval")
        case .connected:
            let name = viewModel.username?.isEmpty == false
                ? (viewModel.username ?? "Simkl User")
                : "Simkl User"
            return L10n.format("tvos_settings_connected_as_user", fallback: "Connected as %@", name)
        }
    }

    private var statusSubtitle: String {
        switch viewModel.mode {
        case .disconnected:
            return L10n.string("tvos_settings_simkl_qr_hint", fallback: "Connect with a QR code and PIN at simkl.com/pin.")
        case .awaitingApproval:
            return L10n.string("tvos_settings_simkl_finish_approving", fallback: "Finish approving this Apple TV in Simkl, or resume the login sheet.")
        case .connected:
            return L10n.string("tvos_settings_simkl_connected_profile", fallback: "This profile is connected to Simkl.")
        }
    }
}

private struct MdbListConnectionSettingsCard: View {
    @ObservedObject var viewModel: MdbListSettingsViewModel
    let accentColor: Color
    let onStartLogin: () -> Void
    let onOpenSettings: () -> Void

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack(alignment: .top, spacing: 18) {
                ZStack {
                    RoundedRectangle(cornerRadius: 18, style: .continuous)
                        .fill(
                            LinearGradient(
                                colors: [
                                    Color(red: 0.10, green: 0.34, blue: 0.24),
                                    Color(red: 0.12, green: 0.23, blue: 0.18)
                                ],
                                startPoint: .topLeading,
                                endPoint: .bottomTrailing
                            )
                        )
                    Text("MDBList")
                        .font(.system(size: 19, weight: .black))
                        .foregroundColor(.white)
                }
                .frame(width: 112, height: 62)

                VStack(alignment: .leading, spacing: 8) {
                    Text(statusTitle)
                        .font(.system(size: 24, weight: .bold))
                        .foregroundColor(.white)

                    Text(statusSubtitle)
                        .font(.system(size: 18, weight: .medium))
                        .foregroundColor(.white.opacity(0.62))
                        .fixedSize(horizontal: false, vertical: true)
                }

                Spacer(minLength: 16)
            }

            switch viewModel.mode {
            case .disconnected, .awaitingApproval:
                SettingsActionRow(
                    title: viewModel.mode == .awaitingApproval
                        ? "Continue MDBList Login"
                        : "Connect MDBList Account",
                    subtitle: viewModel.hasAPIKey
                        ? "An API key is available for playback; account login adds account status and renewable access."
                        : "Scan the QR code and approve MDBList on your phone.",
                    value: viewModel.mode == .awaitingApproval ? "Resume" : "Connect",
                    accentColor: accentColor
                ) {
                    onStartLogin()
                }
            case .connected:
                SettingsActionRow(
                    title: "MDBList Account",
                    subtitle: "Manage playback, watched history, and the connected account.",
                    value: "Open",
                    accentColor: accentColor,
                    action: onOpenSettings
                )
            }

            if let message = viewModel.statusMessage, !message.isEmpty, viewModel.mode == .connected {
                Text(message)
                    .font(.system(size: 17, weight: .medium))
                    .foregroundColor(.white.opacity(0.62))
            }

            if let error = viewModel.errorMessage, !error.isEmpty, viewModel.mode != .awaitingApproval {
                Text(error)
                    .font(.system(size: 17, weight: .semibold))
                    .foregroundColor(Color(red: 1.0, green: 0.43, blue: 0.43))
            }
        }
    }

    private var statusTitle: String {
        switch viewModel.mode {
        case .disconnected:
            return viewModel.hasAPIKey ? "API key ready" : "Not connected"
        case .awaitingApproval:
            return "Waiting for approval"
        case .connected:
            let name = viewModel.displayName?.isEmpty == false
                ? (viewModel.displayName ?? "MDBList User")
                : (viewModel.username ?? "MDBList User")
            return "Connected as \(name)"
        }
    }

    private var statusSubtitle: String {
        switch viewModel.mode {
        case .disconnected:
            return "MDBList can provide remote Continue Watching and watched-state sync."
        case .awaitingApproval:
            return "Finish approving this Apple TV in MDBList, or resume the login sheet."
        case .connected:
            return "This profile can use MDBList-backed playback and watched history."
        }
    }
}

private struct MdbListConnectedSettingsSheet: View {
    @ObservedObject var viewModel: MdbListSettingsViewModel
    let accentColor: Color

    @Environment(\.dismiss) private var dismiss
    @AppStorage(SettingsKey.amoled) private var amoled = false
    @AppStorage(SettingsKey.bodyColor) private var bodyColor = SettingsBackground.charcoal.rawValue
    @State private var showingDisconnectConfirmation = false

    var body: some View {
        ZStack {
            Color.nuvioBackground(amoled: amoled, body: bodyColor)
                .ignoresSafeArea()

            VStack(spacing: 0) {
                ScrollView {
                    VStack(alignment: .leading, spacing: 24) {
                        VStack(alignment: .leading, spacing: 7) {
                            Text("MDBList")
                                .font(.system(size: 36, weight: .bold))
                                .foregroundColor(.white)

                            Text(connectedUsername.isEmpty == false
                                ? L10n.format("tvos_settings_simkl_manage_user_desc", fallback: "Connected as %@. Manage sync and account options.", connectedUsername)
                                : L10n.string("tvos_settings_simkl_manage_desc", fallback: "Manage MDBList sync and account options."))
                                .font(.system(size: 20, weight: .medium))
                                .foregroundColor(.white.opacity(0.62))
                        }

                        SettingsGroup(
                            title: L10n.string("account_title", fallback: "Account"),
                            subtitle: L10n.string("tvos_settings_mdblist_account_info_subtitle", fallback: "Account information returned by MDBList")
                        ) {
                            if let username = viewModel.username, !username.isEmpty {
                                SettingsInfoRow(title: L10n.string("account_username", fallback: "Username"), value: username)
                            }
                            if let displayName = viewModel.displayName, !displayName.isEmpty, displayName != viewModel.username {
                                SettingsInfoRow(title: "Display Name", value: displayName)
                            }
                            if let accountID = viewModel.accountID, !accountID.isEmpty {
                                SettingsInfoRow(title: L10n.string("account_id", fallback: "Account ID"), value: accountID)
                            }
                            SettingsInfoRow(
                                title: "Auth Protocol",
                                value: viewModel.hasAPIKey && viewModel.mode != .connected ? "API Key" : "OAuth 2.0 (Device Flow)"
                            )
                        }

                        SettingsGroup(
                            title: L10n.string("tvos_settings_watch_stats", fallback: "Watch Stats"),
                            subtitle: L10n.string("tvos_settings_mdblist_watch_stats_subtitle", fallback: "Watched activity returned from your MDBList account")
                        ) {
                            MdbListConnectedStatsStrip(
                                stats: viewModel.connectedStats,
                                isLoading: viewModel.isStatsLoading
                            )

                            SettingsActionRow(
                                title: L10n.string("tvos_settings_sync_now", fallback: "Sync Now"),
                                subtitle: L10n.string("tvos_settings_mdblist_sync_watch_stats_subtitle", fallback: "Refresh MDBList watch progress, account information, and watch stats"),
                                value: (viewModel.isLoading || viewModel.isStatsLoading)
                                    ? L10n.string("tvos_settings_syncing", fallback: "Syncing")
                                    : L10n.string("tvos_settings_refresh", fallback: "Refresh"),
                                accentColor: accentColor
                            ) {
                                viewModel.refreshNow()
                            }
                            .disabled(viewModel.isLoading || viewModel.isStatsLoading)
                        }

                        SettingsGroup(
                            title: L10n.string("tvos_settings_mdblist_features", fallback: "MDBList Features"),
                            subtitle: L10n.string("tvos_settings_mdblist_features_subtitle", fallback: "Choose where playback, watched updates, and the Library are stored")
                        ) {
                            SettingsToggleRow(
                                title: L10n.string("tvos_settings_mdblist_scrobble", fallback: "Scrobble Playback"),
                                subtitle: L10n.string(
                                    "tvos_settings_mdblist_scrobble_sheet_subtitle",
                                    fallback: "Send playback progress and watched updates to your MDBList account"
                                ),
                                isOn: Binding(
                                    get: { RemoteTrackingState.isScrobbleEnabled(for: .mdblist) },
                                    set: { RemoteTrackingState.setScrobbleEnabled($0, for: .mdblist) }
                                ),
                                accentColor: accentColor
                            )

                            SettingsChoiceRow(
                                title: L10n.string("trakt_library_source_dialog_title", fallback: "Library Source"),
                                subtitle: L10n.string("tvos_settings_mdblist_library_source_subtitle", fallback: "Use MDBList collection and watchlist as your Nuvio library"),
                                selection: librarySourceSelection,
                                options: RemoteTrackingState.availableLibrarySources().map(\.label),
                                accentColor: accentColor
                            )

                            SettingsChoiceRow(
                                title: L10n.string("trakt_watch_progress_dialog_title", fallback: "Watch Progress"),
                                subtitle: L10n.string("tvos_settings_mdblist_watch_progress_subtitle", fallback: "Use MDBList for remote playback progress and watched updates"),
                                selection: watchProgressSelection,
                                options: RemoteTrackingState.availableProgressSources().map(\.label),
                                accentColor: accentColor
                            )
                        }

                        SettingsGroup(
                            title: L10n.string("account_login", fallback: "Account Login"),
                            subtitle: L10n.string("tvos_settings_mdblist_account_login_subtitle", fallback: "Manage the MDBList connection for this Nuvio profile")
                        ) {
                            SettingsActionRow(
                                title: L10n.string("debrid_disconnect", fallback: "Disconnect"),
                                subtitle: L10n.string("tvos_settings_mdblist_disconnect_subtitle", fallback: "Remove this profile's MDBList tokens from this Apple TV"),
                                value: L10n.string("debrid_disconnect", fallback: "Disconnect"),
                                accentColor: accentColor
                            ) {
                                showingDisconnectConfirmation = true
                            }
                            .disabled(viewModel.isLoading || viewModel.isStatsLoading)
                        }

                        if let message = viewModel.statusMessage, !message.isEmpty {
                            Text(message)
                                .font(.system(size: 18, weight: .medium))
                                .foregroundColor(.white.opacity(0.62))
                        }
                        if let error = viewModel.errorMessage, !error.isEmpty {
                            Text(error)
                                .font(.system(size: 18, weight: .semibold))
                                .foregroundColor(.red.opacity(0.9))
                        }
                    }
                    .frame(width: 1_000, alignment: .leading)
                    .padding(.horizontal, 52)
                    .padding(.vertical, 38)
                }
                .focusSection()
            }
        }
        .onExitCommand { dismiss() }
        .task {
            viewModel.reload()
            viewModel.loadConnectedData()
        }
        .onChange(of: viewModel.mode) { _, mode in
            if mode != .connected { dismiss() }
        }
        .confirmationDialog(
            "Disconnect MDBList?",
            isPresented: $showingDisconnectConfirmation,
            titleVisibility: .visible
        ) {
            Button(L10n.string("debrid_disconnect", fallback: "Disconnect"), role: .destructive) {
                viewModel.disconnect()
            }
            Button(L10n.string("action_cancel", fallback: "Cancel"), role: .cancel) {}
        }
    }

    private var connectedUsername: String {
        let username = (viewModel.displayName ?? viewModel.username ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return username.isEmpty ? "MDBList User" : username
    }

    private var watchProgressSelection: Binding<String> {
        Binding(
            get: { TraktSettingsStore.watchProgressSource.label },
            set: { label in
                TraktSettingsStore.markWatchProgressSourceChosenByUser()
                TraktSettingsStore.watchProgressSource =
                    TraktWatchProgressSource.allCases.first { $0.label == label } ?? .mdblist
            }
        )
    }

    private var librarySourceSelection: Binding<String> {
        Binding(
            get: { TraktSettingsStore.librarySourceMode.label },
            set: { label in
                TraktSettingsStore.librarySourceMode =
                    TraktLibrarySourceMode.allCases.first { $0.label == label } ?? .local
            }
        )
    }

}

private struct MdbListDeviceLoginSheet: View {
    @ObservedObject var viewModel: MdbListSettingsViewModel
    let accentColor: Color

    @Environment(\.dismiss) private var dismiss

    private var activationURL: String {
        viewModel.verificationURL ?? MdbListConfig.deviceLoginURL
    }

    var body: some View {
        VStack(spacing: 28) {
            Text(viewModel.mode == .connected ? "MDBList Connected" : "Connect MDBList")
                .font(.system(size: 42, weight: .regular))
                .foregroundColor(.white)

            if viewModel.mode == .connected {
                Text((viewModel.displayName ?? viewModel.username).map { "Signed in as \($0)" } ?? "This Apple TV is linked to MDBList.")
                    .font(.system(size: 23, weight: .medium))
                    .foregroundColor(.white.opacity(0.66))
                    .multilineTextAlignment(.center)
                dialogButton(title: L10n.string("tvos_common_done", fallback: "Done"), isPrimary: true) { dismiss() }
            } else if let code = viewModel.deviceUserCode, !code.isEmpty {
                Text(L10n.string("settings_mdblist_qr_hint", fallback: "Scan the QR on your phone, or open the MDBList sign-in page and enter the code."))
                    .font(.system(size: 23, weight: .medium))
                    .foregroundColor(.white.opacity(0.68))
                    .multilineTextAlignment(.center)
                    .fixedSize(horizontal: false, vertical: true)

                if let image = QRCode.image(from: activationURL, scale: 10) {
                    Image(uiImage: image)
                        .interpolation(.none)
                        .resizable()
                        .frame(width: 300, height: 300)
                        .padding(16)
                        .background(Color.white, in: RoundedRectangle(cornerRadius: 24, style: .continuous))
                }

                VStack(spacing: 12) {
                    Text(code)
                        .font(.system(size: 54, weight: .bold, design: .rounded))
                        .tracking(4)
                        .foregroundColor(.white)
                        .accessibilityLabel("MDBList activation code \(code)")
                    Text(activationURL)
                        .font(.system(size: 20, weight: .medium))
                        .foregroundColor(.white.opacity(0.54))
                        .lineLimit(1)
                }

                HStack(spacing: 10) {
                    if viewModel.isPolling { ProgressView().tint(.white) }
                    Text(viewModel.statusMessage ?? "Waiting for approval…")
                        .font(.system(size: 20, weight: .medium))
                        .foregroundColor(.white.opacity(0.64))
                }

                if let error = viewModel.errorMessage, !error.isEmpty {
                    Text(error)
                        .font(.system(size: 20, weight: .semibold))
                        .foregroundColor(Color(red: 1.0, green: 0.43, blue: 0.43))
                        .multilineTextAlignment(.center)
                }

                HStack(spacing: 18) {
                    dialogButton(title: "Cancel", isPrimary: false) {
                        viewModel.cancelLogin()
                        dismiss()
                    }
                    dialogButton(title: "Retry", isPrimary: true) {
                        viewModel.cancelLogin()
                        viewModel.connect()
                    }
                }
            } else if viewModel.errorMessage == nil {
                ProgressView()
                    .controlSize(.large)
                    .tint(.white)
                    .frame(height: 320)
                Text(viewModel.statusMessage ?? "Starting MDBList login…")
                    .font(.system(size: 20, weight: .medium))
                    .foregroundColor(.white.opacity(0.64))
                dialogButton(title: "Cancel", isPrimary: false) {
                    viewModel.cancelLogin()
                    dismiss()
                }
            } else {
                Text(viewModel.errorMessage ?? "Unable to start MDBList login.")
                    .font(.system(size: 22, weight: .medium))
                    .foregroundColor(Color(red: 1.0, green: 0.43, blue: 0.43))
                    .multilineTextAlignment(.center)
                HStack(spacing: 18) {
                    dialogButton(title: "Close", isPrimary: false) { dismiss() }
                    dialogButton(title: "Retry", isPrimary: true) { viewModel.connect() }
                }
            }
        }
        .frame(width: 960)
        .padding(.horizontal, 88)
        .padding(.vertical, 64)
        .onAppear {
            viewModel.reload()
            if viewModel.mode == .disconnected && viewModel.deviceUserCode == nil {
                viewModel.connect()
            }
        }
        .onChange(of: viewModel.mode) { _, mode in
            if mode == .connected {
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                    dismiss()
                }
            }
        }
    }

    @ViewBuilder
    private func dialogButton(title: String, isPrimary: Bool, action: @escaping () -> Void) -> some View {
        ProviderLoginGlassButton(title: title, isPrimary: isPrimary, action: action)
    }
}

