                            ) {
                                showingLibraryTransferSources = true
                            }
                            .disabled(
                                viewModel.isLoading
                                    || viewModel.isTransferringHistory
                                    || viewModel.isTransferringLibrary
                                    || viewModel.isTransferringProgress
                            )

                            if let progress = viewModel.libraryTransferProgress {
                                VStack(alignment: .leading, spacing: 12) {
                                    HStack {
                                        Text("\(viewModel.libraryTransferSourceLabel ?? "Library") → Simkl Plan to Watch")
                                            .font(.system(size: 19, weight: .semibold))
                                            .foregroundColor(.white.opacity(0.76))
                                        Spacer()
                                        Text("\(progress)%")
                                            .font(.system(size: 20, weight: .bold, design: .rounded))
                                            .foregroundColor(progress == 100 ? .green : accentColor)
                                    }

                                    ProgressView(value: Double(progress), total: 100)
                                        .tint(progress == 100 ? .green : accentColor)
                                }
                                .padding(.horizontal, 22)
                                .padding(.vertical, 18)
                                .background(Color.white.opacity(0.07), in: RoundedRectangle(cornerRadius: 16))
                            }
                        }

                        SettingsGroup(
                            title: L10n.string("tvos_settings_simkl_transfer_continue_watching", fallback: "Transfer Continue Watching"),
                            subtitle: L10n.string("tvos_settings_simkl_transfer_continue_watching_subtitle", fallback: "Copy unfinished playback positions into Simkl for cross-device resume")
                        ) {
                            SettingsActionRow(
                                title: L10n.string("tvos_settings_simkl_transfer_progress_to_simkl", fallback: "Transfer Progress to Simkl"),
                                subtitle: L10n.string("tvos_settings_simkl_transfer_source_subtitle", fallback: "Choose Nuvio Sync or a connected Trakt account as the source"),
                                value: viewModel.isTransferringProgress
                                    ? "\(viewModel.progressTransferProgress ?? 1)%"
                                    : L10n.string("tvos_settings_choose_source", fallback: "Choose Source"),
                                accentColor: accentColor
                            ) {
                                showingProgressTransferSources = true
                            }
                            .disabled(
                                viewModel.isLoading
                                    || viewModel.isTransferringHistory
                                    || viewModel.isTransferringLibrary
                                    || viewModel.isTransferringProgress
                            )

                            if let progress = viewModel.progressTransferProgress {
                                VStack(alignment: .leading, spacing: 12) {
                                    HStack {
                                        Text("\(viewModel.progressTransferSourceLabel ?? "Progress") → Simkl")
                                            .font(.system(size: 19, weight: .semibold))
                                            .foregroundColor(.white.opacity(0.76))
                                        Spacer()
                                        Text("\(progress)%")
                                            .font(.system(size: 20, weight: .bold, design: .rounded))
                                            .foregroundColor(progress == 100 ? .green : accentColor)
                                    }

                                    ProgressView(value: Double(progress), total: 100)
                                        .tint(progress == 100 ? .green : accentColor)
                                }
                                .padding(.horizontal, 22)
                                .padding(.vertical, 18)
                                .background(Color.white.opacity(0.07), in: RoundedRectangle(cornerRadius: 16))
                            }
                        }

                        SettingsGroup(
                            title: L10n.string("account_login", fallback: "Account Login"),
                            subtitle: L10n.string("tvos_settings_simkl_account_login_subtitle", fallback: "Manage the Simkl connection for this Nuvio profile")
                        ) {
                            if viewModel.isLegacyV1, let onReconnect {
                                SettingsActionRow(
                                    title: "Upgrade to OAuth 2.0",
                                    subtitle: "Reconnect your Simkl account using the new QR device flow",
                                    value: "Reconnect",
                                    accentColor: accentColor
                                ) {
                                    viewModel.disconnect()
                                    onReconnect()
                                }
                                .disabled(
                                    viewModel.isLoading
                                        || viewModel.isTransferringHistory
                                        || viewModel.isTransferringLibrary
                                        || viewModel.isTransferringProgress
                                )
                            }

                            SettingsActionRow(
                                title: L10n.string("debrid_disconnect", fallback: "Disconnect"),
                                subtitle: L10n.string("tvos_settings_simkl_disconnect_subtitle", fallback: "Remove this profile's Simkl token from this Apple TV"),
                                value: L10n.string("debrid_disconnect", fallback: "Disconnect"),
                                accentColor: accentColor
                            ) {
                                showingDisconnectConfirmation = true
                            }
                            .disabled(
                                viewModel.isLoading
                                    || viewModel.isTransferringHistory
                                    || viewModel.isTransferringLibrary
                                    || viewModel.isTransferringProgress
                            )
                        }

                        if let message = viewModel.statusMessage, !message.isEmpty {
                            Text(message)
                                .font(.system(size: 18, weight: .medium))
                                .foregroundColor(.white.opacity(0.62))
                        }
                        if let error = viewModel.errorMessage, !error.isEmpty {
                            Text(error)
                                .font(.system(size: 18, weight: .semibold))
                                .foregroundColor(.red.opacity(0.9))
                        }
                        if let report = viewModel.loadingDebugInfo, !report.isEmpty {
                            SimklLoadingDebugReport(report: report)
                        }
                    }
                    .frame(width: 1_000, alignment: .leading)
                    .padding(.horizontal, 52)
                    .padding(.vertical, 38)
                }
                .focusSection()
            }
        }
        .onExitCommand { dismiss() }
        .task {
            viewModel.reload()
            viewModel.loadConnectedData()
        }
        .onChange(of: simklPlanToWatchHomeCatalogs) { _, _ in
            NotificationCenter.default.post(name: TVHomeCatalogOrder.changedNotification, object: nil)
            NotificationCenter.default.post(name: TVHomeCatalogOrder.snapshotChangedNotification, object: nil)
        }
        .onChange(of: viewModel.mode) { _, mode in
            if mode != .connected { dismiss() }
        }
        .confirmationDialog(
            "Disconnect Simkl?",
            isPresented: $showingDisconnectConfirmation,
            titleVisibility: .visible
        ) {
            Button(L10n.string("debrid_disconnect", fallback: "Disconnect"), role: .destructive) {
                viewModel.disconnect()
            }
            Button(L10n.string("action_cancel", fallback: "Cancel"), role: .cancel) {}
        }
        .confirmationDialog(
            L10n.string("simkl_transfer_history_title", fallback: "Transfer Watch History to Simkl"),
            isPresented: $showingHistoryTransferSources,
            titleVisibility: .visible
        ) {
            Button(L10n.string("simkl_transfer_from_nuvio_sync", fallback: "From Nuvio Sync")) {
                viewModel.transferWatchHistory(from: .nuvioSync)
            }
            if viewModel.isTraktTransferAvailable {
                Button(L10n.string("simkl_transfer_from_trakt", fallback: "From Trakt")) {
                    viewModel.transferWatchHistory(from: .trakt)
                }
            }
            Button(L10n.string("action_cancel", fallback: "Cancel"), role: .cancel) {}
        } message: {
            Text(L10n.string("simkl_transfer_history_msg", fallback: "This only adds watched history to Simkl. Existing Simkl history is not removed."))
        }
        .confirmationDialog(
            L10n.string("simkl_transfer_library_title", fallback: "Transfer Library to Simkl"),
            isPresented: $showingLibraryTransferSources,
            titleVisibility: .visible
        ) {
            Button(L10n.string("simkl_transfer_from_nuvio_library", fallback: "From Nuvio Library")) {
                viewModel.transferLibrary(from: .nuvioLibrary)
            }
            if viewModel.isTraktTransferAvailable {
                Button(L10n.string("simkl_transfer_from_trakt", fallback: "From Trakt")) {
                    viewModel.transferLibrary(from: .trakt)
                }
            }
            Button(L10n.string("action_cancel", fallback: "Cancel"), role: .cancel) {}
        } message: {
            Text(L10n.string("simkl_transfer_library_msg", fallback: "This adds library items to Simkl Plan to Watch. Existing Simkl lists and history are not removed."))
        }
        .confirmationDialog(
            L10n.string("simkl_transfer_cw_title", fallback: "Transfer Continue Watching to Simkl"),
            isPresented: $showingProgressTransferSources,
            titleVisibility: .visible
        ) {
            Button(L10n.string("simkl_transfer_from_nuvio_sync", fallback: "From Nuvio Sync")) {
                viewModel.transferProgress(from: .nuvioSync)
            }
            if viewModel.isTraktTransferAvailable {
                Button(L10n.string("simkl_transfer_from_trakt", fallback: "From Trakt")) {
                    viewModel.transferProgress(from: .trakt)
                }
            }
            Button(L10n.string("action_cancel", fallback: "Cancel"), role: .cancel) {}
        } message: {
            Text(L10n.string("simkl_transfer_cw_msg", fallback: "This saves unfinished playback positions in Simkl. Completed history and existing Simkl lists are unchanged."))
        }
    }

    private var librarySourceSelection: Binding<String> {
        Binding(
            get: { TraktSettingsStore.librarySourceMode.label },
            set: { label in
                TraktSettingsStore.librarySourceMode =
                    TraktLibrarySourceMode.allCases.first { $0.label == label } ?? .local
            }
        )
    }

    private var watchProgressSelection: Binding<String> {
        Binding(
            get: { TraktSettingsStore.watchProgressSource.label },
            set: { label in
                TraktSettingsStore.markWatchProgressSourceChosenByUser()
                TraktSettingsStore.watchProgressSource =
                    TraktWatchProgressSource.allCases.first { $0.label == label } ?? .nuvioSync
            }
        )
    }

    private var moreLikeThisSelection: Binding<String> {
        Binding(
            get: { TraktSettingsStore.moreLikeThisSource.label },
            set: { label in
                TraktSettingsStore.moreLikeThisSource =
                    TraktMoreLikeThisSource.allCases.first { $0.label == label } ?? .tmdb
            }
        )
    }
}

private struct SimklConnectedStatsStrip: View {
    let stats: SimklCachedStats?
    let isLoading: Bool

    var body: some View {
        HStack(spacing: 0) {
            stat(value: stats?.moviesWatched, label: L10n.string("nav_movies", fallback: "Movies"))
            divider
            stat(value: stats?.showsWatched, label: L10n.string("trakt_stat_shows", fallback: "Shows"))
            divider
            stat(value: stats?.episodesWatched, label: L10n.string("tmdb_episodes_title", fallback: "Episodes"))
            divider
            stat(
                text: stats?.totalWatchedHours.map { "\($0)h" },
                label: L10n.string("tvos_settings_hours", fallback: "Watched Hours")
            )
        }
        .padding(.vertical, 18)
        .frame(maxWidth: .infinity)
        .overlay(alignment: .top) { Divider().overlay(Color.white.opacity(0.16)) }
        .overlay(alignment: .bottom) { Divider().overlay(Color.white.opacity(0.16)) }
    }

    private var divider: some View {
        Rectangle()
            .fill(Color.white.opacity(0.16))
            .frame(width: 1, height: 72)
    }

    private func stat(value: Int?, label: String) -> some View {
        stat(text: value.map(String.init), label: label)
    }

    private func stat(text: String?, label: String) -> some View {
        VStack(spacing: 7) {
            Text(text ?? (isLoading ? "..." : "-"))
                .font(.system(size: 27, weight: .semibold))
                .foregroundColor(.white)
            Text(label)
                .font(.system(size: 17, weight: .medium))
                .foregroundColor(.white.opacity(0.62))
                .lineLimit(1)
        }
        .frame(maxWidth: .infinity)
    }
}

private struct SimklPINLoginSheet: View {
    @ObservedObject var viewModel: SimklSettingsViewModel
    let accentColor: Color
    @Environment(\.dismiss) private var dismiss

    private var verificationURI: String {
        let value = viewModel.verificationURI?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return value.isEmpty ? SimklConfig.pinVerificationURL : value
    }

    private var qrURI: String {
        if let complete = viewModel.verificationURIComplete?.trimmingCharacters(in: .whitespacesAndNewlines),
           !complete.isEmpty {
            return complete
        }
        return verificationURI
    }

    var body: some View {
        VStack(spacing: 28) {
            Text(viewModel.mode == .connected ? "Simkl Connected" : "Connect Simkl")
                .font(.system(size: 42, weight: .regular))
                .foregroundColor(.white)

            if viewModel.mode == .connected {
                Text(viewModel.username.map { "Signed in as \($0)" }
                    ?? "This Apple TV is linked to Simkl.")
                    .font(.system(size: 23, weight: .medium))
                    .foregroundColor(.white.opacity(0.66))
                    .multilineTextAlignment(.center)
                dialogButton(
                    title: L10n.string("tvos_settings_done", fallback: "Done"),
                    isPrimary: true
                ) {
                    dismiss()
                }
            } else if viewModel.deviceUserCode == nil && viewModel.errorMessage == nil {
                ProgressView()
                    .controlSize(.large)
                    .tint(.white)
                    .frame(height: 320)
                Text(viewModel.statusMessage ?? "Starting Simkl login…")
                    .font(.system(size: 20, weight: .medium))
                    .foregroundColor(.white.opacity(0.64))
                debugReport
                dialogButton(
                    title: L10n.string("action_cancel", fallback: "Cancel"),
                    isPrimary: false
                ) {
                    viewModel.cancelPINFlow()
                    dismiss()
                }
            } else if let code = viewModel.deviceUserCode, !code.isEmpty {
                Text(viewModel.verificationURIComplete != nil
                    ? "Scan the QR code on your phone to authorize instantly, or visit the link below and enter the PIN."
                    : "Scan the QR on your phone, then enter the PIN shown below.")
                    .font(.system(size: 23, weight: .medium))
                    .foregroundColor(.white.opacity(0.68))
                    .multilineTextAlignment(.center)
                    .fixedSize(horizontal: false, vertical: true)

                if let image = QRCode.image(from: qrURI, scale: 10) {
                    Image(uiImage: image)
                        .interpolation(.none)
                        .resizable()
                        .frame(width: 300, height: 300)
                        .padding(16)
                        .background(
                            Color.white,
                            in: RoundedRectangle(cornerRadius: 24, style: .continuous)
                        )
                }

                VStack(spacing: 12) {
                    Text(code)
                        .font(.system(size: 54, weight: .bold, design: .rounded))
                        .tracking(4)
                        .foregroundColor(.white)
                        .accessibilityLabel("Simkl PIN \(code)")

                    Text(verificationURI)
                        .font(.system(size: 20, weight: .medium))
                        .foregroundColor(.white.opacity(0.54))
                        .lineLimit(1)
                }

                HStack(spacing: 10) {
                    if viewModel.isPolling { ProgressView().tint(.white) }
                    Text(viewModel.statusMessage ?? "Waiting for approval…")
                        .font(.system(size: 20, weight: .medium))
                        .foregroundColor(.white.opacity(0.64))
                }

                if let error = viewModel.errorMessage, !error.isEmpty {
                    Text(error)
                        .font(.system(size: 20, weight: .semibold))
                        .foregroundColor(Color(red: 1.0, green: 0.43, blue: 0.43))
                        .multilineTextAlignment(.center)
                }

                HStack(spacing: 18) {
                    dialogButton(
                        title: L10n.string("action_cancel", fallback: "Cancel"),
                        isPrimary: false
                    ) {
                        viewModel.cancelPINFlow()
                        dismiss()
                    }
                    dialogButton(
                        title: L10n.string("action_retry", fallback: "Retry"),
                        isPrimary: true
                    ) {
                        viewModel.cancelPINFlow()
                        viewModel.connect()
                    }
                }
            } else {
                Text(viewModel.errorMessage ?? "Unable to start Simkl login.")
                    .font(.system(size: 22, weight: .medium))
                    .foregroundColor(Color(red: 1.0, green: 0.43, blue: 0.43))
                    .multilineTextAlignment(.center)
                debugReport
                HStack(spacing: 18) {
                    dialogButton(
                        title: L10n.string("action_close", fallback: "Close"),
                        isPrimary: false
                    ) {
                        dismiss()
                    }
                    dialogButton(
                        title: L10n.string("action_retry", fallback: "Retry"),
                        isPrimary: true
                    ) {
                        viewModel.connect()
                    }
                }
            }
        }
        .frame(width: 960)
        .padding(.horizontal, 88)
        .padding(.vertical, 64)
        .onAppear {
            if viewModel.mode != .connected && viewModel.deviceUserCode == nil {
                viewModel.connect()
            } else if viewModel.mode == .awaitingApproval {
                viewModel.retryPolling()
            }
        }
        .onChange(of: viewModel.mode) { _, mode in
            if mode == .connected {
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                    dismiss()
                }
            }
        }
    }

    @ViewBuilder
    private var debugReport: some View {
        if let report = viewModel.loadingDebugInfo, !report.isEmpty {
            SimklLoadingDebugReport(report: report)
        }
    }

    @ViewBuilder
    private func dialogButton(
        title: String,
        isPrimary: Bool,
        action: @escaping () -> Void
    ) -> some View {
        ProviderLoginGlassButton(title: title, isPrimary: isPrimary, action: action)
    }
}

private struct SimklLoadingDebugReport: View {
    let report: String

    var body: some View {
        VStack(spacing: 12) {
            Text("SIMKL DEBUG REPORT")
                .font(.system(size: 18, weight: .bold, design: .monospaced))
                .foregroundColor(.yellow)

            ScrollView {
                Text(report)
                    .font(.system(size: 14, weight: .medium, design: .monospaced))
                    .foregroundColor(.white.opacity(0.82))
                    .multilineTextAlignment(.leading)
                    .fixedSize(horizontal: false, vertical: true)
                    .frame(maxWidth: .infinity, alignment: .leading)
            }
            .frame(maxHeight: 190)
            .padding(14)
            .background(Color.black.opacity(0.36), in: RoundedRectangle(cornerRadius: 12))

            Text(L10n.string("diagnostic_report_hint", fallback: "Read or screenshot this report and send it to the developer."))
                .font(.system(size: 16, weight: .medium))
                .foregroundColor(.white.opacity(0.58))
        }
        .frame(maxWidth: 820)
    }
}

// MARK: - WeTrakr Views

private struct WeTrakrConnectionSettingsCard: View {
    @ObservedObject var viewModel: WeTrakrSettingsViewModel
    let accentColor: Color
    let credentialsReady: Bool
    let onStartLogin: () -> Void
    let onOpenSettings: () -> Void

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack(alignment: .top, spacing: 18) {
                ZStack {
                    RoundedRectangle(cornerRadius: 18, style: .continuous)
                        .fill(
                            LinearGradient(
                                colors: [
                                    Color(red: 0.50, green: 0.18, blue: 0.76),
                                    Color(red: 0.32, green: 0.08, blue: 0.54)
                                ],
                                startPoint: .topLeading,
                                endPoint: .bottomTrailing
                            )
                        )
                    Text("WeTrakr")
                        .font(.system(size: 19, weight: .black))
                        .foregroundColor(.white)
                }
                .frame(width: 112, height: 62)

                VStack(alignment: .leading, spacing: 8) {
                    Text(statusTitle)
                        .font(.system(size: 24, weight: .bold))
                        .foregroundColor(.white)

                    Text(statusSubtitle)
                        .font(.system(size: 18, weight: .medium))
                        .foregroundColor(.white.opacity(0.62))
                        .fixedSize(horizontal: false, vertical: true)
                }

                Spacer(minLength: 16)
            }

            switch viewModel.mode {
            case .disconnected, .awaitingApproval:
                SettingsActionRow(
                    title: viewModel.mode == .awaitingApproval
                        ? "Continue WeTrakr Login"
                        : "Connect with WeTrakr",
                    subtitle: credentialsReady
                        ? "Scan the QR or enter the PIN at wetrakr.com/activate"
                        : "Enter your WeTrakr Client ID first",
                    value: viewModel.mode == .awaitingApproval
                        ? "Resume"
                        : "Connect",
                    accentColor: accentColor
                ) {
                    onStartLogin()
                }
                .opacity(credentialsReady ? 1 : 0.5)
                .disabled(!credentialsReady)
            case .connected:
                SettingsActionRow(
                    title: "WeTrakr Account",
                    subtitle: "View the connected account or disconnect this profile",
                    value: "Open",
                    accentColor: accentColor,
                    action: onOpenSettings
                )
            }

            if let message = viewModel.statusMessage, !message.isEmpty, viewModel.mode == .connected {
                Text(message)
                    .font(.system(size: 17, weight: .medium))
                    .foregroundColor(.white.opacity(0.62))
            }
            if let error = viewModel.errorMessage, !error.isEmpty, viewModel.mode != .awaitingApproval {
                Text(error)
                    .font(.system(size: 17, weight: .semibold))
                    .foregroundColor(Color(red: 1.0, green: 0.43, blue: 0.43))
            }
        }
    }

    private var statusTitle: String {
        switch viewModel.mode {
        case .connected:
            let name = (viewModel.displayName ?? viewModel.username ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
            return name.isEmpty ? "Connected" : "Connected as \(name)"
        case .awaitingApproval:
            return "Approval Pending"
        case .disconnected:
            return "Not Connected"
        }
    }

    private var statusSubtitle: String {
        switch viewModel.mode {
        case .connected:
            return "Tracks watch progress, scrobbling, and history seamlessly across devices."
        case .awaitingApproval:
            return "Authorization code active. Scan the QR or visit wetrakr.com/activate to finish."
        case .disconnected:
            return credentialsReady
                ? "Start the device pairing flow to sign in with your WeTrakr account."
                : "Enter your WeTrakr Client ID above to enable connection."
        }
    }
}

private struct WeTrakrDeviceLoginSheet: View {
    @ObservedObject var viewModel: WeTrakrSettingsViewModel
    let accentColor: Color

    @Environment(\.dismiss) private var dismiss

    private var activationURL: String {
        viewModel.verificationURI ?? WeTrakrConfig.activationURL
    }

    var body: some View {
        VStack(spacing: 28) {
            Text(viewModel.mode == .connected ? "WeTrakr Connected" : "Connect WeTrakr")
                .font(.system(size: 42, weight: .regular))
                .foregroundColor(.white)

            if viewModel.mode == .connected {
                Text((viewModel.displayName ?? viewModel.username).map { "Signed in as \($0)" } ?? "This Apple TV is linked to WeTrakr.")
                    .font(.system(size: 23, weight: .medium))
                    .foregroundColor(.white.opacity(0.66))
                    .multilineTextAlignment(.center)
                dialogButton(title: L10n.string("tvos_common_done", fallback: "Done"), isPrimary: true) { dismiss() }
            } else if let code = viewModel.deviceUserCode, !code.isEmpty {
                Text(L10n.string("settings_qr_activation_hint", fallback: "Scan the QR code on your phone, or open the link below and enter the activation code."))
                    .font(.system(size: 23, weight: .medium))
                    .foregroundColor(.white.opacity(0.68))
                    .multilineTextAlignment(.center)
                    .fixedSize(horizontal: false, vertical: true)

                if let image = QRCode.image(from: activationURL, scale: 10) {
                    Image(uiImage: image)
                        .interpolation(.none)
                        .resizable()
                        .frame(width: 300, height: 300)
                        .padding(16)
                        .background(Color.white, in: RoundedRectangle(cornerRadius: 24, style: .continuous))
                }

                VStack(spacing: 12) {
                    Text(code)
                        .font(.system(size: 54, weight: .bold, design: .rounded))
                        .tracking(4)
                        .foregroundColor(.white)
                        .accessibilityLabel("WeTrakr activation code \(code)")
                    Text(activationURL)
                        .font(.system(size: 20, weight: .medium))
                        .foregroundColor(.white.opacity(0.54))
                        .lineLimit(1)
                }

                HStack(spacing: 10) {
                    if viewModel.isPolling { ProgressView().tint(.white) }
                    Text(viewModel.statusMessage ?? "Waiting for approval…")
                        .font(.system(size: 20, weight: .medium))
                        .foregroundColor(.white.opacity(0.64))
                }

                if let error = viewModel.errorMessage, !error.isEmpty {
                    Text(error)
                        .font(.system(size: 20, weight: .semibold))
                        .foregroundColor(Color(red: 1.0, green: 0.43, blue: 0.43))
                        .multilineTextAlignment(.center)
                }

                HStack(spacing: 18) {
                    dialogButton(title: "Cancel", isPrimary: false) {
                        viewModel.cancelLogin()
                        dismiss()
                    }
                    dialogButton(title: "Retry", isPrimary: true) {
                        viewModel.cancelLogin()
                        viewModel.startLogin()
                    }
                }
            } else if viewModel.errorMessage == nil {
                ProgressView()
                    .controlSize(.large)
                    .tint(.white)
                    .frame(height: 320)
                Text(viewModel.statusMessage ?? "Starting WeTrakr login…")
                    .font(.system(size: 20, weight: .medium))
                    .foregroundColor(.white.opacity(0.64))
                dialogButton(title: "Cancel", isPrimary: false) {
                    viewModel.cancelLogin()
                    dismiss()
                }
            } else {
                Text(viewModel.errorMessage ?? "Unable to start WeTrakr login.")
                    .font(.system(size: 22, weight: .medium))
                    .foregroundColor(Color(red: 1.0, green: 0.43, blue: 0.43))
                    .multilineTextAlignment(.center)
                HStack(spacing: 18) {
                    dialogButton(title: "Close", isPrimary: false) { dismiss() }
                    dialogButton(title: "Retry", isPrimary: true) { viewModel.startLogin() }
                }
            }
        }
        .frame(width: 960)
        .padding(.horizontal, 88)
        .padding(.vertical, 64)
        .onAppear {
            viewModel.reload()
            if viewModel.mode == .disconnected && viewModel.deviceUserCode == nil {
                viewModel.startLogin()
            }
        }
        .onChange(of: viewModel.mode) { _, mode in
            if mode == .connected {
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                    dismiss()
                }
            }
        }
    }

    @ViewBuilder
    private func dialogButton(title: String, isPrimary: Bool, action: @escaping () -> Void) -> some View {
        ProviderLoginGlassButton(title: title, isPrimary: isPrimary, action: action)
    }
}

private struct WeTrakrConnectedSettingsSheet: View {
    @ObservedObject var viewModel: WeTrakrSettingsViewModel
    let accentColor: Color

    @Environment(\.dismiss) private var dismiss
    @AppStorage(SettingsKey.amoled) private var amoled = false
    @AppStorage(SettingsKey.bodyColor) private var bodyColor = SettingsBackground.charcoal.rawValue
    @State private var showingDisconnectConfirmation = false

    var body: some View {
        ZStack {
            Color.nuvioBackground(amoled: amoled, body: bodyColor)
                .ignoresSafeArea()

            VStack(spacing: 0) {
                ScrollView {
                    VStack(alignment: .leading, spacing: 24) {
                        VStack(alignment: .leading, spacing: 7) {
                            Text("WeTrakr")
                                .font(.system(size: 36, weight: .bold))
                                .foregroundColor(.white)

                            Text(viewModel.username?.isEmpty == false
                                ? L10n.format("tvos_settings_simkl_manage_user_desc", fallback: "Connected as %@. Manage sync and account options.", viewModel.displayName ?? viewModel.username ?? "WeTrakr User")
                                : L10n.string("tvos_settings_simkl_manage_desc", fallback: "Manage WeTrakr sync and account options."))
                                .font(.system(size: 20, weight: .medium))
                                .foregroundColor(.white.opacity(0.62))
                        }

                        SettingsGroup(
                            title: L10n.string("account_title", fallback: "Account"),
                            subtitle: L10n.string("tvos_settings_wetrakr_account_info_subtitle", fallback: "Account information returned by WeTrakr")
                        ) {
                            if let username = viewModel.username, !username.isEmpty {
                                SettingsInfoRow(title: L10n.string("account_username", fallback: "Username"), value: username)
                            }
                            if let displayName = viewModel.displayName, !displayName.isEmpty {
                                SettingsInfoRow(title: "Display Name", value: displayName)
                            }
                            if let plan = viewModel.accountPlan, !plan.isEmpty {
                                SettingsInfoRow(title: L10n.string("account_plan", fallback: "Plan"), value: plan.uppercased())
                            }
                            if let accountID = viewModel.accountID, !accountID.isEmpty {
                                SettingsInfoRow(title: L10n.string("account_id", fallback: "Account ID"), value: accountID)
                            }
                            SettingsInfoRow(
                                title: "Auth Protocol",
                                value: "OAuth 2.0 (Device Flow)"
                            )
                        }

                        SettingsGroup(
                            title: L10n.string("tvos_settings_watch_stats", fallback: "Watch Stats"),
                            subtitle: L10n.string("tvos_settings_wetrakr_watch_stats_subtitle", fallback: "Watched activity returned from your WeTrakr account")
                        ) {
                            WeTrakrConnectedStatsStrip(
                                stats: viewModel.connectedStats,
                                isLoading: viewModel.isStatsLoading
                            )

                            SettingsActionRow(
                                title: L10n.string("tvos_settings_sync_now", fallback: "Sync Now"),
                                subtitle: L10n.string("tvos_settings_wetrakr_sync_watch_stats_subtitle", fallback: "Refresh WeTrakr watch progress, account information, and watch stats"),
                                value: viewModel.isLoading
                                    ? L10n.string("tvos_settings_syncing", fallback: "Syncing")
                                    : L10n.string("tvos_settings_refresh", fallback: "Refresh"),
                                accentColor: accentColor
                            ) {
                                viewModel.refreshNow()
                            }
                            .disabled(viewModel.isLoading)
                        }

                        SettingsGroup(
                            title: L10n.string("tvos_settings_wetrakr_features", fallback: "WeTrakr Features"),
                            subtitle: L10n.string("tvos_settings_wetrakr_features_subtitle", fallback: "Choose how WeTrakr is used throughout Nuvio")
                        ) {
                            SettingsToggleRow(
                                title: L10n.string("tvos_settings_wetrakr_scrobble", fallback: "Scrobble Playback"),
                                subtitle: L10n.string(
                                    "tvos_settings_wetrakr_scrobble_sheet_subtitle",
                                    fallback: "Send playback progress and watched updates to your WeTrakr account"
                                ),
                                isOn: Binding(
                                    get: { RemoteTrackingState.isScrobbleEnabled(for: .wetrakr) },
                                    set: { RemoteTrackingState.setScrobbleEnabled($0, for: .wetrakr) }
                                ),
                                accentColor: accentColor
                            )

                            SettingsChoiceRow(
                                title: L10n.string("trakt_library_source_dialog_title", fallback: "Library Source"),
                                subtitle: L10n.string("tvos_settings_wetrakr_library_source_subtitle", fallback: "Use WeTrakr tracking lists as your Nuvio library"),
                                selection: librarySourceSelection,
                                options: RemoteTrackingState.availableLibrarySources().map(\.label),
                                accentColor: accentColor
                            )

                            SettingsChoiceRow(
                                title: L10n.string("trakt_watch_progress_dialog_title", fallback: "Watch Progress"),
                                subtitle: L10n.string("tvos_settings_wetrakr_watch_progress_subtitle", fallback: "Use WeTrakr for Resume, Continue Watching, and scrobbling"),
                                selection: watchProgressSelection,
                                options: RemoteTrackingState.availableProgressSources().map(\.label),
                                accentColor: accentColor
                            )
                        }

                        SettingsGroup(
                            title: L10n.string("account_login", fallback: "Account Login"),
                            subtitle: L10n.string("tvos_settings_wetrakr_account_login_subtitle", fallback: "Manage the WeTrakr connection for this Nuvio profile")
                        ) {
                            SettingsActionRow(
                                title: L10n.string("debrid_disconnect", fallback: "Disconnect"),
                                subtitle: L10n.string("tvos_settings_wetrakr_disconnect_subtitle", fallback: "Remove this profile's WeTrakr token from this Apple TV"),
                                value: L10n.string("debrid_disconnect", fallback: "Disconnect"),
                                accentColor: accentColor
                            ) {
                                showingDisconnectConfirmation = true
                            }
                            .disabled(viewModel.isLoading)
                        }

                        if let message = viewModel.statusMessage, !message.isEmpty {
                            Text(message)
                                .font(.system(size: 18, weight: .medium))
                                .foregroundColor(.white.opacity(0.62))
                        }
                        if let error = viewModel.errorMessage, !error.isEmpty {
                            Text(error)
                                .font(.system(size: 18, weight: .semibold))
                                .foregroundColor(.red.opacity(0.9))
                        }
                    }
                    .frame(width: 1_000, alignment: .leading)
                    .padding(.horizontal, 52)
                    .padding(.vertical, 38)
                }
                .focusSection()
            }
        }
        .onExitCommand { dismiss() }
        .task {
            viewModel.reload()
            viewModel.loadConnectedData()
        }
        .onChange(of: viewModel.mode) { _, mode in
            if mode != .connected { dismiss() }
        }
        .confirmationDialog(
            "Disconnect WeTrakr?",
            isPresented: $showingDisconnectConfirmation,
            titleVisibility: .visible
        ) {
            Button(L10n.string("debrid_disconnect", fallback: "Disconnect"), role: .destructive) {
                viewModel.disconnect()
            }
            Button(L10n.string("action_cancel", fallback: "Cancel"), role: .cancel) {}
        }
    }

    private var watchProgressSelection: Binding<String> {
        Binding(
            get: { TraktSettingsStore.watchProgressSource.label },
            set: { label in
                TraktSettingsStore.markWatchProgressSourceChosenByUser()
                TraktSettingsStore.watchProgressSource =
                    TraktWatchProgressSource.allCases.first { $0.label == label } ?? .wetrakr
            }
        )
    }

    private var librarySourceSelection: Binding<String> {
        Binding(
            get: { TraktSettingsStore.librarySourceMode.label },
            set: { label in
                TraktSettingsStore.librarySourceMode =
                    TraktLibrarySourceMode.allCases.first { $0.label == label } ?? .local
            }
        )
    }
}

private struct WeTrakrConnectedStatsStrip: View {
    let stats: WeTrakrCachedStats?
    let isLoading: Bool

    var body: some View {
        HStack(spacing: 0) {
            stat(value: stats?.moviesWatched, label: L10n.string("nav_movies", fallback: "Movies"))
            divider
            stat(value: stats?.showsWatched, label: L10n.string("trakt_stat_shows", fallback: "Shows"))
            divider
            stat(value: stats?.episodesWatched, label: L10n.string("tmdb_episodes_title", fallback: "Episodes"))
            divider
            stat(
                text: stats?.totalWatchedHours.map { "\($0)h" },
                label: L10n.string("tvos_settings_hours", fallback: "Watched Hours")
            )
        }
        .padding(.vertical, 18)
        .frame(maxWidth: .infinity)
        .overlay(alignment: .top) { Divider().overlay(Color.white.opacity(0.16)) }
        .overlay(alignment: .bottom) { Divider().overlay(Color.white.opacity(0.16)) }
    }

    private var divider: some View {
        Rectangle()
            .fill(Color.white.opacity(0.16))
            .frame(width: 1, height: 72)
    }

    private func stat(value: Int?, label: String) -> some View {
        stat(text: value.map(String.init), label: label)
    }

    private func stat(text: String?, label: String) -> some View {
        VStack(spacing: 7) {
            Text(text ?? (isLoading ? "..." : "-"))
                .font(.system(size: 27, weight: .semibold))
                .foregroundColor(.white)
            Text(label)
                .font(.system(size: 17, weight: .medium))
                .foregroundColor(.white.opacity(0.62))
                .lineLimit(1)
        }
        .frame(maxWidth: .infinity)
    }
}

struct ProviderLoginGlassButton: View {
    let title: String
    let isPrimary: Bool
    var focusBinding: FocusState<Bool>.Binding? = nil
    let action: () -> Void

    @FocusState private var internalIsFocused: Bool

    private var resolvedFocusBinding: FocusState<Bool>.Binding {
        focusBinding ?? $internalIsFocused
    }

    private var isFocused: Bool {
        focusBinding?.wrappedValue ?? internalIsFocused
    }

    var body: some View {
        Button(action: action) {
            Text(title)
                .font(.system(size: 24, weight: .semibold))
                .foregroundColor(isFocused || isPrimary ? .black : .white)
                .padding(.horizontal, 34)
                .frame(height: 58)
                .loginGlassCapsule(
                    highlighted: isFocused,
                    prominent: isPrimary
                )
                .scaleEffect(isFocused ? 1.04 : 1)
        }
        .buttonStyle(PosterCardButtonStyle())
        .focused(resolvedFocusBinding)
        .focusEffectDisabledIfAvailable()
        .animation(.easeOut(duration: 0.12), value: isFocused)
    }
}

