    private var visiblePlayerButtonCount: Int {
        [playerShowPiP, playerShowEpisodes, playerShowSources, playerShowSubtitles, playerShowAudio, playerShowSpeed]
            .filter { $0 }
            .count
    }

    private func refreshInSightSectionsSummary() {
        let count = TVSceneTabOrder.enabledTabCount()
        guard inSightSectionsEnabledCount != count else { return }
        inSightSectionsEnabledCount = count
    }

    private var audioLanguageSummary: String {
        SubtitleLanguagePreferences.audioSettingsOptions.contains(audioLanguage)
            ? audioLanguage
            : "System"
    }

    private var subtitleLanguageSummary: String {
        let ordered = SubtitleLanguagePreferences.ordered(
            encoded: subtitleLanguages,
            primary: subtitleLanguage,
            secondary: subtitleLanguageSecondary,
            tertiary: subtitleLanguageTertiary
        )
        guard !ordered.isEmpty else { return L10n.string("tvos_settings_system", fallback: "System") }
        guard ordered.count > 2 else { return ordered.joined(separator: ", ") }
        return "\(ordered[0]), \(ordered[1]) +\(ordered.count - 2)"
    }

    @ViewBuilder
    private var streamBadgeSettingsRows: some View {
        // Keep the view dependent on badge-store updates, but do not replace its
        // identity: replacing it after a placement change sends tvOS focus back
        // to the first row in the group.
        let _ = streamBadgeSettingsRevision
        let importedRules = StreamBadgeSettingsStore.snapshot.rules
        let placementBinding = Binding<String>(
            get: { streamBadgePlacement == StreamBadgePlacement.top.rawValue ? "Top" : "Bottom" },
            set: { value in
                let placement: StreamBadgePlacement = value == "Top" ? .top : .bottom
                streamBadgePlacement = placement.rawValue
                StreamBadgeSettingsStore.setPlacement(placement)
            }
        )

        SettingsToggleRow(
            title: L10n.string("tvos_settings_file_size_badges", fallback: "File Size Badges"),
            subtitle: L10n.string("tvos_settings_file_size_badges_subtitle", fallback: "Show the stream file size when the add-on provides it"),
            isOn: $showFileSizeBadges,
            accentColor: accentColor
        )

        SettingsOptionRow(
            title: L10n.string("tvos_settings_badge_placement", fallback: "Badge Placement"),
            subtitle: L10n.string("tvos_settings_badge_placement_subtitle", fallback: "Place imported badges and file sizes above or below the stream details"),
            selection: placementBinding,
            options: ["Top", "Bottom"],
            accentColor: accentColor
        )

        SettingsToggleRow(
            title: L10n.string("tvos_settings_addon_logo", fallback: "Add-on Logo"),
            subtitle: L10n.string("tvos_settings_addon_logo_subtitle", fallback: "Show the source add-on logo beside each stream"),
            isOn: $showAddonLogo,
            accentColor: accentColor
        )

        SettingsActionRow(
            title: L10n.string("tvos_settings_install_gold_badge_pack", fallback: "Install Gold Badge Pack"),
            subtitle: L10n.string("tvos_settings_install_gold_badge_pack_subtitle", fallback: "Install the Android TV Gold pack without entering a URL"),
            value: isImportingStreamBadges
                ? L10n.string("tvos_settings_installing", fallback: "Installing…")
                : L10n.string("action_install", fallback: "Install"),
            accentColor: accentColor,
            action: importGoldBadgePack
        )
        .opacity(isImportingStreamBadges ? 0.55 : 1)
        .disabled(isImportingStreamBadges)

        SettingsNativeTextFieldRow(
            title: L10n.string("tvos_settings_badge_pack_url", fallback: "Badge Pack URL"),
            subtitle: streamBadgeImportError ?? L10n.string("tvos_settings_badge_pack_url_subtitle", fallback: "Paste an Android TV-compatible JSON URL; it imports when you press Done (up to 3)"),
            placeholder: "https://…",
            text: $streamBadgeURL,
            fieldWidth: 520,
            onCommit: importStreamBadgePack
        )
        .opacity(isImportingStreamBadges ? 0.55 : 1)
        .disabled(isImportingStreamBadges)

        if importedRules.imports.isEmpty {
            SettingsInfoRow(
                title: L10n.string("tvos_settings_imported_packs", fallback: "Imported Packs"),
                value: L10n.string("action_none", fallback: "None")
            )
        } else {
            ForEach(importedRules.imports) { imported in
                StreamBadgePackSettingsRow(
                    badgePack: imported,
                    accentColor: accentColor,
                    onEnabledChange: { isEnabled in
                        StreamBadgeSettingsStore.setSourceEnabled(
                            imported.sourceUrl,
                            isEnabled: isEnabled
                        )
                    },
                    onDelete: {
                        StreamBadgeSettingsStore.removeSource(imported.sourceUrl)
                    }
                )
            }
        }
    }

    private func importStreamBadgePack() {
        importStreamBadgePack(from: streamBadgeURL, clearDraft: true)
    }

    private func importGoldBadgePack() {
        importStreamBadgePack(from: StreamBadgeSettingsStore.goldBadgePackURL, clearDraft: false)
    }

    private func importStreamBadgePack(from rawURL: String, clearDraft: Bool) {
        let url = rawURL.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !isImportingStreamBadges, !url.isEmpty else { return }
        isImportingStreamBadges = true
        streamBadgeImportError = nil
        Task { @MainActor in
            do {
                _ = try await StreamBadgeSettingsStore.importRules(from: url)
                if clearDraft {
                    streamBadgeURL = ""
                }
            } catch {
                streamBadgeImportError = error.localizedDescription
            }
            isImportingStreamBadges = false
        }
    }
}

@MainActor
private struct PlayerButtonsSettingsSection: View {
    let accentColor: Color
    @Binding var playerShowPiP: Bool
    @Binding var playerShowEpisodes: Bool
    @Binding var playerShowSources: Bool
    @Binding var playerShowSubtitles: Bool
    @Binding var playerShowAudio: Bool
    @Binding var playerShowSpeed: Bool

    @State private var buttons: [TVPlayerButton] = TVPlayerButtonOrder.currentOrder()
    @FocusState private var focusedButtonID: String?

    var body: some View {
        SettingsGroup(
            title: L10n.string("tvos_settings_player_transport_controls", fallback: "Transport Controls"),
            subtitle: L10n.string(
                "tvos_settings_player_transport_controls_subtitle",
                fallback: "Enable and order the PiP, Episodes, Sources, Subtitles, Audio, and Speed buttons."
            )
        ) {
            SettingsActionRow(
                title: L10n.string("action_reset", fallback: "Reset"),
                subtitle: L10n.string(
                    "tvos_settings_reset_player_buttons_subtitle",
                    fallback: "Restore the default button order and visibility"
                ),
                value: L10n.string("action_reset", fallback: "Reset"),
                accentColor: accentColor
            ) {
                reset()
            }

            ForEach(Array(buttons.enumerated()), id: \.element.id) { index, button in
                HStack(spacing: 14) {
                    Button {
                        toggle(button)
                    } label: {
                        SettingsRowShell(isFocused: focusedButtonID == button.id, accentColor: accentColor) {
                            VStack(alignment: .leading, spacing: 4) {
                                Text(button.title)
                                    .font(.system(size: 22, weight: .semibold))
                                    .foregroundColor(isEnabled(button) ? .white : .white.opacity(0.46))
                                    .lineLimit(1)

                                Text(subtitle(for: button))
                                    .font(.system(size: 16, weight: .medium))
                                    .foregroundColor(.white.opacity(isEnabled(button) ? 0.56 : 0.36))
                                    .lineLimit(1)
                            }

                            Spacer(minLength: 20)

                            Text(isEnabled(button)
                                 ? L10n.string("settings_fusion_badge_url_active", fallback: "Active")
                                 : L10n.string("tvos_settings_disabled", fallback: "Disabled"))
                                .font(.system(size: 18, weight: .bold))
                                .foregroundColor(isEnabled(button) ? .white.opacity(0.7) : .white.opacity(0.42))
                                .lineLimit(1)
                        }
                    }
                    .buttonStyle(PosterCardButtonStyle())
                    .focused($focusedButtonID, equals: button.id)
                    .focusEffectDisabledIfAvailable()
                    .entryLockable()

                    AddonReorderButton(systemImage: "chevron.up", disabled: index == 0) {
                        move(index, up: true)
                    }
                    AddonReorderButton(systemImage: "chevron.down", disabled: index == buttons.count - 1) {
                        move(index, up: false)
                    }
                }
                .id(button.id)
            }

        }
        .onAppear(perform: reload)
        .onReceive(NotificationCenter.default.publisher(for: TVPlayerButtonOrder.changedNotification).receive(on: RunLoop.main)) { _ in
            reload()
        }
        .onReceive(NotificationCenter.default.publisher(for: ProfileSettings.settingsChangedNotification).receive(on: RunLoop.main)) { _ in
            reload()
        }
        .onReceive(NotificationCenter.default.publisher(for: UserDefaults.didChangeNotification).receive(on: RunLoop.main)) { _ in
            reload()
        }
    }

    private func reload() {
        let currentOrder = TVPlayerButtonOrder.currentOrder()
        guard buttons != currentOrder else { return }
        buttons = currentOrder
    }

    private func move(_ index: Int, up: Bool) {
        let target = up ? index - 1 : index + 1
        guard buttons.indices.contains(index), buttons.indices.contains(target) else { return }
        buttons.swapAt(index, target)
        TVPlayerButtonOrder.saveOrder(buttons)
    }

    private func isEnabled(_ button: TVPlayerButton) -> Bool {
        switch button {
        case .pip: return playerShowPiP
        case .episodes: return playerShowEpisodes
        case .sources: return playerShowSources
        case .subtitles: return playerShowSubtitles
        case .audio: return playerShowAudio
        case .speed: return playerShowSpeed
        }
    }

    private func toggle(_ button: TVPlayerButton) {
        switch button {
        case .pip: playerShowPiP.toggle()
        case .episodes: playerShowEpisodes.toggle()
        case .sources: playerShowSources.toggle()
        case .subtitles: playerShowSubtitles.toggle()
        case .audio: playerShowAudio.toggle()
        case .speed: playerShowSpeed.toggle()
        }
    }

    private func subtitle(for button: TVPlayerButton) -> String {
        switch button {
        case .pip:
            return L10n.string("tvos_settings_player_pip_subtitle", fallback: "Show the Picture in Picture button in player controls")
        case .episodes:
            return L10n.string("tvos_settings_player_episodes_subtitle", fallback: "Show the Episodes panel button when watching series")
        case .sources:
            return L10n.string("tvos_settings_player_sources_subtitle", fallback: "Show the alternate streams and sources button")
        case .subtitles:
            return L10n.string("tvos_settings_player_subtitles_subtitle", fallback: "Show the native subtitle selector button in player controls")
        case .audio:
            return L10n.string("tvos_settings_player_audio_subtitle", fallback: "Show the native audio and sound adjustments button in player controls")
        case .speed:
            return L10n.string("tvos_settings_player_speed_subtitle", fallback: "Show the quick playback speed button in player controls")
        }
    }

    private func reset() {
        playerShowPiP = true
        playerShowEpisodes = true
        playerShowSources = true
        playerShowSubtitles = true
        playerShowAudio = true
        playerShowSpeed = true
        TVPlayerButtonOrder.resetToDefaults()
        reload()
    }
}

@MainActor
private struct InSightSectionsSettingsSection: View {
    let accentColor: Color
    @Binding var sceneFeatureEnabled: Bool

    @State private var tabs: [SceneTab] = TVSceneTabOrder.currentOrder()
    @State private var disabledTabs: Set<SceneTab> = TVSceneTabOrder.disabledTabs()
    @FocusState private var focusedTabID: String?

    var body: some View {
        SettingsGroup(
            title: L10n.string("tvos_settings_insight_sections", fallback: "InSight Sections"),
            subtitle: L10n.string(
                "tvos_settings_insight_sections_subtitle",
                fallback: "Choose which InSight panel tabs appear and set their order"
            )
        ) {
            SettingsToggleRow(
                title: L10n.string("tvos_settings_enable_insight", fallback: "Enable InSight"),
                subtitle: L10n.string(
                    "tvos_settings_enable_insight_subtitle",
                    fallback: "Allow opening the InSight panel during playback"
                ),
                isOn: $sceneFeatureEnabled,
                accentColor: accentColor
            )

            SettingsActionRow(
                title: L10n.string("action_reset", fallback: "Reset"),
                subtitle: L10n.string(
                    "tvos_settings_reset_insight_sections_subtitle",
                    fallback: "Restore the default section order and visibility, and enable InSight"
                ),
                value: L10n.string("action_reset", fallback: "Reset"),
                accentColor: accentColor
            ) {
                reset()
            }

            ForEach(Array(tabs.enumerated()), id: \.element.id) { index, tab in
                HStack(spacing: 14) {
                    Button {
                        toggle(tab)
                    } label: {
                        SettingsRowShell(isFocused: focusedTabID == tab.id, accentColor: accentColor) {
                            VStack(alignment: .leading, spacing: 4) {
                                Text(title(for: tab))
                                    .font(.system(size: 22, weight: .semibold))
                                    .foregroundColor(isEnabled(tab) ? .white : .white.opacity(0.46))
                                    .lineLimit(1)

                                Text(subtitle(for: tab))
                                    .font(.system(size: 16, weight: .medium))
                                    .foregroundColor(.white.opacity(isEnabled(tab) ? 0.56 : 0.36))
                                    .lineLimit(1)
                            }

                            Spacer(minLength: 20)

                            Text(isEnabled(tab)
                                 ? L10n.string("settings_fusion_badge_url_active", fallback: "Active")
                                 : L10n.string("tvos_settings_disabled", fallback: "Disabled"))
                                .font(.system(size: 18, weight: .bold))
                                .foregroundColor(isEnabled(tab) ? .white.opacity(0.7) : .white.opacity(0.42))
                                .lineLimit(1)
                        }
                    }
                    .buttonStyle(PosterCardButtonStyle())
                    .focused($focusedTabID, equals: tab.id)
                    .focusEffectDisabledIfAvailable()
                    .entryLockable()

                    AddonReorderButton(systemImage: "chevron.up", disabled: index == 0) {
                        move(index, up: true)
                    }
                    AddonReorderButton(systemImage: "chevron.down", disabled: index == tabs.count - 1) {
                        move(index, up: false)
                    }
                }
                .id(tab.id)
            }
        }
        .onAppear(perform: reload)
        .onReceive(NotificationCenter.default.publisher(for: TVSceneTabOrder.changedNotification).receive(on: RunLoop.main)) { _ in
            reload()
        }
        .onReceive(NotificationCenter.default.publisher(for: ProfileSettings.settingsChangedNotification).receive(on: RunLoop.main)) { _ in
            reload()
        }
        .onReceive(NotificationCenter.default.publisher(for: UserDefaults.didChangeNotification).receive(on: RunLoop.main)) { _ in
            reload()
        }
    }

    private func reload() {
        let currentOrder = TVSceneTabOrder.currentOrder()
        if tabs != currentOrder {
            tabs = currentOrder
        }
        let currentDisabledTabs = TVSceneTabOrder.disabledTabs()
        if disabledTabs != currentDisabledTabs {
            disabledTabs = currentDisabledTabs
        }
    }

    private func isEnabled(_ tab: SceneTab) -> Bool {
        !disabledTabs.contains(tab)
    }

    private func toggle(_ tab: SceneTab) {
        TVSceneTabOrder.setTabEnabled(tab, isEnabled: !isEnabled(tab))
        reload()
    }

    private func move(_ index: Int, up: Bool) {
        let target = up ? index - 1 : index + 1
        guard tabs.indices.contains(index), tabs.indices.contains(target) else { return }
        tabs.swapAt(index, target)
        TVSceneTabOrder.saveOrder(tabs)
    }

    private func subtitle(for tab: SceneTab) -> String {
        switch tab {
        case .chapters:
            return L10n.string("tvos_settings_insight_chapters_subtitle", fallback: "The file's chapters, with stills")
        case .autoSync:
            return L10n.string("tvos_settings_insight_autosync_subtitle", fallback: "Sync add-on subtitles by hand, with diagnostics")
        case .scene:
            return L10n.string("tvos_settings_insight_scene_subtitle", fallback: "Cast and song recognition")
        case .info:
            return L10n.string("tvos_settings_insight_info_subtitle", fallback: "Playback engine and stream details")
        case .upNext:
            return L10n.string("tvos_settings_insight_up_next_subtitle", fallback: "Details for the next episode")
        case .watchParty:
            return L10n.string("tvos_settings_insight_watch_party_subtitle", fallback: "Watch Party session controls")
        }
    }

    private func title(for tab: SceneTab) -> String {
        if tab == .scene {
            return L10n.string("tvos_settings_player_scene", fallback: "Scene (InSight)")
        }
        return tab.localizedTitle
    }

    private func reset() {
        sceneFeatureEnabled = true
        TVSceneTabOrder.resetToDefaults()
        reload()
    }
}

// MARK: - Subtitle Style tab

/// Thin wrapper used by the Settings sidebar tab.
private struct SubtitleStyleSettingsView: View {
    let accentColor: Color
    var body: some View { SubtitleStyleEditor(accentColor: accentColor) }
}

/// A single row in the subtitle presets reorder panel matching the Add-ons manager design.
private struct SubtitlePresetSettingsRow: View {
    let preset: SubtitleStylePreset
    let isActive: Bool
    let accentColor: Color
    var canMoveUp: Bool = false
    var canMoveDown: Bool = false
    var canDelete: Bool = true
    var onSelect: (() -> Void)? = nil
    var onRename: (() -> Void)? = nil
    var onDelete: (() -> Void)? = nil
    var onMove: ((Bool) -> Void)? = nil

    @FocusState private var isFocused: Bool

    var body: some View {
        HStack(spacing: 14) {
            rowButton

            if let onRename {
                AddonReorderButton(systemImage: "pencil", disabled: false, action: onRename)
            }

            if let onDelete {
                AddonReorderButton(systemImage: "trash", disabled: !canDelete, action: onDelete)
            }

            if let onMove {
                AddonReorderButton(systemImage: "chevron.up", disabled: !canMoveUp) {
                    onMove(true)
                }
                AddonReorderButton(systemImage: "chevron.down", disabled: !canMoveDown) {
                    onMove(false)
                }
            }
        }
    }

    private var rowButton: some View {
        Button(action: { onSelect?() }) {
            SettingsRowShell(isFocused: isFocused, accentColor: accentColor) {
                Image(systemName: "captions.bubble.fill")
                    .font(.system(size: 24))
                    .foregroundColor(isActive ? accentColor : .white.opacity(0.4))
                    .frame(width: 44, height: 44)

                VStack(alignment: .leading, spacing: 4) {
                    HStack(spacing: 8) {
                        Text(preset.name)
                            .font(.system(size: 22, weight: .semibold))
                            .foregroundColor(isActive ? .white : .white.opacity(0.88))
                            .lineLimit(1)
                        if isActive {
                            Text(L10n.string("settings_fusion_badge_url_active", fallback: "Active"))
                                .font(.system(size: 13, weight: .bold))
                                .foregroundColor(accentColor)
                        }
                    }

                    Text(subtitleText)
                        .font(.system(size: 16, weight: .medium))
                        .foregroundColor(.white.opacity(isActive ? 0.6 : 0.38))
                        .lineLimit(1)
                }

                Spacer(minLength: 20)

                Text(isActive ? L10n.string("settings_fusion_badge_url_active", fallback: "Active") : L10n.string("common_load", fallback: "Load"))
                    .font(.system(size: 18, weight: .bold))
                    .foregroundColor(isActive ? accentColor : .white.opacity(0.42))
                    .lineLimit(1)
            }
        }
        .buttonStyle(PosterCardButtonStyle())
        .focused($isFocused)
        .focusEffectDisabledIfAvailable()
        .entryLockable()
    }

    private var subtitleText: String {
        var parts: [String] = []
        parts.append(preset.style.fontName)
        parts.append("\(Int(preset.style.textSize))%")
        if preset.style.backgroundEnabled {
            parts.append(L10n.string("subtitle_bg_card", fallback: "Background"))
        } else if preset.style.outlineEnabled {
            parts.append(L10n.string("subtitle_outline", fallback: "Outline"))
        }
        return parts.joined(separator: " · ")
    }
}

/// The reorder and preset management panel presented inside SettingsFeatureSettingsSheet.
private struct SubtitlePresetsSettingsSection: View {
    let accentColor: Color
    let style: SubtitleStyle
    let onSelectPreset: (SubtitleStylePreset) -> Void
    var onChange: (() -> Void)? = nil

    @State private var renamingPresetID: String?
    @State private var renamingText = ""
    @State private var newPresetNameDraft = ""
    @State private var presets: [SubtitleStylePreset] = SubtitleStylePresetStore.shared.allPresets()

    private var activePreset: SubtitleStylePreset? {
        SubtitleStylePresetStore.shared.activePreset(for: style)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 22) {
            SettingsGroup(
                title: L10n.string("subtitle_style_presets", fallback: "Presets"),
                subtitle: L10n.string("subtitle_style_presets_subtitle", fallback: "Create new presets, reorder them, or tap a style to load and edit it.")
            ) {
                SettingsNativeTextFieldRow(
                    title: L10n.string("subtitle_style_preset_name", fallback: "New Preset Name"),
                    subtitle: L10n.string("subtitle_style_preset_name_desc", fallback: "Custom name for creating a new preset"),
                    placeholder: SubtitleStylePresetStore.shared.suggestedCustomPresetName(),
                    text: $newPresetNameDraft
                )
                .settingsEntryAnchor()

                SettingsActionRow(
                    title: L10n.string("subtitle_style_save_preset", fallback: "Save Current Style as New Preset"),
                    subtitle: L10n.string("subtitle_style_save_preset_desc", fallback: "Create a new preset with current appearance settings"),
                    value: L10n.string("common_save", fallback: "Create"),
                    accentColor: accentColor,
                    action: {
                        let name = newPresetNameDraft.trimmingCharacters(in: .whitespacesAndNewlines)
                        let newPreset = SubtitleStylePresetStore.shared.saveCurrentAsPreset(name: name.isEmpty ? nil : name)
                        newPresetNameDraft = ""
                        refreshPresets()
                        onSelectPreset(newPreset)
                        onChange?()
                    }
                )

                ForEach(Array(presets.enumerated()), id: \.element.id) { index, preset in
                    let isActive = activePreset?.id == preset.id

                    VStack(alignment: .leading, spacing: 12) {
                        SubtitlePresetSettingsRow(
                            preset: preset,
                            isActive: isActive,
                            accentColor: accentColor,
                            canMoveUp: index > 0,
                            canMoveDown: index < presets.count - 1,
                            canDelete: presets.count > 1,
                            onSelect: {
                                if isActive {
                                    if renamingPresetID == preset.id {
                                        renamingPresetID = nil
                                        renamingText = ""
                                    } else {
                                        renamingPresetID = preset.id
                                        renamingText = preset.name
                                    }
                                } else {
                                    onSelectPreset(preset)
                                    renamingPresetID = nil
                                    renamingText = ""
                                }
                            },
                            onRename: {
                                if renamingPresetID == preset.id {
                                    renamingPresetID = nil
                                    renamingText = ""
                                } else {
                                    renamingPresetID = preset.id
                                    renamingText = preset.name
                                }
                            },
                            onDelete: {
                                if renamingPresetID == preset.id {
                                    renamingPresetID = nil
                                    renamingText = ""
                                }
                                SubtitleStylePresetStore.shared.deleteCustomPreset(id: preset.id)
                                refreshPresets()
                                if activePreset?.id == preset.id,
                                   let remaining = presets.first {
                                    onSelectPreset(remaining)
                                }
                                onChange?()
                            },
                            onMove: { up in
                                if renamingPresetID == preset.id {
                                    renamingPresetID = nil
                                    renamingText = ""
                                }
                                SubtitleStylePresetStore.shared.movePreset(at: index, up: up)
                                refreshPresets()
                                onChange?()
                            }
                        )

                        if renamingPresetID == preset.id {
                            HStack(spacing: 14) {
                                SettingsTextFieldRow(
                                    title: L10n.string("subtitle_style_rename_preset", fallback: "Rename Style"),
                                    subtitle: L10n.string("subtitle_style_rename_preset_desc", fallback: "Enter a new name for this style"),
                                    placeholder: preset.name,
                                    text: $renamingText,
                                    fieldWidth: 500,
                                    onCommit: { commitRename(for: preset.id) }
                                )
                                AddonReorderButton(systemImage: "checkmark", disabled: false) {
                                    commitRename(for: preset.id)
                                }
                                AddonReorderButton(systemImage: "xmark", disabled: false) {
                                    renamingPresetID = nil
                                    renamingText = ""
                                }
                            }
                            .padding(.leading, 20)
                        }
                    }
                }

                SettingsActionRow(
                    title: L10n.string("subtitle_style_reset_all_presets", fallback: "Reset All Styles to Defaults"),
                    subtitle: L10n.string("subtitle_style_reset_all_presets_desc", fallback: "Restore the 6 built-in Apple TV subtitle styles"),
                    value: L10n.string("common_reset", fallback: "Reset"),
                    accentColor: .red,
                    action: {
                        SubtitleStylePresetStore.shared.resetToDefaults()
                        refreshPresets()
                        if let first = presets.first {
                            onSelectPreset(first)
                        }
                        renamingPresetID = nil
                        renamingText = ""
                        onChange?()
                    }
                )
            }
        }
        .onAppear {
            refreshPresets()
        }
        .onReceive(NotificationCenter.default.publisher(for: SubtitleStylePresetStore.presetsChangedNotification).receive(on: RunLoop.main)) { _ in
            refreshPresets()
        }
    }

    private func refreshPresets() {
        withAnimation(.easeInOut(duration: 0.2)) {
            presets = SubtitleStylePresetStore.shared.allPresets()
        }
    }

    private func commitRename(for presetID: String) {
        let trimmed = renamingText.trimmingCharacters(in: .whitespacesAndNewlines)
        if !trimmed.isEmpty {
            SubtitleStylePresetStore.shared.renameCustomPreset(id: presetID, newName: trimmed)
            refreshPresets()
            onChange?()
        }
        renamingPresetID = nil
        renamingText = ""
    }
}

/// The full subtitle-appearance editor: a live preview plus every control.
/// Reused by the Settings tab and by the in-player styling panel. `onChange`
/// fires after any value changes so the player can re-apply the style to mpv
/// live while you watch.
struct SubtitleStyleEditor: View {
    let accentColor: Color
    var onChange: (() -> Void)? = nil

    @ObservedObject private var fontLibrary = SubtitleFontLibrary.shared
    @State private var showingCustomFonts = false
    @State private var showingPresetsSheet = false
    @State private var presetsRevision = 0
    @State private var isApplyingPreset = false
    @AppStorage(SubtitleStyleKey.fontName) private var fontName = SubtitleStyleDefaults.fontName
    @AppStorage(SubtitleStyleKey.textSize) private var textSize = SubtitleStyleDefaults.textSize
    @AppStorage(SubtitleStyleKey.bold) private var bold = SubtitleStyleDefaults.bold
    @AppStorage(SubtitleStyleKey.verticalAlignment) private var verticalAlignment = SubtitleStyleDefaults.verticalAlignment
    @AppStorage(SubtitleStyleKey.bottomOffset) private var bottomOffset = SubtitleStyleDefaults.bottomOffset
    @AppStorage(SubtitleStyleKey.horizontalMargin) private var horizontalMargin = SubtitleStyleDefaults.horizontalMargin
    @AppStorage(SubtitleStyleKey.letterSpacing) private var letterSpacing = SubtitleStyleDefaults.letterSpacing
    @AppStorage(SubtitleStyleKey.textColor) private var textColor = SubtitleStyleDefaults.textColor
    @AppStorage(SubtitleStyleKey.textOpacity) private var textOpacity = SubtitleStyleDefaults.textOpacity
    @AppStorage(SubtitleStyleKey.outlineEnabled) private var outlineEnabled = SubtitleStyleDefaults.outlineEnabled
    @AppStorage(SubtitleStyleKey.outlineColor) private var outlineColor = SubtitleStyleDefaults.outlineColor
    @AppStorage(SubtitleStyleKey.outlineWidth) private var outlineWidth = SubtitleStyleDefaults.outlineWidth
    @AppStorage(SubtitleStyleKey.backgroundEnabled) private var backgroundEnabled = SubtitleStyleDefaults.backgroundEnabled
    @AppStorage(SubtitleStyleKey.backgroundColor) private var backgroundColor = SubtitleStyleDefaults.backgroundColor
    @AppStorage(SubtitleStyleKey.backgroundOpacity) private var backgroundOpacity = SubtitleStyleDefaults.backgroundOpacity

    private var style: SubtitleStyle {
        SubtitleStyle(
            fontName: fontName,
            textSize: min(220, max(5, textSize)),
            bold: bold,
            verticalAlignment: verticalAlignment,
            bottomOffset: bottomOffset,
            horizontalMargin: horizontalMargin,
            letterSpacing: letterSpacing,
            textColorHex: textColor,
            textOpacity: textOpacity,
            outlineEnabled: outlineEnabled,
            outlineColorHex: outlineColor,
            outlineWidth: min(8, max(1, outlineWidth)),
            backgroundEnabled: backgroundEnabled,
            backgroundColorHex: backgroundColor,
            backgroundOpacity: backgroundOpacity
        )
    }

    /// Concatenation of every value; `.onChange` on it fires `onChange` once per edit.
    private var changeToken: String {
        "\(fontName)|\(textSize)|\(bold)|\(verticalAlignment)|\(bottomOffset)|\(horizontalMargin)|\(letterSpacing)|\(textColor)|\(textOpacity)|\(outlineEnabled)|\(outlineColor)|\(outlineWidth)|\(backgroundEnabled)|\(backgroundColor)|\(backgroundOpacity)"
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 22) {
            SubtitlePreviewCard(style: style)

            ScrollView {
                controls
                    // Generous trailing room so the last rows can scroll clear of
                    // the scroll view's bottom clip edge — without it, focusing the
                    // final stepper leaves its +/- controls sliced off the bottom.
                    .padding(.bottom, 140)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .focusSection()
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .onChange(of: changeToken) { _, _ in
            guard !isApplyingPreset else { return }
            let targetID = SubtitleStylePresetStore.shared.savedPresetID()
                ?? SubtitleStylePresetStore.shared.activePreset(for: style)?.id
                ?? SubtitleStylePresetStore.shared.allPresets().first?.id
            if let targetID {
                SubtitleStylePresetStore.shared.updateCustomPresetStyle(id: targetID, style: style)
            }
            onChange?()
        }
        .sheet(isPresented: $showingCustomFonts) {
            CustomSubtitleFontsSheet(accentColor: accentColor)
                .modifier(ClearPresentationBackgroundIfAvailable())
        }
        .onReceive(NotificationCenter.default.publisher(for: SubtitleStylePresetStore.presetsChangedNotification).receive(on: RunLoop.main)) { _ in
            presetsRevision &+= 1
        }
        .fullScreenCover(isPresented: $showingPresetsSheet) {
            SettingsFeatureSettingsSheet(
                title: L10n.string("subtitle_style_presets", fallback: "Presets"),
                subtitle: L10n.string("subtitle_style_presets_sheet_subtitle", fallback: "Reorder, rename, or delete saved subtitle styles")
            ) {
                SubtitlePresetsSettingsSection(
                    accentColor: accentColor,
                    style: style,
                    onSelectPreset: { preset in
                        applyPreset(preset)
                    },
                    onChange: onChange
                )
            }
            .modifier(ClearPresentationBackgroundIfAvailable())
        }
    }

    private var controls: some View {
        _ = presetsRevision
        let allPresets = SubtitleStylePresetStore.shared.allPresets()

        return VStack(alignment: .leading, spacing: 22) {
            SettingsFeatureSummaryCard(
                featureName: L10n.string("subtitle_style_presets", fallback: "Presets"),
                status: "\(SubtitleStylePresetStore.shared.activePresetTitle(for: style)) · \(settingsCountSummary(allPresets.count, singular: "preset", plural: "presets"))",
                actionSubtitle: L10n.string("subtitle_style_presets_subtitle", fallback: "Create, reorder, rename, or delete preset styles"),
                accentColor: accentColor,
                isEntryAnchor: true
            ) {
                showingPresetsSheet = true
            }

            SettingsGroup(title: L10n.string("tvos_settings_text", fallback: "Text"), subtitle: L10n.string("tvos_settings_size_weight_spacing_color_and_opacity_of_4755001d", fallback: "Size, weight, spacing, color, and opacity of the caption text")) {
                SettingsOptionRow(
                    title: L10n.string("subtitle_font", fallback: "Font"),
                    subtitle: L10n.string("subtitle_font_desc", fallback: "Typeface used for subtitles"),
                    selection: $fontName,
                    options: SubtitleFontOption.allCases.map(\.rawValue) + fontLibrary.familyNames,
                    accentColor: accentColor,
                    optionLabel: { name in
                        // Fonts from Custom Fonts are marked as uploaded.
                        SubtitleFontOption(rawValue: name) == nil && fontLibrary.familyNames.contains(name)
                            ? name + " · " + L10n.string("player_subtitle_font_uploaded", fallback: "Uploaded")
                            : L10n.optionLabel(name)
                    }
                )

                SettingsActionRow(
                    title: L10n.string("subtitle_custom_fonts", fallback: "Custom Fonts"),
                    subtitle: L10n.string(
                        "subtitle_custom_fonts_desc",
                        fallback: "Your own fonts, sent from a phone or computer or downloaded from a link"
                    ),
                    value: fontLibrary.fonts.isEmpty ? "" : "\(fontLibrary.fonts.count)",
                    accentColor: accentColor
                ) {
                    showingCustomFonts = true
                }

                SettingsStepperRow(
                    title: L10n.string("tvos_settings_text_size", fallback: "Text Size"),
                    subtitle: L10n.string("tvos_settings_relative_subtitle_text_size", fallback: "Relative subtitle text size"),
                    value: $textSize,
                    range: 5...220,
                    step: 5,
                    suffix: "%",
                    accentColor: accentColor
                )

                SettingsToggleRow(
                    title: L10n.string("subtitle_bold", fallback: "Bold"),
                    subtitle: L10n.string("tvos_settings_use_a_heavier_caption_weight", fallback: "Use a heavier caption weight"),
                    isOn: $bold,
                    accentColor: accentColor
                )

                SettingsStepperRow(
                    title: L10n.string("tvos_settings_letter_spacing", fallback: "Letter Spacing"),
                    subtitle: L10n.string("tvos_settings_squeeze_the_text_together_or_open_it_up", fallback: "Squeeze the text together or open it up"),
                    value: $letterSpacing,
                    range: -8...40,
                    step: 2,
                    suffix: "",
                    accentColor: accentColor
                )

                SubtitleColorRow(
                    title: L10n.string("subtitle_style_text_color", fallback: "Text Color"),
                    subtitle: L10n.string("tvos_settings_caption_fill_color", fallback: "Caption fill color"),
                    selection: $textColor,
                    accentColor: accentColor
                )

                SettingsStepperRow(
                    title: L10n.string("subtitle_style_text_opacity", fallback: "Text Opacity"),
                    subtitle: L10n.string("tvos_settings_caption_transparency", fallback: "Caption transparency"),
                    value: $textOpacity,
                    range: 20...100,
                    step: 5,
                    suffix: "%",
                    accentColor: accentColor
                )
            }

            SettingsGroup(title: L10n.string("tvos_settings_position", fallback: "Position"), subtitle: L10n.string("tvos_settings_where_captions_sit_on_screen", fallback: "Where captions sit on screen")) {
                SettingsOptionRow(
                    title: L10n.string("subtitle_position", fallback: "Screen Position"),
                    subtitle: L10n.string("subtitle_position_desc", fallback: "Place captions at the bottom or top of the screen"),
                    selection: $verticalAlignment,
                    options: SubtitleVerticalPosition.allCases.map(\.rawValue),
                    accentColor: accentColor
                )

                SettingsStepperRow(
                    title: L10n.string("tvos_settings_vertical_position", fallback: "Vertical Position"),
                    subtitle: L10n.string("subtitle_vertical_position_adjustment_desc", fallback: "Increase to move captions away from the screen edge; decrease to move them closer"),
                    value: $bottomOffset,
                    range: SubtitleStyleDefaults.bottomOffsetRange,
                    step: 4,
                    suffix: "",
                    accentColor: accentColor
                )

                SettingsStepperRow(
                    title: L10n.string("tvos_settings_horizontal_margin", fallback: "Horizontal Margin"),
                    subtitle: L10n.string("tvos_settings_inset_captions_in_from_the_left_and_right_edges", fallback: "Inset captions in from the left and right edges"),
                    value: $horizontalMargin,
                    range: 0...200,
                    step: 5,
                    suffix: "",
                    accentColor: accentColor
                )
            }

            SettingsGroup(title: L10n.string("subtitle_outline", fallback: "Outline"), subtitle: L10n.string("tvos_settings_border_drawn_around_the_text_for_readability", fallback: "Border drawn around the text for readability")) {
                SettingsToggleRow(
                    title: L10n.string("subtitle_outline", fallback: "Outline"),
                    subtitle: L10n.string("tvos_settings_draw_a_border_around_the_text_for_readability", fallback: "Draw a border around the text for readability"),
                    isOn: $outlineEnabled,
                    accentColor: accentColor
                )

                SubtitleColorRow(
                    title: L10n.string("subtitle_outline_color", fallback: "Outline Color"),
                    subtitle: L10n.string("tvos_settings_border_color_drawn_around_the_text", fallback: "Border color drawn around the text"),
                    selection: $outlineColor,
                    accentColor: accentColor
                )
                .opacity(outlineEnabled ? 1 : 0.46)
                .disabled(!outlineEnabled)

                SettingsStepperRow(
                    title: L10n.string("subtitle_outline_width", fallback: "Outline Thickness"),
                    subtitle: L10n.string("subtitle_outline_width_desc", fallback: "Width of the text stroke border"),
                    value: $outlineWidth,
                    range: 1...6,
                    step: 1,
                    suffix: "pt",
                    accentColor: accentColor
                )
                .opacity(outlineEnabled ? 1 : 0.46)
                .disabled(!outlineEnabled)
            }

            SettingsGroup(
                title: L10n.string("subtitle_background", fallback: "Background"),
                subtitle: L10n.string(
                    "tvos_settings_subtitle_background_subtitle",
                    fallback: "A backdrop behind captions for improved readability"
                )
            ) {
                SettingsToggleRow(
                    title: L10n.string("subtitle_background", fallback: "Background"),
                    subtitle: L10n.string(
                        "tvos_settings_subtitle_background_toggle",
                        fallback: "Draw a padded box behind subtitle text"
                    ),
                    isOn: $backgroundEnabled,
                    accentColor: accentColor
                )

                SubtitleColorRow(
                    title: L10n.string("subtitle_background_color", fallback: "Background Color"),
                    subtitle: L10n.string(
                        "tvos_settings_subtitle_background_color_subtitle",
                        fallback: "Color of the subtitle backdrop"
                    ),
                    selection: $backgroundColor,
                    accentColor: accentColor
                )
                .opacity(backgroundEnabled ? 1 : 0.46)
                .disabled(!backgroundEnabled)

                SettingsStepperRow(
                    title: L10n.string("subtitle_background_opacity", fallback: "Background Opacity"),
                    subtitle: L10n.string(
                        "tvos_settings_subtitle_background_opacity_subtitle",
                        fallback: "Transparency of the subtitle backdrop"
                    ),
                    value: $backgroundOpacity,
                    range: 10...100,
                    step: 5,
                    suffix: "%",
                    accentColor: accentColor
                )
                .opacity(backgroundEnabled ? 1 : 0.46)
                .disabled(!backgroundEnabled)
            }

            SettingsGroup(title: L10n.string("subtitle_style_reset", fallback: "Reset"), subtitle: L10n.string("tvos_settings_restore_the_default_subtitle_appearance", fallback: "Restore the default subtitle appearance")) {
                SettingsActionRow(
                    title: L10n.string("subtitle_reset_defaults", fallback: "Reset Defaults"),
                    subtitle: L10n.string("tvos_settings_clears_every_value_on_this_screen", fallback: "Clears every value on this screen"),
                    value: L10n.string("subtitle_style_reset", fallback: "Reset"),
                    accentColor: accentColor,
                    action: resetDefaults
                )
            }
        }
    }

    private func applyPreset(_ preset: SubtitleStylePreset) {
        isApplyingPreset = true
        fontName = preset.style.fontName
        textSize = preset.style.textSize
        bold = preset.style.bold
        verticalAlignment = preset.style.verticalAlignment
        bottomOffset = preset.style.bottomOffset
        horizontalMargin = preset.style.horizontalMargin
        letterSpacing = preset.style.letterSpacing
        textColor = preset.style.textColorHex
        textOpacity = preset.style.textOpacity
        outlineEnabled = preset.style.outlineEnabled
        outlineColor = preset.style.outlineColorHex
        outlineWidth = preset.style.outlineWidth
        backgroundEnabled = preset.style.backgroundEnabled
        backgroundColor = preset.style.backgroundColorHex
        backgroundOpacity = preset.style.backgroundOpacity
        SubtitleStylePresetStore.shared.applyPreset(preset)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) {
            isApplyingPreset = false
        }
        onChange?()
    }

    private func resetDefaults() {
        fontName = SubtitleStyleDefaults.fontName
        textSize = SubtitleStyleDefaults.textSize
        bold = SubtitleStyleDefaults.bold
        verticalAlignment = SubtitleStyleDefaults.verticalAlignment
        bottomOffset = SubtitleStyleDefaults.bottomOffset
        horizontalMargin = SubtitleStyleDefaults.horizontalMargin
        letterSpacing = SubtitleStyleDefaults.letterSpacing
        textColor = SubtitleStyleDefaults.textColor
        textOpacity = SubtitleStyleDefaults.textOpacity
        outlineEnabled = SubtitleStyleDefaults.outlineEnabled
        outlineColor = SubtitleStyleDefaults.outlineColor
        outlineWidth = SubtitleStyleDefaults.outlineWidth
        backgroundEnabled = SubtitleStyleDefaults.backgroundEnabled
        backgroundColor = SubtitleStyleDefaults.backgroundColor
        backgroundOpacity = SubtitleStyleDefaults.backgroundOpacity
    }
}

/// Faux video frame that renders sample captions with the live style so the
/// user sees the result before pressing play.
private struct SubtitlePreviewCard: View {
    let style: SubtitleStyle

    private let sampleText = "The quick brown fox jumps over the lazy dog"

    private var fontSize: CGFloat {
        min(max(CGFloat(style.textSize) / 100.0 * 40.0, 2), 92)
    }

    private var isTopAligned: Bool {
        style.verticalAlignment.caseInsensitiveCompare("Top") == .orderedSame
    }

    private var previewVerticalPadding: CGFloat {
        22 + CGFloat(style.subMarginY - 22) * 0.7
    }

    private var previewHorizontalPadding: CGFloat {
        16 + CGFloat(min(max(style.horizontalMargin, 0), 200)) / 200.0 * 130.0
    }

    private var previewTracking: CGFloat {
        CGFloat(style.subSpacing) * 0.6
    }

    private var outlineWidth: CGFloat {
        guard style.outlineEnabled else { return 0 }
        let configured = max(1, CGFloat(style.outlineWidth) * 0.8)
        return min(configured, max(0.5, fontSize * 0.3))
    }

    private var outlineOffsets: [CGPoint] {
        let w = outlineWidth
        return [
            CGPoint(x: -w, y: 0), CGPoint(x: w, y: 0),
            CGPoint(x: 0, y: -w), CGPoint(x: 0, y: w),
            CGPoint(x: -w, y: -w), CGPoint(x: w, y: -w),
            CGPoint(x: -w, y: w), CGPoint(x: w, y: w)
        ]
    }

    var body: some View {
        // Decorative backdrop only. The 320pt Circle's intrinsic size was warping
        // where `ZStack(.bottom)` placed the caption, dropping it below the card's
        // clipped 220pt bottom. Keeping the caption as a bottom/top *overlay* pins it to
        // the real 220pt frame instead, so its vertical padding is honored.
        ZStack {
            LinearGradient(
                colors: [
                    Color(red: 0.12, green: 0.14, blue: 0.24),
                    Color(red: 0.05, green: 0.06, blue: 0.11),
                    .black
                ],
                startPoint: .top,
                endPoint: .bottom
            )

            Circle()
                .fill(Color.white.opacity(0.06))
                .frame(width: 320, height: 320)
                .blur(radius: 60)
                .offset(x: -180, y: -70)
        }
        .frame(height: 220)
        .frame(maxWidth: .infinity)
        .overlay(alignment: isTopAligned ? .top : .bottom) {
            styledSubtitle
                .frame(maxWidth: .infinity)
                .padding(.horizontal, previewHorizontalPadding)
                .padding(isTopAligned ? .top : .bottom, previewVerticalPadding)
        }
        .clipShape(RoundedRectangle(cornerRadius: 28, style: .continuous))
        .overlay(
            RoundedRectangle(cornerRadius: 28, style: .continuous)
                .strokeBorder(Color.white.opacity(0.12), lineWidth: 1)
        )
        .overlay(alignment: .topLeading) {
            Text(L10n.string("tvos_settings_preview", fallback: "PREVIEW"))
                .font(.system(size: 14, weight: .black))
                .tracking(2)
                .foregroundColor(.white.opacity(0.5))
                .padding(18)
        }
    }

    @ViewBuilder
    private var styledSubtitle: some View {
        if style.backgroundEnabled {
            styledSubtitleText
                .padding(.horizontal, 14)
                .padding(.vertical, 7)
                .background(
                    Color(hex: style.backgroundColorHex)
                        .opacity(Double(min(max(style.backgroundOpacity, 0), 100)) / 100),
                    in: RoundedRectangle(cornerRadius: 8, style: .continuous)
                )
        } else {
            styledSubtitleText
        }
    }

    private var styledSubtitleText: some View {
        let font = style.font(size: fontSize, weight: style.bold ? .heavy : .semibold)
        let fill = Color(hex: style.textColorHex).opacity(Double(min(max(style.textOpacity, 0), 100)) / 100.0)
        let outline = Color(hex: style.outlineColorHex)
        return ZStack {
            if style.outlineEnabled && outlineWidth > 0 {
                ForEach(Array(outlineOffsets.enumerated()), id: \.offset) { _, point in
                    Text(sampleText)
                        .font(font)
                        .foregroundColor(outline)
                        .offset(x: point.x, y: point.y)
                }
            }
            Text(sampleText)
                .font(font)
                .foregroundColor(fill)
        }
        .tracking(previewTracking)
        .multilineTextAlignment(.center)
        .lineLimit(2)
        .shadow(color: .black.opacity(0.5), radius: 3, x: 0, y: 1)
        .animation(.easeOut(duration: 0.12), value: fontSize)
    }
}

private struct SubtitleColorRow: View {
    let title: String
    let subtitle: String
    @Binding var selection: String
    let accentColor: Color
    var colors: [String] = SubtitlePalette.colors

    var body: some View {
        HStack(spacing: 20) {
            SettingsRowText(title: title, subtitle: subtitle)
                .frame(maxWidth: .infinity, alignment: .leading)

            HStack(spacing: 12) {
                ForEach(colors, id: \.self) { hex in
                    SubtitleColorSwatchButton(
                        hex: hex,
                        isSelected: selection.caseInsensitiveCompare(hex) == .orderedSame,
                        accentColor: accentColor
                    ) {
                        selection = hex
                    }
                }
            }
            .fixedSize(horizontal: true, vertical: false)
        }
        .padding(.horizontal, 20)
        .frame(minHeight: 74)
        .frame(maxWidth: .infinity, alignment: .leading)
        .settingsGlass(shape: RoundedRectangle(cornerRadius: 24, style: .continuous), isProminent: false)
        .overlay(
            RoundedRectangle(cornerRadius: 24, style: .continuous)
                .strokeBorder(Color.white.opacity(0.10), lineWidth: 1)
        )
    }
}

private struct SubtitleColorSwatchButton: View {
    let hex: String
    let isSelected: Bool
    let accentColor: Color
    let action: () -> Void

    @FocusState private var isFocused: Bool

    var body: some View {
        Button(action: action) {
            Circle()
                .fill(Color(hex: hex))
                .frame(width: 40, height: 40)
                .overlay(
                    Circle()
                        .strokeBorder(Color.white.opacity(0.16), lineWidth: 1)
                )
                .overlay(
                    Circle()
                        .strokeBorder(ringColor, lineWidth: isFocused ? AppFocusOutline.width : (isSelected ? 4 : 0))
                        .padding(-4)
                )
        }
        .buttonStyle(PosterCardButtonStyle())
        .focused($isFocused)
        .focusEffectDisabledIfAvailable()
        .entryLockable()
        .scaleEffect(isFocused ? 1.18 : 1.0)
        .zIndex(isFocused ? 1 : 0)
        .animation(.easeOut(duration: 0.14), value: isFocused)
    }

    private var ringColor: Color {
        if isFocused { return AppFocusOutline.color }
        return isSelected ? accentColor : .clear
    }
}

private struct LanguagePickerWindow: View {
    let title: String
    let subtitle: String
    let systemImage: String
    @Binding var selection: [String]
    let languages: [String]
    let allowsMultiple: Bool
    let accentColor: Color
    let onDone: () -> Void

    @FocusState private var focusedControl: Control?
    @State private var lastFocusedLanguage: String?

    private enum Control: Hashable {
        case language(String)
        case done
        case leftGuard
    }

    var body: some View {
        ZStack {
            Color.black.opacity(0.62)
                .ignoresSafeArea()

            VStack(alignment: .leading, spacing: 22) {
                HStack(spacing: 18) {
                    Image(systemName: systemImage)
                        .font(.system(size: 38, weight: .semibold))
                        .foregroundColor(accentColor)
                        .frame(width: 58, height: 58)
                        .settingsGlass(shape: Circle(), isProminent: true)

                    VStack(alignment: .leading, spacing: 5) {
                        Text(title)
                            .font(.system(size: 34, weight: .bold))
                            .foregroundColor(.white)
                        Text(subtitle)
                            .font(.system(size: 19, weight: .medium))
                            .foregroundColor(.white.opacity(0.58))
                    }
                }

                ScrollView {
                    VStack(alignment: .leading, spacing: 10) {
                        ForEach(languages, id: \.self) { language in
                            LanguagePickerListRow(
                                language: language,
                                priority: priority(for: language),
                                isSelected: isSelected(language),
                                isFocused: focusedControl == .language(language),
                                accentColor: accentColor
                            ) {
                                toggle(language)
                            }
                            .focused($focusedControl, equals: .language(language))
                        }
                    }
                    .padding(.vertical, 2)
                }
                .frame(maxHeight: 420)
                .clipShape(RoundedRectangle(cornerRadius: 24, style: .continuous))
                .overlay(alignment: .leading) {
                    Button(action: {}) {
                        Color.white.opacity(0.001)
                            .frame(width: 24, height: 390)
                    }
                    .buttonStyle(PosterCardButtonStyle())
                    .focused($focusedControl, equals: .leftGuard)
                    .focusEffectDisabledIfAvailable()
                    .offset(x: -18)
                    .accessibilityHidden(true)
                }
                .focusSection()

                HStack {
                    Spacer()
                    Button(action: onDone) {
                        HStack(spacing: 10) {
                            Image(systemName: "checkmark")
                                .font(.system(size: 18, weight: .bold))
                            Text(L10n.string("tvos_common_done", fallback: "Done"))
                                .font(.system(size: 21, weight: .bold))
                        }
                        .foregroundColor(focusedControl == .done ? .black : .white)
                        .padding(.horizontal, 26)
                        .frame(height: 58)
                        .modifier(
                            TvDetailsGlassBackground(
                                filled: focusedControl == .done,
                                shape: Capsule()
                            )
                        )
                    }
                    .buttonStyle(PosterCardButtonStyle())
                    .focused($focusedControl, equals: .done)
                    .focusEffectDisabledIfAvailable()
                    .scaleEffect(focusedControl == .done ? 1.06 : 1)
                    .animation(.easeOut(duration: 0.14), value: focusedControl == .done)
                }
            }
            .padding(34)
            .frame(width: 900)
            .settingsGlass(shape: RoundedRectangle(cornerRadius: 34, style: .continuous), isProminent: true)
            .overlay(
                RoundedRectangle(cornerRadius: 34, style: .continuous)
                    .strokeBorder(Color.white.opacity(0.20), lineWidth: 1)
            )
            .onAppear {
                let initialLanguage = selectedLanguages.first ?? "System"
                let initialFocus = languages.contains(initialLanguage)
                    ? initialLanguage
                    : (languages.first ?? "System")
                lastFocusedLanguage = initialFocus
                DispatchQueue.main.async {
                    focusedControl = .language(initialFocus)
                }
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .focusSection()
        .onChange(of: focusedControl) { _, control in
            if case .language(let language) = control {
                lastFocusedLanguage = language
            } else if control == .leftGuard {
                let language = lastFocusedLanguage ?? selectedLanguages.first ?? "System"
                DispatchQueue.main.async {
                    focusedControl = .language(languages.contains(language) ? language : (languages.first ?? "System"))
                }
            }
        }
        .onMoveCommand(perform: handleHorizontalMove)
        .onExitCommand(perform: onDone)
    }

    private var selectedLanguages: [String] {
        SubtitleLanguagePreferences.ordered(selection)
    }

    private func priority(for language: String) -> Int? {
        guard allowsMultiple, language != "System" else { return nil }
        return selectedLanguages.firstIndex(of: language).map { $0 + 1 }
    }

    private func isSelected(_ language: String) -> Bool {
        if language == "System" {
            return selectedLanguages.isEmpty
        }
        return selectedLanguages.contains(language)
    }

    private func toggle(_ language: String) {
        if language == "System" {
            selection = []
            return
        }

        guard allowsMultiple else {
            selection = [language]
            return
        }

        var selected = selectedLanguages
        if let index = selected.firstIndex(of: language) {
            selected.remove(at: index)
        } else {
            selected.append(language)
        }
        selection = selected
    }

    private func handleHorizontalMove(_ direction: MoveCommandDirection) {
        guard direction == .right,
              case .language(let language) = focusedControl else {
            return
        }
        lastFocusedLanguage = language
        focusedControl = .done
    }
}

private struct LanguagePickerListRow: View {
    let language: String
    let priority: Int?
    let isSelected: Bool
    let isFocused: Bool
    let accentColor: Color
    let action: () -> Void

    var body: some View {
        Button(action: action) {
            HStack(spacing: 16) {
                Text(language)
                    .font(.system(size: 26, weight: .bold))
                    .foregroundColor(.white)
                    .lineLimit(1)

                Spacer(minLength: 24)

                if let priority {
                    Text("\(priority)")
                        .font(.system(size: 18, weight: .black))
                        .foregroundColor(accentColor == .white ? .black : .white)
                        .frame(width: 34, height: 34)
                        .background(accentColor, in: Circle())
                }

                if isSelected {
                    Image(systemName: "checkmark")
                        .font(.system(size: 20, weight: .black))
                        .foregroundColor(accentColor)
                }
            }
            .padding(.horizontal, 24)
            .frame(height: 72)
            .settingsGlass(shape: Capsule(), isProminent: isFocused)
            .overlay(
                Capsule()
                    .strokeBorder(isFocused ? AppFocusOutline.color : Color.white.opacity(isSelected ? 0.28 : 0.12), lineWidth: isFocused ? AppFocusOutline.width : 1)
            )
        }
        .buttonStyle(PosterCardButtonStyle())
        .focusEffectDisabledIfAvailable()
    }
}

private struct AdvancedSettingsView: View {
    let accentColor: Color

    @AppStorage(PlaybackTimelineRecorder.enabledKey) private var timelineEnabled = false
    @State private var showingPlaybackHistory = false
    @AppStorage(SettingsKey.fastNavigation) private var fastNavigation = false
    @AppStorage(SettingsKey.playbackDiagnostics) private var playbackDiagnostics = false
    @AppStorage(SettingsKey.playbackDebug) private var playbackDebug = false
    @State private var isClearingTestHistory = false
    @State private var testHistoryStatus = ContinueWatchingTestData.status
    @State private var isClearingCache = false
    @State private var clearedCacheStatus: String?
    @AppStorage(SettingsKey.focusHighlighter) private var focusHighlighter = false

    var body: some View {
        VStack(alignment: .leading, spacing: 22) {
            SettingsGroup(
                title: L10n.string("advanced_section_performance", fallback: "Navigation"),
                subtitle: L10n.string(
                    "tvos_advanced_focus",
                    fallback: "Remote focus behavior for dense rows"
                )
            ) {
                SettingsToggleRow(
                    title: L10n.string("advanced_fast_horizontal_navigation", fallback: "Fast Horizontal Navigation"),
                    subtitle: L10n.string("tvos_settings_move_through_long_poster_rows_more_aggressively", fallback: "Move through long poster rows more aggressively"),
                    isOn: $fastNavigation,
                    accentColor: accentColor
                )
                .settingsEntryAnchor()
            }

            SettingsGroup(
                title: L10n.string("advanced_section_diagnostics", fallback: "Diagnostics"),
                subtitle: L10n.string(
                    "tvos_advanced_diagnostics",
                    fallback: "Local tools for debugging playback and focus"
                )
            ) {
                SettingsToggleRow(
                    title: L10n.string("tvos_settings_playback_issue_reports", fallback: "Playback Issue Reports"),
                    subtitle: L10n.string("tvos_settings_keep_diagnostic_snapshots_after_failed_p_cd841397", fallback: "Keep diagnostic snapshots after failed playback attempts"),
                    isOn: $playbackDiagnostics,
                    accentColor: accentColor
                )

                #if os(tvOS)
                SettingsToggleRow(
                    title: L10n.string("tvos_settings_persistent_playback_history", fallback: "Persistent Playback History"),
                    subtitle: L10n.string("tvos_settings_persistent_playback_history_detail", fallback: "Save recent playback actions on this Apple TV for troubleshooting. Off by default; no automatic upload."),
                    isOn: Binding(get: { timelineEnabled }, set: { enabled in
                        PlaybackTimelineRecorder.setEnabled(enabled)
                        timelineEnabled = enabled
                    }),
                    accentColor: accentColor
                )
                SettingsActionRow(
                    title: L10n.string("tvos_settings_view_playback_history", fallback: "View / Export Diagnostic History"),
                    subtitle: L10n.string("tvos_settings_view_playback_history_detail", fallback: "Inspect, delete or download recent diagnostic history from this Apple TV"),
                    value: L10n.string("action_open", fallback: "Open"),
                    accentColor: accentColor,
                    action: { showingPlaybackHistory = true }
                )
                #endif

                // Whether the app can hand its rows to the Top Shelf extension: a sideloaded
                // build only can when its signing kept the App Group.
                SettingsActionRow(
                    title: L10n.string("tvos_settings_topshelf_status", fallback: "Top Shelf"),
                    subtitle: L10n.format(
                        "tvos_settings_topshelf_status_detail",
                        fallback: "Data shared with the home screen row (App Group %@)",
                        topShelfAppGroupID
                    ),
                    value: TopShelfFeedStore.isAvailable
                        ? L10n.string("tvos_settings_topshelf_available", fallback: "OK")
                        : L10n.string("tvos_settings_topshelf_unavailable", fallback: "Unavailable"),
                    accentColor: accentColor,
                    action: {}
                )

                SettingsToggleRow(
                    title: L10n.string("tvos_settings_playback_debug_overlay", fallback: "Playback Debug Overlay"),
                    subtitle: L10n.string("tvos_settings_show_live_playback_engine_details", fallback: "Show live engine, pipeline, codec, HDR, resolution, frame-rate, audio and policy details while playing"),
                    isOn: $playbackDebug,
                    accentColor: accentColor
                )

                SettingsToggleRow(
                    title: L10n.string("tvos_settings_focus_highlighter", fallback: "Focus Highlighter"),
                    subtitle: L10n.string("tvos_settings_draw_extra_focus_outlines_for_layout_debugging", fallback: "Draw extra focus outlines for layout debugging"),
                    isOn: $focusHighlighter,
                    accentColor: accentColor
                )

                // The pull either ran or it did not. Without this, a session the
                // server rejects looks identical to an account with no history:
                // both render an empty Continue Watching row.
                SettingsInfoRow(
                    title: L10n.string("tvos_settings_account_sync", fallback: "Account Sync"),
                    value: NuvioSyncManager.accountSyncDiagnostic,
                    isDiagnostic: true
                )

                // Reports how many synced rows arrived versus how many could be
                // rendered. A large "awaiting metadata" count means add-ons could
                // not resolve those titles — the history itself is still stored.
                SettingsInfoRow(
                    title: L10n.string("tvos_settings_watch_progress_sync", fallback: "Watch Progress Sync"),
                    value: NuvioSyncManager.progressSyncDiagnostic,
                    isDiagnostic: true
                )

                // Why the row holds what it holds: how many entries survived
                // each stage between the ledger and the screen.
                SettingsInfoRow(
                    title: L10n.string("tvos_settings_continue_watching_row", fallback: "Continue Watching Row"),
                    value: ContinueWatchingStore.rowDiagnostic(),
                    isDiagnostic: true
                )

                // Scrobbles fail silently by design (the caller ignores the
                // result), so this is the only place a rejected one is visible.
                SettingsInfoRow(
                    title: L10n.string("tvos_settings_simkl_scrobble", fallback: "Simkl Scrobble"),
                    value: SimklProgressService.scrobbleDiagnostic,
                    isDiagnostic: true
                )

                SettingsActionRow(
                    title: L10n.string("tvos_settings_clear_test_watch_history", fallback: "Remove Test Watch History"),
                    subtitle: L10n.string(
                        "tvos_settings_clear_test_watch_history_subtitle",
                        fallback: "Deletes the seeded entries from this Apple TV and your account, leaving real history untouched"
                    ),
                    value: isClearingTestHistory ? "Working…" : "Remove",
                    accentColor: accentColor,
                    action: {
                        guard !isClearingTestHistory else { return }
                        isClearingTestHistory = true
                        Task { @MainActor in
                            await ContinueWatchingTestData.clear()
                            testHistoryStatus = ContinueWatchingTestData.status
                            isClearingTestHistory = false
                        }
                    }
                )

                SettingsInfoRow(
                    title: L10n.string("tvos_settings_test_watch_history", fallback: "Test Watch History"),
                    value: testHistoryStatus,
                    isDiagnostic: true
                )
            }

            SettingsGroup(
                title: L10n.string("settings_cache_title", fallback: "Cache"),
                subtitle: L10n.string(
                    "settings_cache_subtitle",
                    fallback: "Temporary poster artwork, catalog order, and row data"
                )
            ) {
                SettingsActionRow(
                    title: L10n.string("settings_clear_cache", fallback: "Clear Cache"),
                    subtitle: L10n.string(
                        "settings_clear_cache_description",
                        fallback: "Keeps your settings and logins, but wipes cached posters, catalog order, and rows, then pulls fresh data from your account"
                    ),
                    value: cacheActionValue,
                    accentColor: accentColor,
                    action: clearCache
                )
            }

            SettingsGroup(title: L10n.string("subtitle_style_reset", fallback: "Reset"), subtitle: L10n.string("tvos_settings_clear_local_tvos_settings_saved_by_this_screen", fallback: "Clear local tvOS settings saved by this screen")) {
                SettingsActionRow(
                    title: L10n.string("tvos_settings_reset_settings", fallback: "Reset Settings"),
                    subtitle: L10n.string("tvos_settings_restore_the_core_settings_defaults", fallback: "Restore the core settings defaults"),
                    value: L10n.string("subtitle_style_reset", fallback: "Reset"),
                    accentColor: accentColor,
                    action: resetSettings
                )
            }
        }
        #if os(tvOS)
        .fullScreenCover(isPresented: $showingPlaybackHistory) {
            PlaybackDiagnosticHistoryView(accentColor: accentColor)
        }
        #endif
    }

    private var cacheActionValue: String {
        if isClearingCache {
            return L10n.string("action_clearing", fallback: "Clearing…")
        }
        if let status = clearedCacheStatus {
            return status
        }
        return L10n.string("action_clear", fallback: "Clear")
    }

    private func clearCache() {
        guard !isClearingCache else { return }
        isClearingCache = true
        clearedCacheStatus = nil
        Task { @MainActor in
            await AppCacheManager.clearCache()
            isClearingCache = false
            clearedCacheStatus = L10n.string("action_cleared", fallback: "Cleared")
            try? await Task.sleep(nanoseconds: 2_000_000_000)
            clearedCacheStatus = nil
        }
    }

    private func resetSettings() {
        // Reset only the active profile's settings, not other profiles'.
        let defaults = ProfileSettings.current
        PlaybackTimelineRecorder.setEnabled(false)
        defaults.removeObject(forKey: PlaybackTimelineRecorder.enabledKey)
        SettingsKey.all.forEach { defaults.removeObject(forKey: $0) }
        defaults.removeObject(forKey: SettingsKey.homeCatalogDisabledAddonIDs)
        defaults.removeObject(forKey: SettingsKey.homeCatalogDisabledAddonNames)
        AISubtitleKeyStore.remove()
        Task { await AISubtitleTranslationCache.shared.removeAll(profileScope: ProfileSettings.activeProfileScope) }
    }
}

private struct AboutSettingsView: View {
    let accentColor: Color
    @EnvironmentObject private var releaseUpdateService: ReleaseUpdateService
    @EnvironmentObject private var atvloadlyService: AtvloadlyService
    @EnvironmentObject private var announcementService: AnnouncementService
    @State private var showingLicenses = false
    @State private var showingReleaseQR = false
    @State private var selectedAnnouncement: Announcement?
    @State private var showingSideloadUpdates = false

    var body: some View {
        VStack(alignment: .leading, spacing: 22) {
            SettingsGroup(title: L10n.string("tvos_settings_nuviotv", fallback: "NuvioTV"), subtitle: L10n.string("tvos_settings_build_and_runtime_information", fallback: "Build and runtime information")) {
                SettingsInfoRow(title: L10n.string("tvos_settings_app_version", fallback: "App Version"), value: appVersion)
                SettingsInfoRow(
                    title: L10n.string("release_update_latest_version", fallback: "Latest Version"),
                    value: releaseUpdateService.latestStatus
                )
                if releaseUpdateService.isEnabled {
                    SettingsActionRow(
                        title: L10n.string("release_update_check_now", fallback: "Check Now"),
                        subtitle: atvloadlyService.isEnabled
                            ? L10n.string("release_update_check_now_atvloadly_subtitle", fallback: "Check GitHub now and install a newer version with atvloadly")
                            : L10n.string("release_update_check_now_subtitle", fallback: "Check GitHub for a newer version now"),
                        value: releaseUpdateService.isChecking
                            ? L10n.string("atvloadly_status_checking", fallback: "Checking…")
                            : L10n.string("release_update_check_now_value", fallback: "Check"),
                        accentColor: accentColor
                    ) {
                        Task { await checkNow() }
                    }
                    // The first focusable row of the pane when it's shown.
                    .settingsEntryAnchor()
                }
                SettingsToggleRow(
                    title: L10n.string("release_update_check_toggle", fallback: "Check for Updates"),
                    subtitle: L10n.string("release_update_check_toggle_subtitle", fallback: "Check GitHub for a newer NuvioTV release"),
                    isOn: Binding(
                        get: { releaseUpdateService.isEnabled },
                        set: {
                            releaseUpdateService.setEnabled($0)
                            if $0 {
                                Task { await releaseUpdateService.checkIfNeeded() }
                            }
                        }
                    ),
                    accentColor: accentColor
                )
                .settingsEntryAnchor(!releaseUpdateService.isEnabled)
                SettingsActionRow(
                    title: L10n.string("sideload_updates_title", fallback: "Sideload Updates"),
                    subtitle: L10n.string("sideload_updates_row_subtitle", fallback: "Install new versions with atvloadly on your network"),
                    value: atvloadlyService.isEnabled
                        ? L10n.string("sideload_updates_on", fallback: "atvloadly · On")
                        : L10n.string("sideload_updates_off", fallback: "Off"),
                    accentColor: accentColor
                ) {
                    showingSideloadUpdates = true
                }
                .sheet(isPresented: $showingSideloadUpdates) {
                    SideloadUpdatesSheet(accentColor: accentColor)
                        .environmentObject(atvloadlyService)
                        .modifier(ClearPresentationBackgroundIfAvailable())
                }
                if let release = releaseUpdateService.latestRelease {
                    SettingsActionRow(
                        title: L10n.string("release_update_details", fallback: "Release Details"),
                        subtitle: L10n.string("release_update_details_subtitle", fallback: "View version \(release.displayVersion) release notes and QR code"),
                        value: L10n.string("tvos_settings_view", fallback: "View"),
                        accentColor: accentColor
                    ) {
                        showingReleaseQR = true
                    }
                    .sheet(isPresented: $showingReleaseQR) {
                        ReleaseQRCodeSheet(release: release)
                    }
                }
                SettingsInfoRow(title: L10n.string("tvos_settings_engine_core", fallback: "Engine Core"), value: L10n.string("tvos_settings_pure_swift", fallback: "Pure Swift"))
                SettingsInfoRow(title: L10n.string("tvos_settings_playback_stack", fallback: "Playback Stack"), value: "AetherEngine / MPVKit")
                SettingsInfoRow(title: L10n.string("tvos_settings_catalog_protocol", fallback: "Catalog Protocol"), value: L10n.string("tvos_settings_stremio_compatible", fallback: "Stremio compatible"))
            }

            SettingsGroup(
                title: L10n.string("announcements_title", fallback: "Announcements"),
                subtitle: L10n.string("announcements_settings_subtitle", fallback: "Messages from the NuvioTV maintainers")
            ) {
                SettingsInfoRow(
                    title: L10n.string("announcements_status", fallback: "Message Status"),
                    value: announcementService.status
                )
                SettingsToggleRow(
                    title: L10n.string("announcements_check_toggle", fallback: "Check for Announcements"),
                    subtitle: L10n.string("announcements_check_toggle_subtitle", fallback: "Check for notices from the NuvioTV maintainers"),
                    isOn: Binding(
                        get: { announcementService.isEnabled },
                        set: {
                            announcementService.setEnabled($0)
                            if $0 {
                                Task { await announcementService.checkIfNeeded() }
                            }
                        }
                    ),
                    accentColor: accentColor
                )
                if let announcement = announcementService.firstActiveAnnouncement {
                    SettingsActionRow(
                        title: L10n.string("announcement_read_message", fallback: "Read Message"),
                        subtitle: announcement.title,
                        value: L10n.string("tvos_settings_view", fallback: "View"),
                        accentColor: accentColor
                    ) {
                        selectedAnnouncement = announcement
                    }
                }
            }
            .sheet(item: $selectedAnnouncement) { announcement in
                AppNoticeDetailsSheet(notice: .announcement(announcement))
            }

            SettingsGroup(
                title: L10n.string("about_licenses_attributions", fallback: "Open Source"),
                subtitle: L10n.string(
                    "about_licenses_attributions_subtitle",
                    fallback: "Data sources, acknowledgements, and open-source licenses"
                )
            ) {
                Text("This software uses SwiftUI, AetherEngine, MPVKit (libmpv), and Stremio-compatible catalog APIs.")
                    .font(.system(size: 21, weight: .medium))
                    .foregroundColor(.white.opacity(0.72))
                    .fixedSize(horizontal: false, vertical: true)

                SettingsActionRow(
                    title: L10n.string(
                        "about_licenses_attributions",
                        fallback: "Licenses & Attributions"
                    ),
                    subtitle: L10n.string("tvos_settings_open_source_components_and_data_providers", fallback: "Open-source components and data providers"),
                    value: L10n.string("tvos_settings_view", fallback: "View"),
                    accentColor: accentColor
                ) {
                    showingLicenses = true
                }
            }
        }
        .sheet(isPresented: $showingLicenses) {
            LicensesAttributionsSheet(accentColor: accentColor)
                .modifier(ClearPresentationBackgroundIfAvailable())
        }
    }

    /// Checks GitHub right away. A newer version is installed with atvloadly
    /// when it's on; otherwise its release page and QR code are shown.
    private func checkNow() async {
        await releaseUpdateService.checkIfNeeded(force: true)
        guard releaseUpdateService.isUpdateAvailable, let release = releaseUpdateService.latestRelease else { return }
        if atvloadlyService.isEnabled {
            await atvloadlyService.install(release: release)
        } else {
            showingReleaseQR = true
        }
    }

    private var appVersion: String {
        let version = Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String ?? "1.0"
        let build = Bundle.main.object(forInfoDictionaryKey: "CFBundleVersion") as? String ?? "1"
        return "\(version) (\(build))"
    }
}

/// Local attributions for components this tvOS build actually ships with.
/// Settings → About → Sideload Updates: installing NuvioTV updates with the
/// user's atvloadly server, the self-hosted signer many Apple TV users
/// sideload with. Everything here is off until "Use atvloadly" is turned on.
private struct SideloadUpdatesSheet: View {
    let accentColor: Color

    @EnvironmentObject private var atvloadlyService: AtvloadlyService
    @Environment(\.dismiss) private var dismiss
    @AppStorage(SettingsKey.amoled) private var amoled = false
    @AppStorage(SettingsKey.bodyColor) private var bodyColor = SettingsBackground.charcoal.rawValue
    @State private var serverDraft = ""
    @State private var showingDevices = false

    var body: some View {
        ZStack {
            Color.nuvioBackground(amoled: amoled, body: bodyColor)
                .ignoresSafeArea()

            ScrollView {
                VStack(alignment: .leading, spacing: 24) {
                    VStack(alignment: .leading, spacing: 7) {
                        Text(L10n.string("sideload_updates_title", fallback: "Sideload Updates"))
                            .font(.system(size: 36, weight: .bold))
                            .foregroundColor(.white)

                        Text(L10n.string(
                            "sideload_updates_description",
                            fallback: "Install new NuvioTV versions with atvloadly, the self-hosted signer on your network. NuvioTV has to be linked to a source there (More → Track updates)."
                        ))
                        .font(.system(size: 20, weight: .medium))
                        .foregroundColor(.white.opacity(0.62))
                        .fixedSize(horizontal: false, vertical: true)
                    }

                    SettingsGroup(
                        title: "atvloadly",
                        subtitle: L10n.string("atvloadly_settings_subtitle", fallback: "Your atvloadly server and how updates are installed")
                    ) {
                        SettingsToggleRow(
                            title: L10n.string("atvloadly_use", fallback: "Use atvloadly"),
                            subtitle: L10n.string("atvloadly_use_subtitle", fallback: "Show Install on the update notice and install from Check Now"),
                            isOn: Binding(
                                get: { atvloadlyService.isEnabled },
                                set: { atvloadlyService.setEnabled($0) }
                            ),
                            accentColor: accentColor
                        )
                        if atvloadlyService.isEnabled {
                            SettingsTextFieldRow(
                                title: L10n.string("atvloadly_server", fallback: "Server"),
                                subtitle: L10n.string("atvloadly_server_subtitle", fallback: "The address of your atvloadly"),
                                placeholder: "http://192.168.1.10:9000",
                                text: $serverDraft,
                                fieldWidth: 420,
                                onCommit: {
                                    atvloadlyService.setServerAddress(serverDraft)
                                    Task { await atvloadlyService.refresh() }
                                }
                            )
                            SettingsToggleRow(
                                title: L10n.string("atvloadly_auto_install", fallback: "Install Updates Automatically"),
                                subtitle: L10n.string(
                                    "atvloadly_auto_install_subtitle",
                                    fallback: "Off by default. Installs a new version from the Home screen after a 10-second countdown, never during playback. NuvioTV closes while it updates."
                                ),
                                isOn: Binding(
                                    get: { atvloadlyService.installsAutomatically },
                                    set: { atvloadlyService.setInstallsAutomatically($0) }
                                ),
                                accentColor: accentColor
                            )
                            if atvloadlyService.entries.count > 1 {
                                SettingsActionRow(
                                    title: L10n.string("atvloadly_device", fallback: "Apple TV"),
                                    subtitle: L10n.string("atvloadly_device_subtitle", fallback: "atvloadly has NuvioTV for several Apple TVs"),
                                    value: atvloadlyService.selectedEntry?.deviceLabel
                                        ?? L10n.string("atvloadly_device_choose", fallback: "Choose"),
                                    accentColor: accentColor
                                ) {
                                    showingDevices = true
                                }
                                .confirmationDialog(
                                    L10n.string("atvloadly_device", fallback: "Apple TV"),
                                    isPresented: $showingDevices
                                ) {
                                    ForEach(atvloadlyService.entries) { entry in
                                        Button("\(entry.deviceLabel) · \(entry.version)") {
                                            atvloadlyService.selectApp(id: entry.id)
                                        }
                                    }
                                }
                            }
                            SettingsActionRow(
                                title: L10n.string("atvloadly_status", fallback: "Status"),
                                subtitle: atvloadlyService.statusText,
                                value: L10n.string("atvloadly_status_refresh", fallback: "Refresh"),
                                accentColor: accentColor
                            ) {
                                Task { await atvloadlyService.refresh() }
                            }
                        }
                    }
                }
                .frame(width: 1_000, alignment: .leading)
                .padding(.horizontal, 52)
                .padding(.vertical, 38)
            }
            .focusSection()
        }
        .onExitCommand { dismiss() }
        .onAppear {
            serverDraft = atvloadlyService.serverAddress
            if atvloadlyService.isEnabled {
                Task { await atvloadlyService.refresh() }
            }
        }
        // Kept even if the keyboard is closed without Done.
        .onChange(of: serverDraft) { _, text in
            atvloadlyService.setServerAddress(text)
        }
    }
}

private struct LicensesAttributionsSheet: View {
