    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            HStack(alignment: .center, spacing: 24) {
                VStack(alignment: .leading, spacing: 8) {
                    Text(L10n.string("tvos_settings_licenses_attributions", fallback: "Licenses & Attributions"))
                        .font(.system(size: 36, weight: .bold))
                        .foregroundColor(.white)
                    Text(L10n.string("tvos_settings_components_used_by_this_tvos_build", fallback: "Components used by this tvOS build"))
                        .font(.system(size: 20, weight: .medium))
                        .foregroundColor(.white.opacity(0.62))
                }
                Spacer(minLength: 24)
                Button(action: { dismiss() }) {
                    Text(L10n.string("action_close", fallback: "Close"))
                        .font(.system(size: 20, weight: .bold))
                        .foregroundColor(closeFocused ? .black : .white)
                        .padding(.horizontal, 28)
                        .padding(.vertical, 16)
                        .background(
                            Capsule(style: .continuous)
                                .fill(closeFocused ? accentColor : Color.white.opacity(0.12))
                        )
                }
                .buttonStyle(PosterCardButtonStyle())
                .focused($closeFocused)
                .focusEffectDisabledIfAvailable()
            }
            .padding(.horizontal, 40)
            .padding(.top, 36)
            .padding(.bottom, 20)

            ScrollView {
                VStack(alignment: .leading, spacing: 28) {
                    licenseSection(title: L10n.string("tvos_settings_app", fallback: "App"), entries: appEntries)
                    licenseSection(title: L10n.string("tvos_settings_data_services", fallback: "Data & services"), entries: dataEntries)
                    licenseSection(title: L10n.string("settings_playback", fallback: "Playback"), entries: playbackEntries)
                }
                .padding(.horizontal, 40)
                .padding(.bottom, 48)
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .background(Color.black.opacity(0.55).ignoresSafeArea())
        .onAppear { closeFocused = true }
    }

    @ViewBuilder
    private func licenseSection(title: String, entries: [LicenseEntry]) -> some View {
        VStack(alignment: .leading, spacing: 14) {
            Text(title)
                .font(.system(size: 24, weight: .bold))
                .foregroundColor(.white.opacity(0.9))

            ForEach(entries) { entry in
                VStack(alignment: .leading, spacing: 8) {
                    HStack(alignment: .firstTextBaseline) {
                        Text(entry.title)
                            .font(.system(size: 22, weight: .semibold))
                            .foregroundColor(.white)
                        Spacer(minLength: 16)
                        Text(entry.license)
                            .font(.system(size: 16, weight: .bold))
                            .foregroundColor(accentColor)
                            .lineLimit(2)
                            .multilineTextAlignment(.trailing)
                    }
                    Text(entry.body)
                        .font(.system(size: 18, weight: .medium))
                        .foregroundColor(.white.opacity(0.68))
                        .fixedSize(horizontal: false, vertical: true)
                }
                .padding(22)
                .frame(maxWidth: .infinity, alignment: .leading)
                .settingsGlass(shape: RoundedRectangle(cornerRadius: 22, style: .continuous), isProminent: false)
                .overlay(
                    RoundedRectangle(cornerRadius: 22, style: .continuous)
                        .strokeBorder(Color.white.opacity(0.10), lineWidth: 1)
                )
            }
        }
    }
}

// MARK: - SMB (local network servers)

private struct SMBSettingsSection: View {
    let accentColor: Color

    @ObservedObject private var serverStore = SMBServerStore.shared
    @ObservedObject private var sessionManager = SMBSessionManager.shared
    @State private var editingServer: SMBServerConfig?
    @State private var isAddingServer = false
    @State private var scanningServer: SMBServerConfig?

    var body: some View {
        SettingsGroup(
            title: L10n.string("smb_group_title", fallback: "SMB"),
            subtitle: L10n.string("smb_group_subtitle", fallback: "Play files from a NAS or PC on your local network")
        ) {
            SettingsActionRow(
                title: L10n.string("smb_add_server", fallback: "Add Server"),
                subtitle: L10n.string("smb_add_server_subtitle", fallback: "Connect a share by host or IP address"),
                value: "",
                accentColor: accentColor
            ) {
                isAddingServer = true
            }

            ForEach(serverStore.servers) { server in
                SMBServerRow(
                    server: server,
                    accentColor: accentColor,
                    connectionState: sessionManager.connectionState(for: server.id),
                    testState: sessionManager.testState(for: server.id),
                    scanState: sessionManager.scanState(for: server.id),
                    onEdit: { editingServer = server },
                    onConnect: { Task { await sessionManager.connect(server) } },
                    onDisconnect: { Task { await sessionManager.disconnect(server) } },
                    onTest: { Task { await sessionManager.test(server) } },
                    onScan: { scanningServer = server },
                    onDelete: {
                        Task {
                            await sessionManager.disconnect(server)
                            serverStore.remove(server.id)
                        }
                    }
                )
            }
        }
        .sheet(isPresented: $isAddingServer) {
            SMBServerEditSheet(server: nil, accentColor: accentColor)
                .modifier(ClearPresentationBackgroundIfAvailable())
        }
        .sheet(item: $editingServer) { server in
            SMBServerEditSheet(server: server, accentColor: accentColor)
                .modifier(ClearPresentationBackgroundIfAvailable())
        }
        .sheet(item: $scanningServer) { server in
            SMBShareSelectionSheet(server: server, accentColor: accentColor)
                .modifier(ClearPresentationBackgroundIfAvailable())
        }
    }
}

/// One configured server: connection status plus Connect/Disconnect, Scan,
/// and Test — Scan and Test stay disabled until the connection succeeds, so a
/// server row never lets you scan a share list you don't have yet.
private struct SMBServerRow: View {
    let server: SMBServerConfig
    let accentColor: Color
    let connectionState: SMBConnectionState
    let testState: SMBTestState
    let scanState: SMBScanState
    let onEdit: () -> Void
    let onConnect: () -> Void
    let onDisconnect: () -> Void
    let onTest: () -> Void
    let onScan: () -> Void
    let onDelete: () -> Void

    @FocusState private var isFocused: Bool

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            Button(action: onEdit) {
                SettingsRowShell(isFocused: isFocused, accentColor: accentColor) {
                    SettingsRowText(title: server.displayName, subtitle: subtitleText)

                    Spacer(minLength: 24)

                    HStack(spacing: 8) {
                        Circle()
                            .fill(connectionState.isConnected ? Color.green : Color.white.opacity(0.3))
                            .frame(width: 10, height: 10)
                        Text(statusText)
                            .font(.system(size: 17, weight: .semibold))
                            .foregroundColor(.white.opacity(0.7))
                    }
                }
            }
            .buttonStyle(PosterCardButtonStyle())
            .focused($isFocused)
            .focusEffectDisabledIfAvailable()
            .entryLockable()

            HStack(spacing: 12) {
                if connectionState.isConnected {
                    SMBRowButton(title: L10n.string("smb_disconnect", fallback: "Disconnect"), accentColor: accentColor, action: onDisconnect)
                } else {
                    SMBRowButton(
                        title: connectionState == .connecting
                            ? L10n.string("smb_connecting", fallback: "Connecting…")
                            : L10n.string("smb_connect", fallback: "Connect"),
                        accentColor: accentColor,
                        isLoading: connectionState == .connecting,
                        action: onConnect
                    )
                }
                SMBRowButton(
                    title: scanTitle,
                    accentColor: accentColor,
                    enabled: connectionState.isConnected,
                    isLoading: isScanning,
                    action: onScan
                )
                SMBRowButton(
                    title: L10n.string("smb_test", fallback: "Test"),
                    accentColor: accentColor,
                    enabled: connectionState.isConnected,
                    isLoading: testState == .testing,
                    action: onTest
                )
                Spacer()
                SMBDeleteButton(action: onDelete)
            }
        }
        .padding(.bottom, 4)
    }

    private var subtitleText: String {
        var parts = ["\(server.authSummary) · \(server.hostAndPort)/\(server.selectedShares.joined(separator: ","))"]
        if let count = server.lastScanTitleCount {
            parts.append(L10n.format("smb_title_count", fallback: "%d titles", count))
        }
        if case .failed(let message) = connectionState {
            parts.append(message)
        } else if case .failed(let message) = testState {
            parts.append(message)
        } else if case .reachable(let latencyMs) = testState {
            parts.append(L10n.format("smb_reachable_latency", fallback: "Reachable · %d ms", latencyMs))
        }
        return parts.joined(separator: " — ")
    }

    private var statusText: String {
        switch connectionState {
        case .disconnected: return L10n.string("debrid_not_set", fallback: "Not set")
        case .connecting: return L10n.string("smb_connecting", fallback: "Connecting…")
        case .connected: return L10n.string("debrid_connected", fallback: "Connected")
        case .failed: return L10n.string("smb_failed", fallback: "Failed")
        }
    }

    private var isScanning: Bool {
        if case .scanning = scanState { return true }
        return false
    }

    private var scanTitle: String {
        if case .scanning(let found, _) = scanState {
            return L10n.format("smb_scanning_count", fallback: "Scanning (%d)…", found)
        }
        return L10n.string("smb_scan", fallback: "Scan")
    }
}

private struct SMBRowButton: View {
    let title: String
    let accentColor: Color
    var enabled: Bool = true
    var isLoading: Bool = false
    let action: () -> Void

    @FocusState private var isFocused: Bool

    /// Focused, the capsule takes the accent color: with the White accent
    /// (the default) the label turns black, or it would vanish.
    private var contentColor: Color {
        guard enabled else { return .white.opacity(0.4) }
        return isFocused && accentColor == .white ? .black : .white
    }

    var body: some View {
        Button(action: action) {
            HStack(spacing: 8) {
                if isLoading {
                    ProgressView().tint(contentColor).scaleEffect(0.7)
                }
                Text(title)
                    .font(.system(size: 17, weight: .bold))
                    .foregroundColor(contentColor)
            }
            .padding(.horizontal, 18)
            .padding(.vertical, 10)
            .background(
                Capsule().fill(isFocused && enabled ? accentColor : Color.white.opacity(0.08))
            )
            .overlay(
                Capsule().strokeBorder(isFocused ? AppFocusOutline.color : Color.clear, lineWidth: 2)
            )
        }
        .buttonStyle(PosterCardButtonStyle())
        .focusEffectDisabledIfAvailable()
        .focused($isFocused)
        .disabled(!enabled)
        .opacity(enabled ? 1 : 0.5)
    }
}

/// Delete button shared by the SMB and Jellyfin server rows: an outlined
/// trash glyph that fills solid on focus, matching the "settle in" cue
/// `SMBRowButton` gives its focus ring.
private struct SMBDeleteButton: View {
    let action: () -> Void

    @FocusState private var isFocused: Bool

    var body: some View {
        Button(role: .destructive, action: action) {
            Image(systemName: isFocused ? "trash.circle.fill" : "trash.circle")
                .foregroundColor(.white.opacity(0.6))
        }
        .buttonStyle(PosterCardButtonStyle())
        .focusEffectDisabledIfAvailable()
        .focused($isFocused)
    }
}

/// Shared Cancel/primary button pair for the SMB sheets. The confirm
/// (`isPrimary`) button reads slightly translucent at rest and brightens
/// on focus, rather than jumping straight to solid white — the same "settle
/// in" cue `SettingsMiniButton`/`SMBRowButton` give their focus ring.
private struct SMBDialogButton: View {
    let title: String
    let isPrimary: Bool
    var enabled: Bool = true
    let action: () -> Void

    @FocusState private var isFocused: Bool

    var body: some View {
        Button(action: action) {
            Text(title)
                .font(.system(size: 21, weight: .bold))
                .foregroundColor(isPrimary ? .black : .white)
                .padding(.horizontal, 28)
                .padding(.vertical, 14)
                .background(Capsule().fill(backgroundColor))
                .overlay(
                    Capsule().strokeBorder(isFocused ? AppFocusOutline.color : Color.clear, lineWidth: 2)
                )
        }
        .buttonStyle(PosterCardButtonStyle())
        .focused($isFocused)
        .focusEffectDisabledIfAvailable()
        .disabled(isPrimary && !enabled)
    }

    private var backgroundColor: Color {
        guard isPrimary else { return Color.white.opacity(0.12) }
        guard enabled else { return Color.white.opacity(0.3) }
        return Color.white.opacity(isFocused ? 0.9 : 0.75)
    }
}

/// Add or edit a server's connection settings. The password (when Sign In is
/// chosen) is written to Keychain on save, never to the persisted config.
private struct SMBServerEditSheet: View {
    let server: SMBServerConfig?
    let accentColor: Color

    @Environment(\.dismiss) private var dismiss
    @AppStorage(SettingsKey.amoled) private var amoled = false
    @AppStorage(SettingsKey.bodyColor) private var bodyColor = SettingsBackground.charcoal.rawValue

    @State private var displayName: String
    @State private var host: String
    @State private var portText: String
    @State private var authKind: SMBAuthKind
    @State private var username: String
    @State private var password: String
    @State private var domain: String
    @State private var maxDepth: Int

    init(server: SMBServerConfig?, accentColor: Color) {
        self.server = server
        self.accentColor = accentColor
        _displayName = State(initialValue: server?.displayName ?? "")
        _host = State(initialValue: server?.host ?? "")
        _portText = State(initialValue: server?.port.map(String.init) ?? "")
        _authKind = State(initialValue: server?.authKind ?? .anonymous)
        _username = State(initialValue: server?.username ?? "")
        _password = State(initialValue: server.map { SMBCredentialStore.password(forServerID: $0.id) } ?? "")
        _domain = State(initialValue: server?.domain ?? "")
        _maxDepth = State(initialValue: server?.maxDepth ?? 6)
    }

    var body: some View {
        ZStack {
            Color.nuvioBackground(amoled: amoled, body: bodyColor).ignoresSafeArea()

            ScrollView {
                VStack(alignment: .leading, spacing: 24) {
                    Text(server == nil ? L10n.string("smb_add_server", fallback: "Add Server") : L10n.string("smb_edit_server", fallback: "Edit Server"))
                        .font(.system(size: 36, weight: .bold))
                        .foregroundColor(.white)

                    SettingsGroup(
                        title: L10n.string("smb_connection", fallback: "Connection"),
                        subtitle: L10n.string("smb_connection_subtitle", fallback: "Host or IP address of the server")
                    ) {
                        SettingsNativeTextFieldRow(
                            title: L10n.string("smb_display_name", fallback: "Name"),
                            subtitle: L10n.string("smb_display_name_subtitle", fallback: "Shown in Settings and on Home"),
                            placeholder: "Living Room NAS",
                            text: $displayName
                        )
                        SettingsNativeTextFieldRow(
                            title: L10n.string("smb_host", fallback: "Host"),
                            subtitle: L10n.string("smb_host_subtitle", fallback: "e.g. 192.168.1.10 or nas.local"),
                            placeholder: "192.168.1.10",
                            text: $host
                        )
                        SettingsNativeTextFieldRow(
                            title: L10n.string("smb_port", fallback: "Port"),
                            subtitle: L10n.string("smb_port_subtitle", fallback: "Leave blank for the default (445)"),
                            placeholder: "445",
                            text: $portText
                        )
                    }

                    SettingsGroup(
                        title: L10n.string("smb_authentication", fallback: "Authentication"),
                        subtitle: L10n.string("smb_authentication_subtitle", fallback: "How to sign in to this server")
                    ) {
                        SettingsChoiceRow(
                            title: L10n.string("smb_auth_mode", fallback: "Sign-in Method"),
                            subtitle: "",
                            selection: authKindSelection,
                            options: SMBAuthKind.allCases.map(\.title),
                            accentColor: accentColor
                        )
                        if authKind == .credentials {
                            SettingsNativeTextFieldRow(
                                title: L10n.string("smb_username", fallback: "Username"),
                                subtitle: "",
                                placeholder: L10n.string("debrid_not_set", fallback: "Not set"),
                                text: $username
                            )
                            SettingsNativeTextFieldRow(
                                title: L10n.string("smb_password", fallback: "Password"),
                                subtitle: L10n.string(
                                    "tvos_settings_stored_locally_on_this_apple_tv",
                                    fallback: "Stored locally on this Apple TV"
                                ),
                                placeholder: L10n.string("debrid_not_set", fallback: "Not set"),
                                text: $password,
                                isSecure: true
                            )
                            SettingsNativeTextFieldRow(
                                title: L10n.string("smb_domain", fallback: "Domain (optional)"),
                                subtitle: "",
                                placeholder: "WORKGROUP",
                                text: $domain
                            )
                        }
                    }

                    SettingsGroup(
                        title: L10n.string("smb_scan_settings", fallback: "Scan"),
                        subtitle: L10n.string("smb_scan_settings_subtitle", fallback: "How deep to recurse into folders")
                    ) {
                        SettingsStepperRow(
                            title: L10n.string("smb_max_depth", fallback: "Max Folder Depth"),
                            subtitle: "",
                            value: $maxDepth,
                            range: 1...12,
                            step: 1,
                            suffix: "",
                            accentColor: accentColor
                        )
                    }

                    // Spread edge-to-edge (not packed under `.leading`) so a
                    // downward press from a right-aligned control higher up
                    // the sheet (the depth stepper's + button, the auth
                    // picker) always has a horizontally reachable target —
                    // tvOS's directional focus engine won't bridge a large
                    // gap between a right-edge control and a left-packed
                    // button pair. `.focusSection()` gives this row its own
                    // navigable region.
                    HStack {
                        SMBDialogButton(title: L10n.string("action_cancel", fallback: "Cancel"), isPrimary: false) { dismiss() }
                        Spacer()
                        SMBDialogButton(title: L10n.string("action_save", fallback: "Save"), isPrimary: true, enabled: canSave) {
                            save()
                            dismiss()
                        }
                    }
                    .focusSection()
                }
                .padding(40)
            }
        }
    }

    private var canSave: Bool {
        !displayName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && !host.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    private var authKindSelection: Binding<String> {
        Binding(
            get: { authKind.title },
            set: { title in
                authKind = SMBAuthKind.allCases.first { $0.title == title } ?? .anonymous
            }
        )
    }

    private func save() {
        let id = server?.id ?? UUID().uuidString
        let config = SMBServerConfig(
            id: id,
            displayName: displayName.trimmingCharacters(in: .whitespacesAndNewlines),
            host: host.trimmingCharacters(in: .whitespacesAndNewlines),
            port: Int(portText.trimmingCharacters(in: .whitespacesAndNewlines)),
            authKind: authKind,
            username: username.trimmingCharacters(in: .whitespacesAndNewlines),
            domain: domain.trimmingCharacters(in: .whitespacesAndNewlines),
            selectedShares: server?.selectedShares ?? [],
            maxDepth: maxDepth,
            lastScanDate: server?.lastScanDate,
            lastScanTitleCount: server?.lastScanTitleCount
        )
        SMBCredentialStore.save(password, forServerID: id)
        SMBServerStore.shared.upsert(config)
    }
}

/// Presented after "Scan" on a connected server: pick which shares to walk,
/// then watch live progress and the resulting match report.
private struct SMBShareSelectionSheet: View {
    let server: SMBServerConfig
    let accentColor: Color

    @Environment(\.dismiss) private var dismiss
    @AppStorage(SettingsKey.amoled) private var amoled = false
    @AppStorage(SettingsKey.bodyColor) private var bodyColor = SettingsBackground.charcoal.rawValue
    @ObservedObject private var sessionManager = SMBSessionManager.shared
    @State private var selectedShares: Set<String>

    init(server: SMBServerConfig, accentColor: Color) {
        self.server = server
        self.accentColor = accentColor
        _selectedShares = State(initialValue: Set(server.selectedShares))
    }

    var body: some View {
        ZStack {
            Color.nuvioBackground(amoled: amoled, body: bodyColor).ignoresSafeArea()

            ScrollView {
                VStack(alignment: .leading, spacing: 24) {
                    Text(L10n.format("smb_shares_on_server", fallback: "Shares on %@", server.displayName))
                        .font(.system(size: 36, weight: .bold))
                        .foregroundColor(.white)

                    if let shares = availableShares {
                        SettingsGroup(
                            title: L10n.string("smb_shares", fallback: "Shares"),
                            subtitle: L10n.string("smb_shares_subtitle", fallback: "Choose which shares to scan for video files")
                        ) {
                            ForEach(shares, id: \.name) { share in
                                SettingsToggleRow(
                                    title: share.name + (share.isAdmin ? "  ⚠︎" : ""),
                                    subtitle: share.comment,
                                    isOn: shareBinding(share.name),
                                    accentColor: accentColor
                                )
                            }
                        }
                    }

                    scanStatusView

                    // Spread edge-to-edge for the same reason as
                    // `SMBServerEditSheet`'s Cancel/Save row: the share
                    // toggles above are right-aligned switches, and a
                    // left-packed button pair is too far away for tvOS's
                    // directional focus to reach reliably from there.
                    HStack {
                        SMBDialogButton(title: L10n.string("action_cancel", fallback: "Close"), isPrimary: false) { dismiss() }
                        Spacer()
                        SMBDialogButton(
                            title: L10n.string("smb_start_scan", fallback: "Start Scan"),
                            isPrimary: true,
                            enabled: !selectedShares.isEmpty && !isScanning
                        ) {
                            startScan()
                        }
                    }
                    .focusSection()
                }
                .padding(40)
            }
        }
    }

    private var availableShares: [SMBShareInfo]? {
        if case .connected(let shares) = sessionManager.connectionState(for: server.id) {
            return shares
        }
        return nil
    }

    private var isScanning: Bool {
        if case .scanning = sessionManager.scanState(for: server.id) { return true }
        return false
    }

    private func shareBinding(_ name: String) -> Binding<Bool> {
        Binding(
            get: { selectedShares.contains(name) },
            set: { isOn in
                if isOn { selectedShares.insert(name) } else { selectedShares.remove(name) }
            }
        )
    }

    private func startScan() {
        var updated = server
        updated.selectedShares = Array(selectedShares)
        SMBServerStore.shared.upsert(updated)
        sessionManager.scan(updated)
    }

    @ViewBuilder
    private var scanStatusView: some View {
        switch sessionManager.scanState(for: server.id) {
        case .idle:
            EmptyView()
        case .scanning(let found, let path):
            SettingsGroup(
                title: L10n.string("smb_scanning", fallback: "Scanning…"),
                subtitle: path
            ) {
                SettingsInfoRow(title: L10n.string("smb_found_so_far", fallback: "Found so far"), value: "\(found)")
            }
        case .done(let report):
            SettingsGroup(
                title: L10n.string("smb_scan_complete", fallback: "Scan Complete"),
                subtitle: L10n.string("smb_scan_complete_subtitle", fallback: "Matched titles appear on Home as Local titles")
            ) {
                SettingsInfoRow(title: L10n.string("smb_matched_titles", fallback: "Matched Titles"), value: "\(report.matchedTitles)")
                SettingsInfoRow(title: L10n.string("smb_matched_episodes", fallback: "Matched Episodes"), value: "\(report.matchedEpisodes)")
                SettingsInfoRow(title: L10n.string("smb_unmatched", fallback: "Unmatched"), value: "\(report.unmatched.count)")
                SettingsInfoRow(title: L10n.string("smb_skipped", fallback: "Skipped"), value: "\(report.skipped)")
                if !report.unmatched.isEmpty {
                    VStack(alignment: .leading, spacing: 6) {
                        ForEach(report.unmatched.prefix(20), id: \.self) { name in
                            Text(name)
                                .font(.system(size: 15, weight: .regular))
                                .foregroundColor(.white.opacity(0.5))
                                .lineLimit(1)
                        }
                    }
                }
            }
        case .failed(let message):
            SettingsGroup(
                title: L10n.string("smb_scan_failed", fallback: "Scan Failed"),
                subtitle: message
            ) { EmptyView() }
        }
    }

}

// MARK: - Jellyfin (self-hosted media servers)

private struct JellyfinSettingsSection: View {
    let accentColor: Color

    @ObservedObject private var serverStore = JellyfinServerStore.shared
    @ObservedObject private var sessionManager = JellyfinSessionManager.shared
    @State private var editingServer: JellyfinServerConfig?
    @State private var isAddingServer = false
    @State private var syncingServer: JellyfinServerConfig?

    var body: some View {
        SettingsGroup(
            title: L10n.string("jellyfin_group_title", fallback: "Jellyfin"),
            subtitle: L10n.string("jellyfin_group_subtitle", fallback: "Browse and play a self-hosted Jellyfin server's library")
        ) {
            SettingsActionRow(
                title: L10n.string("jellyfin_add_server", fallback: "Add Server"),
                subtitle: L10n.string("jellyfin_add_server_subtitle", fallback: "Connect a server by URL"),
                value: "",
                accentColor: accentColor
            ) {
                isAddingServer = true
            }

            ForEach(serverStore.servers) { server in
                JellyfinServerRow(
                    server: server,
                    accentColor: accentColor,
                    connectionState: sessionManager.connectionState(for: server.id),
                    syncState: sessionManager.syncState(for: server.id),
                    onEdit: { editingServer = server },
                    onConnect: { Task { await sessionManager.connect(server) } },
                    onDisconnect: { Task { await sessionManager.disconnect(server) } },
                    onSync: { syncingServer = server },
                    onDelete: {
                        Task {
                            await sessionManager.disconnect(server)
                            serverStore.remove(server.id)
                        }
                    }
                )
            }
        }
        .sheet(isPresented: $isAddingServer) {
            JellyfinServerEditSheet(server: nil, accentColor: accentColor)
                .modifier(ClearPresentationBackgroundIfAvailable())
        }
        .sheet(item: $editingServer) { server in
            JellyfinServerEditSheet(server: server, accentColor: accentColor)
                .modifier(ClearPresentationBackgroundIfAvailable())
        }
        .sheet(item: $syncingServer) { server in
            JellyfinLibrarySelectionSheet(server: server, accentColor: accentColor)
                .modifier(ClearPresentationBackgroundIfAvailable())
        }
    }
}

/// One configured server: connection status plus Connect/Disconnect and
/// Sync — Sync stays disabled until the connection succeeds, same as
/// `SMBServerRow`'s Scan.
private struct JellyfinServerRow: View {
    let server: JellyfinServerConfig
    let accentColor: Color
    let connectionState: JellyfinConnectionState
    let syncState: JellyfinSyncState
    let onEdit: () -> Void
    let onConnect: () -> Void
    let onDisconnect: () -> Void
    let onSync: () -> Void
    let onDelete: () -> Void

    @FocusState private var isFocused: Bool

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            Button(action: onEdit) {
                SettingsRowShell(isFocused: isFocused, accentColor: accentColor) {
                    SettingsRowText(title: server.displayName, subtitle: subtitleText)

                    Spacer(minLength: 24)

                    HStack(spacing: 8) {
                        Circle()
                            .fill(connectionState.isConnected ? Color.green : Color.white.opacity(0.3))
                            .frame(width: 10, height: 10)
                        Text(statusText)
                            .font(.system(size: 17, weight: .semibold))
                            .foregroundColor(.white.opacity(0.7))
                    }
                }
            }
            .buttonStyle(PosterCardButtonStyle())
            .focused($isFocused)
            .focusEffectDisabledIfAvailable()
            .entryLockable()

            HStack(spacing: 12) {
                if connectionState.isConnected {
                    SMBRowButton(title: L10n.string("smb_disconnect", fallback: "Disconnect"), accentColor: accentColor, action: onDisconnect)
                } else {
                    SMBRowButton(
                        title: connectionState == .connecting
                            ? L10n.string("smb_connecting", fallback: "Connecting…")
                            : L10n.string("smb_connect", fallback: "Connect"),
                        accentColor: accentColor,
                        isLoading: connectionState == .connecting,
                        action: onConnect
                    )
                }
                SMBRowButton(
                    title: syncTitle,
                    accentColor: accentColor,
                    enabled: connectionState.isConnected,
                    isLoading: isSyncing,
                    action: onSync
                )
                Spacer()
                SMBDeleteButton(action: onDelete)
            }
        }
        .padding(.bottom, 4)
    }

    private var subtitleText: String {
        var parts = ["\(server.authSummary) · \(server.baseURLString)"]
        if let count = server.lastSyncTitleCount {
            parts.append(L10n.format("smb_title_count", fallback: "%d titles", count))
        }
        if case .failed(let message) = connectionState {
            parts.append(message)
        }
        return parts.joined(separator: " — ")
    }

    private var statusText: String {
        switch connectionState {
        case .disconnected: return L10n.string("debrid_not_set", fallback: "Not set")
        case .connecting: return L10n.string("smb_connecting", fallback: "Connecting…")
        case .connected: return L10n.string("debrid_connected", fallback: "Connected")
        case .failed: return L10n.string("smb_failed", fallback: "Failed")
        }
    }

    private var isSyncing: Bool {
        if case .syncing = syncState { return true }
        return false
    }

    private var syncTitle: String {
        if case .syncing(let found, _) = syncState {
            return L10n.format("jellyfin_syncing_count", fallback: "Syncing (%d)…", found)
        }
        return L10n.string("jellyfin_sync", fallback: "Sync")
    }
}

/// Add or edit a server's connection settings. In `.login` mode, Save
/// exchanges the username/password for an access token immediately (so a
/// bad password is caught before the sheet closes) and writes the token to
/// Keychain; in `.apiKey` mode the pasted key is written as-is.
private struct JellyfinServerEditSheet: View {
    let server: JellyfinServerConfig?
    let accentColor: Color

    @Environment(\.dismiss) private var dismiss
    @AppStorage(SettingsKey.amoled) private var amoled = false
    @AppStorage(SettingsKey.bodyColor) private var bodyColor = SettingsBackground.charcoal.rawValue

    @State private var displayName: String
    @State private var baseURLString: String
    @State private var authKind: JellyfinAuthKind
    @State private var username: String
    @State private var password: String
    @State private var apiKey: String
    @State private var syncAutomatically: Bool
    @State private var isSaving = false
    @State private var errorMessage: String?
    @State private var saveTask: Task<Void, Never>?
    @State private var saveGeneration: UInt64 = 0

    init(server: JellyfinServerConfig?, accentColor: Color) {
        self.server = server
        self.accentColor = accentColor
        _displayName = State(initialValue: server?.displayName ?? "")
        _baseURLString = State(initialValue: server?.baseURLString ?? "")
        _authKind = State(initialValue: server?.authKind ?? .apiKey)
        _username = State(initialValue: server?.username ?? "")
        let storedToken = server.map { JellyfinCredentialStore.token(forServerID: $0.id) } ?? ""
        _password = State(initialValue: server?.authKind == .login ? storedToken : "")
        _apiKey = State(initialValue: server?.authKind == .apiKey ? storedToken : "")
        _syncAutomatically = State(initialValue: server?.syncAutomatically ?? true)
    }

    var body: some View {
        ZStack {
            Color.nuvioBackground(amoled: amoled, body: bodyColor).ignoresSafeArea()

            ScrollView {
                VStack(alignment: .leading, spacing: 24) {
                    Text(server == nil ? L10n.string("jellyfin_add_server", fallback: "Add Server") : L10n.string("jellyfin_edit_server", fallback: "Edit Server"))
                        .font(.system(size: 36, weight: .bold))
                        .foregroundColor(.white)

                    SettingsGroup(
                        title: L10n.string("smb_connection", fallback: "Connection"),
                        subtitle: L10n.string("jellyfin_connection_subtitle", fallback: "URL of the Jellyfin server")
                    ) {
                        SettingsNativeTextFieldRow(
                            title: L10n.string("smb_display_name", fallback: "Name"),
                            subtitle: L10n.string("smb_display_name_subtitle", fallback: "Shown in Settings and on Home"),
                            placeholder: "Living Room Server",
                            text: $displayName
                        )
                        SettingsNativeTextFieldRow(
                            title: L10n.string("jellyfin_server_url", fallback: "Server URL"),
                            subtitle: L10n.string("jellyfin_server_url_subtitle", fallback: "e.g. http://192.168.1.10:8096"),
                            placeholder: "http://192.168.1.10:8096",
                            text: $baseURLString
                        )
                    }

                    SettingsGroup(
                        title: L10n.string("smb_authentication", fallback: "Authentication"),
                        subtitle: L10n.string("jellyfin_authentication_subtitle", fallback: "An API key (Dashboard → API Keys) avoids typing a password on the Apple TV keyboard")
                    ) {
                        SettingsChoiceRow(
                            title: L10n.string("smb_auth_mode", fallback: "Sign-in Method"),
                            subtitle: "",
                            selection: authKindSelection,
                            options: JellyfinAuthKind.allCases.map(\.title),
                            accentColor: accentColor
                        )
                        if authKind == .apiKey {
                            SettingsNativeTextFieldRow(
                                title: L10n.string("jellyfin_api_key", fallback: "API Key"),
                                subtitle: "",
                                placeholder: L10n.string("debrid_not_set", fallback: "Not set"),
                                text: $apiKey,
                                isSecure: true
                            )
                        } else {
                            SettingsNativeTextFieldRow(
                                title: L10n.string("smb_username", fallback: "Username"),
                                subtitle: "",
                                placeholder: L10n.string("debrid_not_set", fallback: "Not set"),
                                text: $username
                            )
                            SettingsNativeTextFieldRow(
                                title: L10n.string("smb_password", fallback: "Password"),
                                subtitle: L10n.string(
                                    "tvos_settings_stored_locally_on_this_apple_tv",
                                    fallback: "Stored locally on this Apple TV"
                                ),
                                placeholder: L10n.string("debrid_not_set", fallback: "Not set"),
                                text: $password,
                                isSecure: true
                            )
                        }
                        if let errorMessage {
                            Text(errorMessage)
                                .font(.system(size: 15, weight: .regular))
                                .foregroundColor(.red.opacity(0.85))
                        }
                    }

                    SettingsGroup(
                        title: L10n.string("jellyfin_sync_group_title", fallback: "Library Sync"),
                        subtitle: L10n.string("jellyfin_sync_group_subtitle", fallback: "Automatically refresh library contents in the background")
                    ) {
                        SettingsToggleRow(
                            title: L10n.string("jellyfin_sync_automatically", fallback: "Sync Automatically"),
                            subtitle: L10n.string("jellyfin_sync_automatically_subtitle", fallback: "Refresh library content on launch and when returning to the app"),
                            isOn: $syncAutomatically,
                            accentColor: accentColor
                        )
                    }

                    HStack {
                        SMBDialogButton(title: L10n.string("action_cancel", fallback: "Cancel"), isPrimary: false) {
                            cancelPendingSave()
                            dismiss()
                        }
                        Spacer()
                        SMBDialogButton(
                            title: isSaving
                                ? L10n.string("smb_connecting", fallback: "Connecting…")
                                : L10n.string("action_save", fallback: "Save"),
                            isPrimary: true,
                            enabled: canSave && !isSaving
                        ) {
                            save()
                        }
                    }
                    .focusSection()
                }
                .padding(40)
            }
        }
        .onDisappear(perform: cancelPendingSave)
    }

    private var canSave: Bool {
        guard !displayName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
              URL(string: baseURLString.trimmingCharacters(in: .whitespacesAndNewlines)) != nil else { return false }
        switch authKind {
        case .apiKey: return !apiKey.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        case .login: return !username.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty && !password.isEmpty
        }
    }

    private var authKindSelection: Binding<String> {
        Binding(
            get: { authKind.title },
            set: { title in
                authKind = JellyfinAuthKind.allCases.first { $0.title == title } ?? .apiKey
            }
        )
    }

    private func save() {
        guard let baseURL = URL(string: baseURLString.trimmingCharacters(in: .whitespacesAndNewlines)) else { return }
        cancelPendingSave()
        let generation = saveGeneration
        isSaving = true
        errorMessage = nil
        let id = server?.id ?? UUID().uuidString
        let trimmedName = displayName.trimmingCharacters(in: .whitespacesAndNewlines)

        let selectedAuthKind = authKind
        let selectedAPIKey = apiKey.trimmingCharacters(in: .whitespacesAndNewlines)
        let selectedUsername = username
        let selectedPassword = password

        saveTask = Task { @MainActor in
            defer {
                if generation == saveGeneration {
                    saveTask = nil
                    isSaving = false
                }
            }
            guard !Task.isCancelled, generation == saveGeneration else { return }
            do {
                let token: String
                let userId: String
                switch selectedAuthKind {
                case .apiKey:
                    token = selectedAPIKey
                    userId = try await JellyfinClient.currentUserId(baseURL: baseURL, apiKey: token, username: selectedUsername)
                case .login:
                    let result = try await JellyfinSessionManager.login(baseURL: baseURL, username: selectedUsername, password: selectedPassword)
                    token = result.accessToken
                    userId = result.userId
                }

                guard !Task.isCancelled, generation == saveGeneration else { return }

                let config = JellyfinServerConfig(
                    id: id,
                    displayName: trimmedName,
                    baseURLString: baseURL.absoluteString,
                    authKind: selectedAuthKind,
                    username: selectedUsername.trimmingCharacters(in: .whitespacesAndNewlines),
                    userId: userId,
                    selectedLibraryIDs: server?.selectedLibraryIDs ?? [],
                    lastSyncDate: server?.lastSyncDate,
                    lastSyncTitleCount: server?.lastSyncTitleCount,
                    syncAutomatically: syncAutomatically
                )
                JellyfinCredentialStore.save(token, forServerID: id)
                JellyfinServerStore.shared.upsert(config)
                dismiss()
            } catch {
                guard !Task.isCancelled, generation == saveGeneration else { return }
                errorMessage = error.localizedDescription
            }
        }
    }

    private func cancelPendingSave() {
        saveGeneration &+= 1
        saveTask?.cancel()
        saveTask = nil
        isSaving = false
    }
}

/// Presented after "Sync" on a connected server: pick which libraries to
/// pull from, then watch live progress and the resulting match report.
private struct JellyfinLibrarySelectionSheet: View {
    let server: JellyfinServerConfig
    let accentColor: Color

    @Environment(\.dismiss) private var dismiss
    @AppStorage(SettingsKey.amoled) private var amoled = false
    @AppStorage(SettingsKey.bodyColor) private var bodyColor = SettingsBackground.charcoal.rawValue
    @ObservedObject private var sessionManager = JellyfinSessionManager.shared
    @State private var selectedLibraryIDs: Set<String>
    @State private var syncAutomatically: Bool

    init(server: JellyfinServerConfig, accentColor: Color) {
        self.server = server
        self.accentColor = accentColor
        _selectedLibraryIDs = State(initialValue: Set(server.selectedLibraryIDs))
        _syncAutomatically = State(initialValue: server.syncAutomatically)
    }

    var body: some View {
        ZStack {
            Color.nuvioBackground(amoled: amoled, body: bodyColor).ignoresSafeArea()

            ScrollView {
                VStack(alignment: .leading, spacing: 24) {
                    Text(L10n.format("jellyfin_libraries_on_server", fallback: "Libraries on %@", server.displayName))
                        .font(.system(size: 36, weight: .bold))
                        .foregroundColor(.white)

                    SettingsGroup(
                        title: L10n.string("jellyfin_sync_options", fallback: "Sync Options"),
                        subtitle: L10n.string("jellyfin_sync_options_subtitle", fallback: "Automatic background updates for this server")
                    ) {
                        SettingsToggleRow(
                            title: L10n.string("jellyfin_sync_automatically", fallback: "Sync Automatically"),
                            subtitle: L10n.string("jellyfin_sync_automatically_subtitle", fallback: "Refresh library content on launch and when returning to the app"),
                            isOn: syncAutomaticallyBinding,
                            accentColor: accentColor
                        )
                    }

                    if let libraries = availableLibraries {
                        SettingsGroup(
                            title: L10n.string("jellyfin_libraries", fallback: "Libraries"),
                            subtitle: L10n.string("jellyfin_libraries_subtitle", fallback: "Choose which libraries to sync")
                        ) {
                            ForEach(libraries) { library in
                                SettingsToggleRow(
                                    title: library.name,
                                    subtitle: library.collectionType ?? "",
                                    isOn: libraryBinding(library.id),
                                    accentColor: accentColor
                                )
                            }
                        }
                    }

                    syncStatusView

                    HStack {
                        SMBDialogButton(title: L10n.string("action_cancel", fallback: "Close"), isPrimary: false) { dismiss() }
                        Spacer()
                        SMBDialogButton(
                            title: L10n.string("jellyfin_start_sync", fallback: "Start Sync"),
                            isPrimary: true,
                            enabled: !selectedLibraryIDs.isEmpty && !isSyncing
                        ) {
                            startSync()
                        }
                    }
                    .focusSection()
                }
                .padding(40)
            }
        }
    }

    private var availableLibraries: [JellyfinLibrary]? {
        if case .connected(let libraries) = sessionManager.connectionState(for: server.id) {
            return libraries
        }
        return nil
    }

    private var isSyncing: Bool {
        if case .syncing = sessionManager.syncState(for: server.id) { return true }
        return false
    }

    private func libraryBinding(_ id: String) -> Binding<Bool> {
        Binding(
            get: { selectedLibraryIDs.contains(id) },
            set: { isOn in
                if isOn { selectedLibraryIDs.insert(id) } else { selectedLibraryIDs.remove(id) }
            }
        )
    }

    private var syncAutomaticallyBinding: Binding<Bool> {
        Binding(
            get: { syncAutomatically },
            set: { newValue in
                syncAutomatically = newValue
                if var current = JellyfinServerStore.shared.server(id: server.id) {
                    current.syncAutomatically = newValue
                    JellyfinServerStore.shared.upsert(current)
                }
            }
        )
    }

    private func startSync() {
        var updated = server
        updated.selectedLibraryIDs = Array(selectedLibraryIDs)
        updated.syncAutomatically = syncAutomatically
        JellyfinServerStore.shared.upsert(updated)
        sessionManager.sync(updated)
    }

    @ViewBuilder
    private var syncStatusView: some View {
        switch sessionManager.syncState(for: server.id) {
        case .idle:
            EmptyView()
        case .syncing(let found, let library):
            SettingsGroup(
                title: L10n.string("jellyfin_syncing", fallback: "Syncing…"),
                subtitle: library
            ) {
                SettingsInfoRow(title: L10n.string("smb_found_so_far", fallback: "Found so far"), value: "\(found)")
            }
        case .done(let report):
            SettingsGroup(
                title: L10n.string("smb_scan_complete", fallback: "Scan Complete"),
                subtitle: L10n.string("jellyfin_sync_complete_subtitle", fallback: "Matched titles appear on Home as Jellyfin")
            ) {
                SettingsInfoRow(title: L10n.string("smb_matched_titles", fallback: "Matched Titles"), value: "\(report.matchedTitles)")
                SettingsInfoRow(title: L10n.string("smb_matched_episodes", fallback: "Matched Episodes"), value: "\(report.matchedEpisodes)")
                SettingsInfoRow(title: L10n.string("smb_unmatched", fallback: "Unmatched"), value: "\(report.unmatched.count)")
                if !report.unmatched.isEmpty {
                    VStack(alignment: .leading, spacing: 6) {
                        ForEach(report.unmatched.prefix(20), id: \.self) { name in
                            Text(name)
                                .font(.system(size: 15, weight: .regular))
                                .foregroundColor(.white.opacity(0.5))
                                .lineLimit(1)
                        }
                    }
                }
            }
        case .failed(let message):
            SettingsGroup(
                title: L10n.string("smb_scan_failed", fallback: "Scan Failed"),
                subtitle: message
            ) { EmptyView() }
        }
    }
}

// MARK: - Addons (moved here from the former Addons tab)

private struct AddonsSettingsSection: View {
    let accentColor: Color
    var onSyncedAddonsChange: (([SyncedAddon]) -> Void)? = nil

    @AppStorage(SettingsKey.streamAddonManifestURL) private var streamAddonManifestURL = ""
    @AppStorage(SettingsKey.streamAddonManifestURLs) private var streamAddonManifestURLs = ""
    @AppStorage(SettingsKey.streamAddonManifestStates) private var streamAddonManifestStates = ""
    @State private var addonURLInput = ""
    @State private var addonNameInput = ""
    @State private var renamingAddonID: String?
    @State private var renamingText = ""
    @State private var addons: [AddonItem] = AddonsSettingsSection.initialLocalAddons()
    @State private var syncedAddons: [SyncedAddon] = []

    var body: some View {
        VStack(alignment: .leading, spacing: 28) {
            SettingsGroup(title: L10n.string("tvos_settings_add_ons", fallback: "Add-ons"), subtitle: L10n.string("tvos_settings_stremio_compatible_catalogs_streams_and__cd03738a", fallback: "Stremio-compatible catalogs, streams, and subtitles")) {
                SettingsTextFieldRow(
                    title: L10n.string("tvos_settings_add_on_url", fallback: "Add-on URL"),
                    subtitle: L10n.string("tvos_settings_paste_a_stremio_manifest_link_or_stremio_2968c517", fallback: "Paste a Stremio manifest link or stremio:// install URL"),
                    placeholder: L10n.string(
                        "tvos_settings_addon_url_placeholder",
                        fallback: "https://.../manifest.json"
                    ),
                    text: $addonURLInput,
                    fieldWidth: 560,
                    onCommit: addAddonFromInput
                )
                .settingsEntryAnchor()

                SettingsTextFieldRow(
                    title: L10n.string("tvos_settings_add_on_name_optional", fallback: "Add-on Name (Optional)"),
                    subtitle: L10n.string("tvos_settings_add_on_name_optional_subtitle", fallback: "Custom title for this add-on (e.g. AIOStreams 4K)"),
                    placeholder: L10n.string(
                        "tvos_settings_addon_name_placeholder",
                        fallback: "e.g. AIOStreams 4K"
                    ),
                    text: $addonNameInput,
                    fieldWidth: 560,
                    onCommit: {
                        if !addonURLInput.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                            addAddonFromInput()
                        }
                    }
                )

                ForEach(Array(syncedAddons.enumerated()), id: \.element.id) { index, addon in
                    VStack(alignment: .leading, spacing: 12) {
                        SyncedAddonSettingsRow(
                            addon: addon,
                            accentColor: accentColor,
                            canMoveUp: index > 0,
                            canMoveDown: index < syncedAddons.count - 1,
                            onEnabledChange: { isEnabled in setAddonEnabled(at: index, isEnabled: isEnabled) },
                            onRename: {
                                if renamingAddonID == addon.id {
                                    renamingAddonID = nil
                                    renamingText = ""
                                } else {
                                    renamingAddonID = addon.id
                                    renamingText = addon.customName ?? addon.name
                                }
                            },
                            onDelete: {
                                if renamingAddonID == addon.id {
                                    renamingAddonID = nil
                                    renamingText = ""
                                }
                                removeAddon(at: index)
                            },
                            onMove: { up in
                                if renamingAddonID == addon.id {
                                    renamingAddonID = nil
                                    renamingText = ""
                                }
                                moveAddon(at: index, up: up)
                            }
                        )

                        if renamingAddonID == addon.id {
                            HStack(spacing: 14) {
                                SettingsTextFieldRow(
                                    title: L10n.string("tvos_settings_rename_addon", fallback: "Rename Add-on"),
                                    subtitle: L10n.string("tvos_settings_rename_addon_subtitle", fallback: "Custom title for this add-on"),
                                    placeholder: addon.name,
                                    text: $renamingText,
                                    fieldWidth: 500,
                                    onCommit: { saveRenamedAddon(at: index) }
                                )
                                AddonReorderButton(systemImage: "checkmark", disabled: false) {
                                    saveRenamedAddon(at: index)
                                }
                                AddonReorderButton(systemImage: "xmark", disabled: false) {
                                    renamingAddonID = nil
                                    renamingText = ""
                                }
                            }
                            .padding(.leading, 20)
                        }
                    }
                }

                let uncoveredAddons = Array(addons.enumerated()).filter { !isCoveredBySyncedAddon($0.element) }
                ForEach(Array(uncoveredAddons.enumerated()), id: \.element.element.id) { displayIndex, item in
                    let (originalIndex, addon) = item
                    AddonSettingsRow(
                        addon: addon,
                        accentColor: accentColor,
                        canMoveUp: displayIndex > 0,
                        canMoveDown: displayIndex < uncoveredAddons.count - 1,
                        onEnabledChange: { isEnabled in
                            setLocalAddonEnabled(at: originalIndex, isEnabled: isEnabled)
                        },
                        onDelete: {
                            removeLocalAddon(at: originalIndex)
                        },
                        onMove: { up in
                            let targetDisplayIndex = up ? displayIndex - 1 : displayIndex + 1
                            guard uncoveredAddons.indices.contains(targetDisplayIndex) else { return }
                            let targetOriginalIndex = uncoveredAddons[targetDisplayIndex].offset
                            moveLocalAddon(from: originalIndex, to: targetOriginalIndex)
                        }
                    )
                }
            }
        }
        .task(id: streamAddonManifestURL + "\n" + streamAddonManifestURLs + "\n" + streamAddonManifestStates) {
            await loadSyncedAddons()
        }
    }

    /// Reorders the configured manifests, rewrites the settings the repository
    /// reads (order = stream priority and Home row order), and pushes the new
    /// order to the account so the next sync pull can't revert it.
    private func moveAddon(at index: Int, up: Bool) {
        let target = up ? index - 1 : index + 1
        guard syncedAddons.indices.contains(index), syncedAddons.indices.contains(target) else { return }
        syncedAddons.swapAt(index, target)
        persistSyncedAddons()
    }

    private func setAddonEnabled(at index: Int, isEnabled: Bool) {
        guard syncedAddons.indices.contains(index) else { return }
        syncedAddons[index].isEnabled = isEnabled
        persistSyncedAddons()
    }

    /// Uninstalls the add-on: drops the manifest from the configured list rather
    /// than disabling it, and pushes the shortened list so the removal reaches
    /// the account instead of returning on the next pull.
    private func removeAddon(at index: Int) {
        guard syncedAddons.indices.contains(index) else { return }
        let removed = syncedAddons.remove(at: index)
        persistSyncedAddons(removedAddon: removed)
    }

    private func saveRenamedAddon(at index: Int) {
        guard syncedAddons.indices.contains(index) else { return }
        let trimmed = renamingText.trimmingCharacters(in: .whitespacesAndNewlines)
        syncedAddons[index].customName = trimmed.isEmpty ? nil : trimmed
        syncedAddons[index].name = trimmed.isEmpty
            ? (syncedAddons[index].manifestID ?? CinemetaCatalogRepository.streamAddonName(for: syncedAddons[index].url))
            : trimmed
        persistSyncedAddons()
        renamingAddonID = nil
        renamingText = ""
    }

    /// Finalizing the URL field is an add operation, not just a local settings
    /// edit. Canonicalize the complete list and notify sync immediately so the
    /// new add-on reaches the user's other devices.
    private func addAddonFromInput() {
        let editedProfileId = ProfileSettings.activeProfileID ?? ""
        guard let url = CinemetaCatalogRepository.normalizedManifestURL(from: addonURLInput) else { return }
        var preferences = CinemetaCatalogRepository.configuredStreamAddonPreferences
        let customName = addonNameInput.trimmingCharacters(in: .whitespacesAndNewlines)
        let nameToStore = customName.isEmpty ? nil : customName
        if let index = preferences.firstIndex(where: { $0.url == url.absoluteString }) {
            preferences[index].enabled = true
            if let nameToStore { preferences[index].name = nameToStore }
        } else {
            preferences.append(StreamAddonPreference(url: url.absoluteString, enabled: true, name: nameToStore))
        }
        let cinemetaURL = "https://v3-cinemeta.strem.io/manifest.json"
        if url.absoluteString.caseInsensitiveCompare(cinemetaURL) == .orderedSame {
            CinemetaCatalogRepository.setCinemetaDisabled(false)
            var deleted = Self.deletedLocalAddonIDs()
            deleted.remove("cinemeta")
            Self.setDeletedLocalAddonIDs(deleted)
        }

        CinemetaCatalogRepository.setConfiguredStreamAddonPreferences(preferences)
        streamAddonManifestURL = ProfileSettings.current.string(forKey: SettingsKey.streamAddonManifestURL) ?? ""
        streamAddonManifestURLs = ProfileSettings.current.string(forKey: SettingsKey.streamAddonManifestURLs) ?? ""
        streamAddonManifestStates = ProfileSettings.current.string(forKey: SettingsKey.streamAddonManifestStates) ?? ""
        addonURLInput = ""
        addonNameInput = ""
        NotificationCenter.default.post(
            name: NuvioSyncManager.addonOrderChangedNotification,
            object: preferences,
            userInfo: [NuvioSyncManager.addonEditedProfileIdUserInfoKey: editedProfileId]
        )
    }

    private func persistSyncedAddons(removedAddon: SyncedAddon? = nil) {
        let editedProfileId = ProfileSettings.activeProfileID ?? ""
        let preferences = syncedAddons.map {
            StreamAddonPreference(url: $0.url.absoluteString, enabled: $0.isEnabled, name: $0.customName)
        }
        var identities: [String: String] = [:]
        for addon in syncedAddons + [removedAddon].compactMap({ $0 }) {
            if let id = addon.manifestID { identities[addon.url.absoluteString] = id }
        }
        CinemetaCatalogRepository.setConfiguredStreamAddonPreferences(preferences, knownManifestIDs: identities)
        onSyncedAddonsChange?(syncedAddons)
        TVHomeCatalogOrder.setDisabledAddonSources(
            ids: Set(syncedAddons.filter { !$0.isEnabled }.compactMap(\.manifestID)),
            names: Set(
                syncedAddons
                    .filter { !$0.isEnabled }
                    .map { TVHomeCatalogOrder.normalizedAddonSourceName($0.name) }
            )
        )
        streamAddonManifestURL = ProfileSettings.current.string(forKey: SettingsKey.streamAddonManifestURL) ?? ""
        streamAddonManifestURLs = ProfileSettings.current.string(forKey: SettingsKey.streamAddonManifestURLs) ?? ""
        streamAddonManifestStates = ProfileSettings.current.string(forKey: SettingsKey.streamAddonManifestStates) ?? ""
        NotificationCenter.default.post(
            name: NuvioSyncManager.addonOrderChangedNotification,
            object: preferences,
            userInfo: [NuvioSyncManager.addonEditedProfileIdUserInfoKey: editedProfileId]
        )
    }

    /// Lists every configured/synced manifest immediately (named by host), then
    /// upgrades each row with the real name/version/description from its
    /// manifest as the fetches come back.
    private func loadSyncedAddons() async {
        let activeProfileID = ProfileSettings.activeProfileID
        let preferences = CinemetaCatalogRepository.configuredStreamAddonPreferences
        // Keep already-resolved names/descriptions (e.g. across a reorder) so
        // rows don't flash back to host-derived names.
        var resolved = preferences.compactMap { preference -> SyncedAddon? in
            guard let url = CinemetaCatalogRepository.normalizedManifestURL(from: preference.url) else { return nil }
            var addon = syncedAddons.first { $0.url == url } ?? SyncedAddon(url: url, isEnabled: preference.enabled, customName: preference.name)
            addon.isEnabled = preference.enabled
            if let prefName = preference.name?.trimmingCharacters(in: .whitespacesAndNewlines), !prefName.isEmpty {
                addon.customName = prefName
                addon.name = prefName
            }
            return addon
        }
        syncedAddons = resolved
        addons = Self.initialLocalAddons()
        onSyncedAddonsChange?(resolved)

        var pendingRowUpdates: [(addonID: String, addonName: String, additions: [TVHomeCatalogOrder.SnapshotRow])] = []

        for index in resolved.indices {
            guard !Task.isCancelled else { return }
            let manifest = await StremioManifest.fetch(from: resolved[index].url)
            guard !Task.isCancelled, ProfileSettings.activeProfileID == activeProfileID else { return }
            guard let manifest else {
                continue
            }
            resolved[index].apply(manifest)
            syncedAddons = resolved
            onSyncedAddonsChange?(resolved)
            if resolved[index].isEnabled,
               let addonID = manifest.id,
               addonID != CinemetaCatalogRepository.cinemetaAddonId {
                let rows = resolvedHomeRows(
                    manifest: manifest,
                    manifestURL: resolved[index].url,
                    addonID: addonID,
                    addonName: resolved[index].name
                )
                pendingRowUpdates.append((addonID: addonID, addonName: resolved[index].name, additions: rows))
            }
        }

        if !pendingRowUpdates.isEmpty, !Task.isCancelled, ProfileSettings.activeProfileID == activeProfileID {
            TVHomeCatalogOrder.batchReplaceSnapshotRows(pendingRowUpdates)
        }
    }

    /// Declaratively resolves the home catalog rows declared by an add-on's manifest,
    /// matching Android TV's architecture. Catalogs are registered into Settings immediately
    /// without blocking on live catalog item requests or failing on transient server outages.
    private func resolvedHomeRows(
        manifest: StremioManifest,
        manifestURL: URL,
        addonID: String,
        addonName: String
    ) -> [TVHomeCatalogOrder.SnapshotRow] {
        let catalogs = (manifest.catalogs ?? []).filter { catalog in
            catalog.eligibleForHome
                && (!catalog.requiresGenre || catalog.firstGenreOption != nil)
        }
        return catalogs.compactMap { catalog in
            snapshotRow(
                for: catalog,
                addonID: addonID,
                addonName: addonName,
                manifestURL: manifestURL.absoluteString
            )
        }
    }

    private func snapshotRow(
        for catalog: StremioManifestCatalog,
        addonID: String,
        addonName: String,
        manifestURL: String
    ) -> TVHomeCatalogOrder.SnapshotRow? {
        guard let type = catalog.type,
              let catalogID = catalog.id else { return nil }
        let settingsKey = TVHomeCatalogOrder.catalogSettingsKey(
            addonId: addonID,
            contentType: type,
            catalogId: catalogID
        )
        let customTitle = TVHomeCatalogOrder.customTitle(forCatalogKey: settingsKey)
        return TVHomeCatalogOrder.SnapshotRow(
            id: "addon_\(addonID)_\(type)_\(catalogID)",
            title: TVHomeCatalogOrder.catalogDisplayTitle(
                catalog.name ?? catalogID,
                contentType: type,
                showType: ProfileSettings.current.object(forKey: SettingsKey.homeCatalogShowType) as? Bool ?? true,
                addonName: addonName,
                customTitle: customTitle
            ),
            addonName: addonName,
            addonId: addonID,
            contentType: type,
            catalogId: catalogID,
            manifestURL: manifestURL,
            manifestShowInHome: catalog.showInHome,
            settingsKey: settingsKey
        )
    }


    /// Hides a built-in placeholder row when the account sync already provides
    /// the same addon (matched loosely by name/host, so the synced "Cinemeta"
    /// covers the built-in Cinemeta row instead of showing a duplicate).
    private func isCoveredBySyncedAddon(_ addon: AddonItem) -> Bool {
        Self.isCoveredBySyncedAddon(addon, sources: syncedAddons)
    }

    private static func isCoveredBySyncedAddon(_ addon: AddonItem, sources: [SyncedAddon]) -> Bool {
        let target = Self.normalizedAddonKey(addon.name)
        guard !target.isEmpty else { return false }
        return sources.contains { synced in
            Self.normalizedAddonKey(synced.name).contains(target)
                || Self.normalizedAddonKey(synced.url.host ?? "").contains(target)
        }
    }

    private static func normalizedAddonKey(_ value: String) -> String {
        value.lowercased().filter { $0.isLetter || $0.isNumber }
    }

    static func deletedLocalAddonIDs() -> Set<String> {
        guard let data = ProfileSettings.current.data(forKey: SettingsKey.deletedLocalAddons),
              let list = try? JSONDecoder().decode([String].self, from: data) else {
            return []
        }
        return Set(list)
    }

    static func setDeletedLocalAddonIDs(_ ids: Set<String>) {
        guard let data = try? JSONEncoder().encode(Array(ids).sorted()) else { return }
        ProfileSettings.current.set(data, forKey: SettingsKey.deletedLocalAddons)
    }

    static func initialLocalAddons() -> [AddonItem] {
        let deleted = deletedLocalAddonIDs()
        let isCinemetaActive = CinemetaCatalogRepository.isCinemetaEnabled
        return AddonItem.defaults.compactMap { item in
            if deleted.contains(item.id) { return nil }
            var updated = item
            if item.id == "cinemeta" {
                if !isCinemetaActive && ProfileSettings.current.bool(forKey: SettingsKey.cinemetaDisabled) {
                    return nil
                }
                updated.isInstalled = isCinemetaActive
            }
            return updated
        }
    }

    static func configuredSyncedAddons() -> [SyncedAddon] {
        CinemetaCatalogRepository.configuredStreamAddonPreferences.compactMap { preference in
            guard let url = CinemetaCatalogRepository.normalizedManifestURL(from: preference.url) else { return nil }
            return SyncedAddon(url: url, isEnabled: preference.enabled)
        }
    }

    static func displayedRowCount(using syncedAddons: [SyncedAddon]) -> Int {
        let uncoveredLocalAddons = initialLocalAddons().filter {
            !isCoveredBySyncedAddon($0, sources: syncedAddons)
        }
        return syncedAddons.count + uncoveredLocalAddons.count
    }

    private func setLocalAddonEnabled(at index: Int, isEnabled: Bool) {
        let editedProfileId = ProfileSettings.activeProfileID ?? ""
        guard addons.indices.contains(index) else { return }
        addons[index].isInstalled = isEnabled
        let addon = addons[index]
        if addon.id == "cinemeta" {
            var preferences = CinemetaCatalogRepository.configuredStreamAddonPreferences
            let cinemetaURL = "https://v3-cinemeta.strem.io/manifest.json"
            if let idx = preferences.firstIndex(where: { $0.url.caseInsensitiveCompare(cinemetaURL) == .orderedSame }) {
                preferences[idx].enabled = isEnabled
            } else {
                preferences.append(StreamAddonPreference(url: cinemetaURL, enabled: isEnabled))
            }
            CinemetaCatalogRepository.setConfiguredStreamAddonPreferences(preferences)
            CinemetaCatalogRepository.setCinemetaDisabled(!isEnabled)
            streamAddonManifestStates = ProfileSettings.current.string(forKey: SettingsKey.streamAddonManifestStates) ?? ""
            NotificationCenter.default.post(
                name: NuvioSyncManager.addonOrderChangedNotification,
                object: preferences,
                userInfo: [NuvioSyncManager.addonEditedProfileIdUserInfoKey: editedProfileId]
            )
            NotificationCenter.default.post(
                name: TVHomeCatalogOrder.changedNotification,
                object: nil
            )
            NotificationCenter.default.post(
                name: TVHomeCatalogOrder.snapshotChangedNotification,
                object: nil
            )
        }
    }

    private func removeLocalAddon(at index: Int) {
        let editedProfileId = ProfileSettings.activeProfileID ?? ""
        guard addons.indices.contains(index) else { return }
        let addon = addons.remove(at: index)
        var deleted = Self.deletedLocalAddonIDs()
        deleted.insert(addon.id)
        Self.setDeletedLocalAddonIDs(deleted)
        if addon.id == "cinemeta" {
            var preferences = CinemetaCatalogRepository.configuredStreamAddonPreferences
            let cinemetaURL = "https://v3-cinemeta.strem.io/manifest.json"
            preferences.removeAll(where: { $0.url.caseInsensitiveCompare(cinemetaURL) == .orderedSame })
            CinemetaCatalogRepository.setConfiguredStreamAddonPreferences(preferences)
            CinemetaCatalogRepository.setCinemetaDisabled(true)
            AddonCatalogRemovalStore.removeBuiltInCinemeta(in: ProfileSettings.current)
            streamAddonManifestStates = ProfileSettings.current.string(forKey: SettingsKey.streamAddonManifestStates) ?? ""
            NotificationCenter.default.post(
                name: NuvioSyncManager.addonOrderChangedNotification,
                object: preferences,
                userInfo: [NuvioSyncManager.addonEditedProfileIdUserInfoKey: editedProfileId]
            )
            NotificationCenter.default.post(
                name: TVHomeCatalogOrder.changedNotification,
                object: nil
            )
            NotificationCenter.default.post(
                name: TVHomeCatalogOrder.snapshotChangedNotification,
                object: nil
            )
        }
        onSyncedAddonsChange?(syncedAddons)
    }

    private func moveLocalAddon(from source: Int, to target: Int) {
        guard addons.indices.contains(source), addons.indices.contains(target) else { return }
        addons.swapAt(source, target)
    }
}

/// One add-on synced from the account (or entered manually), shown in the
/// Add-ons section. Starts with just the manifest URL; name/version/description
/// arrive once the manifest is fetched.
private struct SyncedAddon: Identifiable {
    let url: URL
    var name: String
    var customName: String?
    var manifestID: String?
    var version: String?
    var description: String?
    /// The add-on's own artwork from its manifest, shown in place of the generic
    /// sync glyph. Nil until the manifest lands, or when it declares neither a
    /// logo nor an icon.
    var logoURL: URL?
    var isEnabled: Bool

    var id: String { url.absoluteString }

    init(url: URL, isEnabled: Bool = true, customName: String? = nil) {
        self.url = url
        self.customName = customName
        let trimmedCustom = customName?.trimmingCharacters(in: .whitespacesAndNewlines)
        if let trimmedCustom, !trimmedCustom.isEmpty {
            self.name = trimmedCustom
        } else {
            self.name = CinemetaCatalogRepository.streamAddonName(for: url)
        }
        self.manifestID = nil
        self.isEnabled = isEnabled
    }

    mutating func apply(_ manifest: StremioManifest) {
        manifestID = manifest.id
        if let customName = customName?.trimmingCharacters(in: .whitespacesAndNewlines), !customName.isEmpty {
            name = customName
        } else if let manifestName = manifest.name?.trimmingCharacters(in: .whitespacesAndNewlines),
           !manifestName.isEmpty {
            name = manifestName
        }
        version = manifest.version
        description = manifest.description
        logoURL = manifest.artworkURL(relativeTo: url)
    }

    var subtitle: String {
        let trimmed = description?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return trimmed.isEmpty ? (url.host ?? url.absoluteString) : trimmed
    }
}

struct StremioManifest: Decodable {
    let id: String?
    let name: String?
    let version: String?
    let description: String?
    let catalogs: [StremioManifestCatalog]?
    /// Stremio manifests carry `logo` (wide/wordmark) and/or `icon` (square).
    let logo: String?
    let icon: String?

    /// Absolute artwork URL, preferring the logo. A manifest may give a path
    /// relative to its own location ("/logo.png"), which has to be resolved
    /// against the manifest URL or it loads nothing.
    func artworkURL(relativeTo manifestURL: URL) -> URL? {
        for candidate in [logo, icon] {
            guard let raw = candidate?.trimmingCharacters(in: .whitespacesAndNewlines),
                  !raw.isEmpty else { continue }
            if let absolute = URL(string: raw), absolute.scheme != nil { return absolute }
            if let resolved = URL(string: raw, relativeTo: manifestURL)?.absoluteURL {
                return resolved
            }
        }
        return nil
    }

    static func fetch(from manifestURL: URL) async -> StremioManifest? {
        guard let data = await StremioManifestDataCache.shared.data(for: manifestURL) else {
            return nil
        }
        return try? JSONDecoder().decode(StremioManifest.self, from: data)
    }
}

struct StremioManifestCatalog: Decodable {
    let type: String?
    let id: String?
    let name: String?
    let showInHome: Bool?
    let extra: [StremioManifestCatalogExtra]?
    let extraRequired: [String]?

    var eligibleForHome: Bool {
        let required = requiredExtraNames
        if showInHome == false || required.contains("search") { return false }
        return required.allSatisfy { $0 == "genre" }
    }

    var requiresGenre: Bool { requiredExtraNames.contains("genre") }

    var firstGenreOption: String? {
        extra?.first { $0.name.lowercased() == "genre" }?.options?.first
    }

    private var requiredExtraNames: [String] {
        let structured = (extra ?? [])
            .filter { $0.isRequired == true }
            .map { $0.name.lowercased() }
        let legacy = (extraRequired ?? []).map { $0.lowercased() }
        return structured + legacy
    }

    func settingsKey(addonID: String) -> String? {
        guard let type, let id else { return nil }
        return TVHomeCatalogOrder.catalogSettingsKey(
            addonId: addonID,
            contentType: type,
            catalogId: id
        )
    }
}

struct StremioManifestCatalogExtra: Decodable {
    let name: String
    let isRequired: Bool?
    let options: [String]?
}


private struct SyncedAddonSettingsRow: View {
    let addon: SyncedAddon
    let accentColor: Color
    var canMoveUp: Bool = false
    var canMoveDown: Bool = false
    var onEnabledChange: ((Bool) -> Void)? = nil
    var onRename: (() -> Void)? = nil
    var onDelete: (() -> Void)? = nil
    /// Called with `true` for up, `false` for down. nil hides the arrows.
    var onMove: ((Bool) -> Void)? = nil

    @FocusState private var isFocused: Bool

    var body: some View {
        HStack(spacing: 14) {
            rowButton

            if let onRename {
                AddonReorderButton(systemImage: "pencil", disabled: false, action: onRename)
            }

            // The row itself toggles active/inactive, so a power button beside it
            // did the same job twice. Uninstall is what the row could not offer.
            if let onDelete {
                AddonReorderButton(systemImage: "trash", disabled: false, action: onDelete)
            }

            if let onMove {
                AddonReorderButton(systemImage: "chevron.up", disabled: !canMoveUp) {
                    onMove(true)
                }
                AddonReorderButton(systemImage: "chevron.down", disabled: !canMoveDown) {
                    onMove(false)
                }
            }
        }
    }

    private var rowButton: some View {
        Button(action: { onEnabledChange?(!addon.isEnabled) }) {
            SettingsRowShell(isFocused: isFocused, accentColor: accentColor) {
                addonArtwork

                VStack(alignment: .leading, spacing: 4) {
                    HStack(spacing: 8) {
                        Text(addon.name)
                            .font(.system(size: 22, weight: .semibold))
                            .foregroundColor(addon.isEnabled ? .white : .white.opacity(0.46))
                            .lineLimit(1)
                        if let version = addon.version, !version.isEmpty {
                            Text("v\(version)")
                                .font(.system(size: 15, weight: .medium))
                                .foregroundColor(.white.opacity(0.4))
                        }
                        Text(L10n.string("tvos_settings_synced", fallback: "Synced"))
                            .font(.system(size: 13, weight: .bold))
                            .foregroundColor(accentColor)
                    }
                    Text(addon.subtitle)
                        .font(.system(size: 16, weight: .medium))
                        .foregroundColor(.white.opacity(addon.isEnabled ? 0.56 : 0.36))
                        .lineLimit(2)
                }

                Spacer(minLength: 20)

                Text(addon.isEnabled ? L10n.string("settings_fusion_badge_url_active", fallback: "Active") : L10n.string("tvos_settings_disabled", fallback: "Disabled"))
                    .font(.system(size: 18, weight: .bold))
                    .foregroundColor(addon.isEnabled ? .white.opacity(0.7) : .white.opacity(0.42))
                    .lineLimit(1)
            }
        }
        .buttonStyle(PosterCardButtonStyle())
        .focused($isFocused)
        .focusEffectDisabledIfAvailable()
        .entryLockable()
    }

    /// The add-on's own logo once its manifest has been read, falling back to the
    /// sync glyph while that is in flight or for a manifest that ships no
    /// artwork. Logos are wordmarks as often as square icons, so this fits rather
    /// than fills — cropping a wordmark to a square makes it unreadable.
    private var addonArtwork: some View {
        Group {
            if let logoURL = addon.logoURL {
                AsyncImage(url: logoURL) { phase in
                    if let image = phase.image {
                        image
                            .resizable()
                            .aspectRatio(contentMode: .fit)
                    } else {
                        fallbackGlyph
                    }
                }
            } else {
                fallbackGlyph
            }
        }
        .frame(width: 48, height: 48)
        .opacity(addon.isEnabled ? 1 : 0.42)
    }

    private var fallbackGlyph: some View {
        Image(systemName: "arrow.triangle.2.circlepath")
            .font(.system(size: 26))
            .foregroundColor(addon.isEnabled ? accentColor : .white.opacity(0.38))
    }
}

/// Mirrors installed add-ons: selecting a pack enables or disables it, while
/// the adjacent trash button removes the downloaded rules altogether.
private struct StreamBadgePackSettingsRow: View {
    let badgePack: StreamBadgeImport
    let accentColor: Color
    let onEnabledChange: (Bool) -> Void
    let onDelete: () -> Void

    @FocusState private var isFocused: Bool

    var body: some View {
        HStack(spacing: 14) {
            Button(action: { onEnabledChange(!badgePack.isActive) }) {
                SettingsRowShell(isFocused: isFocused, accentColor: accentColor) {
                    Image(systemName: "tag.fill")
                        .font(.system(size: 25, weight: .semibold))
                        .foregroundColor(badgePack.isActive ? accentColor : .white.opacity(0.38))
                        .frame(width: 48, height: 48)

                    VStack(alignment: .leading, spacing: 4) {
                        Text(packName)
                            .font(.system(size: 22, weight: .semibold))
                            .foregroundColor(badgePack.isActive ? .white : .white.opacity(0.46))
                            .lineLimit(1)

                        Text("\(badgePack.enabledFilterCount) badge rules · \(badgePack.sourceUrl)")
                            .font(.system(size: 16, weight: .medium))
                            .foregroundColor(.white.opacity(badgePack.isActive ? 0.56 : 0.36))
                            .lineLimit(2)
                    }

                    Spacer(minLength: 20)

                    Text(badgePack.isActive ? "Active" : "Disabled")
                        .font(.system(size: 18, weight: .bold))
                        .foregroundColor(badgePack.isActive ? .white.opacity(0.7) : .white.opacity(0.42))
                        .lineLimit(1)
                }
            }
            .buttonStyle(PosterCardButtonStyle())
            .focused($isFocused)
            .focusEffectDisabledIfAvailable()
            .entryLockable()

            AddonReorderButton(systemImage: "trash", disabled: false, action: onDelete)
        }
    }

    private var packName: String {
        if badgePack.sourceUrl.caseInsensitiveCompare(StreamBadgeSettingsStore.goldBadgePackURL) == .orderedSame {
            return "Gold Badge Pack"
        }
        let filename = URL(string: badgePack.sourceUrl)?
            .deletingPathExtension()
            .lastPathComponent
            .replacingOccurrences(of: "_", with: " ")
            .replacingOccurrences(of: "-", with: " ")
            .capitalized ?? ""
        return filename.isEmpty ? "Badge Pack" : filename
    }
}

/// Chevron button for moving an add-on up/down in the priority order.
private struct AddonReorderButton: View {
    let systemImage: String
    let disabled: Bool
    let action: () -> Void

    @FocusState private var focused: Bool

    var body: some View {
        Button(action: action) {
            Image(systemName: systemImage)
                .font(.system(size: 20, weight: .bold))
                .foregroundColor(focused ? .black : .white.opacity(0.8))
                .frame(width: 52, height: 52)
                .background(focused ? Color.white : Color.white.opacity(0.1))
                .clipShape(Circle())
                .opacity(disabled ? 0.35 : 1)
                .scaleEffect(focused && !disabled ? 1.08 : 1)
        }
        .buttonStyle(PosterCardButtonStyle())
        .disabled(disabled)
        .focused($focused)
        .focusEffectDisabledIfAvailable()
        .animation(.easeOut(duration: 0.12), value: focused)
        .entryLockable()
    }
}

// MARK: - Plugins

/// Settings → Integrations → Plugins: repositories added by their
/// `manifest.json` link (as on Android), their providers, and each provider's
/// own settings form. The repository list syncs with the Nuvio account.
private struct PluginsSettingsSection: View {
    let accentColor: Color

    @ObservedObject private var store = PluginStore.shared
    @State private var manifestURLInput = ""
    @State private var addStatus: String?
    @State private var addFailed = false
    @State private var isAdding = false
    @State private var settingsScraper: PluginScraperRecord?
    @State private var logScraper: PluginScraperRecord?
    @State private var testScraper: PluginScraperRecord?
    @State private var showingWebSetup = false

    var body: some View {
        VStack(alignment: .leading, spacing: 28) {
            SettingsGroup(
                title: L10n.string("tvos_settings_plugins", fallback: "Plugins"),
                subtitle: L10n.string(
                    "tvos_settings_plugins_group_subtitle",
                    fallback: "Providers written in JavaScript that run on this Apple TV. The repository list syncs with your Nuvio account; provider settings stay on this device."
                )
            ) {
                SettingsTextFieldRow(
                    title: L10n.string("tvos_settings_plugin_repository_url", fallback: "Repository URL"),
                    subtitle: addStatus ?? L10n.string(
                        "tvos_settings_plugin_repository_url_subtitle",
                        fallback: "Paste the link to a plugin manifest.json — a GitHub link works too"
                    ),
                    placeholder: isAdding
                        ? L10n.string("tvos_settings_plugin_adding", fallback: "Adding…")
                        : "https://.../manifest.json",
                    text: $manifestURLInput,
                    fieldWidth: 560,
                    onCommit: addRepository
                )
                .settingsEntryAnchor()

                SettingsToggleRow(
                    title: L10n.string("tvos_settings_plugins_enabled", fallback: "Use Plugins"),
                    subtitle: L10n.string(
                        "tvos_settings_plugins_enabled_subtitle",
                        fallback: "Ask the enabled providers for streams and subtitles next to your add-ons"
                    ),
                    isOn: Binding(
                        get: { store.state.pluginsEnabled },
                        set: { store.setPluginsEnabled($0) }
                    ),
                    accentColor: accentColor
                )

                SettingsToggleRow(
                    title: L10n.string("tvos_settings_plugins_auto_update", fallback: "Update Automatically"),
                    subtitle: L10n.string(
                        "tvos_settings_plugins_auto_update_subtitle",
                        fallback: "Download new versions of the repositories at most once a day, when Nuvio starts"
                    ),
                    isOn: Binding(
                        get: { store.autoUpdates },
                        set: { store.setAutoUpdates($0) }
                    ),
                    accentColor: accentColor
                )

                SettingsActionRow(
                    title: L10n.string("tvos_settings_plugins_web_setup", fallback: "Set Up from a Computer"),
                    subtitle: L10n.string(
                        "tvos_settings_plugins_web_setup_subtitle",
                        fallback: "Add repositories, enter API keys, test providers and read their logs in a browser on the same network"
                    ),
                    value: L10n.string("tvos_settings_plugins_web_setup_action", fallback: "Open"),
                    accentColor: accentColor
                ) {
                    showingWebSetup = true
                }
            }

            ForEach(Array(store.state.repositories.enumerated()), id: \.element.id) { index, repository in
                SettingsGroup(title: repository.name, subtitle: subtitle(for: repository)) {
                    HStack(spacing: 14) {
                        SettingsActionRow(
                            title: L10n.string("tvos_settings_plugin_update", fallback: "Update Repository"),
                            subtitle: repository.manifestURL,
                            value: store.refreshing.contains(repository.manifestURL)
                                ? L10n.string("tvos_settings_plugin_updating", fallback: "Updating…")
                                : L10n.string("tvos_settings_plugin_update_action", fallback: "Update"),
                            accentColor: accentColor
                        ) {
                            Task { await store.refreshRepository(repository.manifestURL) }
                        }
                        AddonReorderButton(systemImage: "trash", disabled: false) {
                            store.removeRepository(repository.manifestURL)
                        }
                        AddonReorderButton(systemImage: "chevron.up", disabled: index == 0) {
                            store.moveRepository(repository.manifestURL, up: true)
                        }
                        AddonReorderButton(
                            systemImage: "chevron.down",
                            disabled: index == store.state.repositories.count - 1
                        ) {
                            store.moveRepository(repository.manifestURL, up: false)
                        }
                    }

                    SettingsToggleRow(
                        title: L10n.string("tvos_settings_plugin_developer_mode", fallback: "Developer Mode"),
                        subtitle: L10n.string(
                            "tvos_settings_plugin_developer_mode_subtitle",
                            fallback: "Download the providers' code again before every search, so changes show without updating the repository"
                        ),
                        isOn: Binding(
                            get: { repository.alwaysReload == true },
                            set: { store.setAlwaysReload(repository.manifestURL, enabled: $0) }
                        ),
                        accentColor: accentColor
                    )

                    ForEach(store.state.scrapers.filter { $0.repositoryURL == repository.manifestURL }) { scraper in
                        PluginScraperSettingsRow(
                            scraper: scraper,
                            accentColor: accentColor,
                            onToggle: { store.setScraperEnabled(scraper.id, enabled: !scraper.enabled) },
                            onSettings: { settingsScraper = scraper },
                            onTest: { testScraper = scraper },
                            onLogs: { logScraper = scraper }
                        )
                    }
                }
            }
        }
        .onAppear { store.ensureLoaded() }
        .sheet(item: $settingsScraper) { scraper in
            PluginScraperSettingsSheet(scraper: scraper, accentColor: accentColor)
                .modifier(ClearPresentationBackgroundIfAvailable())
        }
        .sheet(item: $logScraper) { scraper in
            PluginLogSheet(scraper: scraper, accentColor: accentColor)
                .modifier(ClearPresentationBackgroundIfAvailable())
        }
        .sheet(item: $testScraper) { scraper in
            PluginTestSheet(scraper: scraper, accentColor: accentColor)
                .modifier(ClearPresentationBackgroundIfAvailable())
        }
        .sheet(isPresented: $showingWebSetup) {
            PluginWebSetupSheet(accentColor: accentColor)
                .modifier(ClearPresentationBackgroundIfAvailable())
        }
    }

    private func subtitle(for repository: PluginRepositoryRecord) -> String {
        var parts: [String] = []
        if let version = repository.version, !version.isEmpty { parts.append("v\(version)") }
        if let author = repository.author, !author.isEmpty { parts.append(author) }
        parts.append(settingsCountSummary(repository.scraperCount, singular: "provider", plural: "providers"))
        var text = parts.joined(separator: " · ")
        if let description = repository.description, !description.isEmpty { text += "\n" + description }
        if let error = repository.errorMessage, !error.isEmpty { text += "\n⚠︎ " + error }
        return text
    }

    private func addRepository() {
        let input = manifestURLInput.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !input.isEmpty, !isAdding else { return }
        isAdding = true
        addStatus = L10n.string("tvos_settings_plugin_adding", fallback: "Adding…")
        Task { @MainActor in
            defer { isAdding = false }
            do {
                let repository = try await store.addRepository(input)
                manifestURLInput = ""
                addFailed = false
                addStatus = L10n.format(
                    "tvos_settings_plugin_added",
                    fallback: "Added %@",
                    repository.name
                )
            } catch is CancellationError {
                addStatus = nil
            } catch {
                addFailed = true
                addStatus = "✕ " + error.localizedDescription
            }
        }
    }
}

private struct PluginScraperSettingsRow: View {
    let scraper: PluginScraperRecord
    let accentColor: Color
    let onToggle: () -> Void
    let onSettings: () -> Void
    let onTest: () -> Void
    let onLogs: () -> Void

    @FocusState private var isFocused: Bool

    private var isActive: Bool { scraper.enabled && scraper.manifestEnabled }

    var body: some View {
        HStack(spacing: 14) {
            Button(action: onToggle) {
                SettingsRowShell(isFocused: isFocused, accentColor: accentColor) {
                    artwork

                    VStack(alignment: .leading, spacing: 4) {
                        HStack(spacing: 8) {
                            Text(scraper.name)
                                .font(.system(size: 22, weight: .semibold))
                                .foregroundColor(isActive ? .white : .white.opacity(0.46))
                                .lineLimit(1)
                            Text("v\(scraper.version)")
                                .font(.system(size: 15, weight: .medium))
                                .foregroundColor(.white.opacity(0.4))
                        }
                        Text(details)
                            .font(.system(size: 16, weight: .medium))
                            .foregroundColor(.white.opacity(isActive ? 0.56 : 0.36))
                            .lineLimit(2)
                    }

                    Spacer(minLength: 20)

                    Text(isActive
                         ? L10n.string("settings_fusion_badge_url_active", fallback: "Active")
                         : L10n.string("tvos_settings_disabled", fallback: "Disabled"))
                        .font(.system(size: 18, weight: .bold))
                        .foregroundColor(isActive ? .white.opacity(0.7) : .white.opacity(0.42))
                        .lineLimit(1)
                }
            }
            .buttonStyle(PosterCardButtonStyle())
            .focused($isFocused)
            .focusEffectDisabledIfAvailable()
            .entryLockable()
            .disabled(!scraper.manifestEnabled)

            AddonReorderButton(systemImage: "gearshape", disabled: false, action: onSettings)
            AddonReorderButton(systemImage: "play.circle", disabled: false, action: onTest)
            AddonReorderButton(systemImage: "doc.text.magnifyingglass", disabled: false, action: onLogs)
        }
    }

    private var details: String {
        var parts: [String] = []
        let offers = PluginResourceNames.summary(scraper)
        if !offers.isEmpty { parts.append(offers) }
        let types = scraper.supportedTypes.map { $0 == "tv" ? "Series" : $0.capitalized }
        if !types.isEmpty { parts.append(types.joined(separator: ", ")) }
        if !scraper.contentLanguage.isEmpty { parts.append(scraper.contentLanguage.joined(separator: ", ").uppercased()) }
        if !scraper.description.isEmpty { parts.append(scraper.description) }
        if scraper.uploadedCode == true {
            parts.append(L10n.string("tvos_settings_plugin_uploaded_code", fallback: "Uploaded code"))
        }
        if scraper.throughAIO == true {
            parts.insert("Through AIOStreams", at: 0)
        }
        return parts.joined(separator: " · ")
    }

    private var artwork: some View {
        Group {
            if let logo = scraper.logo, let url = URL(string: logo) {
                AsyncImage(url: url) { phase in
                    if let image = phase.image {
                        image.resizable().aspectRatio(contentMode: .fit)
                    } else {
                        fallbackGlyph
                    }
                }
            } else {
                fallbackGlyph
            }
        }
        .frame(width: 48, height: 48)
        .opacity(isActive ? 1 : 0.42)
    }

    private var fallbackGlyph: some View {
        Image(systemName: "puzzlepiece.extension")
            .font(.system(size: 26))
            .foregroundColor(isActive ? accentColor : .white.opacity(0.38))
    }
}

/// A provider's own settings, built from the form its `onSettings()` returns
/// (text and password fields, choices, switches and notes, as on Android).
private struct PluginScraperSettingsSheet: View {
    let scraper: PluginScraperRecord
    let accentColor: Color

    @Environment(\.dismiss) private var dismiss
    @ObservedObject private var store = PluginStore.shared
    @State private var fields: [PluginSettingField] = []
    @State private var texts: [String: String] = [:]
    @State private var toggles: [String: Bool] = [:]
    @State private var isLoading = true
    @State private var loadError: String?
    @State private var canVerify = false
    @State private var status: String?
    @State private var isWorking = false

    var body: some View {
        SettingsFeatureSettingsSheet(
            title: scraper.name,
            subtitle: L10n.string(
                "tvos_settings_plugin_settings_subtitle",
                fallback: "Saved on this Apple TV only, for the active profile"
            )
        ) {
            VStack(alignment: .leading, spacing: 18) {
                // The plugin as an add-on in AIOStreams (PluginAIOBridge).
                SettingsToggleRow(
                    title: "Through AIOStreams",
                    subtitle: "In AIOStreams' list with your other add-ons (add the \"Nuvio plugins\" card on its configuration page), and only there while AIOStreams runs: its streams, subtitles, catalogs and details are not shown here as well. Results come when it has finished. Its ratings stay here.",
                    isOn: Binding(
                        get: { store.state.scrapers.first { $0.id == scraper.id }?.throughAIO == true },
                        set: { store.setScraperThroughAIO(scraper.id, enabled: $0) }
                    ),
                    accentColor: accentColor
                )

                if isLoading {
                    SettingsInfoRow(
                        title: L10n.string("tvos_settings_plugin_settings_loading", fallback: "Loading the provider's settings…"),
                        value: ""
                    )
                } else if let loadError {
                    SettingsInfoRow(title: L10n.string("tvos_settings_plugin_settings_error", fallback: "Settings unavailable"), value: loadError, isDiagnostic: true)
                } else if fields.isEmpty {
                    SettingsInfoRow(
                        title: L10n.string("tvos_settings_plugin_settings_none", fallback: "This provider has no settings."),
                        value: ""
                    )
                } else {
                    ForEach(fields) { field in
                        fieldRow(field)
                    }

                    SettingsActionRow(
                        title: L10n.string("tvos_settings_plugin_settings_save", fallback: "Save"),
                        subtitle: status ?? L10n.string(
                            "tvos_settings_plugin_settings_save_subtitle",
                            fallback: "The provider uses the new values on its next search"
                        ),
                        value: isWorking ? "…" : L10n.string("tvos_settings_plugin_settings_save_action", fallback: "Save"),
                        accentColor: accentColor,
                        action: save
                    )

                    if canVerify {
                        SettingsActionRow(
                            title: L10n.string("tvos_settings_plugin_settings_verify", fallback: "Verify"),
                            subtitle: L10n.string(
                                "tvos_settings_plugin_settings_verify_subtitle",
                                fallback: "Let the provider check these values (keys, addresses) before you save"
                            ),
                            value: isWorking ? "…" : L10n.string("tvos_settings_plugin_settings_verify_action", fallback: "Verify"),
                            accentColor: accentColor,
                            action: verify
                        )
                    }
                }
            }
            .settingsEntryAnchor()
        }
        .task { await load() }
    }

    @ViewBuilder
    private func fieldRow(_ field: PluginSettingField) -> some View {
        switch field.kind {
        case .text(let isPassword, let placeholder):
            SettingsTextFieldRow(
                title: field.label,
                subtitle: field.description ?? "",
                placeholder: placeholder ?? L10n.string("debrid_not_set", fallback: "Not set"),
                text: Binding(
                    get: { texts[field.key] ?? "" },
                    set: { texts[field.key] = $0 }
                ),
                isSecure: isPassword,
                fieldWidth: 420
            )
        case .select(let options):
            SettingsChoiceRow(
                title: field.label,
                subtitle: field.description ?? "",
                selection: Binding(
                    get: { texts[field.key] ?? options.first?.value ?? "" },
                    set: { texts[field.key] = $0 }
                ),
                options: options.map(\.value),
                optionLabels: Dictionary(options.map { ($0.value, $0.label) }, uniquingKeysWith: { first, _ in first }),
                accentColor: accentColor
            )
        case .toggle:
            SettingsToggleRow(
                title: field.label,
                subtitle: field.description ?? "",
                isOn: Binding(
                    get: { toggles[field.key] ?? false },
                    set: { toggles[field.key] = $0 }
                ),
                accentColor: accentColor
            )
        case .info:
            VStack(alignment: .leading, spacing: 6) {
                if !field.label.isEmpty {
                    Text(field.label)
                        .font(.system(size: 21, weight: .semibold))
                        .foregroundColor(.white)
                }
                if let description = field.description, !description.isEmpty {
                    Text(description)
                        .font(.system(size: 18, weight: .medium))
                        .foregroundColor(.white.opacity(0.6))
                        .fixedSize(horizontal: false, vertical: true)
                }
            }
            .padding(.horizontal, 20)
            .frame(maxWidth: .infinity, alignment: .leading)
        }
    }

    private func load() async {
        isLoading = true
        let saved = PluginSettingsVault.settings(scraperID: scraper.id)
        do {
            let layout = try await PluginSettingsService.layout(for: scraper)
            var nextTexts: [String: String] = [:]
            var nextToggles: [String: Bool] = [:]
            for field in layout where !field.key.isEmpty {
                let value = saved[field.key]
                switch field.kind {
                case .toggle:
                    nextToggles[field.key] = (value as? Bool) ?? field.defaultBool ?? false
                case .text, .select:
                    nextTexts[field.key] = value.flatMap(PluginJSON.text) ?? field.defaultText ?? ""
                case .info:
                    break
                }
            }
            fields = layout
            texts = nextTexts
            toggles = nextToggles
            if let code = await PluginStore.shared.code(for: scraper) {
                canVerify = PluginSettingsService.hasVerify(code: code)
            }
            loadError = nil
        } catch {
            loadError = error.localizedDescription
        }
        isLoading = false
    }

    private var currentValues: [String: Any] {
        var values = PluginSettingsVault.settings(scraperID: scraper.id)
        for field in fields where !field.key.isEmpty {
            switch field.kind {
            case .toggle:
                values[field.key] = toggles[field.key] ?? false
            case .text, .select:
                values[field.key] = (texts[field.key] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
            case .info:
                break
            }
        }
        return values
    }

    private func save() {
        guard !isWorking else { return }
        if PluginSettingsVault.save(currentValues, scraperID: scraper.id) {
            status = "✓ " + L10n.string("tvos_settings_plugin_settings_saved", fallback: "Saved")
            dismiss()
        } else {
            status = "✕ " + L10n.string("tvos_settings_plugin_settings_save_failed", fallback: "The settings could not be saved")
        }
    }

    private func verify() {
        guard !isWorking else { return }
        isWorking = true
        status = L10n.string("tvos_settings_plugin_settings_verifying", fallback: "Checking…")
        let values = currentValues
        Task { @MainActor in
            let result = await PluginSettingsService.verify(scraper: scraper, settings: values)
            isWorking = false
            if let result {
                status = (result.ok ? "✓ " : "✕ ") + result.message
            } else {
                status = L10n.string("tvos_settings_plugin_settings_no_verify", fallback: "This provider cannot check its settings")
            }
        }
    }
}

/// The provider's recent console output, to see why it found nothing.
private struct PluginLogSheet: View {
    let scraper: PluginScraperRecord
    let accentColor: Color

    @State private var entries: [PluginLogEntry] = []

    private static let timeFormatter: DateFormatter = {
        let formatter = DateFormatter()
        formatter.dateFormat = "HH:mm:ss"
        return formatter
    }()

    var body: some View {
        SettingsFeatureSettingsSheet(
            title: L10n.format("tvos_settings_plugin_logs_title", fallback: "%@ Logs", scraper.name),
            subtitle: L10n.string(
                "tvos_settings_plugin_logs_subtitle",
                fallback: "The newest lines the provider wrote with console.log, its requests (blue, keys hidden) and how long each call took, on this Apple TV since the app started"
            )
        ) {
            VStack(alignment: .leading, spacing: 12) {
                HStack(spacing: 14) {
                    SettingsActionRow(
                        title: L10n.string("tvos_settings_plugin_logs_refresh", fallback: "Refresh"),
                        subtitle: settingsCountSummary(entries.count, singular: "line", plural: "lines"),
                        value: L10n.string("tvos_settings_plugin_logs_refresh_action", fallback: "Refresh"),
                        accentColor: accentColor
                    ) {
                        entries = PluginLogStore.shared.entries(for: scraper.id)
                    }
                    AddonReorderButton(systemImage: "trash", disabled: entries.isEmpty) {
                        PluginLogStore.shared.clear(scraper.id)
                        entries = []
                    }
                }

                ForEach(entries.reversed()) { entry in
                    PluginLogLine(entry: entry, time: Self.timeFormatter.string(from: entry.date))
                }
            }
            .settingsEntryAnchor()
        }
        .onAppear { entries = PluginLogStore.shared.entries(for: scraper.id) }
    }
}

private struct PluginLogLine: View {
    let entry: PluginLogEntry
    let time: String

    @FocusState private var isFocused: Bool

    var body: some View {
        HStack(alignment: .firstTextBaseline, spacing: 14) {
            Text(time)
                .font(.system(size: 15, weight: .medium, design: .monospaced))
                .foregroundColor(.white.opacity(0.45))
            Text(entry.message)
                .font(.system(size: 16, weight: .regular, design: .monospaced))
                .foregroundColor(color)
                .fixedSize(horizontal: false, vertical: true)
                .frame(maxWidth: .infinity, alignment: .leading)
        }
        .padding(.horizontal, 16)
        .padding(.vertical, 8)
        .background(
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .fill(Color.white.opacity(isFocused ? 0.16 : 0.05))
        )
        .focusable(true)
        .focused($isFocused)
    }

    private var color: Color {
        switch entry.level {
        case .error: return Color(red: 1, green: 0.55, blue: 0.5)
        case .warn: return Color(red: 1, green: 0.82, blue: 0.45)
        case .net: return Color(red: 0.55, green: 0.78, blue: 1).opacity(0.85)
        default: return .white.opacity(0.85)
        }
    }
}

/// "Test" next to a provider: one stream search for a sample movie or
/// episode, with what came back and what the provider logged meanwhile.
private struct PluginTestSheet: View {
    let scraper: PluginScraperRecord
    let accentColor: Color

    @State private var running: PluginTester.Sample?
    @State private var report: PluginTester.Report?

    private static let timeFormatter: DateFormatter = {
        let formatter = DateFormatter()
        formatter.dateFormat = "HH:mm:ss"
        return formatter
    }()

    var body: some View {
        SettingsFeatureSettingsSheet(
            title: L10n.format("tvos_settings_plugin_test_title", fallback: "Test %@", scraper.name),
            subtitle: L10n.string(
                "tvos_settings_plugin_test_subtitle",
                fallback: "Asks the provider for everything it offers (streams, subtitles, catalogs, metadata, ratings) for a sample title, with its current settings"
            )
        ) {
            VStack(alignment: .leading, spacing: 14) {
                if scraper.supportedTypes.isEmpty || scraper.supportedTypes.contains("movie") {
                    sampleRow(
                        .movie,
                        title: L10n.string("tvos_settings_plugin_test_movie", fallback: "Movie"),
