/// "Set Up from a Computer": runs `PluginWebServer` while open and shows its
/// address as a QR code and as text.
private struct PluginWebSetupSheet: View {
    let accentColor: Color

    @Environment(\.dismiss) private var dismiss
    @ObservedObject private var server = PluginWebServer.shared

    private static let timeFormatter: DateFormatter = {
        let formatter = DateFormatter()
        formatter.timeStyle = .short
        formatter.dateStyle = .none
        return formatter
    }()

    var body: some View {
        SettingsFeatureSettingsSheet(
            title: L10n.string("tvos_settings_plugins_web_setup", fallback: "Set Up from a Computer"),
            subtitle: L10n.string(
                "tvos_settings_plugins_web_setup_sheet_subtitle",
                fallback: "Open this address in a browser on a computer or phone connected to the same network as this Apple TV"
            )
        ) {
            VStack(alignment: .leading, spacing: 26) {
                HStack(alignment: .center, spacing: 40) {
                    qrCode

                    VStack(alignment: .leading, spacing: 14) {
                        Text(address)
                            .font(.system(size: 30, weight: .bold, design: .monospaced))
                            .foregroundColor(.white)
                            .lineLimit(2)
                            .minimumScaleFactor(0.6)
                        Text(status)
                            .font(.system(size: 20, weight: .semibold))
                            .foregroundColor(statusColor)
                            .fixedSize(horizontal: false, vertical: true)
                        Text(L10n.string(
                            "tvos_settings_plugins_web_setup_note",
                            fallback: "Keep this screen open while you use the page. It stops when you close this screen or after 15 minutes without use. Saved passwords and keys are never shown in full."
                        ))
                        .font(.system(size: 17, weight: .medium))
                        .foregroundColor(.white.opacity(0.55))
                        .fixedSize(horizontal: false, vertical: true)
                    }
                }

                SettingsToggleRow(
                    title: L10n.string("tvos_settings_plugins_web_setup_keep", fallback: "Keep the Same Address"),
                    subtitle: L10n.string(
                        "tvos_settings_plugins_web_setup_keep_subtitle",
                        fallback: "The address stays the same after restarts, so you can bookmark it. Give the Apple TV a fixed IP address in your router so that part doesn't change either."
                    ),
                    isOn: Binding(
                        get: { server.keepsAddress },
                        set: { server.setKeepsAddress($0) }
                    ),
                    accentColor: accentColor
                )

                if server.keepsAddress {
                    SettingsActionRow(
                        title: L10n.string("tvos_settings_plugins_web_setup_new_address", fallback: "New Address"),
                        subtitle: L10n.string(
                            "tvos_settings_plugins_web_setup_new_address_subtitle",
                            fallback: "Make a new code in the address, for example when someone else knows this one"
                        ),
                        value: L10n.string("tvos_settings_plugins_web_setup_new_address_action", fallback: "Change"),
                        accentColor: accentColor
                    ) {
                        server.makeNewAddress()
                    }
                }

                if canRestart {
                    SettingsActionRow(
                        title: L10n.string("tvos_settings_plugins_web_setup_retry", fallback: "Try Again"),
                        subtitle: L10n.string(
                            "tvos_settings_plugins_web_setup_retry_subtitle",
                            fallback: "Start the page again"
                        ),
                        value: L10n.string("tvos_settings_plugins_web_setup_retry_action", fallback: "Start"),
                        accentColor: accentColor
                    ) {
                        server.start()
                    }
                }

                SettingsActionRow(
                    title: L10n.string("tvos_settings_plugins_web_setup_done", fallback: "Done"),
                    subtitle: L10n.string(
                        "tvos_settings_plugins_web_setup_done_subtitle",
                        fallback: "Stop the page and go back to Plugins"
                    ),
                    value: L10n.string("tvos_settings_plugins_web_setup_done_action", fallback: "Close"),
                    accentColor: accentColor
                ) {
                    dismiss()
                }
            }
            .settingsEntryAnchor()
        }
        .onAppear { server.start() }
        .onDisappear { server.stop() }
    }

    @ViewBuilder
    private var qrCode: some View {
        if case .ready(let url) = server.phase, let image = SettingsQRCode.image(for: url.absoluteString) {
            Image(decorative: image, scale: 1, orientation: .up)
                .interpolation(.none)
                .resizable()
                .frame(width: 240, height: 240)
                .padding(14)
                .background(Color.white, in: RoundedRectangle(cornerRadius: 18, style: .continuous))
        } else {
            RoundedRectangle(cornerRadius: 18, style: .continuous)
                .fill(Color.white.opacity(0.08))
                .frame(width: 268, height: 268)
                .overlay(ProgressView().opacity(server.phase == .starting ? 1 : 0))
        }
    }

    private var canRestart: Bool {
        switch server.phase {
        case .failed, .stopped: return true
        case .starting, .ready: return false
        }
    }

    private var address: String {
        switch server.phase {
        case .ready(let url): return url.absoluteString
        case .starting: return L10n.string("tvos_settings_plugins_web_setup_starting", fallback: "Starting…")
        case .failed, .stopped: return "—"
        }
    }

    private var status: String {
        switch server.phase {
        case .ready:
            if let lastActivity = server.lastActivity {
                return L10n.format(
                    "tvos_settings_plugins_web_setup_connected",
                    fallback: "✓ A browser used the page at %@",
                    Self.timeFormatter.string(from: lastActivity)
                )
            }
            return L10n.string("tvos_settings_plugins_web_setup_waiting", fallback: "Waiting for a browser…")
        case .starting:
            return ""
        case .failed(let message):
            return "✕ " + message
        case .stopped:
            return L10n.string("tvos_settings_plugins_web_setup_stopped", fallback: "The page has stopped.")
        }
    }

    private var statusColor: Color {
        switch server.phase {
        case .failed: return Color(red: 1, green: 0.55, blue: 0.5)
        case .ready where server.lastActivity != nil: return Color(red: 0.45, green: 0.85, blue: 0.55)
        default: return .white.opacity(0.7)
        }
    }
}

// MARK: - Home catalog reordering

private enum HomeCatalogOrderFocus: Hashable {
    case refresh
    case row(String)
}

/// Settings → Layout → Home Catalogs: reorder the rows Home shows. The list
/// comes from the snapshot Home writes on every load; moves persist to the
/// active profile's settings and re-apply to a mounted Home immediately.
@MainActor
private struct HomeCatalogOrderSection: View {
    let accentColor: Color
    @AppStorage(SettingsKey.catalogAutoRefreshInterval) private var catalogAutoRefreshInterval = "30 Minutes"
    private let catalogAutoRefreshOptions = ["Disabled", "15 Minutes", "30 Minutes", "1 Hour", "Always"]
    @State private var rows: [TVHomeCatalogOrder.SnapshotRow] = []
    @FocusState private var focusedControl: HomeCatalogOrderFocus?
    @State private var deletionFocusRequest: DeletionFocusRequest?

    private struct DeletionFocusRequest: Equatable {
        let target: HomeCatalogOrderFocus
        let profileID: String?
    }

    /// Enabled state per row, read once on appear and updated by the taps here.
    /// Kept beside `rows` rather than re-read per redraw: each read decodes two
    /// JSON blobs out of the profile's settings.
    @State private var enabledByRowId: [String: Bool] = [:]

    var body: some View {
        SettingsGroup(title: L10n.string("tvos_settings_home_catalogs", fallback: "Home Catalogs"), subtitle: L10n.string("tvos_settings_controls_catalog_and_collection_row_orde_b7069193", fallback: "Controls catalog and collection row order on Home")) {
            SettingsActionRow(
                title: L10n.string("settings_refresh_all_catalogs_now", fallback: "Refresh All Catalogs"),
                subtitle: L10n.string("settings_refresh_all_catalogs_subtitle", fallback: "Reload fresh items from all add-ons now"),
                value: L10n.string("settings_refresh_action", fallback: "Refresh"),
                accentColor: accentColor
            ) {
                NotificationCenter.default.post(name: TVHomeCatalogOrder.forceRefreshNotification, object: nil)
            }
            .focused($focusedControl, equals: .refresh)

            SettingsOptionRow(
                title: L10n.string("settings_catalog_auto_refresh", fallback: "Auto-Refresh Catalogs"),
                subtitle: L10n.string("settings_catalog_auto_refresh_subtitle", fallback: "Reload catalogs after inactivity when returning to Home"),
                selection: $catalogAutoRefreshInterval,
                options: catalogAutoRefreshOptions,
                accentColor: accentColor
            )

            if rows.isEmpty {
                SettingsInfoRow(title: L10n.string("tvos_settings_no_rows_recorded_yet", fallback: "No rows recorded yet"), value: L10n.string("tvos_settings_open_home_once", fallback: "Open Home once"))
            } else {
                ForEach(Array(rows.enumerated()), id: \.element.id) { index, row in
                    HomeCatalogOrderRow(
                        rowID: row.id,
                        focus: $focusedControl,
                        title: row.title,
                        addonName: row.addonName,
                        isEnabled: enabledByRowId[row.id] ?? true,
                        canToggle: row.settingsKey != nil,
                        accentColor: accentColor,
                        canMoveUp: index > 0,
                        canMoveDown: index < rows.count - 1,
                        canDelete: row.settingsKey != nil,
                        onToggle: { setEnabled(row, isEnabled: !(enabledByRowId[row.id] ?? true)) },
                        onDelete: row.settingsKey != nil ? { deleteRow(row) } : nil,
                        onMove: { up in move(index, up: up) }
                    )
                }
            }
        }
        .onAppear(perform: reload)
        .onDisappear { deletionFocusRequest = nil }
        .task(id: deletionFocusRequest) {
            guard let request = deletionFocusRequest else { return }
            // Let SwiftUI remove the deleted button and bind the surviving row
            // before handing focus back to the list.
            await Task.yield()
            guard !Task.isCancelled else { return }
            guard ProfileSettings.activeProfileID == request.profileID else {
                deletionFocusRequest = nil
                return
            }
            if case .row(let id) = request.target,
               !rows.contains(where: { $0.id == id && $0.settingsKey != nil }) {
                focusedControl = .refresh
            } else {
                focusedControl = request.target
            }
            deletionFocusRequest = nil
        }
        .onReceive(NotificationCenter.default.publisher(for: NuvioSyncManager.addonOrderChangedNotification).receive(on: RunLoop.main)) { _ in
            reload()
        }
        .onReceive(NotificationCenter.default.publisher(for: NuvioSyncManager.homeContentSyncedNotification).receive(on: RunLoop.main)) { _ in
            reload()
        }
        .onReceive(NotificationCenter.default.publisher(for: TVHomeCatalogOrder.changedNotification).receive(on: RunLoop.main)) { _ in
            reload()
        }
        .onReceive(NotificationCenter.default.publisher(for: TVHomeCatalogOrder.snapshotChangedNotification).receive(on: RunLoop.main)) { _ in
            reload()
        }
    }

    private func reload() {
        rows = layoutVisibleHomeCatalogRows()
        let visibility = TVHomeCatalogOrder.homeVisibilityContext()
        enabledByRowId = Dictionary(
            uniqueKeysWithValues: rows.map { ($0.id, TVHomeCatalogOrder.isRowEnabled($0, context: visibility)) }
        )
    }

    private func setEnabled(_ row: TVHomeCatalogOrder.SnapshotRow, isEnabled: Bool) {
        guard row.settingsKey != nil else { return }
        enabledByRowId[row.id] = isEnabled
        TVHomeCatalogOrder.setRowEnabled(row, isEnabled: isEnabled)
        // Home keys its load on this revision, so the row leaves (or comes back
        // to) the mounted Home instead of waiting for the next launch.
        NuvioSyncManager.current?.noteHomeCatalogSettingsChangedLocally()
    }

    private func deleteRow(_ row: TVHomeCatalogOrder.SnapshotRow) {
        guard row.settingsKey != nil,
              let index = rows.firstIndex(where: { $0.id == row.id }) else { return }
        let neighbor = rows.dropFirst(index + 1).first(where: { $0.settingsKey != nil })
            ?? rows.prefix(index).last(where: { $0.settingsKey != nil })
        let request = DeletionFocusRequest(
            target: neighbor.map { .row($0.id) } ?? .refresh,
            profileID: ProfileSettings.activeProfileID
        )
        rows.removeAll { $0.id == row.id }
        enabledByRowId.removeValue(forKey: row.id)
        TVHomeCatalogOrder.deleteRow(row)
        NuvioSyncManager.current?.noteHomeCatalogSettingsChangedLocally()
        deletionFocusRequest = request
    }

    private func move(_ index: Int, up: Bool) {
        let target = up ? index - 1 : index + 1
        guard rows.indices.contains(index), rows.indices.contains(target) else { return }
        rows.swapAt(index, target)
        TVHomeCatalogOrder.save(rows.map(\.id))
        TVHomeCatalogOrder.writeSnapshotRows(rows)
        NuvioSyncManager.current?.noteHomeCatalogSettingsChangedLocally()
    }
}

private struct HomeCatalogOrderRow: View {
    let rowID: String
    let focus: FocusState<HomeCatalogOrderFocus?>.Binding
    let title: String
    let addonName: String?
    let isEnabled: Bool
    /// False for a row that is not a catalog (Continue Watching): it stays put
    /// and reads "Always on" rather than offering a toggle that does nothing.
    let canToggle: Bool
    let accentColor: Color
    let canMoveUp: Bool
    let canMoveDown: Bool
    var canDelete: Bool = true
    let onToggle: () -> Void
    var onDelete: (() -> Void)? = nil
    let onMove: (Bool) -> Void

    private var isFocused: Bool { focus.wrappedValue == .row(rowID) }

    var body: some View {
        HStack(spacing: 14) {
            Button(action: onToggle) {
                SettingsRowShell(isFocused: isFocused, accentColor: accentColor) {
                    VStack(alignment: .leading, spacing: 4) {
                        Text(title)
                            .font(.system(size: 22, weight: .semibold))
                            .foregroundColor(isEnabled ? .white : .white.opacity(0.46))
                            .lineLimit(1)
                        if let addonName, !addonName.isEmpty {
                            Text(addonName)
                                .font(.system(size: 16, weight: .medium))
                                .foregroundColor(.white.opacity(isEnabled ? 0.56 : 0.36))
                                .lineLimit(1)
                        }
                    }

                    Spacer(minLength: 20)

                    Text(statusText)
                        .font(.system(size: 18, weight: .bold))
                        .foregroundColor(statusColor)
                        .lineLimit(1)
                }
            }
            .buttonStyle(PosterCardButtonStyle())
            .disabled(!canToggle)
            .focused(focus, equals: .row(rowID))
            .focusEffectDisabledIfAvailable()
            .entryLockable()

            if let onDelete {
                AddonReorderButton(systemImage: "trash", disabled: !canDelete, action: onDelete)
            }
            AddonReorderButton(systemImage: "chevron.up", disabled: !canMoveUp) { onMove(true) }
            AddonReorderButton(systemImage: "chevron.down", disabled: !canMoveDown) { onMove(false) }
        }
    }

    private var statusText: String {
        guard canToggle else {
            return L10n.string("tvos_settings_row_always_on", fallback: "Always on")
        }
        return isEnabled
            ? L10n.string("settings_fusion_badge_url_active", fallback: "Active")
            : L10n.string("tvos_settings_disabled", fallback: "Disabled")
    }

    private var statusColor: Color {
        guard canToggle else { return .white.opacity(0.42) }
        return isEnabled ? .white.opacity(0.7) : .white.opacity(0.42)
    }
}

// MARK: - Details Sections manager

@MainActor
private struct DetailsSectionsOrderSection: View {
    let accentColor: Color
    @State private var sections: [TVDetailsSection] = []
    @State private var disabledSections: Set<TVDetailsSection> = []
    @FocusState private var focusedControl: DetailsSectionOrderFocus?

    enum DetailsSectionOrderFocus: Hashable {
        case reset
        case section(String)
    }

    var body: some View {
        SettingsGroup(
            title: L10n.string("tvos_settings_details_sections", fallback: "Details Sections"),
            subtitle: L10n.string("tvos_settings_details_sections_sheet_subtitle", fallback: "Reorder and toggle sections on Details screens")
        ) {
            SettingsActionRow(
                title: L10n.string("action_reset", fallback: "Reset"),
                subtitle: L10n.string("tvos_settings_reset_details_sections_subtitle", fallback: "Restore the default Details page section order and visibility"),
                value: L10n.string("action_reset", fallback: "Reset"),
                accentColor: accentColor
            ) {
                reset()
            }
            .focused($focusedControl, equals: .reset)

            ForEach(Array(sections.enumerated()), id: \.element.id) { index, section in
                DetailsSectionOrderRow(
                    section: section,
                    focus: $focusedControl,
                    isEnabled: !disabledSections.contains(section),
                    accentColor: accentColor,
                    canMoveUp: index > 0,
                    canMoveDown: index < sections.count - 1,
                    onToggle: {
                        toggleSection(section)
                    },
                    onMove: { up in
                        move(index, up: up)
                    }
                )
            }
        }
        .onAppear(perform: reload)
        .onReceive(NotificationCenter.default.publisher(for: TVDetailsSectionOrder.changedNotification).receive(on: RunLoop.main)) { _ in
            reload()
        }
    }

    private func reload() {
        sections = TVDetailsSectionOrder.currentOrder()
        disabledSections = TVDetailsSectionOrder.disabledSections()
    }

    private func toggleSection(_ section: TVDetailsSection) {
        let isCurrentlyEnabled = !disabledSections.contains(section)
        TVDetailsSectionOrder.setSectionEnabled(section, isEnabled: !isCurrentlyEnabled)
        disabledSections = TVDetailsSectionOrder.disabledSections()
    }

    private func move(_ index: Int, up: Bool) {
        let target = up ? index - 1 : index + 1
        guard sections.indices.contains(index), sections.indices.contains(target) else { return }
        sections.swapAt(index, target)
        TVDetailsSectionOrder.saveOrder(sections)
    }

    private func reset() {
        TVDetailsSectionOrder.resetToDefaults()
        reload()
    }
}

