        (nil, "Any"),
        (50, "50+"),
        (100, "100+"),
        (500, "500+"),
        (1000, "1,000+")
    ]

    private let datePresets: [(label: String, from: String, to: String)] = [
        ("Any", "", ""),
        ("2020s", "2020-01-01", ""),
        ("2010s", "2010-01-01", "2019-12-31"),
        ("2000s", "2000-01-01", "2009-12-31"),
        ("1990s", "1990-01-01", "1999-12-31"),
        ("1980s", "1980-01-01", "1989-12-31"),
        ("Classic", "1900-01-01", "1979-12-31")
    ]

    private var currentGenres: [TmdbGenreItem] {
        mediaType == "tv" ? tvGenres : movieGenres
    }

    private var canAdd: Bool {
        !titleText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    var body: some View {
        sourceSheetChrome(
            title: isEditing
                ? L10n.string("tvos_settings_edit_tmdb_source", fallback: "Edit TMDB Source")
                : L10n.string("tvos_settings_add_tmdb_source", fallback: "Add TMDB Source"),
            subtitle: isEditing
                ? "Update filters, sort order, and release date criteria for this TMDB catalog source."
                : L10n.string("tvos_settings_attach_a_tmdb_list_collection_company_or_b80d234f", fallback: "Attach a TMDB list, collection, company, or discover query with custom filters."),
            scrollable: true
        ) {
            labeled(L10n.string("tvos_settings_source_title", fallback: "Title")) {
                SettingsSearchStyleField(text: $titleText, placeholder: L10n.string("tvos_settings_source_title", fallback: "Source title"), height: 58, fontSize: 20, horizontalPadding: 22)
            }

            labeled("Source type") {
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack(spacing: 10) {
                        ForEach(sourceTypes, id: \.self) { type in
                            CollectionChipButton(title: type.capitalized, isSelected: sourceType == type) {
                                sourceType = type
                            }
                        }
                    }
                }
            }

            if sourceType != "DISCOVER" {
                labeled("TMDB ID") {
                    SettingsSearchStyleField(text: $tmdbIdText, placeholder: L10n.string("tvos_settings_numeric_tmdb_id", fallback: "Numeric TMDB id"), height: 58, fontSize: 20, horizontalPadding: 22)
                }
            }

            labeled("Media type") {
                HStack(spacing: 12) {
                    ForEach(mediaTypes, id: \.0) { id, label in
                        CollectionChipButton(title: label, isSelected: mediaType == id) {
                            mediaType = id
                        }
                    }
                }
            }

            if sourceType == "DISCOVER" {
                labeled("Sort by") {
                    ScrollView(.horizontal, showsIndicators: false) {
                        HStack(spacing: 10) {
                            ForEach(sortOptions, id: \.id) { opt in
                                CollectionChipButton(title: opt.label, isSelected: sortBy == opt.id) {
                                    sortBy = opt.id
                                }
                            }
                        }
                        .padding(.vertical, 4)
                    }
                }

                labeled("Include Genres") {
                    ScrollView(.horizontal, showsIndicators: false) {
                        HStack(spacing: 10) {
                            ForEach(currentGenres) { genre in
                                let isSelected = includedGenres.contains(genre.id)
                                CollectionChipButton(
                                    title: genre.name,
                                    isSelected: isSelected
                                ) {
                                    if isSelected {
                                        includedGenres.remove(genre.id)
                                    } else {
                                        includedGenres.insert(genre.id)
                                        excludedGenres.remove(genre.id)
                                    }
                                }
                            }
                        }
                        .padding(.vertical, 4)
                    }
                }

                labeled("Exclude Genres") {
                    ScrollView(.horizontal, showsIndicators: false) {
                        HStack(spacing: 10) {
                            ForEach(currentGenres) { genre in
                                let isSelected = excludedGenres.contains(genre.id)
                                CollectionChipButton(
                                    title: genre.name,
                                    isSelected: isSelected
                                ) {
                                    if isSelected {
                                        excludedGenres.remove(genre.id)
                                    } else {
                                        excludedGenres.insert(genre.id)
                                        includedGenres.remove(genre.id)
                                    }
                                }
                            }
                        }
                        .padding(.vertical, 4)
                    }
                }

                labeled("Include Original Language") {
                    VStack(alignment: .leading, spacing: 10) {
                        ScrollView(.horizontal, showsIndicators: false) {
                            HStack(spacing: 10) {
                                CollectionChipButton(title: "Any", isSelected: includedLanguage.isEmpty) {
                                    includedLanguage = ""
                                }
                                ForEach(commonLanguages, id: \.code) { lang in
                                    CollectionChipButton(title: lang.label, isSelected: includedLanguage == lang.code) {
                                        includedLanguage = lang.code
                                        if excludedLanguage == lang.code {
                                            excludedLanguage = ""
                                        }
                                    }
                                }
                            }
                            .padding(.vertical, 4)
                        }
                        SettingsSearchStyleField(
                            text: $includedLanguage,
                            placeholder: "Custom ISO-639-1 language code (e.g. en, ja, fr)",
                            height: 52,
                            fontSize: 18,
                            horizontalPadding: 20
                        )
                    }
                }

                labeled("Exclude Original Language") {
                    VStack(alignment: .leading, spacing: 10) {
                        ScrollView(.horizontal, showsIndicators: false) {
                            HStack(spacing: 10) {
                                CollectionChipButton(title: "None", isSelected: excludedLanguage.isEmpty) {
                                    excludedLanguage = ""
                                }
                                ForEach(commonLanguages, id: \.code) { lang in
                                    CollectionChipButton(title: lang.label, isSelected: excludedLanguage == lang.code) {
                                        excludedLanguage = lang.code
                                        if includedLanguage == lang.code {
                                            includedLanguage = ""
                                        }
                                    }
                                }
                            }
                            .padding(.vertical, 4)
                        }
                        SettingsSearchStyleField(
                            text: $excludedLanguage,
                            placeholder: "Custom excluded ISO-639-1 code (e.g. en, ja)",
                            height: 52,
                            fontSize: 18,
                            horizontalPadding: 20
                        )
                    }
                }

                labeled("Minimum Rating") {
                    ScrollView(.horizontal, showsIndicators: false) {
                        HStack(spacing: 10) {
                            ForEach(ratingOptions, id: \.label) { opt in
                                CollectionChipButton(title: opt.label, isSelected: minRating == opt.val) {
                                    minRating = opt.val
                                }
                            }
                        }
                        .padding(.vertical, 4)
                    }
                }

                labeled("Minimum Vote Count") {
                    ScrollView(.horizontal, showsIndicators: false) {
                        HStack(spacing: 10) {
                            ForEach(voteOptions, id: \.label) { opt in
                                CollectionChipButton(title: opt.label, isSelected: minVotes == opt.val) {
                                    minVotes = opt.val
                                }
                            }
                        }
                        .padding(.vertical, 4)
                    }
                }

                labeled("Release Date Range") {
                    VStack(alignment: .leading, spacing: 10) {
                        ScrollView(.horizontal, showsIndicators: false) {
                            HStack(spacing: 10) {
                                ForEach(datePresets, id: \.label) { preset in
                                    let isSelected = (preset.from.isEmpty && preset.to.isEmpty && releaseDateFromText.isEmpty && releaseDateToText.isEmpty)
                                        || (!preset.from.isEmpty && releaseDateFromText == preset.from && (preset.to.isEmpty ? releaseDateToText.isEmpty : releaseDateToText == preset.to))
                                    CollectionChipButton(title: preset.label, isSelected: isSelected) {
                                        releaseDateFromText = preset.from
                                        releaseDateToText = preset.to
                                    }
                                }
                            }
                            .padding(.vertical, 4)
                        }
                        HStack(spacing: 14) {
                            SettingsSearchStyleField(
                                text: $releaseDateFromText,
                                placeholder: "From date (e.g. 01 January 2000 or 2000-01-01)",
                                height: 52,
                                fontSize: 18,
                                horizontalPadding: 20
                            )
                            SettingsSearchStyleField(
                                text: $releaseDateToText,
                                placeholder: "To date (e.g. 31 December 2010 or 2010-12-31)",
                                height: 52,
                                fontSize: 18,
                                horizontalPadding: 20
                            )
                        }
                    }
                }

                labeled("Release Year") {
                    SettingsSearchStyleField(
                        text: $releaseYearText,
                        placeholder: "e.g. 2024 (optional single year)",
                        height: 52,
                        fontSize: 18,
                        horizontalPadding: 20
                    )
                }

                labeled("Origin Country") {
                    SettingsSearchStyleField(
                        text: $originCountryText,
                        placeholder: "e.g. US, JP, KR, GB, FR (optional)",
                        height: 52,
                        fontSize: 18,
                        horizontalPadding: 20
                    )
                }

                labeled("Keywords (Include / Exclude IDs)") {
                    VStack(alignment: .leading, spacing: 10) {
                        SettingsSearchStyleField(
                            text: $keywordsText,
                            placeholder: "Included TMDB keyword IDs (comma-separated)",
                            height: 52,
                            fontSize: 18,
                            horizontalPadding: 20
                        )
                        SettingsSearchStyleField(
                            text: $excludedKeywordsText,
                            placeholder: "Excluded TMDB keyword IDs (comma-separated)",
                            height: 52,
                            fontSize: 18,
                            horizontalPadding: 20
                        )
                    }
                }
            }
        } footer: {
            CollectionsGlassButton(title: L10n.string("action_cancel", fallback: "Cancel"), action: { dismiss() })
            CollectionsGlassButton(
                title: isEditing ? L10n.string("action_save", fallback: "Save") : L10n.string("tvos_settings_add", fallback: "Add"),
                systemImage: isEditing ? "checkmark" : "plus",
                prominent: true,
                disabled: !canAdd,
                action: save
            )
        }
    }

    private func save() {
        let trimmedTitle = titleText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedTitle.isEmpty else { return }
        var payload: [String: Any] = [
            "provider": "tmdb",
            "tmdbSourceType": sourceType,
            "title": trimmedTitle,
            "mediaType": mediaType,
            "sortBy": sortBy
        ]
        if let id = Int(tmdbIdText.trimmingCharacters(in: .whitespacesAndNewlines)), id > 0 {
            payload["tmdbId"] = id
        }
        if sourceType == "DISCOVER" {
            var filters: [String: Any] = [:]
            if !includedGenres.isEmpty {
                let genresStr = includedGenres.sorted().joined(separator: ",")
                filters["withGenres"] = genresStr
                filters["with_genres"] = genresStr
            }
            if !excludedGenres.isEmpty {
                let genresStr = excludedGenres.sorted().joined(separator: ",")
                filters["withoutGenres"] = genresStr
                filters["without_genres"] = genresStr
            }
            let incLang = includedLanguage.trimmingCharacters(in: .whitespacesAndNewlines)
            if !incLang.isEmpty {
                filters["withOriginalLanguage"] = incLang
                filters["with_original_language"] = incLang
            }
            let excLang = excludedLanguage.trimmingCharacters(in: .whitespacesAndNewlines)
            if !excLang.isEmpty {
                filters["withoutOriginalLanguage"] = excLang
                filters["without_original_language"] = excLang
            }
            if let rating = minRating, rating > 0 {
                filters["voteAverageGte"] = rating
                filters["vote_average_gte"] = rating
            }
            if let votes = minVotes, votes > 0 {
                filters["voteCountGte"] = votes
                filters["vote_count_gte"] = votes
            }
            if let year = Int(releaseYearText.trimmingCharacters(in: .whitespacesAndNewlines)), year > 1880 {
                filters["year"] = year
            }

            let gte = TmdbDateNormalizer.normalize(releaseDateFromText, isEndDate: false)
            var lte = TmdbDateNormalizer.normalize(releaseDateToText, isEndDate: true)
            let lowerFrom = releaseDateFromText.lowercased()
            if lte == nil && (lowerFrom.contains(" to ") || releaseDateFromText.contains(" - ") || releaseDateFromText.contains(" – ")) {
                lte = TmdbDateNormalizer.normalize(releaseDateFromText, isEndDate: true)
            }
            if let gte, !gte.isEmpty {
                filters["releaseDateGte"] = gte
                filters["release_date_gte"] = gte
                filters["primary_release_date.gte"] = gte
            }
            if let lte, !lte.isEmpty {
                filters["releaseDateLte"] = lte
                filters["release_date_lte"] = lte
                filters["primary_release_date.lte"] = lte
            }

            let country = originCountryText.trimmingCharacters(in: .whitespacesAndNewlines)
            if !country.isEmpty {
                filters["withOriginCountry"] = country
                filters["with_origin_country"] = country
            }
            let kw = keywordsText.trimmingCharacters(in: .whitespacesAndNewlines)
            if !kw.isEmpty {
                filters["withKeywords"] = kw
                filters["with_keywords"] = kw
            }
            let excKw = excludedKeywordsText.trimmingCharacters(in: .whitespacesAndNewlines)
            if !excKw.isEmpty {
                filters["withoutKeywords"] = excKw
                filters["without_keywords"] = excKw
            }
            if !filters.isEmpty {
                payload["filters"] = filters
            }
        }
        onSave(payload)
        dismiss()
    }
}

/// Minimal Trakt list form — writes Android-compatible `provider: trakt` JSON.
private struct CollectionTraktSourceSheet: View {
    let accentColor: Color
    var initialSource: [String: Any]? = nil
    let onSave: ([String: Any]) -> Void

    @Environment(\.dismiss) private var dismiss
    @State private var titleText = ""
    @State private var listIdText = ""
    @State private var mediaType = "movie"

    private let mediaTypes = [("movie", "Movie"), ("tv", "TV")]
    private var isEditing: Bool { initialSource != nil }

    init(accentColor: Color, initialSource: [String: Any]? = nil, onSave: @escaping ([String: Any]) -> Void) {
        self.accentColor = accentColor
        self.initialSource = initialSource
        self.onSave = onSave

        let title = initialSource?["title"] as? String ?? ""
        var listId = ""
        if let id = initialSource?["traktListId"] as? Int64 {
            listId = String(id)
        } else if let id = initialSource?["traktListId"] as? Int {
            listId = String(id)
        } else if let id = initialSource?["trakt_list_id"] as? Int64 {
            listId = String(id)
        } else if let id = initialSource?["trakt_list_id"] as? Int {
            listId = String(id)
        } else if let idStr = initialSource?["traktListId"] as? String {
            listId = idStr
        } else if let idStr = initialSource?["trakt_list_id"] as? String {
            listId = idStr
        }
        let media = (initialSource?["mediaType"] as? String)
            ?? (initialSource?["media_type"] as? String)
            ?? "movie"

        _titleText = State(initialValue: title)
        _listIdText = State(initialValue: listId)
        _mediaType = State(initialValue: media)
    }

    private var canAdd: Bool {
        !titleText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && Int64(listIdText.trimmingCharacters(in: .whitespacesAndNewlines)) != nil
    }

    var body: some View {
        sourceSheetChrome(
            title: isEditing
                ? L10n.string("tvos_settings_edit_trakt_list", fallback: "Edit Trakt List")
                : L10n.string("tvos_settings_add_trakt_list", fallback: "Add Trakt List"),
            subtitle: isEditing
                ? "Update the public Trakt list ID or media type."
                : L10n.string("tvos_settings_attach_a_public_trakt_list_by_numeric_list_id", fallback: "Attach a public Trakt list by numeric list id.")
        ) {
            labeled("Title") {
                SettingsSearchStyleField(text: $titleText, placeholder: L10n.string("tvos_settings_list_title", fallback: "List title"), height: 58, fontSize: 20, horizontalPadding: 22)
            }
            labeled("Trakt list ID") {
                SettingsSearchStyleField(text: $listIdText, placeholder: L10n.string("tvos_settings_e_g_123456", fallback: "e.g. 123456"), height: 58, fontSize: 20, horizontalPadding: 22)
            }
            labeled("Media type") {
                HStack(spacing: 12) {
                    ForEach(mediaTypes, id: \.0) { id, label in
                        CollectionChipButton(title: label, isSelected: mediaType == id) {
                            mediaType = id
                        }
                    }
                }
            }
        } footer: {
            CollectionsGlassButton(title: L10n.string("action_cancel", fallback: "Cancel"), action: { dismiss() })
            CollectionsGlassButton(
                title: isEditing ? L10n.string("action_save", fallback: "Save") : L10n.string("tvos_settings_add", fallback: "Add"),
                systemImage: isEditing ? "checkmark" : "plus",
                prominent: true,
                disabled: !canAdd,
                action: save
            )
        }
    }

    private func save() {
        let trimmedTitle = titleText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let listId = Int64(listIdText.trimmingCharacters(in: .whitespacesAndNewlines)), listId > 0 else { return }
        guard !trimmedTitle.isEmpty else { return }
        onSave([
            "provider": "trakt",
            "title": trimmedTitle,
            "traktListId": listId,
            "trakt_list_id": listId,
            "mediaType": mediaType,
            "media_type": mediaType,
            "sortBy": "rank",
            "sortHow": "asc"
        ])
        dismiss()
    }
}

/// Minimal MDBList form — writes Android-compatible `provider: mdblist` JSON.
private struct CollectionMdbListSourceSheet: View {
    let accentColor: Color
    var initialSource: [String: Any]? = nil
    let onSave: ([String: Any]) -> Void

    @Environment(\.dismiss) private var dismiss
    @State private var titleText = ""
    @State private var listSourceText = ""
    @State private var mediaType = "all"
    @State private var sortBy = "rank"
    @State private var userLists: [MdbListUserList] = []
    @State private var isLoadingUserLists = false

    private let mediaTypes = [("all", "All"), ("movie", "Movie"), ("tv", "TV Series")]
    private let sortOptions = [
        ("rank", "Rank"),
        ("title.asc", "Title (A-Z)"),
        ("year.desc", "Release Date")
    ]

    private var isEditing: Bool { initialSource != nil }

    init(accentColor: Color, initialSource: [String: Any]? = nil, onSave: @escaping ([String: Any]) -> Void) {
        self.accentColor = accentColor
        self.initialSource = initialSource
        self.onSave = onSave

        let title = initialSource?["title"] as? String ?? ""
        var sourceText = ""
        if let url = initialSource?["mdblistUrl"] as? String, !url.isEmpty {
            sourceText = url
        } else if let url = initialSource?["mdblist_url"] as? String, !url.isEmpty {
            sourceText = url
        } else if let slug = initialSource?["mdblistSlug"] as? String, !slug.isEmpty {
            sourceText = slug
        } else if let slug = initialSource?["mdblist_slug"] as? String, !slug.isEmpty {
            sourceText = slug
        } else if let id = initialSource?["mdblistId"] as? Int {
            sourceText = String(id)
        } else if let id = initialSource?["mdblist_id"] as? Int {
            sourceText = String(id)
        } else if let idStr = initialSource?["mdblistId"] as? String {
            sourceText = idStr
        } else if let idStr = initialSource?["mdblist_id"] as? String {
            sourceText = idStr
        }
        let media = (initialSource?["mediaType"] as? String)
            ?? (initialSource?["media_type"] as? String)
            ?? "all"
        let sort = (initialSource?["sortBy"] as? String)
            ?? (initialSource?["sort_by"] as? String)
            ?? "rank"

        _titleText = State(initialValue: title)
        _listSourceText = State(initialValue: sourceText)
        _mediaType = State(initialValue: media)
        _sortBy = State(initialValue: sort)
    }

    private var canAdd: Bool {
        !titleText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && !listSourceText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    var body: some View {
        sourceSheetChrome(
            title: isEditing
                ? L10n.string("tvos_settings_edit_mdblist", fallback: "Edit MDBList")
                : L10n.string("tvos_settings_add_mdblist", fallback: "Add MDBList"),
            subtitle: isEditing
                ? "Update the MDBList list URL, media filter, or sort option."
                : L10n.string("tvos_settings_add_mdblist_subtitle", fallback: "Attach a public MDBList list by URL, username/slug, or list ID."),
            scrollable: true
        ) {
            labeled(L10n.string("tvos_settings_source_title", fallback: "Title")) {
                SettingsSearchStyleField(
                    text: $titleText,
                    placeholder: L10n.string("tvos_settings_source_title", fallback: "List title"),
                    height: 58,
                    fontSize: 20,
                    horizontalPadding: 22
                )
            }

            labeled("MDBList URL, Slug, or List ID") {
                SettingsSearchStyleField(
                    text: $listSourceText,
                    placeholder: "e.g. https://mdblist.com/lists/user/slug or list ID",
                    height: 58,
                    fontSize: 20,
                    horizontalPadding: 22
                )
            }

            if !userLists.isEmpty {
                labeled("My MDBList Lists") {
                    ScrollView(.horizontal, showsIndicators: false) {
                        HStack(spacing: 10) {
                            ForEach(userLists) { list in
                                CollectionChipButton(
                                    title: list.name,
                                    isSelected: listSourceText == (list.slug ?? String(list.id))
                                ) {
                                    if titleText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                                        titleText = list.name
                                    }
                                    listSourceText = list.slug ?? String(list.id)
                                }
                            }
                        }
                        .padding(.vertical, 4)
                    }
                }
            }

            labeled(L10n.string("tvos_settings_media_type", fallback: "Media type")) {
                HStack(spacing: 12) {
                    ForEach(mediaTypes, id: \.0) { id, label in
                        CollectionChipButton(title: label, isSelected: mediaType == id) {
                            mediaType = id
                        }
                    }
                }
            }

            labeled(L10n.string("tvos_settings_sort_by", fallback: "Sort by")) {
                HStack(spacing: 12) {
                    ForEach(sortOptions, id: \.0) { id, label in
                        CollectionChipButton(title: label, isSelected: sortBy == id) {
                            sortBy = id
                        }
                    }
                }
            }
        } footer: {
            CollectionsGlassButton(title: L10n.string("action_cancel", fallback: "Cancel"), action: { dismiss() })
            CollectionsGlassButton(
                title: isEditing ? L10n.string("action_save", fallback: "Save") : L10n.string("tvos_settings_add", fallback: "Add"),
                systemImage: isEditing ? "checkmark" : "plus",
                prominent: true,
                disabled: !canAdd,
                action: save
            )
        }
        .task {
            await loadUserLists()
        }
    }

    private func loadUserLists() async {
        guard !isLoadingUserLists else { return }
        isLoadingUserLists = true
        if let lists = await MdbListListService.fetchUserLists(), !lists.isEmpty {
            userLists = lists
        }
        isLoadingUserLists = false
    }

    private func save() {
        let trimmedTitle = titleText.trimmingCharacters(in: .whitespacesAndNewlines)
        let trimmedSource = listSourceText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedTitle.isEmpty, !trimmedSource.isEmpty else { return }

        var payload: [String: Any] = [
            "provider": "mdblist",
            "title": trimmedTitle,
            "mediaType": mediaType,
            "media_type": mediaType,
            "sortBy": sortBy,
            "sort_by": sortBy
        ]

        if let id = Int(trimmedSource), id > 0 {
            payload["mdblistId"] = id
            payload["mdblist_id"] = id
        } else if trimmedSource.lowercased().hasPrefix("http://") || trimmedSource.lowercased().hasPrefix("https://") {
            payload["mdblistUrl"] = trimmedSource
            payload["mdblist_url"] = trimmedSource
            if let components = URLComponents(string: trimmedSource) {
                let parts = components.path.split(separator: "/").map(String.init)
                if let listsIndex = parts.firstIndex(of: "lists"), listsIndex + 2 <= parts.count {
                    let userAndSlug = "\(parts[listsIndex + 1])/\(parts[listsIndex + 2].replacingOccurrences(of: ".json", with: ""))"
                    payload["mdblistSlug"] = userAndSlug
                    payload["mdblist_slug"] = userAndSlug
                }
            }
        } else {
            payload["mdblistSlug"] = trimmedSource
            payload["mdblist_slug"] = trimmedSource
        }

        onSave(payload)
        dismiss()
    }
}

/// Shared liquid-glass panel chrome for the TMDB / Trakt add sheets.
private func sourceSheetChrome<Content: View, Footer: View>(
    title: String,
    subtitle: String,
    scrollable: Bool = false,
    @ViewBuilder content: () -> Content,
    @ViewBuilder footer: () -> Footer
) -> some View {
    ZStack {
        Color.black.opacity(0.62).ignoresSafeArea()
        VStack(alignment: .leading, spacing: 22) {
            VStack(alignment: .leading, spacing: 5) {
                Text(title)
                    .font(.system(size: 34, weight: .bold))
                    .foregroundColor(.white)
                Text(subtitle)
                    .font(.system(size: 19, weight: .medium))
                    .foregroundColor(.white.opacity(0.58))
                    .fixedSize(horizontal: false, vertical: true)
            }
            if scrollable {
                ScrollView(.vertical, showsIndicators: true) {
                    VStack(alignment: .leading, spacing: 18) {
                        content()
                    }
                    .padding(.top, 4)
                    .padding(.bottom, 24)
                    .padding(.horizontal, 4)
                }
                .frame(maxHeight: 520)
                .focusSection()
            } else {
                VStack(alignment: .leading, spacing: 18) {
                    content()
                }
            }
            HStack(spacing: 14) {
                Spacer()
                footer()
            }
        }
        .padding(.vertical, 34)
        .padding(.horizontal, 48)
        .frame(width: 900)
        .settingsGlass(shape: RoundedRectangle(cornerRadius: 34, style: .continuous), isProminent: true)
        .overlay(
            RoundedRectangle(cornerRadius: 34, style: .continuous)
                .strokeBorder(Color.white.opacity(0.20), lineWidth: 1)
        )
    }
    .frame(maxWidth: .infinity, maxHeight: .infinity)
}

@ViewBuilder
private func labeled<Content: View>(_ title: String, @ViewBuilder content: () -> Content) -> some View {
    VStack(alignment: .leading, spacing: 10) {
        Text(title)
            .font(.system(size: 17, weight: .semibold))
            .foregroundColor(.white.opacity(0.55))
        content()
    }
}

private struct AddonSettingsRow: View {
    let addon: AddonItem
    let accentColor: Color
    var canMoveUp: Bool = false
    var canMoveDown: Bool = false
    var onEnabledChange: ((Bool) -> Void)? = nil
    var onDelete: (() -> Void)? = nil
    var onMove: ((Bool) -> Void)? = nil

    @FocusState private var isFocused: Bool

    var body: some View {
        HStack(spacing: 14) {
            rowButton

            if let onDelete {
                AddonReorderButton(systemImage: "trash", disabled: false, action: onDelete)
            }

            if let onMove {
                AddonReorderButton(systemImage: "chevron.up", disabled: !canMoveUp) {
                    onMove(true)
                }
                AddonReorderButton(systemImage: "chevron.down", disabled: !canMoveDown) {
                    onMove(false)
                }
            }
        }
    }

    private var rowButton: some View {
        Button(action: { onEnabledChange?(!addon.isInstalled) }) {
            SettingsRowShell(isFocused: isFocused, accentColor: accentColor) {
                Image(systemName: addon.logoSystemName)
                    .font(.system(size: 26))
                    .foregroundColor(addon.isInstalled ? accentColor : .white.opacity(0.38))
                    .frame(width: 48, height: 48)
                    .opacity(addon.isInstalled ? 1 : 0.42)

                VStack(alignment: .leading, spacing: 4) {
                    HStack(spacing: 8) {
                        Text(addon.name)
                            .font(.system(size: 22, weight: .semibold))
                            .foregroundColor(addon.isInstalled ? .white : .white.opacity(0.46))
                            .lineLimit(1)
                        if !addon.version.isEmpty {
                            Text("v\(addon.version)")
                                .font(.system(size: 15, weight: .medium))
                                .foregroundColor(.white.opacity(0.4))
                        }
                        Text(L10n.string("tvos_settings_synced", fallback: "Synced"))
                            .font(.system(size: 13, weight: .bold))
                            .foregroundColor(accentColor)
                    }
                    Text(addon.description)
                        .font(.system(size: 16, weight: .medium))
                        .foregroundColor(.white.opacity(addon.isInstalled ? 0.56 : 0.36))
                        .lineLimit(2)
                }

                Spacer(minLength: 20)

                Text(addon.isInstalled ? L10n.string("settings_fusion_badge_url_active", fallback: "Active") : L10n.string("tvos_settings_disabled", fallback: "Disabled"))
                    .font(.system(size: 18, weight: .bold))
                    .foregroundColor(addon.isInstalled ? .white.opacity(0.7) : .white.opacity(0.42))
                    .lineLimit(1)
            }
        }
        .buttonStyle(PosterCardButtonStyle())
        .focused($isFocused)
        .focusEffectDisabledIfAvailable()
        .entryLockable()
    }
}

