// MARK: - Usenet

/// Usenet providers for on-device NZB streaming. Server details live in the
/// profile's settings, passwords in Keychain (`UsenetCredentialStore`).
@MainActor
private final class UsenetSettingsModel: ObservableObject {
    enum TestState: Equatable {
        case idle
        case testing
        case ok
        case failed(String)
    }

    @Published var servers: [UsenetSavedServer] = UsenetSettings.servers()
    @Published var tests: [String: TestState] = [:]

    func reload() { servers = UsenetSettings.servers() }

    func remove(_ server: UsenetSavedServer) {
        UsenetSettings.remove(server.id)
        tests[server.id] = nil
        reload()
    }

    func test(_ server: UsenetSavedServer) {
        tests[server.id] = .testing
        let config = server.config(password: UsenetCredentialStore.password(forServerID: server.id))
        Task {
            let connection = UsenetNNTPConnection(config: config)
            do {
                try await connection.open()
                await connection.close()
                tests[server.id] = .ok
            } catch let error as UsenetNNTPError {
                await connection.close()
                tests[server.id] = .failed(UsenetConnectionPool.describe(error))
            } catch {
                await connection.close()
                tests[server.id] = .failed(error.localizedDescription)
            }
        }
    }
}

private struct UsenetSettingsSection: View {
    let accentColor: Color

    @StateObject private var model = UsenetSettingsModel()
    @State private var editingServer: UsenetSavedServer?
    @State private var isAddingServer = false
    @State private var profile = UsenetSettings.profile().rawValue
    @State private var prefersOwnServers = UsenetSettings.prefersOwnServers()
    @State private var speedLimit = String(UsenetSettings.speedLimitMbps())
    @State private var syncToAccount = UsenetSettings.syncChoice() ?? false

    var body: some View {
        SettingsGroup(
            title: L10n.string("usenet_group_title", fallback: "Usenet"),
            subtitle: L10n.string("usenet_group_subtitle", fallback: "Stream NZB sources on this Apple TV with your own Usenet provider")
        ) {
            SettingsActionRow(
                title: L10n.string("usenet_add_server", fallback: "Add Server"),
                subtitle: L10n.string("usenet_add_server_subtitle", fallback: "Host, port and login of your provider (e.g. Eweka, Newshosting)"),
                value: "",
                accentColor: accentColor
            ) {
                isAddingServer = true
            }

            ForEach(model.servers) { server in
                UsenetServerRow(
                    server: server,
                    accentColor: accentColor,
                    testState: model.tests[server.id] ?? .idle,
                    onEdit: { editingServer = server },
                    onTest: { model.test(server) },
                    onDelete: { model.remove(server) }
                )
            }

            SettingsChoiceRow(
                title: L10n.string("usenet_profile_title", fallback: "Performance Profile"),
                subtitle: L10n.string("usenet_profile_subtitle", fallback: "Memory for buffered articles and how far ahead to read (32 / 64 / 128 MB)"),
                selection: $profile,
                options: UsenetMemoryProfile.allCases.map(\.rawValue),
                optionLabels: Dictionary(uniqueKeysWithValues: UsenetMemoryProfile.allCases.map { ($0.rawValue, $0.title) }),
                accentColor: accentColor
            )

            SettingsChoiceRow(
                title: L10n.string("usenet_speed_limit_title", fallback: "Speed Limit"),
                subtitle: L10n.string("usenet_speed_limit_subtitle", fallback: "Cap downloads while playing so buffering doesn't saturate your connection. 1080p needs about 5–10 Mbit/s, 4K remux up to 80."),
                selection: $speedLimit,
                options: UsenetSettings.speedLimitOptions.map(String.init),
                optionLabels: Dictionary(uniqueKeysWithValues: UsenetSettings.speedLimitOptions.map {
                    (String($0), $0 == 0 ? L10n.string("usenet_speed_unlimited", fallback: "Unlimited") : "\($0) Mbit/s")
                }),
                accentColor: accentColor
            )

            SettingsToggleRow(
                title: L10n.string("usenet_prefer_own_title", fallback: "Always Use My Servers"),
                subtitle: L10n.string("usenet_prefer_own_subtitle", fallback: "Ignore servers an add-on sends with its streams. When off, yours are the fallback."),
                isOn: $prefersOwnServers,
                accentColor: accentColor
            )

            // Written only from the toggle: a profile that never chose leaves
            // the account's copy alone (see UsenetSettingsSync).
            SettingsToggleRow(
                title: L10n.string("usenet_sync_title", fallback: "Save to Nuvio Account"),
                subtitle: L10n.string(
                    "usenet_sync_subtitle",
                    fallback: "Keep these servers and their passwords in this profile of your Nuvio account, so a reinstall or another Apple TV gets them back. Passwords are stored like debrid keys. Turning it off removes them from the account."
                ),
                isOn: Binding(
                    get: { syncToAccount },
                    set: { value in
                        syncToAccount = value
                        UsenetSettings.setSyncChoice(value)
                    }
                ),
                accentColor: accentColor
            )
        }
        .onChange(of: profile) { _, value in
            UsenetSettings.setProfile(UsenetMemoryProfile(rawValue: value) ?? .balanced)
        }
        .onChange(of: prefersOwnServers) { _, value in
            UsenetSettings.setPrefersOwnServers(value)
        }
        .onChange(of: speedLimit) { _, value in
            UsenetSettings.setSpeedLimitMbps(Int(value) ?? 0)
        }
        .onReceive(NotificationCenter.default.publisher(for: .usenetServersChanged)) { _ in
            model.reload()
            // An account pull may have brought servers and settings in.
            syncToAccount = UsenetSettings.syncChoice() ?? false
            profile = UsenetSettings.profile().rawValue
            prefersOwnServers = UsenetSettings.prefersOwnServers()
            speedLimit = String(UsenetSettings.speedLimitMbps())
        }
        .sheet(isPresented: $isAddingServer) {
            UsenetServerEditSheet(server: nil, accentColor: accentColor)
                .modifier(ClearPresentationBackgroundIfAvailable())
        }
        .sheet(item: $editingServer) { server in
            UsenetServerEditSheet(server: server, accentColor: accentColor)
                .modifier(ClearPresentationBackgroundIfAvailable())
        }
    }
}

private struct UsenetServerRow: View {
    let server: UsenetSavedServer
    let accentColor: Color
    let testState: UsenetSettingsModel.TestState
    let onEdit: () -> Void
    let onTest: () -> Void
    let onDelete: () -> Void

    @FocusState private var isFocused: Bool

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            Button(action: onEdit) {
                SettingsRowShell(isFocused: isFocused, accentColor: accentColor) {
                    SettingsRowText(title: server.displayName, subtitle: subtitleText)
                    Spacer(minLength: 24)
                    HStack(spacing: 8) {
                        Circle()
                            .fill(testState == .ok ? Color.green : Color.white.opacity(0.3))
                            .frame(width: 10, height: 10)
                        Text(statusText)
                            .font(.system(size: 17, weight: .semibold))
                            .foregroundColor(.white.opacity(0.7))
                    }
                }
            }
            .buttonStyle(PosterCardButtonStyle())
            .focused($isFocused)
            .focusEffectDisabledIfAvailable()

            HStack(spacing: 12) {
                SMBRowButton(
                    title: L10n.string("smb_test", fallback: "Test"),
                    accentColor: accentColor,
                    isLoading: testState == .testing,
                    action: onTest
                )
                Spacer()
                SMBDeleteButton(action: onDelete)
            }
        }
        .padding(.bottom, 4)
    }

    private var subtitleText: String {
        var parts = ["\(server.host):\(server.port)" + (server.useSSL ? " · SSL" : ""),
                     L10n.format("usenet_connections_count", fallback: "%d connections", server.connections)]
        if !server.isEnabled { parts.append(L10n.string("tvos_settings_disabled", fallback: "Disabled")) }
        if case .failed(let message) = testState { parts.append(message) }
        return parts.joined(separator: " · ")
    }

    private var statusText: String {
        switch testState {
        case .idle: return ""
        case .testing: return L10n.string("smb_connecting", fallback: "Connecting…")
        case .ok: return L10n.string("usenet_test_ok", fallback: "Login OK")
        case .failed: return L10n.string("smb_failed", fallback: "Failed")
        }
    }
}

/// How many connections to set and what more of them does, under the
/// Connections stepper. Measured on a 4K remux: on a line that tops out at
/// ~25 MB/s, 20 connections gave the same speed as 50 and jumps about a
/// second faster, because each article shares the line with fewer others.
private struct UsenetConnectionsGuide: View {
    private var lines: [String] {
        [
            L10n.string(
                "usenet_connections_guide_plan",
                fallback: "Never more than your plan allows: the server turns the rest away and Nuvio keeps to the ones it accepted."
            ),
            L10n.string(
                "usenet_connections_guide_line",
                fallback: "More connections help only until your internet line is full. A good start is one per 10 Mbit/s of your line: 20 for 200 Mbit/s, 50 for 500 Mbit/s."
            ),
            L10n.string(
                "usenet_connections_guide_more",
                fallback: "Beyond that, the speed stays the same but each article arrives later, so jumps in large 4K files take longer."
            ),
            L10n.string(
                "usenet_connections_guide_check",
                fallback: "To check, turn on the Playback Debug Overlay: if the Usenet speed doesn't rise with more connections, go back down."
            ),
        ]
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            ForEach(lines, id: \.self) { line in
                HStack(alignment: .firstTextBaseline, spacing: 10) {
                    Text("•")
                    Text(line)
                        .fixedSize(horizontal: false, vertical: true)
                }
            }
        }
        .font(.system(size: 17, weight: .medium))
        .foregroundColor(.white.opacity(0.56))
        .padding(.horizontal, 20)
        .padding(.vertical, 4)
        .frame(maxWidth: .infinity, alignment: .leading)
    }
}

private struct UsenetServerEditSheet: View {
    let server: UsenetSavedServer?
    let accentColor: Color

    @Environment(\.dismiss) private var dismiss
    @AppStorage(SettingsKey.amoled) private var amoled = false
    @AppStorage(SettingsKey.bodyColor) private var bodyColor = SettingsBackground.charcoal.rawValue

    @State private var name: String
    @State private var host: String
    @State private var portText: String
    @State private var useSSL: Bool
    @State private var username: String
    @State private var password: String
    @State private var connections: Int
    @State private var isEnabled: Bool

    init(server: UsenetSavedServer?, accentColor: Color) {
        self.server = server
        self.accentColor = accentColor
        _name = State(initialValue: server?.name ?? "")
        _host = State(initialValue: server?.host ?? "")
        _portText = State(initialValue: server.map { String($0.port) } ?? "")
        _useSSL = State(initialValue: server?.useSSL ?? true)
        _username = State(initialValue: server?.username ?? "")
        _password = State(initialValue: server.map { UsenetCredentialStore.password(forServerID: $0.id) } ?? "")
        _connections = State(initialValue: server?.connections ?? UsenetServerConfig.defaultConnections)
        _isEnabled = State(initialValue: server?.isEnabled ?? true)
    }

    var body: some View {
        ZStack {
            Color.nuvioBackground(amoled: amoled, body: bodyColor).ignoresSafeArea()

            ScrollView {
                VStack(alignment: .leading, spacing: 24) {
                    Text(server == nil
                         ? L10n.string("usenet_add_server", fallback: "Add Server")
                         : L10n.string("usenet_edit_server", fallback: "Edit Server"))
                        .font(.system(size: 36, weight: .bold))
                        .foregroundColor(.white)

                    SettingsGroup(
                        title: L10n.string("smb_connection", fallback: "Connection"),
                        subtitle: L10n.string("usenet_connection_subtitle", fallback: "Your provider's news server")
                    ) {
                        SettingsNativeTextFieldRow(
                            title: L10n.string("smb_display_name", fallback: "Name"),
                            subtitle: "",
                            placeholder: "Eweka",
                            text: $name
                        )
                        SettingsNativeTextFieldRow(
                            title: L10n.string("smb_host", fallback: "Host"),
                            subtitle: L10n.string("usenet_host_subtitle", fallback: "e.g. news.eweka.nl"),
                            placeholder: "news.example.com",
                            text: $host
                        )
                        SettingsToggleRow(
                            title: L10n.string("usenet_ssl", fallback: "SSL / TLS"),
                            subtitle: L10n.string("usenet_ssl_subtitle", fallback: "Encrypted connection (port 563 by default)"),
                            isOn: $useSSL,
                            accentColor: accentColor
                        )
                        SettingsNativeTextFieldRow(
                            title: L10n.string("smb_port", fallback: "Port"),
                            subtitle: L10n.string("usenet_port_subtitle", fallback: "Leave blank for the default (563 with SSL, 119 without)"),
                            placeholder: useSSL ? "563" : "119",
                            text: $portText
                        )
                        SettingsStepperRow(
                            title: L10n.string("usenet_connections", fallback: "Connections"),
                            subtitle: L10n.string(
                                "usenet_connections_subtitle",
                                fallback: "At most what your plan allows (up to 100)."
                            ),
                            value: $connections,
                            range: 1...UsenetServerConfig.maxConnectionsLimit,
                            step: 1,
                            suffix: "",
                            accentColor: accentColor
                        )
                        UsenetConnectionsGuide()
                        SettingsToggleRow(
                            title: L10n.string("usenet_enabled", fallback: "Use This Server"),
                            subtitle: "",
                            isOn: $isEnabled,
                            accentColor: accentColor
                        )
                    }

                    SettingsGroup(
                        title: L10n.string("smb_authentication", fallback: "Authentication"),
                        subtitle: ""
                    ) {
                        SettingsNativeTextFieldRow(
                            title: L10n.string("smb_username", fallback: "Username"),
                            subtitle: "",
                            placeholder: L10n.string("debrid_not_set", fallback: "Not set"),
                            text: $username
                        )
                        SettingsNativeTextFieldRow(
                            title: L10n.string("smb_password", fallback: "Password"),
                            subtitle: L10n.string("tvos_settings_stored_locally_on_this_apple_tv", fallback: "Stored locally on this Apple TV"),
                            placeholder: L10n.string("debrid_not_set", fallback: "Not set"),
                            text: $password,
                            isSecure: true
                        )
                    }

                    HStack {
                        SMBDialogButton(title: L10n.string("action_cancel", fallback: "Cancel"), isPrimary: false) { dismiss() }
                        Spacer()
                        SMBDialogButton(title: L10n.string("action_save", fallback: "Save"), isPrimary: true, enabled: canSave) {
                            save()
                            dismiss()
                        }
                    }
                    .focusSection()
                }
                .padding(40)
            }
        }
    }

    private var trimmedHost: String { host.trimmingCharacters(in: .whitespacesAndNewlines) }

    private var canSave: Bool { !trimmedHost.isEmpty }

    private func save() {
        let port = Int(portText.trimmingCharacters(in: .whitespacesAndNewlines)) ?? (useSSL ? 563 : 119)
        let saved = UsenetSavedServer(
            id: server?.id ?? UUID().uuidString,
            name: name.trimmingCharacters(in: .whitespacesAndNewlines),
            host: trimmedHost,
            port: port,
            useSSL: useSSL,
            username: username.trimmingCharacters(in: .whitespacesAndNewlines),
            connections: connections,
            isEnabled: isEnabled
        )
        UsenetSettings.upsert(saved, password: password)
    }
}

/// AIOStreams' card in Integrations (under Plugins): the original AIOStreams
/// in Node.js on this Apple TV (AIOStreamsHost). Its sheet starts it (once per
/// app run) and shows the configuration page's address, the addon it added,
/// the start times, memory and its log.
private struct AIOStreamsHostSummaryCard: View {
    let accentColor: Color

    @ObservedObject private var aio = AIOStreamsHost.shared
    @State private var showingSheet = false

    var body: some View {
        SettingsFeatureSummaryCard(
            featureName: "AIOStreams",
            status: status,
            actionSubtitle: "The original AIOStreams in Node.js on this Apple TV: start it, open its configuration page, update it and see how it runs",
            accentColor: accentColor
        ) {
            showingSheet = true
        }
        .sheet(isPresented: $showingSheet) {
            AIOStreamsHostSheet(accentColor: accentColor)
                .modifier(ClearPresentationBackgroundIfAvailable())
        }
    }

    private var status: String {
        let version = aio.packageVersion.isEmpty ? "" : " · AIOStreams \(aio.packageVersion)"
        switch aio.phase {
        case .running: return "Running" + version
        case .starting: return "Starting…"
        case .stopped: return "Not running"
        case .notAnswering: return "Started, but not answering"
        case .exited: return "Node.js stopped"
        case .unavailable(let reason): return reason
        }
    }
}

private struct AIOStreamsHostSheet: View {
    let accentColor: Color

    @Environment(\.dismiss) private var dismiss
    @ObservedObject private var aio = AIOStreamsHost.shared
    @State private var sourceDraft = ""

    var body: some View {
        SettingsFeatureSettingsSheet(
            title: "AIOStreams",
            subtitle: "Node.js \(aio.packageVersion.isEmpty ? "" : "· AIOStreams \(aio.packageVersion)")"
        ) {
            VStack(alignment: .leading, spacing: 22) {
                HStack(alignment: .center, spacing: 36) {
                    qrCode
                    VStack(alignment: .leading, spacing: 10) {
                        Text(statusText)
                            .font(.system(size: 26, weight: .bold))
                            .foregroundColor(statusColor)
                        if let page = aio.configurationPageURL, aio.phase == .running {
                            Text("Configuration page — open it in a browser on your computer (it is not an add-on address):")
                                .font(.system(size: 18, weight: .medium))
                                .foregroundColor(.white.opacity(0.65))
                                .fixedSize(horizontal: false, vertical: true)
                            Text(page)
                                .font(.system(size: 24, weight: .semibold, design: .monospaced))
                                .foregroundColor(.white)
                                .lineLimit(2)
                                .minimumScaleFactor(0.6)
                        }
                        Text(details)
                            .font(.system(size: 19, weight: .medium))
                            .foregroundColor(.white.opacity(0.65))
                            .fixedSize(horizontal: false, vertical: true)
                        if let profile = aio.startupProfile {
                            Text(profile)
                                .font(.system(size: 17, weight: .medium))
                                .foregroundColor(.white.opacity(0.55))
                                .fixedSize(horizontal: false, vertical: true)
                        }
                    }
                }

                if let notice = aio.notice {
                    Text(notice)
                        .font(.system(size: 20, weight: .semibold))
                        .foregroundColor(.yellow)
                        .fixedSize(horizontal: false, vertical: true)
                }

                if aio.phase == .stopped {
                    SettingsActionRow(
                        title: "Start AIOStreams",
                        subtitle: "The first start unpacks AIOStreams, which takes a while. It then runs until Nuvio is closed.",
                        value: "Start",
                        accentColor: accentColor
                    ) {
                        aio.start()
                    }
                    SettingsActionRow(
                        title: "Test Node.js only",
                        subtitle: "Runs only Node.js with a short test, without AIOStreams. Close and reopen Nuvio afterwards to start AIOStreams.",
                        value: "Test",
                        accentColor: accentColor
                    ) {
                        aio.testNodeOnly()
                    }
                }

                SettingsToggleRow(
                    title: "Start with Nuvio",
                    subtitle: "Run AIOStreams whenever Nuvio runs",
                    isOn: Binding(get: { aio.autoStart }, set: { aio.setAutoStart($0) }),
                    accentColor: accentColor
                )

                Text("Version")
                    .font(.system(size: 22, weight: .bold))
                    .foregroundColor(.white)

                SettingsActionRow(
                    title: "Check for updates",
                    subtitle: versionLine,
                    value: "Check",
                    accentColor: accentColor
                ) {
                    Task { await aio.checkForUpdates() }
                }

                if aio.phase == .running {
                    SettingsActionRow(
                        title: "Update AIOStreams",
                        subtitle: aio.updateStatus ?? "Installs the newest version from the source while this one keeps running; it starts with the next start of Nuvio",
                        value: aio.updating ? "…" : "Update",
                        accentColor: accentColor
                    ) {
                        Task { await aio.update() }
                    }
                }

                if let previous = aio.previousVersion, !aio.usePreviousAtNextStart {
                    SettingsActionRow(
                        title: "Use the previous version",
                        subtitle: "\(previous), from the next start of Nuvio",
                        value: "Use",
                        accentColor: accentColor
                    ) {
                        aio.usePreviousVersion()
                    }
                }

                SettingsTextFieldRow(
                    title: "Source",
                    subtitle: "AIOStreams' official image, another image or the address of a package (aio.tar.gz) — from the next start",
                    placeholder: AIOStreamsHost.defaultSource,
                    text: $sourceDraft,
                    fieldWidth: 560,
                    onCommit: { aio.setSource(sourceDraft) }
                )

                if aio.source != AIOStreamsHost.defaultSource {
                    SettingsActionRow(
                        title: "Restore the default source",
                        subtitle: AIOStreamsHost.defaultSource,
                        value: "Restore",
                        accentColor: accentColor
                    ) {
                        aio.resetSource()
                        sourceDraft = aio.source
                    }
                }

                SettingsToggleRow(
                    title: "Detailed AIOStreams log",
                    subtitle: "Every request in the log, not only warnings and errors (from the next start)",
                    isOn: Binding(get: { aio.detailedLog }, set: { aio.setDetailedLog($0) }),
                    accentColor: accentColor
                )

                SettingsToggleRow(
                    title: "Use the AIOStreams Addon",
                    subtitle: aio.manifestURL == nil
                        ? "Save a configuration on the page and Nuvio adds the addon (on this Apple TV only)"
                        : "Its streams and catalogs next to your add-ons, on this Apple TV only",
                    isOn: Binding(get: { aio.addonEnabled }, set: { aio.setAddonEnabled($0) }),
                    accentColor: accentColor
                )

                // Written only from here: an Apple TV that never chose leaves the
                // account's copy alone (see AIOSettingsSync).
                SettingsToggleRow(
                    title: "Save to Nuvio Account",
                    subtitle: "Keep these settings and your configuration with its password in this profile of your Nuvio account, so a reinstall or another Apple TV gets them back (each runs its own AIOStreams). Stored like debrid keys. Turning it off removes them from the account.",
                    isOn: Binding(get: { aio.syncToAccount }, set: { aio.setSyncToAccount($0) }),
                    accentColor: accentColor
                )

                SettingsActionRow(
                    title: "Anime searches",
                    subtitle: "With the AniList integration, an AniList title: \(aio.animeRequest.explanation)"
                        + (aio.lastAnimeSearch.map { "\nLast: \($0)" } ?? ""),
                    value: aio.animeRequest.label,
                    accentColor: accentColor
                ) {
                    aio.cycleAnimeRequest()
                }

                if let previous = aio.previousRun, aio.phase == .stopped || previous.unexpected {
                    VStack(alignment: .leading, spacing: 4) {
                        Text("Last run" + (previous.date.map { " · " + $0.formatted(date: .abbreviated, time: .shortened) } ?? ""))
                            .font(.system(size: 22, weight: .bold))
                            .foregroundColor(.white)
                        Text(previous.summary)
                            .font(.system(size: 20, weight: .semibold))
                            .foregroundColor(previous.unexpected ? .red : .white.opacity(0.8))
                            .fixedSize(horizontal: false, vertical: true)
                            .focusable()
                        ForEach(Array(previous.lines.enumerated()), id: \.offset) { _, line in
                            logLine(line)
                        }
                    }
                }

                if !aio.logLines.isEmpty {
                    VStack(alignment: .leading, spacing: 4) {
                        Text("Log")
                            .font(.system(size: 22, weight: .bold))
                            .foregroundColor(.white)
                        ForEach(Array(aio.logLines.suffix(80).enumerated()), id: \.offset) { _, line in
                            logLine(line)
                        }
                    }
                }

                SettingsActionRow(
                    title: "Done",
                    subtitle: "AIOStreams keeps running",
                    value: "Close",
                    accentColor: accentColor
                ) {
                    dismiss()
                }
            }
            .settingsEntryAnchor()
        }
        .onAppear {
            aio.setLogVisible(true)
            sourceDraft = aio.source
        }
        .onDisappear { aio.setLogVisible(false) }
    }

    private func logLine(_ line: String) -> some View {
        Text(line)
            .font(.system(size: 15, weight: .regular, design: .monospaced))
            .foregroundColor(line.contains("CRASH") || line.hasPrefix("✕") || line.contains("FAILED") ? .red
                : line.hasPrefix("!") ? .yellow : .white.opacity(0.8))
            .lineLimit(3)
            .frame(maxWidth: .infinity, alignment: .leading)
            .focusable()
    }

    @ViewBuilder
    private var qrCode: some View {
        if aio.phase == .running, let page = aio.configurationPageURL, let image = SettingsQRCode.image(for: page) {
            Image(decorative: image, scale: 1, orientation: .up)
                .interpolation(.none)
                .resizable()
                .frame(width: 220, height: 220)
                .padding(12)
                .background(Color.white, in: RoundedRectangle(cornerRadius: 18, style: .continuous))
        } else {
            RoundedRectangle(cornerRadius: 18, style: .continuous)
                .fill(Color.white.opacity(0.08))
                .frame(width: 244, height: 244)
                .overlay(ProgressView().opacity(aio.phase == .starting ? 1 : 0))
        }
    }

    private var statusText: String {
        switch aio.phase {
        case .stopped: return "Not running"
        case .starting: return aio.runKind == .nodeTest ? "Testing Node.js…" : (aio.installProgress ?? "Starting…")
        case .running: return "Running"
        case .notAnswering: return "Started, but not answering"
        case .exited(let code) where aio.runKind == .nodeTest:
            return "Node.js test finished (\(code)) — close and reopen Nuvio to start AIOStreams"
        case .exited(let code): return "Node.js stopped (\(code)) — restart Nuvio to try again"
        case .unavailable(let reason): return reason
        }
    }

    private var statusColor: Color {
        switch aio.phase {
        case .running, .exited(0) where aio.runKind == .nodeTest: return .green
        case .starting, .stopped: return .white
        default: return .red
        }
    }

    private var versionLine: String {
        var parts = ["Installed: \(aio.packageVersion.isEmpty ? "none yet" : aio.packageVersion)"]
        if let pending = aio.pendingVersion { parts.append("\(pending) after a restart") }
        if let latest = aio.latestVersion { parts.append("newest: \(latest)") }
        if let status = aio.updateStatus, aio.phase != .running { parts.append(status) }
        return parts.joined(separator: " · ")
    }

    private var details: String {
        var parts: [String] = []
        if let seconds = aio.startupSeconds { parts.append(String(format: "Ready in %.1f s", seconds)) }
        if let node = aio.nodeMemoryMB { parts.append("Node.js \(node) MB") }
        if let app = aio.appMemoryMB { parts.append("Nuvio in total \(app) MB") }
        parts.append(aio.manifestURL == nil ? "No configuration saved yet" : "Addon added")
        parts.append(aio.hasBackup ? "Configuration backed up" : "No backup yet")
        if let warmUp = aio.lastWarmUp { parts.append("Warm-up: \(warmUp)") }
        return parts.joined(separator: " · ")
    }
}
